def build_uploaded_image_from_data_url(data_url, filename_prefix):
    """Convert a base64 data URL into a Django ContentFile."""
    if not data_url or ';base64,' not in data_url:
        return None
    try:
        header, encoded = data_url.split(';base64,', 1)
        extension = header.split('/')[-1].lower() if '/' in header else 'png'
        extension = 'jpg' if extension == 'jpeg' else extension
        safe_prefix = slugify(filename_prefix) or 'capture'
        return ContentFile(base64.b64decode(encoded), name=f"{safe_prefix}_capture.{extension}")
    except Exception:
        return None


def parse_staff_role(raw_role):
    role_value = (raw_role or 'teacher').strip().lower()
    valid_roles = {choice[0] for choice in ROLE_CHOICES}
    return role_value if role_value in valid_roles else 'teacher'


def apply_teacher_photo_from_request(teacher, request, fallback_name=None):
    photo_file = request.FILES.get('photo')
    if not photo_file:
        photo_file = build_uploaded_image_from_data_url(
            request.POST.get('captured_photo_data'),
            fallback_name or teacher.teacherName or teacher.user.username,
        )
    if photo_file:
        teacher.photo = photo_file
        teacher.save(update_fields=['photo'])
        if teacher.photo:
            teacher.save_face_encoding()


def sync_student_photo_from_passport(student, passport_info):
    if not passport_info or not passport_info.passport_photo:
        return None

    student.photo = passport_info.passport_photo.name
    student.save(update_fields=['photo'])
    if student.photo:
        student.save_face_encoding()
    return student.photo.url if student.photo else ''


def role_badge_class(role):
    return {
        'teacher': 'primary',
        'accountant': 'success',
        'driver': 'warning',
        'admin': 'dark',
    }.get(role, 'secondary')


def get_transport_filters(request):
    vehicle_id = request.GET.get('vehicle')
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')
    filtered_vehicle = (
        Vehicle.objects.filter(pk=vehicle_id, user=request.effective_user)
        .select_related('driver', 'driver__user')
        .first()
        if vehicle_id
        else None
    )
    return vehicle_id, start_date, end_date, filtered_vehicle


def filter_transport_records(queryset, start_date=None, end_date=None):
    if start_date:
        queryset = queryset.filter(date__gte=start_date)
    if end_date:
        queryset = queryset.filter(date__lte=end_date)
    return queryset


def filter_by_user(queryset, request, user_lookup='user'):
    return queryset.filter(**{user_lookup: request.effective_user})


def _transport_vehicle_queryset(request):
    return filter_by_user(
        Vehicle.objects.select_related('driver', 'driver__user').prefetch_related('routes'),
        request,
    ).order_by('name', 'plate_number')


def _restrict_transport_form_choices(form, request):
    if 'vehicle' in form.fields:
        form.fields['vehicle'].queryset = filter_by_user(
            Vehicle.objects.select_related('driver', 'driver__user'),
            request,
        ).order_by('name', 'plate_number')
    if 'driver' in form.fields:
        form.fields['driver'].queryset = Teacher.objects.filter(
            teacher_role='driver',
        ).filter(
            Q(created_by=request.effective_user) | Q(user=request.effective_user),
        ).select_related('user').order_by('teacherName', 'user__username')


def has_perm(user, perm_name):
    teacher = user.teacher_profile.first()
    if not teacher:
        return False
    perm = getattr(teacher, 'userpermission', None)
    return getattr(perm, perm_name, False) if perm else False


def has_teacher_permission(user, perm_name):
    if user.is_superuser:
        return True

    from rps_app.models import Teacher

    teacher = Teacher.objects.filter(user=user).select_related('userpermission').first()
    if not teacher or not hasattr(teacher, 'userpermission'):
        return False

    return getattr(teacher.userpermission, perm_name, False)


