def _derive_class_code(teacherclass):
    class_name = ''
    try:
        class_name = (teacherclass.ClassName.class_name or '').upper()
    except Exception:
        class_name = ''
    cleaned = re.sub(r'[^A-Z0-9]+', '', class_name)
    if not cleaned:
        return ''
    return cleaned[:4]


def generate_student_index_number_for_class(user, teacherclass):
    year_label = timezone.now().year
    if teacherclass and teacherclass.academicclassyear and teacherclass.academicclassyear.academic_year_name:
        year_match = re.search(r'(\d{4})', teacherclass.academicclassyear.academic_year_name)
        if year_match:
            year_label = year_match.group(1)

    class_code = _derive_class_code(teacherclass)
    prefix = f"BRT-{year_label}-{class_code}-" if class_code else f"BRT-{year_label}-"

    existing_numbers = Student.objects.filter(
        manager=user,
        indexNumber__startswith=prefix
    ).values_list('indexNumber', flat=True)

    max_counter = 0
    for idx in existing_numbers:
        if not idx:
            continue
        tail = str(idx).split('-')[-1]
        if tail.isdigit():
            max_counter = max(max_counter, int(tail))

    candidate_counter = max_counter + 1
    while True:
        candidate = f"{prefix}{candidate_counter:04d}"
        if not Student.objects.filter(indexNumber=candidate).exclude(manager=user).exists():
            return candidate
        candidate_counter += 1


def build_student_academic_prefill(student):
    teacherclass = getattr(student, 'teacherclass', None)
    class_name = getattr(getattr(teacherclass, 'ClassName', None), 'class_name', '') if teacherclass else ''
    academic_year = getattr(getattr(teacherclass, 'academicclassyear', None), 'academic_year_name', '') if teacherclass else ''

    normalized_name = (class_name or '').lower()
    academic_level = ''
    if any(x in normalized_name for x in ['form 5', 'form v', 'form 6', 'form vi', 'a level', 'alevel']):
        academic_level = 'A-Level'
    elif any(x in normalized_name for x in ['grade', 'std', 'standard', 'primary']):
        academic_level = 'Primary'
    elif class_name:
        academic_level = 'O-Level'

    return {
        'registration_number': student.indexNumber or '',
        'academic_level': academic_level if academic_level in dict(STUDENT_ACADEMIC_LEVEL_CHOICES) else '',
        'academic_year': academic_year or '',
        'class_name': class_name or '',
    }


@effective_user_decorator
@login_required
@transaction.atomic
def create_student(request):
    if not request.effective_user.is_teacher:
        messages.error(request, "You are not authorized to perform this action.")
        return redirect('teacher_dashboard')

    if request.method == 'POST':
        fullName = request.POST.get('fullName', '').strip()
        sex = request.POST.get('sex', '').strip().upper()
        indexNumber = request.POST.get('indexNumber', '').strip()
        teacherclass_id = request.POST.get('teacherclass')
        contact = request.POST.get('contact', '').strip()
        academic_level = request.POST.get('academic_level', '').strip()

        valid_academic_levels = {value for value, _ in STUDENT_ACADEMIC_LEVEL_CHOICES}
        if not all([fullName, sex, indexNumber, teacherclass_id, contact, academic_level]):
            messages.error(request, "All fields are required.")
            return redirect(f"{reverse('create_student')}?class={teacherclass_id or ''}")
        if academic_level not in valid_academic_levels:
            messages.error(request, "Please select a valid academic level.")
            return redirect(f"{reverse('create_student')}?class={teacherclass_id or ''}")

        try:
            teacherclass = get_object_or_404(TeacherClass, id=teacherclass_id, user=request.effective_user)

            if Student.objects.filter(
                Q(indexNumber=indexNumber, teacherclass=teacherclass) | Q(indexNumber=indexNumber)
            ).exclude(manager=request.effective_user).exists():
                messages.error(
                    request,
                    f"A student with index number {indexNumber} already exists (managed by another user)."
                )
                return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

            username = indexNumber
            password = str(contact)
            user, user_created = User.objects.get_or_create(
                username=username,
                defaults={'is_student': True, 'is_teacher': False}
            )

            if user_created:
                user.set_password(password)
                user.save()

            if Student.objects.filter(user=user, teacherclass=teacherclass, manager=request.effective_user).exists():
                messages.error(
                    request,
                    f"A student with index number {indexNumber} already exists in this class."
                )
                return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

            student = Student.objects.create(
                user=user,
                indexNumber=indexNumber,
                fullName=fullName,
                sex=sex,
                contact=contact,
                teacherclass=teacherclass,
                manager=request.effective_user
            )
            captured_photo_data = request.POST.get('captured_photo_data')
            student_photo = request.FILES.get('photo') or build_uploaded_image_from_data_url(
                captured_photo_data,
                fullName or indexNumber,
            )
            if student_photo:
                student.photo = student_photo
                student.save(update_fields=['photo'])
                student.save_face_encoding()
                StudentPassportPhoto.objects.update_or_create(
                    student=student,
                    defaults={
                        'passport_photo': student.photo.name,
                        'captured_at': timezone.now() if captured_photo_data else None,
                    }
                )

            StudentAcademicInformation.objects.update_or_create(
                student=student,
                defaults={
                    'registration_number': student.indexNumber or '',
                    'academic_level': academic_level,
                    'academic_year': getattr(getattr(teacherclass, 'academicclassyear', None), 'academic_year_name', '') or '',
                    'class_name': getattr(getattr(teacherclass, 'ClassName', None), 'class_name', '') or '',
                    'short_course_validity_months': 3 if academic_level in SHORT_COURSE_ACADEMIC_LEVELS else None,
                }
            )

            messages.success(
                request,
                f"Student {fullName} created successfully. Username: {indexNumber}, Default Password: {contact}"
            )
            return redirect('student_information_page', student_id=student.id)

        except Exception as e:
            messages.error(request, f"An unexpected error occurred: {str(e)}")
            return redirect(f"{reverse('create_student')}?class={teacherclass_id or ''}")

    classes = TeacherClass.objects.filter(
        user=request.effective_user,
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear').order_by('ClassName__class_name')

    selected_class_id = request.GET.get('class')
    selected_class = None
    if selected_class_id:
        selected_class = get_object_or_404(
            TeacherClass.objects.select_related('ClassName', 'academicclassyear'),
            id=selected_class_id,
            user=request.effective_user,
        )
    elif classes.exists():
        selected_class = classes.first()

    query = request.GET.get('q', '').strip()
    students = Student.objects.none()
    if selected_class:
        students = Student.objects.filter(
            manager=request.effective_user,
            teacherclass=selected_class
        ).select_related('teacherclass__ClassName', 'teacherclass__academicclassyear', 'user', 'academic_information').order_by('fullName')
        if query:
            students = students.filter(Q(fullName__icontains=query) | Q(indexNumber__icontains=query) | Q(contact__icontains=query))

    class_ids = list(classes.values_list('id', flat=True))
    class_counts = {
        item['teacherclass']: item['count']
        for item in Student.objects.filter(manager=request.effective_user, teacherclass_id__in=class_ids)
        .values('teacherclass').annotate(count=Count('id'))
    }

    context = {
        'classes': classes,
        'students': students,
        'selected_class': selected_class,
        'class_counts': class_counts,
        'search_query': query,
        'created_student': request.GET.get('created_student', ''),
        'open_info': request.GET.get('open_info') == '1',
        'index_number_seed': generate_student_index_number_for_class(request.effective_user, selected_class) if selected_class else '',
    }
    return render(request, 'create_student.html', context)

from django.contrib.auth.decorators import login_required
from django.contrib import messages
from django.db import transaction
from django.shortcuts import redirect, get_object_or_404
from django.urls import reverse
from django.db.models import Q
import pandas as pd

from .models import Student, TeacherClass, User

@effective_user_decorator
@login_required
@transaction.atomic
def upload_students(request):
    if not request.effective_user.is_teacher:
        messages.error(request, "You are not authorized to perform this action.")
        return redirect('teacher_dashboard')

    if request.method == 'POST':
        teacherclass_id = request.POST.get('teacherclass')
        if not teacherclass_id:
            messages.error(request, "Please select a class before uploading.")
            return redirect('create_student')

        try:
            teacherclass = get_object_or_404(
                TeacherClass,
                id=teacherclass_id,
                user=request.effective_user,
                academicclassyear__active_year=True
            )

            file = request.FILES.get('file')
            if not file:
                messages.error(request, "No file was uploaded.")
                return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

            # File reading and validation
            file_extension = file.name.split('.')[-1].lower()
            if file_extension == 'csv':
                df = pd.read_csv(file)
            elif file_extension in ['xls', 'xlsx']:
                df = pd.read_excel(file)
            else:
                messages.error(request, "Unsupported file format. Please upload a CSV or Excel file.")
                return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

            # Ensure required columns exist
            required_columns = ['fullName', 'sex', 'indexNumber', 'contact']
            if not all(col in df.columns for col in required_columns):
                messages.error(
                    request,
                    "File must contain 'fullName', 'sex', 'indexNumber', and 'contact' columns."
                )
                return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

            for index, row in df.iterrows():
                try:
                    index_number = str(row['indexNumber']).strip()
                    full_name = str(row['fullName']).strip()
                    contact = str(row['contact']).strip()
                    sex = str(row['sex']).strip().upper()

                    if not all([index_number, full_name, contact, sex]):
                        messages.warning(request, f"Skipping row {index + 2}: Contains empty required values.")
                        continue

                    if sex not in ['M', 'F', 'O']:
                        messages.warning(request, f"Skipping row {index + 2}: Invalid sex value. Must be 'M', 'F', or 'O'.")
                        continue

                except (ValueError, TypeError) as e:
                    messages.warning(request, f"Skipping row {index + 2}: Invalid data format. Error: {e}")
                    continue

                # Check for existing student in the same teacherclass
                existing_student = Student.objects.filter(
                    indexNumber=index_number,
                    teacherclass=teacherclass,
                    manager=request.effective_user
                ).first()

                username = index_number

                # Check if indexNumber is used by another manager
                if Student.objects.filter(
                    Q(indexNumber=index_number)
                ).exclude(manager=request.effective_user).exists():
                    messages.warning(
                        request,
                        f"Skipping row {index + 2}: Student with index number {index_number} already exists (managed by another user)."
                    )
                    continue

                # Update or create the User object
                user, user_created = User.objects.get_or_create(
                    username=username,
                    defaults={'is_student': True, 'is_teacher': False}
                )

                if user_created:
                    user.set_password(contact)  # Default password = contact
                    user.save()
                elif existing_student:
                    # Update user password if student exists
                    user.set_password(contact)
                    user.save()

                if existing_student:
                    # Update existing student
                    existing_student.fullName = full_name
                    existing_student.sex = sex
                    existing_student.contact = contact
                    existing_student.save()
                    messages.success(request, f"Student '{full_name}' updated successfully.")
                else:
                    # Create new student
                    Student.objects.create(
                        user=user,
                        indexNumber=index_number,
                        fullName=full_name,
                        sex=sex,
                        contact=contact,
                        teacherclass=teacherclass,
                        manager=request.effective_user,
                    )
                    messages.success(request, f"Student '{full_name}' created successfully.")

        except Exception as e:
            messages.error(request, f"A critical error occurred while processing the file: {str(e)}")
            return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

        return redirect(f"{reverse('create_student')}?class={teacherclass_id}")

    return redirect('create_student')

@effective_user_decorator
@login_required
def export_students_excel(request, class_id):
    if not request.effective_user.is_teacher:
        messages.error(request, "You are not authorized to perform this action.")
        return redirect('teacher_dashboard')

    try:
        teacherclass = get_object_or_404(
            TeacherClass,
            id=class_id,
            user=request.effective_user,
            academicclassyear__active_year=True
        )
        students = Student.objects.filter(
            teacherclass=teacherclass,
            manager=request.effective_user
        ).select_related('user').order_by('fullName')

        if not students.exists():
            messages.warning(request, f"No students found in class '{teacherclass.ClassName}'.")
            return redirect('create_student')

        # Prepare data for Excel, matching import columns: fullName, sex, indexNumber, contact
        data = []
        for student in students:
            data.append({
                'fullName': student.fullName,
                'sex': student.sex,
                'indexNumber': student.indexNumber,
                'contact': student.contact,
            })

        df = pd.DataFrame(data)

        # Generate Excel in memory
        output = BytesIO()
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='Students', index=False)
            worksheet = writer.sheets['Students']
            for column in worksheet.columns:
                max_cell_length = max(len(str(cell.value)) for cell in column if cell.value is not None)
                col_letter_length = len(column[1].column_letter)
                max_length = max(col_letter_length, max_cell_length)
                worksheet.column_dimensions[column[1].column_letter].width = min(max_length + 2, 50)

        output.seek(0)

        # Return as HttpResponse
        response = HttpResponse(
            output.read(),
            content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
        year_str = teacherclass.academicclassyear.academic_year_name if teacherclass.academicclassyear else "noyear"
        response['Content-Disposition'] = f'attachment; filename="students_{teacherclass.ClassName.class_name}_{year_str}.xlsx"'
        return response

    except Exception as e:
        logger.error(f"Excel export error: {str(e)}")
        messages.error(request, f"Failed to export students: {str(e)}")
        return redirect('create_student')


