def _safe_source_signature_url(owner_user=None, source_doc=None):
    source_doc = source_doc or _get_usable_source_document(owner_user)
    signature_path, _, signature_field = _get_source_signature_file_info(source_doc)
    if not signature_path:
        return None
    try:
        return signature_field.url if signature_field and signature_field.name else None
    except Exception:
        return None


def _is_valid_image_path(image_path):
    if not image_path or not os.path.exists(image_path) or not os.access(image_path, os.R_OK):
        return False
    try:
        with PILImage.open(image_path) as img:
            img.verify()
        return True
    except Exception:
        return False


def _get_source_signature_file_info(source_doc):
    """
    Resolve a usable signature file from disk.
    Prefer the extracted transparent PNG, then fall back to an uploaded image.
    """
    if not source_doc:
        return None, None, None

    for field_name in ('extracted_signature', 'file_signature'):
        signature_field = getattr(source_doc, field_name, None)
        if not signature_field or not getattr(signature_field, 'name', None):
            continue
        try:
            signature_path = signature_field.path
        except Exception:
            signature_path = None
        if not _is_valid_image_path(signature_path):
            continue
        mime_type = mimetypes.guess_type(signature_path)[0] or 'image/png'
        return signature_path, mime_type, signature_field

    return None, None, None


def _get_usable_source_document(owner_user):
    """Return an allowed source document with a real signature image on disk."""
    if not owner_user:
        return None
    usable_docs = SourceDocument.objects.filter(user=owner_user, allow_to_be_used=True).order_by('-created_at')
    for doc in usable_docs:
        signature_path, _, _ = _get_source_signature_file_info(doc)
        if signature_path:
            return doc
    return None


def _build_source_signature_data_uri(owner_user=None, source_doc=None):
    """Build a print-safe data URI for the principal signature."""
    source_doc = source_doc or _get_usable_source_document(owner_user)
    signature_path, mime_type, _ = _get_source_signature_file_info(source_doc)
    if not signature_path:
        return None
    try:
        with open(signature_path, 'rb') as f:
            signature_bytes = f.read()
        if not signature_bytes:
            return None

        encoded_signature = base64.b64encode(signature_bytes).decode('ascii')
        return f"data:{mime_type};base64,{encoded_signature}"
    except Exception:
        return None


def _resolve_student_id_signature_source_document(request, student):
    """
    Resolve the most appropriate usable source document for ID signature rendering.
    Priority follows the active effective-user context first, then student manager, then
    the logged-in user to avoid mismatches between upload and render contexts.
    """
    candidate_users = [
        getattr(request, 'effective_user', None),
        getattr(student, 'manager', None),
        getattr(request, 'user', None),
    ]

    seen_user_ids = set()
    for user in candidate_users:
        if not user or user.id in seen_user_ids:
            continue
        seen_user_ids.add(user.id)
        source_doc = _get_usable_source_document(user)
        if source_doc:
            return source_doc
    return None


def _resolve_student_id_signature_assets(request, student):
    """
    Single source of truth for student-ID signature rendering in preview and print.
    """
    source_doc = _resolve_student_id_signature_source_document(request, student)
    principal_signature_data_uri = _build_source_signature_data_uri(source_doc=source_doc)
    principal_signature_url = _safe_source_signature_url(source_doc=source_doc)
    principal_signature_src = principal_signature_data_uri
    return {
        'principal_signature_url': principal_signature_url,
        'principal_signature_data_uri': principal_signature_data_uri,
        'principal_signature_src': principal_signature_src,
        'uses_url_fallback': bool(principal_signature_url and not principal_signature_data_uri),
    }


def _resolve_student_id_signature_image(request, student):
    """
    Resolve a PIL signature image for student-ID PNG output.
    Priority: request.effective_user, student.manager, request.user; within a
    source document prefer extracted_signature, then uploaded file_signature.
    """
    source_doc = _resolve_student_id_signature_source_document(request, student)
    signature_path, _, _ = _get_source_signature_file_info(source_doc)
    if not signature_path:
        return None
    return _load_image_from_path(signature_path)


def _build_student_id_qr_payload(student, registration_number, issued_date_text, expiry_text):
    """Build scanner-friendly plain-text payload for student ID QR."""
    student_class = getattr(getattr(student, 'teacherclass', None), 'ClassName', None)
    class_name = getattr(student_class, 'class_name', None) or '-'

    payload_lines = [
        "THE BRITISH SCHOOL",
        "STUDENT INFORMATION",
        f"Name: {student.fullName or '-'}",
        f"ID: {student.indexNumber or '-'}",
        f"Class: {class_name}",
        f"Academic Level: {_resolve_student_academic_level(student)}",
        f"Reg No: {registration_number or '-'}",
        f"Issued: {issued_date_text or '-'}",
        f"Expiry: {expiry_text or '-'}",
    ]
    payload_text = "\n".join(payload_lines).strip()

    # Guardrails: ensure payload remains plain card text and not an URL.
    if not payload_text or payload_text.lower().startswith(('http://', 'https://')):
        return "THE BRITISH SCHOOL\nSTUDENT INFORMATION\nName: -\nID: -\nClass: -\nAcademic Level: -\nReg No: -\nIssued: -\nExpiry: -"
    return payload_text


def _build_student_id_qr_target(request, student, registration_number, issued_date_text, expiry_text):
    """
    Build the actual student-ID QR target.

    Student ID cards must encode offline plain text only. Legacy public URL
    helpers remain available separately, but they are not QR card content.
    """
    return _build_student_id_qr_payload(
        student=student,
        registration_number=registration_number,
        issued_date_text=issued_date_text,
        expiry_text=expiry_text,
    )


def _build_student_id_qr_image_data_uri(qr_payload_text):
    """Build a high-contrast, print-safe QR image data URI from payload text."""
    if not qr_payload_text:
        return None
    if str(qr_payload_text).strip().lower().startswith(('http://', 'https://')):
        logger.warning("Refusing to generate student ID QR from URL payload.")
        return None

    try:
        qr = qrcode.QRCode(
            version=None,
            error_correction=qrcode.constants.ERROR_CORRECT_H,
            box_size=16,
            border=4,
        )
        qr.add_data(qr_payload_text)
        qr.make(fit=True)

        qr_img = qr.make_image(fill_color='black', back_color='white').convert('RGB')
        buffer = BytesIO()
        qr_img.save(buffer, format='PNG', optimize=False, compress_level=0)
        encoded = base64.b64encode(buffer.getvalue()).decode('ascii')
        return f"data:image/png;base64,{encoded}"
    except Exception as exc:
        logger.warning("Student ID QR image generation failed: %s", exc)
        return None


def _build_student_id_qr_rl_image(qr_payload_text, width, height):
    """Create a ReportLab Image for QR code generated fully server-side."""
    if not qr_payload_text:
        return None
    if str(qr_payload_text).strip().lower().startswith(('http://', 'https://')):
        logger.warning("Refusing to generate ReportLab student ID QR from URL payload.")
        return None
    try:
        qr = qrcode.QRCode(
            version=None,
            error_correction=qrcode.constants.ERROR_CORRECT_H,
            box_size=16,
            border=4,
        )
        qr.add_data(qr_payload_text)
        qr.make(fit=True)
        qr_img = qr.make_image(fill_color='black', back_color='white').convert('RGB')
        buffer = BytesIO()
        qr_img.save(buffer, format='PNG', optimize=False, compress_level=0)
        qr_bytes = buffer.getvalue()
        if not qr_bytes:
            return None
        verify_buffer = BytesIO(qr_bytes)
        PILImage.open(verify_buffer).verify()
        return RLImage(BytesIO(qr_bytes), width=width, height=height)
    except Exception as exc:
        logger.warning("Student ID ReportLab QR image generation failed: %s", exc)
        return None


def _build_rl_image_from_path(image_path, width, height):
    """Validate a filesystem image path then build an RLImage."""
    if not image_path or not os.path.exists(image_path) or not os.access(image_path, os.R_OK):
        return None
    try:
        with PILImage.open(image_path) as img:
            img.verify()
        return RLImage(image_path, width=width, height=height)
    except Exception:
        return None


def _build_rl_image_from_data_url(data_url, width, height):
    """Validate a data URL image and convert it to RLImage."""
    if not data_url or ';base64,' not in data_url:
        return None
    try:
        _, encoded = data_url.split(';base64,', 1)
        image_bytes = base64.b64decode(encoded)
        if not image_bytes:
            return None
        verify_buffer = BytesIO(image_bytes)
        PILImage.open(verify_buffer).verify()
        return RLImage(BytesIO(image_bytes), width=width, height=height)
    except Exception:
        return None


def _hex_to_rgb(color, fallback='#000000'):
    color = str(color or fallback)
    if not re.fullmatch(r'#[0-9A-Fa-f]{6}', color):
        color = fallback
    return tuple(int(color.lstrip('#')[i:i + 2], 16) for i in (0, 2, 4))


def _rgb_to_hex(rgb):
    return '#{:02x}{:02x}{:02x}'.format(*(max(0, min(255, int(v))) for v in rgb[:3]))


def _mix_color(color, target, amount):
    rgb = _hex_to_rgb(color)
    target_rgb = _hex_to_rgb(target)
    amount = max(0, min(1, float(amount)))
    return _rgb_to_hex(tuple(rgb[i] + ((target_rgb[i] - rgb[i]) * amount) for i in range(3)))


def _lighten_color(color, amount=0.2):
    return _mix_color(color, '#ffffff', amount)


def _darken_color(color, amount=0.2):
    return _mix_color(color, '#000000', amount)


def _readable_text_color(background_color):
    r, g, b = _hex_to_rgb(background_color, '#ffffff')
    luminance = ((r * 299) + (g * 587) + (b * 114)) / 1000
    return '#111111' if luminance >= 150 else '#ffffff'


def _is_dark_color(color):
    r, g, b = _hex_to_rgb(color)
    return (((r * 299) + (g * 587) + (b * 114)) / 1000) < 150


def _student_id_solid_panel_color(background_color, text_color):
    text_is_dark = _is_dark_color(text_color)
    if (_readable_text_color(background_color) == '#111111') == text_is_dark:
        r, g, b = _hex_to_rgb(background_color)
        if text_is_dark:
            return _darken_color(background_color, 0.06) if min(r, g, b) > 238 else _lighten_color(background_color, 0.34)
        return _darken_color(background_color, 0.18)
    return _lighten_color(background_color, 0.64) if text_is_dark else _darken_color(background_color, 0.24)


