def _default_student_id_appearance_for_level(academic_level):
    academic_level = academic_level if academic_level in STUDENT_ID_APPEARANCE_DEFAULTS else 'FTNA'
    defaults = STUDENT_ID_APPEARANCE_DEFAULTS[academic_level].copy()
    defaults['academic_level'] = academic_level
    return defaults


def _resolve_student_academic_level(student):
    academic_info = getattr(student, 'academic_information', None)
    academic_level = getattr(academic_info, 'academic_level', '') or ''
    return academic_level if academic_level in STUDENT_ID_APPEARANCE_DEFAULTS else 'FTNA'


def _ensure_default_student_id_appearance_settings(user):
    if not user or not getattr(user, 'is_authenticated', False):
        return []
    settings_list = []
    for academic_level, _ in STUDENT_ACADEMIC_LEVEL_CHOICES:
        defaults = _default_student_id_appearance_for_level(academic_level)
        setting, created = StudentIDAppearanceSetting.objects.get_or_create(
            user=user,
            academic_level=academic_level,
            defaults=defaults,
        )
        if created:
            settings_list.append(setting)
            continue
        changed = False
        for field, value in defaults.items():
            if field == 'academic_level':
                continue
            if field == 'front_text_color':
                value = '#111111'
                if getattr(setting, field, None) != value:
                    setattr(setting, field, value)
                    changed = True
                continue
            if getattr(setting, field, None) in [None, '']:
                setattr(setting, field, value)
                changed = True
        if changed:
            setting.save()
        settings_list.append(setting)
    return settings_list


def _student_id_appearance_to_dict(setting=None, academic_level=None):
    fallback = _default_student_id_appearance_for_level(academic_level or getattr(setting, 'academic_level', None))
    if not setting:
        return fallback
    data = fallback.copy()
    for field in [
        'academic_level', 'group', 'use_badge', 'badge_text',
        'front_header_color', 'front_body_color', 'front_accent_color', 'front_text_color',
        'back_header_color', 'back_body_color', 'back_accent_color', 'back_text_color',
    ]:
        value = getattr(setting, field, None)
        if value not in [None, '']:
            data[field] = value
    data['front_text_color'] = '#111111'
    data['use_badge'] = bool(getattr(setting, 'use_badge', data.get('use_badge')))
    return data


def _get_student_id_appearance_setting(request, student):
    user = getattr(request, 'effective_user', None) or getattr(student, 'manager', None) or getattr(request, 'user', None)
    academic_level = _resolve_student_academic_level(student)
    if user and getattr(user, 'is_authenticated', False):
        _ensure_default_student_id_appearance_settings(user)
        setting = StudentIDAppearanceSetting.objects.filter(user=user, academic_level=academic_level).first()
        return _student_id_appearance_to_dict(setting, academic_level)
    return _student_id_appearance_to_dict(None, academic_level)


def _student_id_owner_user(request, student=None):
    for user in [
        getattr(request, 'effective_user', None),
        getattr(student, 'manager', None) if student is not None else None,
        getattr(request, 'user', None),
    ]:
        if user and getattr(user, 'is_authenticated', False):
            return user
    return None


def _get_student_id_global_setting(user):
    if not user or not getattr(user, 'is_authenticated', False):
        return None
    setting, _ = StudentIDGlobalSetting.objects.get_or_create(user=user)
    return setting


def _student_id_settings_field_key(academic_level):
    return slugify(academic_level or '') or 'level'


def _student_id_decimal_setting(setting, field):
    value = getattr(setting, field, None) if setting else None
    if value in [None, '']:
        value = STUDENT_ID_GLOBAL_DEFAULTS[field]
    try:
        return float(value)
    except (TypeError, ValueError):
        return float(STUDENT_ID_GLOBAL_DEFAULTS[field])


def _student_id_optional_decimal_setting(setting, field):
    value = getattr(setting, field, None) if setting else None
    if value in [None, '']:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _student_id_logo_data_uri(setting):
    if not setting or not getattr(setting, 'logo', None):
        return ''
    try:
        logo_path = setting.logo.path
    except Exception:
        return ''
    if not logo_path or not os.path.exists(logo_path) or not os.access(logo_path, os.R_OK):
        return ''
    try:
        content_type = mimetypes.guess_type(logo_path)[0] or 'image/png'
        with open(logo_path, 'rb') as logo_file:
            encoded = base64.b64encode(logo_file.read()).decode('ascii')
        return f"data:{content_type};base64,{encoded}"
    except Exception:
        return ''


def _student_id_global_bool_setting(setting, field):
    value = getattr(setting, field, None) if setting else None
    if value is None:
        return bool(STUDENT_ID_GLOBAL_DEFAULTS[field])
    return bool(value)


def _student_id_global_settings_to_dict(setting=None, request=None, apply_layout_scopes=True):
    logo_url = ''
    logo_path = ''
    logo_data_uri = _student_id_logo_data_uri(setting)
    if setting and getattr(setting, 'logo', None):
        try:
            logo_url = setting.logo.url
            if request:
                logo_url = request.build_absolute_uri(logo_url)
        except Exception:
            logo_url = ''
        try:
            logo_path = setting.logo.path
        except Exception:
            logo_path = ''

    def _resolve_oriented(base_field, horizontal_field, vertical_field):
        explicit_base = _student_id_optional_decimal_setting(setting, base_field)
        base_value = explicit_base if explicit_base is not None else STUDENT_ID_GLOBAL_DEFAULTS[base_field]
        explicit_horizontal = _student_id_optional_decimal_setting(setting, horizontal_field)
        explicit_vertical = _student_id_optional_decimal_setting(setting, vertical_field)
        horizontal_value = explicit_horizontal if explicit_horizontal is not None else base_value
        vertical_value = explicit_vertical if explicit_vertical is not None else (
            base_value if explicit_base is not None else STUDENT_ID_GLOBAL_DEFAULTS[vertical_field]
        )
        return base_value, horizontal_value, vertical_value

    logo_size, horizontal_logo_size, vertical_logo_size = _resolve_oriented('logo_size', 'horizontal_logo_size', 'vertical_logo_size')
    header_size, horizontal_header_size, vertical_header_size = _resolve_oriented('header_size', 'horizontal_header_size', 'vertical_header_size')
    title_size, horizontal_title_size, vertical_title_size = _resolve_oriented('title_size', 'horizontal_title_size', 'vertical_title_size')
    subtitle_size, horizontal_subtitle_size, vertical_subtitle_size = _resolve_oriented('subtitle_size', 'horizontal_subtitle_size', 'vertical_subtitle_size')
    title_x_percent, horizontal_title_x_percent, vertical_title_x_percent = _resolve_oriented('title_x_percent', 'horizontal_title_x_percent', 'vertical_title_x_percent')
    title_y_percent, horizontal_title_y_percent, vertical_title_y_percent = _resolve_oriented('title_y_percent', 'horizontal_title_y_percent', 'vertical_title_y_percent')
    subtitle_x_percent, horizontal_subtitle_x_percent, vertical_subtitle_x_percent = _resolve_oriented('subtitle_x_percent', 'horizontal_subtitle_x_percent', 'vertical_subtitle_x_percent')
    subtitle_y_percent, horizontal_subtitle_y_percent, vertical_subtitle_y_percent = _resolve_oriented('subtitle_y_percent', 'horizontal_subtitle_y_percent', 'vertical_subtitle_y_percent')
    apply_layout_adjustments_horizontal = _student_id_global_bool_setting(setting, 'apply_layout_adjustments_horizontal')
    apply_layout_adjustments_vertical = _student_id_global_bool_setting(setting, 'apply_layout_adjustments_vertical')

    if apply_layout_scopes:
        if not apply_layout_adjustments_horizontal:
            horizontal_header_size = STUDENT_ID_GLOBAL_DEFAULTS['horizontal_header_size']
            horizontal_title_x_percent = STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_x_percent']
            horizontal_title_y_percent = STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_y_percent']
            horizontal_subtitle_x_percent = STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_x_percent']
            horizontal_subtitle_y_percent = STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_y_percent']
        if not apply_layout_adjustments_vertical:
            vertical_header_size = STUDENT_ID_GLOBAL_DEFAULTS['vertical_header_size']
            vertical_title_x_percent = STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_x_percent']
            vertical_title_y_percent = STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_y_percent']
            vertical_subtitle_x_percent = STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_x_percent']
            vertical_subtitle_y_percent = STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_y_percent']

    return {
        'logo_url': logo_url,
        'logo_data_uri': logo_data_uri,
        'logo_src': logo_data_uri or logo_url,
        'logo_path': logo_path,
        'logo_size': logo_size,
        'horizontal_logo_size': horizontal_logo_size,
        'vertical_logo_size': vertical_logo_size,
        'header_size': header_size,
        'horizontal_header_size': horizontal_header_size,
        'vertical_header_size': vertical_header_size,
        'title_size': title_size,
        'horizontal_title_size': horizontal_title_size,
        'vertical_title_size': vertical_title_size,
        'subtitle_size': subtitle_size,
        'horizontal_subtitle_size': horizontal_subtitle_size,
        'vertical_subtitle_size': vertical_subtitle_size,
        'title_x_percent': title_x_percent,
        'title_y_percent': title_y_percent,
        'horizontal_title_x_percent': horizontal_title_x_percent,
        'horizontal_title_y_percent': horizontal_title_y_percent,
        'vertical_title_x_percent': vertical_title_x_percent,
        'vertical_title_y_percent': vertical_title_y_percent,
        'subtitle_x_percent': subtitle_x_percent,
        'subtitle_y_percent': subtitle_y_percent,
        'horizontal_subtitle_x_percent': horizontal_subtitle_x_percent,
        'horizontal_subtitle_y_percent': horizontal_subtitle_y_percent,
        'vertical_subtitle_x_percent': vertical_subtitle_x_percent,
        'vertical_subtitle_y_percent': vertical_subtitle_y_percent,
        'apply_layout_adjustments_horizontal': apply_layout_adjustments_horizontal,
        'apply_layout_adjustments_vertical': apply_layout_adjustments_vertical,
    }


def _resolve_student_id_logo_src(request, global_settings):
    if request:
        logo_data = request.GET.get('logoData', '')
        if logo_data and _load_image_from_data_url(logo_data):
            return logo_data
    if global_settings and global_settings.get('logo_data_uri'):
        return global_settings['logo_data_uri']
    if global_settings and global_settings.get('logo_url'):
        return global_settings['logo_url']
    static_url = settings.STATIC_URL.rstrip('/') + '/BRITISH_LOGO.png'
    return request.build_absolute_uri(static_url) if request else static_url


def _resolve_student_id_logo_image(request, id_settings, student=None):
    logo_img = _load_image_from_data_url(id_settings.get('logo_data'))
    if logo_img:
        return logo_img
    logo_path = id_settings.get('global_logo_path')
    logo_img = _load_image_from_path(logo_path)
    if logo_img:
        return logo_img
    return _load_image_from_path(finders.find('BRITISH_LOGO.png'))


def _rgba_from_hex(color, alpha):
    r, g, b = _hex_to_rgb(color)
    return (r, g, b, max(0, min(255, int(round(alpha * 255)))))


def _derive_student_id_palette(settings):
    horizontal_primary = settings['horizontal_front_primary_color']
    horizontal_back_top = settings['horizontal_back_top_color']
    vertical_front_top = settings['vertical_front_top_color']
    vertical_back_top = settings['vertical_back_top_color']
    vertical_back_bottom = settings['vertical_back_bottom_color']
    front_text = '#111111'
    front_accent = settings.get('horizontal_front_accent_color') or horizontal_primary

    return {
        'horizontal_front_body_end_color': horizontal_primary,
        'horizontal_front_border_color': front_accent,
        'horizontal_front_inner_border_color': _lighten_color(front_accent, 0.70),
        'horizontal_front_panel_color': _student_id_solid_panel_color(horizontal_primary, front_text),
        'horizontal_back_top_end_color': _lighten_color(horizontal_back_top, 0.14),
        'horizontal_back_inner_border_color': _lighten_color(settings['horizontal_back_accent_color'], 0.52),
        'vertical_front_top_end_color': _darken_color(vertical_front_top, 0.08),
        'vertical_front_subtitle_color': '#111111',
        'vertical_back_top_end_color': _lighten_color(vertical_back_top, 0.14),
        'vertical_back_accent_color': _darken_color(vertical_back_top, 0.2),
        'vertical_back_inner_border_color': _lighten_color(vertical_back_top, 0.55),
        'vertical_back_text_color': '#111111',
    }


def _parse_student_id_settings_from_request(request, appearance_defaults=None, global_settings=None):
    appearance_defaults = appearance_defaults or _default_student_id_appearance_for_level('FTNA')
    if global_settings is None:
        global_settings = _student_id_global_settings_to_dict(
            _get_student_id_global_setting(_student_id_owner_user(request)),
            request=request,
        )

    def _safe_float(name, default, minimum=None, maximum=None):
        raw = request.GET.get(name)
        try:
            value = float(raw) if raw is not None else float(default)
        except (TypeError, ValueError):
            value = float(default)
        if minimum is not None:
            value = max(minimum, value)
        if maximum is not None:
            value = min(maximum, value)
        return value

    def _safe_color(name, default):
        color = request.GET.get(name, default)
        return color if re.fullmatch(r'#[0-9A-Fa-f]{6}', str(color)) else default

    theme_color = _safe_color('themeColor', appearance_defaults.get('front_body_color', '#0b86d8'))
    card_design = request.GET.get('cardDesign', 'horizontal')
    if card_design not in ['horizontal', 'vertical']:
        card_design = 'horizontal'

    print_layout = request.GET.get('printLayout', 'single')
    if print_layout not in ['single', 'multiple']:
        print_layout = 'single'

    base_logo_size = (
        global_settings.get('vertical_logo_size', STUDENT_ID_GLOBAL_DEFAULTS['vertical_logo_size'])
        if card_design == 'vertical'
        else global_settings.get('horizontal_logo_size', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_logo_size'])
    )
    logo_scale = _safe_float(
        'logoScale',
        base_logo_size,
        STUDENT_ID_BRANDING_SIZE_MIN,
        STUDENT_ID_BRANDING_SIZE_MAX,
    )
    apply_horizontal_adjustments = bool(global_settings.get('apply_layout_adjustments_horizontal', STUDENT_ID_GLOBAL_DEFAULTS['apply_layout_adjustments_horizontal']))
    apply_vertical_adjustments = bool(global_settings.get('apply_layout_adjustments_vertical', STUDENT_ID_GLOBAL_DEFAULTS['apply_layout_adjustments_vertical']))

    def _scoped_safe_float(enabled, name, default, fallback, minimum=None, maximum=None):
        if not enabled:
            return float(fallback)
        return _safe_float(name, default, minimum, maximum)

    parsed_settings = {
        'scale': _safe_float('scale', 1, 0.85, 1.2),
        'photo_x_mm': _safe_float('photoX', 0, -20, 20) * 0.264583,
        'photo_y_mm': _safe_float('photoY', 0, -20, 20) * 0.264583,
        'photo_scale': _safe_float('photoScale', 1, 0.8, 1.4),
        'logo_x_mm': _safe_float('logoX', 0, -20, 20) * 0.264583,
        'logo_y_mm': _safe_float('logoY', 0, -20, 20) * 0.264583,
        'logo_scale': logo_scale,
        'content_x_mm': _safe_float('contentX', 0, -20, 20) * 0.264583,
        'content_y_mm': _safe_float('contentY', 0, -20, 20) * 0.264583,
        'qr_x_mm': _safe_float('qrX', 0, -20, 20) * 0.264583,
        'qr_y_mm': _safe_float('qrY', 0, -20, 20) * 0.264583,
        'qr_scale': _safe_float('qrScale', 1, 0.8, 2.4),
        'name_size_px': int(_safe_float('nameSize', 14, 12, 18)),
        'theme_color': theme_color,
        'photo_bg_color': _safe_color('photoBgColor', '#000000'),
        'vertical_front_top_color': _safe_color('verticalFrontTopColor', appearance_defaults.get('front_header_color', '#111418')),
        'vertical_front_bottom_color': _safe_color('verticalFrontBottomColor', appearance_defaults.get('front_body_color', '#ffffff')),
        'vertical_front_accent_color': _safe_color('verticalFrontAccentColor', appearance_defaults.get('front_accent_color', '#1469c8')),
        'vertical_back_top_color': _safe_color('verticalBackTopColor', appearance_defaults.get('back_header_color', '#0a5c9f')),
        'vertical_back_bottom_color': _safe_color('verticalBackBottomColor', appearance_defaults.get('back_body_color', '#ffffff')),
        'horizontal_front_primary_color': _safe_color('horizontalFrontPrimaryColor', theme_color),
        'horizontal_front_header_color': _safe_color('horizontalFrontHeaderColor', appearance_defaults.get('front_header_color', '#ffffff')),
        'horizontal_front_accent_color': _safe_color('horizontalFrontAccentColor', appearance_defaults.get('front_accent_color', theme_color)),
        'horizontal_front_text_color': '#111111',
        'horizontal_back_top_color': _safe_color('horizontalBackTopColor', appearance_defaults.get('back_header_color', '#0a5c9f')),
        'horizontal_back_bottom_color': _safe_color('horizontalBackBottomColor', appearance_defaults.get('back_body_color', '#ffffff')),
        'horizontal_back_accent_color': _safe_color('horizontalBackAccentColor', appearance_defaults.get('back_accent_color', '#113765')),
        'horizontal_back_text_color': _safe_color('horizontalBackTextColor', appearance_defaults.get('back_text_color', '#111111')),
        'academic_level': appearance_defaults.get('academic_level', 'FTNA'),
        'group': appearance_defaults.get('group', 'O_LEVEL'),
        'use_badge': str(request.GET.get('useBadge', appearance_defaults.get('use_badge', False))).lower() in ['1', 'true', 'yes', 'on'],
        'badge_text': (request.GET.get('badgeText') or appearance_defaults.get('badge_text') or appearance_defaults.get('academic_level') or '').strip()[:50],
        'card_design': card_design,
        'print_layout': print_layout,
        'logo_data': request.GET.get('logoData', ''),
        'global_logo_url': global_settings.get('logo_url', ''),
        'global_logo_path': global_settings.get('logo_path', ''),
        'horizontal_logo_size': global_settings.get('horizontal_logo_size', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_logo_size']),
        'vertical_logo_size': global_settings.get('vertical_logo_size', STUDENT_ID_GLOBAL_DEFAULTS['vertical_logo_size']),
        'apply_layout_adjustments_horizontal': apply_horizontal_adjustments,
        'apply_layout_adjustments_vertical': apply_vertical_adjustments,
        'horizontal_header_size': _scoped_safe_float(apply_horizontal_adjustments, 'horizontalHeaderSize', global_settings.get('horizontal_header_size', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_header_size']), STUDENT_ID_GLOBAL_DEFAULTS['horizontal_header_size'], STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX),
        'vertical_header_size': _scoped_safe_float(apply_vertical_adjustments, 'verticalHeaderSize', global_settings.get('vertical_header_size', STUDENT_ID_GLOBAL_DEFAULTS['vertical_header_size']), STUDENT_ID_GLOBAL_DEFAULTS['vertical_header_size'], STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX),
        'horizontal_title_size': _safe_float('horizontalTitleSize', global_settings.get('horizontal_title_size', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_size']), STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX),
        'vertical_title_size': _safe_float('verticalTitleSize', global_settings.get('vertical_title_size', STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_size']), STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX),
        'horizontal_subtitle_size': _safe_float('horizontalSubtitleSize', global_settings.get('horizontal_subtitle_size', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_size']), STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX),
        'vertical_subtitle_size': _safe_float('verticalSubtitleSize', global_settings.get('vertical_subtitle_size', STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_size']), STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX),
        'horizontal_title_x_percent': _scoped_safe_float(apply_horizontal_adjustments, 'horizontalTitleXPercent', global_settings.get('horizontal_title_x_percent', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_x_percent']), STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_x_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'horizontal_title_y_percent': _scoped_safe_float(apply_horizontal_adjustments, 'horizontalTitleYPercent', global_settings.get('horizontal_title_y_percent', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_y_percent']), STUDENT_ID_GLOBAL_DEFAULTS['horizontal_title_y_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'vertical_title_x_percent': _scoped_safe_float(apply_vertical_adjustments, 'verticalTitleXPercent', global_settings.get('vertical_title_x_percent', STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_x_percent']), STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_x_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'vertical_title_y_percent': _scoped_safe_float(apply_vertical_adjustments, 'verticalTitleYPercent', global_settings.get('vertical_title_y_percent', STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_y_percent']), STUDENT_ID_GLOBAL_DEFAULTS['vertical_title_y_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'horizontal_subtitle_x_percent': _scoped_safe_float(apply_horizontal_adjustments, 'horizontalSubtitleXPercent', global_settings.get('horizontal_subtitle_x_percent', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_x_percent']), STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_x_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'horizontal_subtitle_y_percent': _scoped_safe_float(apply_horizontal_adjustments, 'horizontalSubtitleYPercent', global_settings.get('horizontal_subtitle_y_percent', STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_y_percent']), STUDENT_ID_GLOBAL_DEFAULTS['horizontal_subtitle_y_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'vertical_subtitle_x_percent': _scoped_safe_float(apply_vertical_adjustments, 'verticalSubtitleXPercent', global_settings.get('vertical_subtitle_x_percent', STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_x_percent']), STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_x_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
        'vertical_subtitle_y_percent': _scoped_safe_float(apply_vertical_adjustments, 'verticalSubtitleYPercent', global_settings.get('vertical_subtitle_y_percent', STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_y_percent']), STUDENT_ID_GLOBAL_DEFAULTS['vertical_subtitle_y_percent'], STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX),
    }
    parsed_settings.update(_derive_student_id_palette(parsed_settings))
    return parsed_settings


