def _build_public_result_token(student):
    payload = {
        'sid': student.id,
        'mid': student.manager_id,
        'idx': student.indexNumber or '',
    }
    return signing.dumps(payload, salt=PUBLIC_QR_SALT)


def _resolve_public_qr_base_url(request):
    configured = getattr(settings, 'PUBLIC_ACADEMIC_BASE_URL', '').strip()
    if configured:
        return configured.rstrip('/')
    return "https://academics.britishschool.ac.tz"


def _resolve_student_id_qr_base_url(request):
    configured = getattr(settings, 'STUDENT_ID_QR_BASE_URL', '').strip()
    if configured:
        return configured.rstrip('/')
    return "https://sims.britishschool.ac.tz"


def _student_public_result_link(request, student):
    token = _build_public_result_token(student)
    path = reverse('public_student_qr_result') + '?' + urlencode({'token': token})
    return f"{_resolve_public_qr_base_url(request)}{path}"


def _student_id_qr_link(request, student):
    token = _build_public_result_token(student)
    path = reverse('public_student_id_details', kwargs={'token': token})
    return f"{_resolve_student_id_qr_base_url(request)}{path}"


SHORT_COURSE_ACADEMIC_LEVELS = {'English course', 'Computer course'}
SHORT_COURSE_VALIDITY_CHOICES = (3, 6, 12)


def _add_months(base_date, months):
    month_index = (base_date.month - 1) + int(months)
    year = base_date.year + (month_index // 12)
    month = (month_index % 12) + 1
    day = min(base_date.day, calendar.monthrange(year, month)[1])
    return base_date.replace(year=year, month=month, day=day)


def _parse_academic_year_expiry(academic_year):
    years = [int(value) for value in re.findall(r'\d{4}', academic_year or '')]
    if not years:
        return None
    expiry_year = max(years)
    return datetime(expiry_year, 12, 31).date()


def _student_academic_info(student):
    try:
        return getattr(student, 'academic_information', None)
    except (ObjectDoesNotExist, AttributeError):
        return None


def _safe_student_lookup_from_public_token(payload):
    student = Student.objects.filter(
        id=payload.get('sid'),
        manager_id=payload.get('mid'),
    ).select_related('teacherclass__ClassName', 'academic_information').first()
    if student:
        return student

    index_number = (payload.get('idx') or '').strip()
    manager_id = payload.get('mid')
    if not index_number or not manager_id:
        return None

    return Student.objects.filter(
        indexNumber=index_number,
        manager_id=manager_id,
    ).select_related('teacherclass__ClassName', 'academic_information').first()


def _resolve_student_issued_expiry_dates(student):
    today = timezone.localdate()
    issued_date = today
    academic_info = None
    try:
        academic_info = _student_academic_info(student)
        if academic_info and academic_info.created_at:
            issued_date = timezone.localtime(academic_info.created_at).date()
    except Exception:
        issued_date = today

    academic_level = getattr(academic_info, 'academic_level', '') if academic_info else ''
    if academic_level in SHORT_COURSE_ACADEMIC_LEVELS:
        validity_months = getattr(academic_info, 'short_course_validity_months', None) or 3
        if validity_months not in SHORT_COURSE_VALIDITY_CHOICES:
            validity_months = 3
        expiry_date = _add_months(issued_date, validity_months)
        return issued_date, expiry_date

    expiry_date = _parse_academic_year_expiry(getattr(academic_info, 'academic_year', '') if academic_info else '')
    if not expiry_date or expiry_date < issued_date:
        expiry_date = _add_months(issued_date, 12)
    return issued_date, expiry_date


def _resolve_student_registration_number(student):
    academic_info = _student_academic_info(student)
    registration_number = getattr(academic_info, 'registration_number', None)
    return registration_number or student.indexNumber or '-'


def _resolve_student_id_signature_rl_image(request, student, width, height):
    """
    Resolve principal signature for student-ID PDF using robust on-disk checks.
    Mirrors download_pdf style checks: allow_to_be_used, path exists, readable, PIL-verified.
    """
    source_doc = _resolve_student_id_signature_source_document(request, student)
    if not source_doc:
        return None
    signature_path, _, _ = _get_source_signature_file_info(source_doc)
    if not signature_path or not os.path.exists(signature_path) or not os.access(signature_path, os.R_OK):
        return None
    return _build_rl_image_from_path(signature_path, width=width, height=height)


def _student_id_resample_filter():
    return PILImage.Resampling.LANCZOS if hasattr(PILImage, 'Resampling') else PILImage.LANCZOS


def _load_image_from_path(image_path):
    if not image_path or not os.path.exists(image_path) or not os.access(image_path, os.R_OK):
        return None
    try:
        return PILImage.open(image_path).convert('RGBA')
    except Exception as exc:
        logger.warning("Student ID image path load failed (%s): %s", image_path, exc)
        return None


def _load_image_from_data_url(data_url):
    if not data_url or ';base64,' not in data_url:
        return None
    try:
        header, encoded = data_url.split(';base64,', 1)
        if not header.lower().startswith('data:image/'):
            return None
        image_bytes = base64.b64decode(encoded, validate=True)
        if not image_bytes or len(image_bytes) > 5 * 1024 * 1024:
            return None
        return PILImage.open(BytesIO(image_bytes)).convert('RGBA')
    except Exception as exc:
        logger.warning("Student ID custom logo data URL load failed: %s", exc)
        return None


def _student_id_font(size, bold=False):
    candidates = [
        '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
        '/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf' if bold else '/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf',
    ]
    for path in candidates:
        if os.path.exists(path):
            return ImageFont.truetype(path, size=size)
    return ImageFont.load_default()


def _rounded_rectangle(draw, box, radius, fill, outline=None, width=1):
    draw.rounded_rectangle(box, radius=radius, fill=fill, outline=outline, width=width)


def _draw_cover_image(canvas, image, box, radius=0, fallback_fill='#f2f6fb'):
    x, y, w, h = [int(round(v)) for v in box]
    if w <= 0 or h <= 0:
        return False
    if not image:
        ImageDraw.Draw(canvas).rounded_rectangle((x, y, x + w, y + h), radius=radius, fill=fallback_fill)
        return False

    try:
        img = image.convert('RGBA')
        src_w, src_h = img.size
        target_ratio = w / h
        src_ratio = src_w / src_h
        if src_ratio > target_ratio:
            crop_w = int(src_h * target_ratio)
            crop_h = src_h
            left = max((src_w - crop_w) // 2, 0)
            top = 0
        else:
            crop_w = src_w
            crop_h = int(src_w / target_ratio)
            left = 0
            top = max((src_h - crop_h) // 2, 0)
        img = img.crop((left, top, left + crop_w, top + crop_h)).resize((w, h), _student_id_resample_filter())
        if radius:
            mask = PILImage.new('L', (w, h), 0)
            ImageDraw.Draw(mask).rounded_rectangle((0, 0, w, h), radius=radius, fill=255)
            canvas.paste(img, (x, y), mask)
        else:
            canvas.alpha_composite(img, (x, y))
        return True
    except Exception as exc:
        logger.warning("Student ID cover image draw failed: %s", exc)
        ImageDraw.Draw(canvas).rounded_rectangle((x, y, x + w, y + h), radius=radius, fill=fallback_fill)
        return False


def _draw_centered_text(draw, xy, text, font, fill):
    x, y = xy
    bbox = draw.textbbox((0, 0), str(text), font=font)
    draw.text((x - ((bbox[2] - bbox[0]) / 2), y), str(text), font=font, fill=fill)


def _fit_text(draw, text, max_width, size, bold=False, min_size=18):
    text = str(text or '-')
    current = int(size)
    while current > min_size:
        font = _student_id_font(current, bold=bold)
        if draw.textbbox((0, 0), text, font=font)[2] <= max_width:
            return font
        current -= 1
    return _student_id_font(min_size, bold=bold)


def _make_student_id_qr_pil_image(qr_payload_text, size):
    if not qr_payload_text:
        return None
    if str(qr_payload_text).strip().lower().startswith(('http://', 'https://')):
        logger.warning("Refusing to generate PIL student ID QR from URL payload.")
        return None
    try:
        qr = qrcode.QRCode(
            version=None,
            error_correction=qrcode.constants.ERROR_CORRECT_H,
            box_size=18,
            border=4,
        )
        qr.add_data(qr_payload_text)
        qr.make(fit=True)
        qr_img = qr.make_image(fill_color='black', back_color='white').convert('RGBA')
        return qr_img.resize((int(size), int(size)), PILImage.Resampling.NEAREST if hasattr(PILImage, 'Resampling') else PILImage.NEAREST)
    except Exception as exc:
        logger.warning("Student ID PIL QR generation failed: %s", exc)
        return None


def _student_id_gradient(size, top_color, bottom_color):
    width, height = size
    image = PILImage.new('RGBA', size, top_color)
    draw = ImageDraw.Draw(image)
    top = tuple(int(top_color.lstrip('#')[i:i + 2], 16) for i in (0, 2, 4))
    bottom = tuple(int(bottom_color.lstrip('#')[i:i + 2], 16) for i in (0, 2, 4))
    for y in range(height):
        ratio = y / max(height - 1, 1)
        color = tuple(int(top[i] + (bottom[i] - top[i]) * ratio) for i in range(3)) + (255,)
        draw.line((0, y, width, y), fill=color)
    return image


def _paste_rounded_card(canvas, card, origin, radius):
    x, y = [int(round(v)) for v in origin]
    mask = PILImage.new('L', card.size, 0)
    ImageDraw.Draw(mask).rounded_rectangle((0, 0, card.size[0], card.size[1]), radius=radius, fill=255)
    canvas.paste(card, (x, y), mask)


def _draw_student_id_logo(draw, canvas, logo_img, box, initials="TBS", shape="plain", accent_color='#0a5c9f'):
    x, y, w, h = [int(round(v)) for v in box]
    is_circle = shape == "circle"
    if logo_img:
        if is_circle:
            diameter = min(w, h)
            logo_canvas = PILImage.new('RGBA', (diameter, diameter), '#ffffff')
            img = logo_img.copy().convert('RGBA')
            img.thumbnail((int(diameter * 0.82), int(diameter * 0.82)), _student_id_resample_filter())
            logo_canvas.alpha_composite(img, ((diameter - img.size[0]) // 2, (diameter - img.size[1]) // 2))
            mask = PILImage.new('L', (diameter, diameter), 0)
            ImageDraw.Draw(mask).ellipse((0, 0, diameter - 1, diameter - 1), fill=255)
            canvas.paste(logo_canvas, (x, y), mask)
            draw.ellipse((x, y, x + diameter, y + diameter), outline='#d9ecff', width=max(2, diameter // 24))
        else:
            img = logo_img.copy()
            img.thumbnail((w, h), _student_id_resample_filter())
            canvas.alpha_composite(img, (x + (w - img.size[0]) // 2, y + (h - img.size[1]) // 2))
        return
    if is_circle:
        diameter = min(w, h)
        draw.ellipse((x, y, x + diameter, y + diameter), fill='#ffffff', outline='#d9ecff', width=max(2, diameter // 24))
        box_w = box_h = diameter
    else:
        draw.ellipse((x, y, x + w, y + h), fill='#ffffff', outline=accent_color, width=max(2, w // 24))
        box_w, box_h = w, h
    font = _student_id_font(max(16, w // 4), bold=True)
    bbox = draw.textbbox((0, 0), initials, font=font)
    draw.text((x + (box_w - (bbox[2] - bbox[0])) / 2, y + (box_h - (bbox[3] - bbox[1])) / 2 - 2), initials, font=font, fill=accent_color)


def _draw_student_photo_placeholder(draw, box, initials="ST"):
    x, y, w, h = [int(round(v)) for v in box]
    draw.rounded_rectangle((x, y, x + w, y + h), radius=18, fill='#e9f1fb')
    draw.ellipse((x + w * 0.32, y + h * 0.18, x + w * 0.68, y + h * 0.48), fill='#9bb7d6')
    draw.rounded_rectangle((x + w * 0.20, y + h * 0.55, x + w * 0.80, y + h * 0.88), radius=24, fill='#9bb7d6')


def _build_student_id_png(request, student, id_settings, qr_target_text, registration_number, issued_date_text, expiry_text, side=None):
    from PIL import ImageDraw

    scale = id_settings['scale']
    design = id_settings['card_design']
    base_card_w, base_card_h = (1011, 638) if design == 'horizontal' else (638, 1011)
    card_w = int(base_card_w * scale)
    card_h = int(base_card_h * scale)
    mm_to_px = card_w / (85.6 if design == 'horizontal' else 54)
    px = lambda mm: int(round(mm * mm_to_px))
    shift = lambda mm: int(round(mm * mm_to_px))

    class_obj = getattr(getattr(student, 'teacherclass', None), 'ClassName', None)
    class_name = getattr(class_obj, 'class_name', None) or '-'
    student_name = student.fullName or 'Unnamed Student'

    logo_img = _resolve_student_id_logo_image(request, id_settings, student)

    photo_path = None
    try:
        photo_path = student.photo.path if getattr(student, 'photo', None) else None
    except Exception:
        photo_path = None
    photo_img = _load_image_from_path(photo_path)

    signature_img = _resolve_student_id_signature_image(request, student)

    qr_size = int((142 if design == 'horizontal' else 118) * id_settings['qr_scale'] * scale)
    qr_img = _make_student_id_qr_pil_image(qr_target_text, max(qr_size, 96))

    def new_card(fill='#ffffff'):
        return PILImage.new('RGBA', (card_w, card_h), fill)

    def draw_card_frame(draw, accent_color):
        draw.rounded_rectangle(
            (px(1), px(1), card_w - px(1), card_h - px(1)),
            radius=px(2.6),
            outline=accent_color,
            width=max(3, px(.42)),
        )

    def resize_qr(size):
        if not qr_img:
            return None
        resample = PILImage.Resampling.NEAREST if hasattr(PILImage, 'Resampling') else PILImage.NEAREST
        return qr_img.resize((int(size), int(size)), resample)

    def has_front_wave():
        return id_settings.get('academic_level') in STUDENT_ID_FRONT_WAVE_LEVELS

    def draw_front_wave_polygon(draw, left, top, width, height, points):
        mapped_points = [
            (int(round(left + (width * x_pct / 100))), int(round(top + (height * y_pct / 100))))
            for x_pct, y_pct in points
        ]
        draw.polygon(mapped_points, fill='#ffffff')

    def draw_centered_text_in_header(draw, x, center_y, text, font, fill):
        bbox = draw.textbbox((0, 0), str(text), font=font)
        text_h = bbox[3] - bbox[1]
        _draw_centered_text(draw, (x, center_y - (text_h / 2)), text, font, fill)

    def draw_horizontal_front_wave(draw, cx, cy):
        # Mirrors .front-wave .id-h-body::after in create_student.html.
        metrics = _student_id_horizontal_layout_metrics()
        left = cx(metrics['wave_left'])
        top = card_h - cy(metrics['wave_h'])
        width = card_w + cx(metrics['wave_extra_w'])
        height = cy(metrics['wave_h'])
        draw_front_wave_polygon(draw, left, top, width, height, metrics['wave_points'])

    def draw_vertical_front_wave(draw, cx, cy, body_y):
        # Mirrors .front-wave .vertical-bottom::after in create_student.html.
        metrics = _student_id_vertical_layout_metrics()
        left = cx(metrics['wave_left'])
        top = card_h - cy(metrics['wave_h'])
        width = card_w + cx(metrics['wave_extra_w'])
        height = cy(metrics['wave_h'])
        top = max(top, body_y)
        draw_front_wave_polygon(draw, left, top, width, height, metrics['wave_points'])

    def draw_horizontal_front():
        card = new_card()
        draw = ImageDraw.Draw(card)
        metrics = _student_id_horizontal_layout_metrics()
        ux = card_w / metrics['preview_w']
        uy = card_h / metrics['preview_h']
        cx = lambda value: int(round(value * ux))
        cy = lambda value: int(round(value * uy))
        css_shift_x = lambda mm: int(round((mm / 0.264583) * ux))
        css_shift_y = lambda mm: int(round((mm / 0.264583) * uy))

        header_h = cy(metrics['header_h'] * id_settings['horizontal_header_size'])
        body_y = header_h
        body_h = card_h - body_y
        draw.rectangle((0, 0, card_w, header_h), fill=id_settings['horizontal_front_header_color'])
        draw.rectangle((0, body_y, card_w, card_h), fill=id_settings['horizontal_front_primary_color'])
        if has_front_wave():
            draw_horizontal_front_wave(draw, cx, cy)

        logo_size = int(cx(metrics['logo_size']) * id_settings['logo_scale'])
        logo_x = cx(metrics['logo_x']) + css_shift_x(id_settings['logo_x_mm'])
        logo_y = cy(metrics['logo_y']) + css_shift_y(id_settings['logo_y_mm'])
        _draw_student_id_logo(draw, card, logo_img, (logo_x, logo_y, logo_size, logo_size), accent_color=id_settings['horizontal_front_border_color'])

        title_font = _student_id_font(max(1, int(cx(metrics['title_font']) * id_settings['horizontal_title_size'])), bold=True)
        subtitle_font = _student_id_font(max(1, int(cx(metrics['subtitle_font']) * id_settings['horizontal_subtitle_size'])))
        title_x = card_w * (id_settings['horizontal_title_x_percent'] / 100)
        title_y = header_h * (id_settings['horizontal_title_y_percent'] / 100)
        subtitle_x = card_w * (id_settings['horizontal_subtitle_x_percent'] / 100)
        subtitle_y = header_h * (id_settings['horizontal_subtitle_y_percent'] / 100)
        draw_centered_text_in_header(draw, title_x, title_y, "THE BRITISH SECONDARY SCHOOL", title_font, '#111111')
        draw_centered_text_in_header(draw, subtitle_x, subtitle_y, "STUDENT IDENTIFICATION CARD", subtitle_font, '#111111')
        if id_settings.get('use_badge') and id_settings.get('badge_text'):
            badge_text = str(id_settings['badge_text'])[:18]
            badge_font = _student_id_font(cx(metrics['badge_font']), bold=True)
            bbox = draw.textbbox((0, 0), badge_text, font=badge_font)
            badge_w = (bbox[2] - bbox[0]) + cx(metrics['badge_pad_x'] * 2)
            badge_h = cy(metrics['badge_h'])
            badge_x = card_w - badge_w - cx(metrics['badge_right'])
            badge_y = cy(metrics['badge_y'])
            draw.rounded_rectangle((badge_x, badge_y, badge_x + badge_w, badge_y + badge_h), radius=cx(metrics['badge_radius']), fill=id_settings['horizontal_front_accent_color'])
            draw.text((badge_x + cx(metrics['badge_pad_x']), badge_y + cy(4)), badge_text, font=badge_font, fill='#ffffff')

        body_pad_x = cx(metrics['body_pad_x'])
        body_pad_y = cy(metrics['body_pad_y'])
        grid_gap = cx(metrics['grid_gap'])
        photo_col_w = cx(metrics['photo_col_w'])
        qr_col_w = cx(metrics['qr_col_w'])
        photo_x = body_pad_x
        photo_y = body_y + body_pad_y
        photo_w = cx(metrics['photo_w'])
        photo_h = cy(metrics['photo_h'])
        photo_radius = cx(metrics['photo_radius'])
        photo_border = cx(metrics['photo_border'])
        draw.rounded_rectangle((photo_x - photo_border, photo_y - photo_border, photo_x + photo_w + photo_border, photo_y + photo_h + photo_border), radius=photo_radius, fill='#ffffff', outline='#dce8ff', width=max(2, photo_border))
        if photo_img:
            photo_layer = PILImage.new('RGBA', (photo_w, photo_h), (255, 255, 255, 0))
            scaled_w = max(1, int(round(photo_w * id_settings['photo_scale'])))
            scaled_h = max(1, int(round(photo_h * id_settings['photo_scale'])))
            image_x = int(round((photo_w - scaled_w) / 2)) + css_shift_x(id_settings['photo_x_mm'])
            image_y = int(round((photo_h - scaled_h) / 2)) + css_shift_y(id_settings['photo_y_mm'])
            photo_drawn = False
            try:
                img = photo_img.convert('RGBA')
                src_w, src_h = img.size
                target_ratio = scaled_w / scaled_h
                src_ratio = src_w / src_h
                if src_ratio > target_ratio:
                    crop_w = int(src_h * target_ratio)
                    crop_h = src_h
                    left = max((src_w - crop_w) // 2, 0)
                    top = 0
                else:
                    crop_w = src_w
                    crop_h = int(src_w / target_ratio)
                    left = 0
                    top = max((src_h - crop_h) // 2, 0)
                fitted = img.crop((left, top, left + crop_w, top + crop_h)).resize((scaled_w, scaled_h), _student_id_resample_filter())
                photo_layer.paste(fitted, (image_x, image_y), fitted)
                photo_drawn = True
            except Exception as exc:
                logger.warning("Student ID horizontal photo transform failed: %s", exc)
            if photo_drawn:
                photo_mask = PILImage.new('L', (photo_w, photo_h), 0)
                ImageDraw.Draw(photo_mask).rounded_rectangle((0, 0, photo_w, photo_h), radius=photo_radius, fill=255)
                card.paste(photo_layer, (photo_x, photo_y), photo_mask)
            else:
                _draw_student_photo_placeholder(draw, (photo_x, photo_y, photo_w, photo_h))
        else:
            _draw_student_photo_placeholder(draw, (photo_x, photo_y, photo_w, photo_h))

        qr_draw_size = int(cx(metrics['qr_size']) * id_settings['qr_scale'])
        qr_col_x = card_w - body_pad_x - qr_col_w
        qr_x = qr_col_x + qr_col_w - qr_draw_size + css_shift_x(id_settings['qr_x_mm'])
        qr_y = body_y + body_pad_y + css_shift_y(id_settings['qr_y_mm'])
        draw.rounded_rectangle((qr_x - cx(metrics['qr_pad']), qr_y - cy(metrics['qr_pad']), qr_x + qr_draw_size + cx(metrics['qr_pad']), qr_y + qr_draw_size + cy(metrics['qr_pad'])), radius=cx(metrics['qr_radius']), fill='#ffffff')
        resized_qr = resize_qr(qr_draw_size)
        if resized_qr:
            card.alpha_composite(resized_qr, (qr_x, qr_y))

        qr_meta_top = qr_y + qr_draw_size + cy(metrics['qr_meta_gap'])
        qr_meta_w = max(qr_draw_size, qr_col_w)
        qr_meta_center = qr_x + (qr_draw_size / 2)
        qr_label_font = _student_id_font(cx(metrics['qr_label_font']), bold=True)
        qr_label_color = '#111111'

        def draw_qr_meta(label, value, y):
            value_font = _fit_text(draw, str(value), qr_meta_w, cx(metrics['qr_value_font']), bold=True, min_size=cx(6.2))
            _draw_centered_text(draw, (qr_meta_center, y), label, qr_label_font, qr_label_color)
            _draw_centered_text(draw, (qr_meta_center, y + cy(13)), str(value), value_font, '#111111')

        draw_qr_meta("Issued", issued_date_text, qr_meta_top)
        draw_qr_meta("Expire", expiry_text, qr_meta_top + cy(metrics['qr_meta_row_gap']))

        content_x = body_pad_x + photo_col_w + grid_gap + css_shift_x(id_settings['content_x_mm'])
        content_y = body_y + body_pad_y + css_shift_y(id_settings['content_y_mm'])
        max_text_w = max(qr_col_x - grid_gap - content_x, cx(88))
        front_text_color = '#111111'
        label_color = '#111111'
        name_font = _fit_text(draw, student_name, max_text_w, int(id_settings['name_size_px'] * ux), bold=True, min_size=cx(metrics['name_min_font']))
        draw.text((content_x, content_y), student_name, font=name_font, fill=front_text_color)
        name_bbox = draw.textbbox((content_x, content_y), student_name, font=name_font)

        def draw_stacked_detail(label, value, y):
            label_font = _student_id_font(cx(metrics['detail_label_font']), bold=True)
            value_font = _fit_text(draw, str(value), max_text_w, cx(metrics['detail_value_font']), bold=True, min_size=cx(6.7))
            draw.text((content_x, y), label.upper(), font=label_font, fill=label_color)
            draw.text((content_x, y + cy(12)), str(value), font=value_font, fill=front_text_color)

        detail_top = name_bbox[3] + cy(metrics['detail_gap_after_name'])
        row_gap = cy(metrics['detail_row_gap'])
