        metrics = _student_id_vertical_layout_metrics()
        ux = card_w / metrics['preview_w']
        uy = card_h / metrics['preview_h']
        cx = lambda value: int(round(value * ux))
        cy = lambda value: int(round(value * uy))
        css_shift_x = lambda mm: int(round((mm / 0.264583) * ux))
        css_shift_y = lambda mm: int(round((mm / 0.264583) * uy))

        top_h = cy(metrics['top_h'] * id_settings['vertical_header_size'])
        body_y = top_h
        top = _student_id_gradient((card_w, top_h), id_settings['vertical_front_top_color'], id_settings['vertical_front_top_end_color'])
        card.alpha_composite(top, (0, 0))
        if has_front_wave():
            draw_vertical_front_wave(draw, cx, cy, body_y)

        logo_size = int(cx(metrics['logo_size']) * id_settings['logo_scale'])
        logo_x = cx(metrics['logo_x']) + css_shift_x(id_settings['logo_x_mm'])
        logo_y = cy(metrics['logo_y']) + css_shift_y(id_settings['logo_y_mm'])
        _draw_student_id_logo(draw, card, logo_img, (logo_x, logo_y, logo_size, logo_size), shape="circle", accent_color=id_settings['vertical_front_accent_color'])

        vertical_text_color = '#111111'
        heading_w = cx(metrics['heading_w'])
        heading_left = ((card_w - heading_w) / 2) + cx(metrics['heading_offset_x'])
        title_font = _student_id_font(max(1, int(cx(metrics['title_font']) * id_settings['vertical_title_size'])), bold=True)
        subtitle_font = _student_id_font(max(1, int(cx(metrics['subtitle_font']) * id_settings['vertical_subtitle_size'])))
        title_x = heading_left + (heading_w * id_settings['vertical_title_x_percent'] / 100)
        title_y = top_h * (id_settings['vertical_title_y_percent'] / 100)
        subtitle_x = heading_left + (heading_w * id_settings['vertical_subtitle_x_percent'] / 100)
        subtitle_y = top_h * (id_settings['vertical_subtitle_y_percent'] / 100)
        draw_centered_text_in_header(draw, title_x, title_y, "THE BRITISH SCHOOL", title_font, vertical_text_color)
        draw_centered_text_in_header(draw, subtitle_x, subtitle_y, "STUDENT IDENTIFICATION CARD", subtitle_font, vertical_text_color)
        if id_settings.get('use_badge') and id_settings.get('badge_text'):
            badge_text = str(id_settings['badge_text'])[:18]
            badge_font = _student_id_font(cx(metrics['badge_font']), bold=True)
