        inner_border = cx(metrics['photo_border'])
        inner_x = photo_x + inner_border
        inner_y = photo_y + inner_border
        inner_w = photo_box_w - (inner_border * 2)
        inner_h = photo_box_h - (inner_border * 2)
        draw.rounded_rectangle((inner_x, inner_y, inner_x + inner_w, inner_y + inner_h), radius=cx(6), fill=id_settings['photo_bg_color'])
        if photo_img:
            photo_layer = PILImage.new('RGBA', (inner_w, inner_h), (255, 255, 255, 0))
            scaled_w = max(1, int(round(inner_w * id_settings['photo_scale'])))
            scaled_h = max(1, int(round(inner_h * id_settings['photo_scale'])))
            image_x = int(round((inner_w - scaled_w) / 2)) + css_shift_x(id_settings['photo_x_mm'])
            image_y = int(round((inner_h - scaled_h) / 2)) + css_shift_y(id_settings['photo_y_mm'])
            photo_drawn = False
            try:
                img = photo_img.convert('RGBA')
                src_w, src_h = img.size
                target_ratio = scaled_w / scaled_h
                src_ratio = src_w / src_h
                if src_ratio > target_ratio:
                    crop_w = int(src_h * target_ratio)
                    crop_h = src_h
                    left = max((src_w - crop_w) // 2, 0)
                    top_crop = 0
                else:
                    crop_w = src_w
                    crop_h = int(src_w / target_ratio)
                    left = 0
                    top_crop = max((src_h - crop_h) // 2, 0)
                fitted = img.crop((left, top_crop, left + crop_w, top_crop + crop_h)).resize((scaled_w, scaled_h), _student_id_resample_filter())
                photo_layer.paste(fitted, (image_x, image_y), fitted)
                photo_drawn = True
            except Exception as exc:
                logger.warning("Student ID vertical photo transform failed: %s", exc)
            if photo_drawn:
                photo_mask = PILImage.new('L', (inner_w, inner_h), 0)
