        name_bbox = draw.textbbox((0, name_y), student_name, font=name_font)
        name_bottom = name_y + (name_bbox[3] - name_bbox[1])

        content_x = body_pad_x + css_shift_x(id_settings['content_x_mm'])
        content_y = name_bottom + cy(metrics['name_margin_bottom'] + metrics['details_gap']) + css_shift_y(id_settings['content_y_mm'])
        rows = [("ID", student.indexNumber or '-'), ("Class", class_name), ("Reg No", registration_number), ("Issued", issued_date_text), ("Expire", expiry_text)]
        curve_safe_bottom = card_h - body_bottom_pad
        if has_front_wave():
            curve_top = card_h - cy(metrics['wave_h'])
            curve_safe_bottom = max(body_y + cy(230), curve_top + cy(18))
        available_h = curve_safe_bottom - content_y
        row_gap = cy(metrics['row_wave_gap'] if has_front_wave() else metrics['row_gap'])
        row_size = cx(metrics['row_wave_font'] if has_front_wave() else metrics['row_font'])
        if available_h < row_gap * len(rows):
            row_gap = max(cy(13), int(available_h / max(len(rows), 1)))
            row_size = max(cx(7), int(row_gap * 0.62))
        min_detail_y = name_bottom + cy(8)
        max_detail_y = curve_safe_bottom - (row_gap * len(rows))
        content_y = min_detail_y if max_detail_y < min_detail_y else min(max(content_y, min_detail_y), max_detail_y)
        label_font = _student_id_font(row_size, bold=True)
        for idx, (label, value) in enumerate(rows):
            y = content_y + idx * row_gap
            value_font = _fit_text(draw, str(value), card_w - content_x - cx(metrics['value_x'] + 10), row_size, bold=False, min_size=max(cx(7), int(row_size * .72)))
            draw.text((content_x, y), label, font=label_font, fill=vertical_text_color)
            draw.text((content_x + cx(metrics['label_w']), y), ":", font=label_font, fill=vertical_text_color)
            draw.text((content_x + cx(metrics['value_x']), y), str(value), font=value_font, fill=vertical_text_color)
        draw_card_frame(draw, id_settings['vertical_front_accent_color'])
        return card

