        v_qr_x = min(max(v_qr_x, px(8)), card_w - v_qr_size - px(8))
        v_qr_y = min(max(v_qr_y, qr_zone_top), qr_zone_bottom - v_qr_size)
        draw.rounded_rectangle((v_qr_x - qr_padding, v_qr_y - qr_padding, v_qr_x + v_qr_size + qr_padding, v_qr_y + v_qr_size + qr_padding), radius=px(2), fill='#ffffff', outline=id_settings['vertical_back_inner_border_color'], width=max(2, px(.18)))
        vertical_qr_img = _make_student_id_qr_pil_image(qr_target_text, v_qr_size)
