@effective_user_decorator
@login_required
@transaction.atomic
def delete_selected_students(request):
    selected_class_id = request.POST.get('class_id') if request.method == 'POST' else request.GET.get('class')

    if request.method != 'POST':
        messages.error(request, "Invalid request method for bulk deletion.")
        return redirect(f"{reverse('create_student')}?class={selected_class_id or ''}")

    if not request.effective_user.is_teacher:
        messages.error(request, "You are not authorized to perform this action.")
        return redirect('teacher_dashboard')

    if not selected_class_id:
        messages.error(request, "Please select a class before deleting students.")
        return redirect('create_student')

    selected_class = get_object_or_404(
        TeacherClass,
        id=selected_class_id,
        user=request.effective_user,
        academicclassyear__active_year=True
    )

    student_ids = request.POST.getlist('student_ids[]') or request.POST.getlist('student_ids')
    if not student_ids:
        messages.error(request, "Please select at least one student to delete.")
        return redirect(f"{reverse('create_student')}?class={selected_class.id}")

    students_to_delete = Student.objects.filter(
        id__in=student_ids,
        manager=request.effective_user,
        teacherclass=selected_class
    )

    deleted_count, _ = students_to_delete.delete()
    if deleted_count > 0:
        messages.success(
            request,
            f"Successfully deleted {deleted_count} selected student(s) from {selected_class.ClassName.class_name}."
        )
    else:
        messages.error(request, "No matching students were found to delete.")

    return redirect(f"{reverse('create_student')}?class={selected_class.id}")



@effective_user_decorator
@login_required
@transaction.atomic
def update_student(request, id):
    # Retrieve the student managed by the current user
    student = get_object_or_404(Student, id=id, manager=request.effective_user)
    
    # Fetch all TeacherClass instances assigned to the user, ordered by ClassName
    teacher_classes = TeacherClass.objects.filter(
        user=request.effective_user
    ).select_related('ClassName', 'academicclassyear').order_by('ClassName__class_name')

    if request.method == 'POST':
        fullName = request.POST.get('fullName', '').strip()
        sex = request.POST.get('sex', '').strip().upper()
        indexNumber = request.POST.get('indexNumber', '').strip()
        teacherclass_id = request.POST.get('teacherclass')
        contact = request.POST.get('contact', '').strip()
        academic_level = request.POST.get('academic_level', '').strip()
        valid_academic_levels = {value for value, _ in STUDENT_ACADEMIC_LEVEL_CHOICES}

        # Validate inputs
        if not all([fullName, sex, indexNumber, contact, academic_level]):
            messages.error(request, "All fields are required.")
            return render(request, 'update_student.html', {'st': student, 'teacher_classes': teacher_classes, 'academic_level_choices': STUDENT_ACADEMIC_LEVEL_CHOICES})
        if academic_level not in valid_academic_levels:
            messages.error(request, "Please select a valid academic level.")
            return render(request, 'update_student.html', {'st': student, 'teacher_classes': teacher_classes, 'academic_level_choices': STUDENT_ACADEMIC_LEVEL_CHOICES})

        # Get the selected TeacherClass
        teacher_class = student.teacherclass
        if teacherclass_id:
            teacher_class = get_object_or_404(TeacherClass, id=teacherclass_id, user=request.effective_user)

        # Check if indexNumber already exists in this class or under another manager (excluding current student)
        if Student.objects.filter(
            Q(indexNumber=indexNumber, teacherclass=teacher_class) |
            Q(indexNumber=indexNumber)
        ).exclude(id=student.id).exclude(manager=request.effective_user).exists():
            messages.error(
                request,
                f'Index number "{indexNumber}" is already used by another student (possibly managed by another teacher).'
            )
            return render(request, 'update_student.html', {'st': student, 'teacher_classes': teacher_classes, 'academic_level_choices': STUDENT_ACADEMIC_LEVEL_CHOICES})

        # Check if the username is unique in User model (excluding current student)
        if student.user.username != indexNumber and User.objects.filter(username=indexNumber).exclude(id=student.user.id).exists():
            messages.error(request, f'Username "{indexNumber}" is already in use by another user.')
            return render(request, 'update_student.html', {'st': student, 'teacher_classes': teacher_classes, 'academic_level_choices': STUDENT_ACADEMIC_LEVEL_CHOICES})

        # Update student fields
        student.fullName = fullName
        student.sex = sex
        student.indexNumber = indexNumber
        student.contact = contact
        student.teacherclass = teacher_class
        student.save()

        # Update associated User
        student.user.username = indexNumber
        student.user.set_password(str(contact))
        student.user.save()

        StudentAcademicInformation.objects.update_or_create(
            student=student,
            defaults={
                'registration_number': student.indexNumber or '',
                'academic_level': academic_level,
                'academic_year': getattr(getattr(teacher_class, 'academicclassyear', None), 'academic_year_name', '') or '',
                'class_name': getattr(getattr(teacher_class, 'ClassName', None), 'class_name', '') or '',
            }
        )

        messages.success(request, f'{student.fullName} updated successfully. New password set to: {contact}')
        return redirect(f"{reverse('create_student')}?class={student.teacherclass.id}")

    return render(request, 'update_student.html', {
        'st': student,
        'teacher_classes': teacher_classes,
        'academic_level_choices': STUDENT_ACADEMIC_LEVEL_CHOICES,
    })


