from django.contrib import messages
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib.auth.decorators import login_required
from django.db import transaction
from django.http import JsonResponse
from .models import User, Teacher
import secrets
import string
from .decorators import effective_user_decorator
def generate_teacher_key():
    """Generate a random 12-character teacher_key"""
    alphabet = string.ascii_letters + string.digits
    return ''.join(secrets.choice(alphabet) for _ in range(12))
@effective_user_decorator
@login_required
@transaction.atomic
def create_teacher(request):
    if not (request.effective_user.is_superuser or request.effective_user.is_teacher):
        messages.error(request, "You don’t have permission to create users.")
        return redirect('homepage')

    if request.method == 'POST':
        username = request.POST.get('username')
        teacher_name = request.POST.get('teacherName')
        email = request.POST.get('email')
        password = request.POST.get('password')
        confirm_password = request.POST.get('confirmPassword')
        role = parse_staff_role(request.POST.get('role'))

        # Validation
        if not all([username, teacher_name, email, password, confirm_password, role]):
            messages.error(request, 'All fields are required.')
            return redirect('create_teacher')

        if password != confirm_password:
            messages.error(request, 'Passwords do not match.')
            return redirect('create_teacher')

        if User.objects.filter(username=username).exists():
            messages.error(request, f'Username "{username}" already exists.')
            return redirect('create_teacher')
        if User.objects.filter(email=email).exists():
            messages.error(request, f'Email "{email}" already exists.')
            return redirect('create_teacher')

        while True:
            teacher_key = generate_teacher_key()
            if not Teacher.objects.filter(teacher_key=teacher_key).exists():
                break

        # Create User
        new_user = User.objects.create_user(
            username=username,
            email=email,
            password=password,
            is_teacher=True,
            is_staff=role in ['accountant', 'admin'],
            is_student=False,
        )

        # Create Teacher profile
        teacher = Teacher.objects.create(
            user=new_user,
            teacherName=teacher_name,
            teacher_key=teacher_key,
            teacher_role=role,
            created_by=request.effective_user
        )

        apply_teacher_photo_from_request(teacher, request, teacher_name)

        messages.success(request, f'{teacher_name} created successfully as {role.title()}!')
        return redirect('create_teacher')

    teachers = Teacher.objects.filter(created_by=request.effective_user).select_related('user').order_by('teacherName', 'user__username')
    return render(request, 'teachers.html', {'teachers': teachers, 'role_choices': ROLE_CHOICES, 'role_badges': {key: role_badge_class(key) for key, _ in ROLE_CHOICES}})

