from django.http import JsonResponse
from django.shortcuts import get_object_or_404
from django.contrib.auth.decorators import login_required
from .models import Teacher

@login_required
def get_teacher(request, teacher_id):
    """Return JSON with the teacher data for the edit-modal."""
    teacher = get_object_or_404(Teacher, id=teacher_id)
    # Only the creator or a super-user may read the data
    if not (request.user.is_superuser or teacher.created_by == request.user):
        return JsonResponse({'success': False, 'message': 'Permission denied'}, status=403)

    data = {
        'username': teacher.user.username,
        'teacherName': teacher.teacherName or '',
        'email': teacher.user.email,
        'role': teacher.teacher_role or 'teacher',
    }
    return JsonResponse(data)


@login_required
@transaction.atomic
def update_teacher(request, teacher_id):
    """Same as the view you already posted, but always return JSON."""
    teacher = get_object_or_404(Teacher, id=teacher_id)

    if not (request.user.is_superuser or teacher.created_by == request.user):
        return JsonResponse({'success': False, 'message': 'Permission denied'}, status=403)

    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Invalid request'}, status=400)

    # ----- extract POST data -------------------------------------------------
    username      = request.POST.get('username')
    teacher_name  = request.POST.get('teacherName')
    email         = request.POST.get('email')
    password      = request.POST.get('password')
    role          = parse_staff_role(request.POST.get('role'))

    if not all([username, teacher_name, email, role]):
        return JsonResponse({'success': False, 'message': 'All fields required'})

    # ----- uniqueness checks -------------------------------------------------
    if User.objects.filter(username=username).exclude(id=teacher.user.id).exists():
        return JsonResponse({'success': False, 'message': 'Username already exists'})
    if User.objects.filter(email=email).exclude(id=teacher.user.id).exists():
        return JsonResponse({'success': False, 'message': 'Email already exists'})

    # ----- update User -------------------------------------------------------
    teacher.user.username = username
    teacher.user.email    = email
    if password:
        teacher.user.set_password(password)
    teacher.user.is_teacher = True
    teacher.user.is_staff   = role in ('accountant', 'admin')
    teacher.user.save()

    # ----- update Teacher ----------------------------------------------------
    teacher.teacherName = teacher_name
    teacher.teacher_role = role
    teacher.save()

    # ----- optional photo ----------------------------------------------------
    apply_teacher_photo_from_request(teacher, request, teacher_name)

    return JsonResponse({'success': True, 'message': 'Updated successfully'})


@login_required
def delete_teacher_ajax(request, teacher_id):
    """Simple AJAX delete – only creator or super-user."""
    teacher = get_object_or_404(Teacher, id=teacher_id)
    if not (request.user.is_superuser or teacher.created_by == request.user):
        return JsonResponse({'success': False, 'message': 'Permission denied'}, status=403)

    teacher.user.delete()          # cascades to Teacher
    return JsonResponse({'success': True, 'message': 'Deleted'})
from django.contrib.auth.decorators import login_required
from django.shortcuts import render, get_object_or_404
from django.contrib import messages
from .models import Subject, TeacherClass, Teacher


@effective_user_decorator
@login_required
def create_subject(request):
    # Ensure the user is a teacher
    if not request.effective_user.is_teacher:
        messages.error(request, "Only teachers can create subjects.")
        return redirect('homepage')

    try:
        # Get the teacher's profile
        teacher_profile = Teacher.objects.get(user=request.effective_user)
    except Teacher.DoesNotExist:
        messages.error(request, "Teacher profile not found. Please contact the administrator.")
        return redirect('homepage')

    # Get classes managed by the teacher (created_by or user)
    teacher_classes = TeacherClass.objects.filter(user=request.effective_user,academicclassyear__active_year=True)

    if request.method == 'POST':
        nameSubject = request.POST.get('nameSubject')
        teacherclass_id = request.POST.get('teacherclass')

        # Validate inputs
        if not nameSubject:
            messages.error(request, "Subject name is required.")
            return render(request, 'subjects.html', {
                'subjects': Subject.objects.filter(user=request.effective_user),
                'teacher_classes': teacher_classes
            })

        # Validate teacherclass if provided
        teacherclass = None
        if teacherclass_id:
            try:
                teacherclass = TeacherClass.objects.get(id=teacherclass_id, user=request.effective_user,academiclassyear__active_year=True)
            except TeacherClass.DoesNotExist:
                messages.error(request, "Selected class is invalid or not managed by you.")
                return render(request, 'subjects.html', {
                    'subjects': Subject.objects.filter(user=request.user),
                    'teacher_classes': teacher_classes
                })

        # Create the subject
        subject = Subject.objects.create(
            user=request.effective_user,
            nameSubject=nameSubject,
            teacherclass=teacherclass
        )
        messages.success(request, f'Subject "{nameSubject}" added successfully!')
        return render(request, 'subjects.html', {
            'subjects': Subject.objects.filter(user=request.effective_user),
            'teacher_classes': teacher_classes
        })
    else:
        # GET request: Show the form and existing subjects
        return render(request, 'subjects.html', {
            'subjects': Subject.objects.filter(user=request.effective_user),
            'teacher_classes': teacher_classes
        })


