from django.shortcuts import render, redirect
from django.http import HttpResponse
from django.contrib import messages
from django.utils import timezone

def get_hostname(request):
    """Extract and return hostname string without port."""
    return request.get_host().split(':')[0]


def get_host_object(hostname):
    """Return Host object or None if not found."""
    try:
        return Host.objects.get(host_name=hostname)
    except Host.DoesNotExist:
        return None

from django.shortcuts import render, redirect
from django.contrib import messages
from django.contrib.auth import authenticate
from django.contrib.auth import login as auth_login
from django.utils import timezone
from django.utils.http import url_has_allowed_host_and_scheme
from django.views.decorators.cache import never_cache
from django.views.decorators.csrf import csrf_protect, ensure_csrf_cookie


@never_cache
@csrf_protect
@ensure_csrf_cookie
def login_view(request):
    hostname = get_hostname(request)
    host = get_host_object(hostname)
    top = Top.objects.filter(host_required=host).first() if host else None

    MAIN_DOMAIN = 'britishschool.ac.tz'

    next_url = request.POST.get('next') or request.GET.get('next') or None

    context = {
        'top': top,
        'next': next_url or '',
    }

    # --- Main domain: show website ---
    if hostname == MAIN_DOMAIN:
        return render(request, 'index.html', context)

    # --- Subdomain: handle login ---
    if request.method == 'POST':
        username_input = request.POST.get('username')
        password_input = request.POST.get('password1')

        if not username_input or not password_input:
            messages.error(request, 'Please provide both username and password.')
            return redirect(f"{request.path}?next={next_url}" if next_url else request.path)

        user = authenticate(request, username=username_input, password=password_input)

        if user is None:
            messages.error(request, 'Invalid username or password.')
            return redirect(f"{request.path}?next={next_url}" if next_url else request.path)

        if not user.is_active:
            messages.error(request, 'This account is inactive.')
            return redirect(f"{request.path}?next={next_url}" if next_url else request.path)

        auth_login(request, user)

        if not request.session.session_key:
            request.session.save()

        user.last_login = timezone.now()
        user.save(update_fields=['last_login'])

        session_key = request.session.session_key
        if session_key:
            UserSessionAccount.objects.update_or_create(
                user=user,
                session_key=session_key,
                defaults={
                    'username': user.username,
                    'last_login': timezone.now(),
                    'is_active': True,
                }
            )

        # Safe next redirect first
        if next_url and url_has_allowed_host_and_scheme(
            url=next_url,
            allowed_hosts={request.get_host()},
            require_https=request.is_secure(),
        ):
            return redirect(next_url)

        # Role-based fallback redirect
        if user.is_student:
            student_profile = (
                Student.objects.filter(
                    user=user,
                    teacherclass__academicclassyear__active_year=True
                ).first()
                or Student.objects.filter(user=user).first()
            )

            if not student_profile:
                messages.error(request, 'Student profile not found.')
                return redirect('login_view')

            request.session['student_id'] = student_profile.id
            messages.success(request, f'Welcome Student, {student_profile.fullName or user.username}!')
            return redirect('student_profile')

        elif user.is_teacher:
            teacher_profile = Teacher.objects.get(user=user)
            full_name = teacher_profile.teacherName or user.username

            if user.is_superuser:
                return redirect('create_student')

            return redirect('teacher_dashboard')

        else:
            messages.error(request, 'Invalid user role.')
            return redirect('login_view')

    # GET request → show login page for subdomains
    response = render(request, 'login.html', context)
    response['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
    response['Pragma'] = 'no-cache'
    response['Expires'] = '0'
    return response




def user_logout(request):
    if request.user.is_authenticated:
        # Get the current user's ID
        user_id = request.user.id
        
        # Delete all sessions for this user
        active_sessions = Session.objects.filter(
            expire_date__gte=timezone.now()  # Only active (non-expired) sessions
        )
        for session in active_sessions:
            session_data = session.get_decoded()
            if str(user_id) == str(session_data.get('_auth_user_id')):
                session.delete()  # Delete the session

    # Log out the current session
    messages.success(request,'You logout to all devices, Login again')
    logout(request)
    
    # Redirect to login page
    return redirect('login_view')



# Assuming this is your teacher_validation view


def determine_grade(marks, grading_system):
    """Determine the grade based on the grading system."""
    if marks >= grading_system.grade_a:
        return 'A'
    elif marks >= grading_system.grade_b:
        return 'B'
    elif marks >= grading_system.grade_c:
        return 'C'
    elif marks >= grading_system.grade_d:
        return 'D'
    elif marks >= grading_system.grade_e:
        return 'E'
    elif marks >= grading_system.grade_s:
        return 'S'
    else:
        return 'F'

