@effective_user_decorator
@login_required
def search_result(request):
    teacher_profile = Teacher.objects.get(user=request.effective_user)
    user = request.effective_user
    creator = teacher_profile.created_by
    """
    Handles student result search, filtering marks by RequiredSubject and computing grades based on selected grading system.
    Blocks students and restricts access for accountants.
    """
    # Block students and accountants
    if hasattr(request.effective_user, 'is_student') and request.effective_user.is_student:
        logger.warning(f"Student {request.effective_user.username} attempted to access search_result")
        return render(request, 'search.html', {
            'message': 'Students are not allowed to search.'
        })
    if request.session.get('teacher_role') == 'Accountant':
        logger.warning(f"Accountant {request.effective_user.username} attempted to access search_result")
        return render(request, 'search.html', {
            'message': 'Accountants are not allowed to access this page.'
        })

    # Fetch all relevant user IDs (user and their subordinates)
    subordinate_user_ids = Teacher.objects.filter(created_by=request.effective_user if user.is_superuser else creator).values_list('user_id', flat=True)
    all_user_ids = list(subordinate_user_ids) + [request.effective_user.id]

    # Fetch classes and examinations for the user and subordinates
    class_names = TeacherClass.objects.filter(
        user_id__in=all_user_ids, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear').distinct()
    examination_names = ExaminationName.objects.filter(
        user_id__in=all_user_ids
    ).distinct()

    # Fetch grading systems for the effective user
    grades = GradingModel.objects.filter(user=request.effective_user)

    context = {
        'examination_names': examination_names,
        'class_names': class_names,
        'grades': grades,
    }

    if request.method == 'POST':
        student_name = request.POST.get('searched_student', '').strip()
        examination_id = request.POST.get('examination_id')
        class_id = request.POST.get('class_id')
        grade_id = request.POST.get('grade_id')

        # Input Validation
        if not student_name:
            context['message'] = 'Please enter a student name.'
            logger.warning(f"Empty student name in search by {request.effective_user.username}")
            return render(request, 'search.html', context)
        
        if not examination_id:
            context['message'] = 'Please select an examination.'
            logger.warning(f"No examination selected in search by {request.effective_user.username}")
            return render(request, 'search.html', context)
        
        if not class_id:
            context['message'] = 'Please select a class.'
            logger.warning(f"No class selected in search by {request.effective_user.username}")
            return render(request, 'search.html', context)

        if not grade_id:
            context['message'] = 'Please select a grading system.'
            logger.warning(f"No grading system selected in search by {request.effective_user.username}")
            return render(request, 'search.html', context)

        # Verify class and examination exist for the user
        try:
            selected_class = class_names.get(id=class_id)
            selected_exam = examination_names.get(id=examination_id)
            grading_required = get_object_or_404(GradingModel, id=grade_id, user=request.effective_user)
        except TeacherClass.DoesNotExist:
            context['message'] = 'Selected class is invalid or you do not have permission.'
            logger.error(f"Class {class_id} not found for user {request.effective_user.username}")
            return render(request, 'search.html', context)
        except ExaminationName.DoesNotExist:
            context['message'] = 'Selected examination is invalid or you do not have permission.'
            logger.error(f"Examination {examination_id} not found for user {request.effective_user.username}")
            return render(request, 'search.html', context)
        except GradingModel.DoesNotExist:
            context['message'] = 'Selected grading system is invalid or you do not have permission.'
            logger.error(f"Grading {grade_id} not found for user {request.effective_user.username}")
            return render(request, 'search.html', context)

        # Search for students in the selected class
        students = Student.objects.filter(
            teacherclass_id=class_id,
            fullName__icontains=student_name
        )
        logger.debug(f"Searching for student '{student_name}' in class {class_id}. Found {students.count()} students")

        student = students.first()

        if student:
            result_payload = _compute_student_result_context(
                request.effective_user,
                student,
                selected_class,
                selected_exam,
                grading_required,
                all_user_ids=all_user_ids,
            )
            if result_payload.get('error'):
                context['message'] = result_payload['error']
                context['student'] = student
                return render(request, 'search.html', context)

            context['student'] = student
            context['student_marks'] = result_payload['student_marks']
            context['average_marks'] = result_payload['average_marks']
            context['total_marks'] = result_payload['total_marks']
            context['overall_grade'] = result_payload['overall_grade']
            context['division'] = result_payload['division']
            context['total_points'] = result_payload['total_points']
            context['is_primary'] = result_payload['is_primary']
            context['selected_class'] = selected_class
            context['selected_exam'] = selected_exam
            context['selected_grade'] = grading_required
            context['student_position'] = result_payload['student_position']
        else:
            context['message'] = f'Student named "{student_name}" was not found in the selected class.'
            logger.info(f"No student found with name '{student_name}' in class {class_id}")

        return render(request, 'search.html', context)

    # For GET requests
    return render(request, 'search.html', context)
