from django.shortcuts import render, redirect
from django.contrib import messages
from django.contrib.auth.decorators import login_required
from .decorators import effective_user_decorator  # Assuming this exists as in the original
from .models import TeacherClassStream, TeacherClass

@effective_user_decorator
@login_required
def create_teacher_stream(request):
    if not request.effective_user.is_teacher:
        messages.error(request, "Only teachers can create streams.")
        return redirect('create_teacher_class')

    if request.method == 'POST':
        stream_name = request.POST.get('stream_name', '').strip()
        selected_class_ids = request.POST.getlist('teacherclasses')

        if not stream_name:
            messages.error(request, "Stream name is required.")
        else:
            stream = TeacherClassStream.objects.create(
                user=request.effective_user, 
                stream_name=stream_name
            )
            added_count = 0
            for class_id in selected_class_ids:
                try:
                    tc = TeacherClass.objects.get(
                        id=class_id, 
                        user=request.effective_user
                    )
                    stream.teacherclass.add(tc)
                    added_count += 1
                except TeacherClass.DoesNotExist:
                    continue
            if added_count > 0:
                messages.success(request, f'Stream "{stream_name}" created successfully with {added_count} classes assigned!')
            else:
                messages.warning(request, f'Stream "{stream_name}" created, but no valid classes assigned.')

    return redirect('create_teacher_class')

@effective_user_decorator
@login_required
def update_teacher_stream(request):
    if not request.effective_user.is_teacher:
        messages.error(request, "Only teachers can update streams.")
        return redirect('create_teacher_class')

    if request.method == 'POST':
        stream_id = request.POST.get('stream_id')
        stream_name = request.POST.get('stream_name', '').strip()
        selected_class_ids = request.POST.getlist('teacherclasses')

        if not stream_id or not stream_name:
            messages.error(request, "Stream ID and name are required.")
        else:
            try:
                stream = TeacherClassStream.objects.get(
                    id=stream_id, 
                    user=request.effective_user
                )
                stream.stream_name = stream_name
                stream.save()

                # Clear and re-add classes
                stream.teacherclass.clear()
                added_count = 0
                for class_id in selected_class_ids:
                    try:
                        tc = TeacherClass.objects.get(
                            id=class_id, 
                            user=request.effective_user
                        )
                        stream.teacherclass.add(tc)
                        added_count += 1
                    except TeacherClass.DoesNotExist:
                        continue

                if added_count > 0:
                    messages.success(request, f'Stream "{stream_name}" updated successfully with {added_count} classes assigned!')
                else:
                    messages.success(request, f'Stream "{stream_name}" updated, but no valid classes assigned.')
            except TeacherClassStream.DoesNotExist:
                messages.error(request, "Stream not found.")

    return redirect('create_teacher_class')

@effective_user_decorator
@login_required
def delete_teacher_stream(request, stream_id):
    if not request.effective_user.is_teacher:
        messages.error(request, "Only teachers can delete streams.")
        return redirect('create_teacher_class')

    try:
        stream = TeacherClassStream.objects.get(
            id=stream_id, 
            user=request.effective_user
        )
        stream_name = stream.stream_name
        stream.delete()
        messages.success(request, f'Stream "{stream_name}" deleted successfully!')
    except TeacherClassStream.DoesNotExist:
        messages.error(request, "Stream not found.")

    return redirect('create_teacher_class')


@effective_user_decorator
@login_required
def edit_class(request, id):
    if not request.effective_user.is_teacher:
        messages.error(request, "Only teachers can edit classes.")
        return redirect('homepage')

    teacher_class = get_object_or_404(
        TeacherClass.objects.select_related('ClassName', 'academicclassyear'),
        id=id,
        user=request.effective_user,
        academicclassyear__active_year=True
    )

    if request.method != 'POST':
        return redirect('create_teacher_class')

    class_name = request.POST.get('ClassName', '').strip()
    academic_year_id = request.POST.get('academicclassyear')

    if not class_name:
        messages.error(request, "Class name is required.")
        return redirect('create_teacher_class')

    academic_year = AcademicClassYear.objects.filter(
        id=academic_year_id,
        user=request.effective_user,
        active_year=True
    ).first()
    if not academic_year:
        messages.error(request, "Selected academic year is invalid, inactive, or not owned by you.")
        return redirect('create_teacher_class')

    duplicate_class_name = RegisterClass.objects.filter(
        user=request.effective_user,
        class_name__iexact=class_name
    ).exclude(id=teacher_class.ClassName_id).exists()
    if duplicate_class_name:
        messages.error(request, f'Class "{class_name}" already exists.')
        return redirect('create_teacher_class')

    duplicate_assignment = TeacherClass.objects.filter(
        user=request.effective_user,
        ClassName=teacher_class.ClassName,
        academicclassyear=academic_year
    ).exclude(id=teacher_class.id).exists()
    if duplicate_assignment:
        messages.error(request, "This class is already assigned to the selected academic year.")
        return redirect('create_teacher_class')

    with transaction.atomic():
        register_class = teacher_class.ClassName
        register_class.class_name = class_name
        register_class.save(update_fields=['class_name'])

        teacher_class.academicclassyear = academic_year
        teacher_class.save(update_fields=['academicclassyear'])

    messages.success(request, f'Class "{class_name}" updated successfully.')
    return redirect('create_teacher_class')


@effective_user_decorator
@login_required
def assign_academic_year(request):
    if not request.effective_user.is_teacher:
        messages.error(request, "Only teachers can assign academic years.")
        return redirect('homepage')

    try:
        teacher_profile = Teacher.objects.get(user=request.effective_user)
    except Teacher.DoesNotExist:
        messages.error(request, "Teacher profile not found. Please contact the administrator.")
        return redirect('homepage')

    if request.method == 'POST':
        register_class_id = request.POST.get('selected_register_class')
        academic_year_id = request.POST.get('academicclassyear')

        try:
            register_class = RegisterClass.objects.get(id=register_class_id, user=request.effective_user)
            academic_year = AcademicClassYear.objects.get(id=academic_year_id, active_year=True,user=request.effective_user)
            if TeacherClass.objects.filter(
                user=request.effective_user,
                ClassName=register_class,
                academicclassyear=academic_year
            ).exists():
                messages.error(request, f'Class "{register_class.class_name}" is already assigned to "{academic_year.academic_year_name}".')
                return redirect('create_teacher_class')
            
            # Create a new TeacherClass instance instead of updating
            teacher_class = TeacherClass.objects.create(
                user=request.effective_user,
                ClassName=register_class,
                academicclassyear=academic_year
            )
            messages.success(request, f'Academic year "{academic_year.academic_year_name}" assigned to class "{register_class.class_name}" successfully!')
        except RegisterClass.DoesNotExist:
            messages.error(request, "Selected class is invalid or not owned by you.")
        except AcademicClassYear.DoesNotExist:
            messages.error(request, "Selected academic year is invalid or not active.")
        
        return redirect('create_teacher_class')

    return render(request, 'create_teacher_class.html', _class_management_context(request.effective_user))

@login_required
def select_teacher_class(request):
    if not request.user.is_teacher:
        messages.error(request, "Only teachers can select classes.")
        return redirect('homepage')

    try:
        teacher_profile = Teacher.objects.get(user=request.user)
    except Teacher.DoesNotExist:
        messages.error(request, "Teacher profile not found. Please contact the administrator.")
        return redirect('homepage')

    active_years = AcademicClassYear.objects.filter(active_year=True,user=request.user)
    active_classes = TeacherClass.objects.filter(academicclassyear__active_year=True)

    if request.method == 'POST':
        teacher_class_id = request.POST.get('selected_teacher_class')
        try:
            selected_class = TeacherClass.objects.get(id=teacher_class_id, academicclassyear__active_year=True)
            # Store selected class in session or perform desired action
            request.session['selected_teacher_class'] = teacher_class_id
            messages.success(request, f'Class "{selected_class.ClassName.class_name}" selected successfully!')
            return redirect('create_teacher_class')  # Or redirect to appropriate view
        except TeacherClass.DoesNotExist:
            messages.error(request, "Selected class is invalid or not associated with an active academic year.")
    
    return render(request, 'create_teacher_class.html', {
        'classes': TeacherClass.objects.filter(user=request.user, academicclassyear__active_year=True),
        'active_years': active_years,
        'active_classes': active_classes
    })


