from django.shortcuts import render, redirect, get_object_or_404
from django.contrib import messages
from django.contrib.auth.decorators import login_required
from .models import Teacher, TeacherSubject, ExaminationName

@effective_user_decorator
@login_required
def select_examination_name(request, teacher_subject_id):
    # Use effective_user from decorator
    effective_user = request.effective_user

    # 1. Get the TeacherSubject assignment
    teacher_subject = get_object_or_404(
        TeacherSubject,
        id=teacher_subject_id
    )

    # 2. Determine who is allowed to access:
    #    - The assigned teacher
    #    - OR the creator of the assignment
    allowed = False
    assigned_teacher = teacher_subject.teacher
    creator = teacher_subject.user  # Who created the TeacherSubject

    if request.user == assigned_teacher.user:
        allowed = True  # The teacher himself
    elif effective_user == creator:
        allowed = True  # The creator (admin/manager)

    if not allowed:
        messages.error(request, "You do not have permission to select an examination for this subject.")
        return redirect('teacher_dashboard')

    # 3. Get examination names created by the creator
    examination_names = ExaminationName.objects.filter(user=creator).order_by('exam_name')

    if not examination_names.exists():
        messages.error(request, "No examination names available. Contact your administrator.")
        return redirect('teacher_dashboard')

    # 4. Handle form submission
    if request.method == 'POST':
        examination_name_id = request.POST.get('examination_name_id')
        if examination_name_id:
            try:
                examination_name = examination_names.get(id=examination_name_id)
                request.session['selected_examination_id'] = str(examination_name_id)
                messages.success(
                    request,
                    f"Examination '{examination_name.exam_name}' selected successfully."
                )
                return redirect('fill_marks', teacher_subject_id=teacher_subject_id)
            except ExaminationName.DoesNotExist:
                messages.error(request, "Invalid examination selected.")
        else:
            messages.error(request, "Please select an examination.")
        return redirect('select_examination_name', teacher_subject_id=teacher_subject_id)

    # 5. Render template
    context = {
        'examination_names': examination_names,
        'teacher_subject_id': teacher_subject_id,
        'teacher_subject': teacher_subject,
        'is_creator': effective_user == creator,
        'assigned_teacher': assigned_teacher,
    }
    return render(request, 'examination_selection.html', context)
