def get_level(grading):
    if grading.is_primary:
        return 'Primary'
    elif grading.is_advance:
        return 'Alevel'
    else:
        return 'Olevel'

def get_level_filter(level):
    if level == 'Primary':
        return {'is_primary': True, 'is_advance': False}
    elif level == 'Alevel':
        return {'is_primary': False, 'is_advance': True}
    else:  # Olevel
        return {'is_primary': False, 'is_advance': False}

