@login_required
def student_profile(request):
    from finance.views import _sync_online_payfee,_fetch_gateway_payments_by_token,_resolve_payment_tracking
    if not request.user.is_student:
        return redirect('login_view')

    # Get all Student profiles for the logged-in user
    student_profiles = Student.objects.filter(user=request.user).select_related(
        'teacherclass__ClassName', 'teacherclass__academicclassyear', 'manager'
    )
    if not student_profiles.exists():
        return redirect('login_view')

    manager = student_profiles.first().manager

    # Get filters
    class_ids = request.GET.getlist('class_filter')
    grading_filter = request.GET.get('grading_filter', '')
    examination_filter = request.GET.get('examination_filter', '')
    rank_by = request.GET.get('rank_by', 'class')  # 'class', 'stream', 'all'
    payment_from = request.GET.get('payment_from', '')
    payment_to = request.GET.get('payment_to', '')
    payment_from_date = None
    payment_to_date = None
    if payment_from:
        try:
            payment_from_date = datetime.strptime(payment_from, "%Y-%m-%d").date()
        except ValueError:
            payment_from_date = None
    if payment_to:
        try:
            payment_to_date = datetime.strptime(payment_to, "%Y-%m-%d").date()
        except ValueError:
            payment_to_date = None

    # All possible classes for this student - ensure all unique teacherclasses are captured
    all_classes = []
    tc_ids_all = set()
    for sp in student_profiles:
        tc = sp.teacherclass
        tc_id = tc.id
        if tc_id not in tc_ids_all:
            tc_ids_all.add(tc_id)
            all_classes.append({
                'id': tc_id,
                'class_name': tc.ClassName.class_name or 'Unnamed Class',
                'academic_year': tc.academicclassyear.academic_year_name if tc.academicclassyear else 'N/A'
            })
    unique_classes = all_classes  # Already unique by construction

    # Selected class IDs (default all)
    selected_tc_ids = set(int(cid) for cid in class_ids) if class_ids else tc_ids_all

    # Filtered students (only those in selected classes)
    filtered_students = [sp for sp in student_profiles if sp.teacherclass.id in selected_tc_ids]

    # All grading levels always available
    unique_levels = ['PRIMARY', 'O LEVEL', 'A LEVEL']

    # Unique examinations
    unique_examinations = list(ExaminationName.objects.filter(user=manager).values('id', 'exam_name'))

    # Sidebar subjects: unique across selected
    subjects_set = set()
    for student in filtered_students:
        ss = StudentSubject.objects.filter(student=student, teacherclass=student.teacherclass).first()
        if ss:
            for s in ss.subject.all():
                subjects_set.add(s.nameSubject or 'Unnamed Subject')
    subjects = [{'name': name} for name in subjects_set]

    # Academic data
    academic_data = []
    exclude_subjects_global = set(ExcludeSubject.objects.filter(user=manager).values_list('exclude_subject_id', flat=True))

    # Filter examinations
    examinations = ExaminationName.objects.filter(user=manager)
    if examination_filter:
        examinations = examinations.filter(id=examination_filter)

    # Now per student/class
    for student in filtered_students:
        tc = student.teacherclass
        # Determine class_level
        rs_level = RequiredSubject.objects.filter(teacherclass=tc, user=manager).first()
        class_level = rs_level.level if rs_level else 'O LEVEL'
        applied_level = grading_filter if grading_filter else class_level

        is_primary = applied_level == 'PRIMARY'
        is_advance = applied_level == 'A LEVEL'

        grading_kwargs = {'user': manager}
        if is_primary:
            grading_kwargs.update({'is_primary': True, 'is_advance': False})
        elif is_advance:
            grading_kwargs.update({'is_primary': False, 'is_advance': True})
        else:
            grading_kwargs.update({'is_primary': False, 'is_advance': False})

        grading_required = GradingModel.objects.filter(**grading_kwargs).first()
        if not grading_required:
            continue

        # Grade thresholds
        if is_primary:
            grade_thresholds = {
                grading_required.grade_a: 'A', grading_required.grade_b: 'B',
                grading_required.grade_c: 'C', grading_required.grade_d: 'D',
                grading_required.grade_f: 'E'
            }
            grade_points = None
            req_subs_for_div = None
        elif is_advance:
            grade_thresholds = {
                grading_required.grade_a: 'A', grading_required.grade_b: 'B',
                grading_required.grade_c: 'C', grading_required.grade_d: 'D',
                grading_required.grade_e: 'E', grading_required.grade_s: 'S',
                grading_required.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
            req_subs_for_div = 3
        else:
            grade_thresholds = {
                grading_required.grade_a: 'A', grading_required.grade_b: 'B',
                grading_required.grade_c: 'C', grading_required.grade_d: 'D',
                grading_required.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
            req_subs_for_div = 7

        division_thresholds = [
            {'max': grading_required.division_1, 'label': 'I'},
            {'max': grading_required.division_2, 'label': 'II'},
            {'max': grading_required.division_3, 'label': 'III'},
            {'max': grading_required.division_4, 'label': 'IV'},
            {'max': float('inf'), 'label': '0'}
        ]

        # Subjects for this class
        ss = StudentSubject.objects.filter(student=student, teacherclass=tc).first()
        class_subjects = ss.subject.all().order_by('nameSubject') if ss else []

        exclude_subjects = set() if is_primary else exclude_subjects_global

        class_data = {
            'id': tc.id,
            'class_name': tc.ClassName.class_name or 'Unnamed Class',
            'academic_year': tc.academicclassyear.academic_year_name if tc.academicclassyear else 'N/A',
            'level': applied_level,
            'is_primary': is_primary,
            'examinations': []
        }

        # Determine pool_tc_ids based on rank_by
        pool_tcs = [tc.id]
        has_stream = TeacherClassStream.objects.filter(teacherclass=tc).exists()
        if has_stream and rank_by != 'class':
            if rank_by == 'all':
                pool_tcs = list(TeacherClass.objects.filter(teacherclassstream__isnull=False).values_list('id', flat=True))
            else:  # stream
                stream = TeacherClassStream.objects.filter(teacherclass=tc).first()
                if stream:
                    pool_tcs = list(stream.teacherclass.values_list('id', flat=True))

        for exam in examinations:
            marks = Mark.objects.filter(
                student=student, examinationname=exam, teacherclass=tc, subject__in=class_subjects
            ).select_related('subject', 'user').prefetch_related('user__teacher_profile')

            if not marks.exists() and not class_subjects:
                continue

            exam_data = {'exam_name': exam.exam_name, 'subjects': [], 'total_marks': 0, 'average_marks': 0, 'position': '-', 'division': None, 'total_points': None}

            valid_marks = []
            grades_for_division = []
            for subject in class_subjects:
                mark_obj = marks.filter(subject=subject).first()
                if not mark_obj:
                    continue  # Skip subjects without marks
                mark_value = mark_obj.marks
                grade = '-'
                if mark_value > 0:
                    for thresh, letter in sorted(grade_thresholds.items(), reverse=True):
                        if mark_value >= thresh:
                            grade = letter
                            break
                    if grade == '-':
                        grade = 'E' if is_primary else 'F'

                teacher_profile = mark_obj.user.teacher_profile.first() if mark_obj else None
                teacher_name = teacher_profile.teacherName if teacher_profile else (mark_obj.user.username if mark_obj else 'N/A')

                exam_data['subjects'].append({
                    'name': subject.nameSubject or 'Unnamed',
                    'mark': mark_value,
                    'grade': grade,
                    'teacher': teacher_name
                })

                valid_marks.append(mark_value)
                if not is_primary and subject.id not in exclude_subjects:
                    grades_for_division.append(grade)

            if not exam_data['subjects']:
                continue  # Skip exam if no subjects with marks

            exam_data['total_marks'] = sum(valid_marks)
            exam_data['average_marks'] = round(sum(valid_marks) / len(valid_marks), 2)

            # Position across pool
            all_students_pool = Student.objects.filter(teacherclass__id__in=pool_tcs)
            student_averages = []
            for st in all_students_pool:
                st_tc = st.teacherclass
                st_ss = StudentSubject.objects.filter(student=st, teacherclass=st_tc).first()
                if st_ss and st_ss.subject.exists():
                    st_class_subs = st_ss.subject.all()
                    st_avg = Mark.objects.filter(
                        student=st, examinationname=exam, subject__in=st_class_subs, teacherclass=st_tc
                    ).aggregate(avg=Avg('marks'))['avg'] or 0
                    student_averages.append((st, st_avg))
            ranked = sorted(student_averages, key=lambda x: x[1], reverse=True)
            rank_dict = {st: idx + 1 for idx, (st, avg) in enumerate(ranked)}
            total_stu = len(ranked)
            rank = rank_dict.get(student, '-')
            exam_data['position'] = f"{rank}/{total_stu}" if rank != '-' else f"-/{total_stu}"

            # Division
            if not is_primary and grade_points and req_subs_for_div:
                filtered_grades = [g for g in grades_for_division if g != '-']
                num_valid = len(filtered_grades)
                if num_valid < req_subs_for_div:
                    exam_data['division'] = 'Inc'
                    exam_data['total_points'] = 0
                else:
                    sorted_grades = sorted(filtered_grades, key=lambda x: grade_points.get(x, 9))[:req_subs_for_div]
                    total_points = sum(grade_points.get(g, 9) for g in sorted_grades)
                    exam_data['total_points'] = total_points
                    division = '0'
                    for thresh in division_thresholds:
                        if total_points <= thresh['max']:
                            division = thresh['label']
                            break
                    exam_data['division'] = division

            class_data['examinations'].append(exam_data)

        if class_data['examinations'] or class_subjects:
            academic_data.append(class_data)

    from collections import defaultdict
    from finance.models import StudentPayment, PaymentTransaction, PaymentSegment, PaymentSegmentTransaction

    fee_assignments_for_payments = StudentFee.objects.filter(
        student__in=filtered_students,
    ).select_related("student", "fee", "teacherclass")

    ensured_payment_ids = []
    for assignment in fee_assignments_for_payments:
        if not assignment.student_id or not assignment.fee_id or not assignment.teacherclass_id:
            continue
        required_amount = assignment.amount_required or Decimal("0.00")
        payment_record, _ = StudentPayment.objects.get_or_create(
            student_id=assignment.student_id,
            fee_id=assignment.fee_id,
            teacherclass_id=assignment.teacherclass_id,
            defaults={
                "user": assignment.user or manager,
                "amount_due": required_amount,
                "status": StudentPayment.STATUS_PENDING,
            },
        )
        if payment_record.amount_due != required_amount:
            payment_record.amount_due = required_amount
            if payment_record.user_id is None:
                payment_record.user = assignment.user or manager
            payment_record.save(update_fields=["amount_due", "user", "updated_at"])
        ensured_payment_ids.append(payment_record.id)

    payment_qs = StudentPayment.objects.filter(
        id__in=ensured_payment_ids
    ).select_related("student", "fee", "teacherclass", "teacherclass__ClassName").prefetch_related("transactions")
    payment_ids = list(payment_qs.values_list("id", flat=True))
    completed_statuses = [PaymentTransaction.TX_COMPLETED, PaymentTransaction.TX_SUCCESS]
    payment_by_id = {payment.id: payment for payment in payment_qs}
    online_paid_by_key = defaultdict(Decimal)
    online_payments_for_table = []
    completed_totals_by_payment = defaultdict(Decimal)
    if payment_ids:
        online_transactions = PaymentTransaction.objects.filter(
            payment_id__in=payment_ids,
            tx_status__in=completed_statuses,
        ).select_related("payment")

        for tx in online_transactions:
            payment = payment_by_id.get(tx.payment_id)
            if not payment:
                continue
            completed_totals_by_payment[payment.id] += tx.amount
            key = (payment.student_id, payment.fee_id)
            online_paid_by_key[key] += tx.amount

            if payment_from_date and tx.created_at.date() < payment_from_date:
                continue
            if payment_to_date and tx.created_at.date() > payment_to_date:
                continue

            online_payments_for_table.append(
                {
                    "date": tx.created_at,
                    "fee_name": payment.fee.fee_name if payment.fee else "-",
                    "class_name": payment.teacherclass.ClassName.class_name if payment.teacherclass and payment.teacherclass.ClassName else "-",
                    "academic_year": payment.teacherclass.academicclassyear.academic_year_name if payment.teacherclass and payment.teacherclass.academicclassyear else "N/A",
                    "amount": tx.amount,
                    "description": "Online payment",
                    "payer_account_no": tx.bill_pay_number or tx.payment_token or "-",
                    "is_online": True,
                }
            )

        for payment in payment_qs:
            if payment.status != StudentPayment.STATUS_PAID:
                continue
            completed_total = completed_totals_by_payment.get(payment.id, Decimal("0.00"))
            if payment.amount_paid <= completed_total:
                continue
            additional_paid = payment.amount_paid - completed_total
            key = (payment.student_id, payment.fee_id)
            online_paid_by_key[key] += additional_paid

            payment_date = payment.updated_at or payment.created_at
            if payment_from_date and payment_date.date() < payment_from_date:
                continue
            if payment_to_date and payment_date.date() > payment_to_date:
                continue

            latest_billpay = payment.transactions.filter(method=PaymentTransaction.METHOD_BILLPAY).order_by("-created_at").first()
            payer_account = "-"
            if latest_billpay:
                payer_account = latest_billpay.bill_pay_number or latest_billpay.payment_token or "-"

            online_payments_for_table.append(
                {
                    "date": payment_date,
                    "fee_name": payment.fee.fee_name if payment.fee else "-",
                    "class_name": payment.teacherclass.ClassName.class_name if payment.teacherclass and payment.teacherclass.ClassName else "-",
                    "academic_year": payment.teacherclass.academicclassyear.academic_year_name if payment.teacherclass and payment.teacherclass.academicclassyear else "N/A",
                    "amount": additional_paid,
                    "description": "Online payment",
                    "payer_account_no": payer_account,
                    "is_online": True,
                }
            )
        for payment in payment_qs:
            completed_total = completed_totals_by_payment.get(payment.id, Decimal("0.00"))
            if completed_total > 0 or (payment.status == StudentPayment.STATUS_PAID and payment.amount_paid):
                _sync_online_payfee(payment, completed_total=completed_total)

    # Financial data
    financial_data = []
    total_required_all = Decimal('0.00')
    total_paid_all = Decimal('0.00')
    total_balance_all = Decimal('0.00')
    total_discount_all = Decimal('0.00')
    all_payments_data = []

    accountant_user_ids = set(
        Teacher.objects.filter(created_by=manager).values_list('user_id', flat=True)
    )
    accountant_user_ids.add(manager.id)

    for student in filtered_students:
        tc = student.teacherclass
        class_financial_data = {
            'id': tc.id,
            'class_name': tc.ClassName.class_name or 'Unnamed Class',
            'academic_year': tc.academicclassyear.academic_year_name if tc.academicclassyear else 'N/A',
            'fees': [],
            'total_required': Decimal('0.00'),
            'total_paid': Decimal('0.00'),
            'total_discount': Decimal('0.00'),
            'total_balance': Decimal('0.00')
        }

        # Fees, payments, discounts
        student_fees = StudentFee.objects.filter(student=student, teacherclass=tc).select_related('fee')
        all_payments = PayFee.objects.filter(
            student=student,
            user__in=accountant_user_ids,
            fee__in=student_fees.values('fee'),
        ).select_related('fee').order_by('-date_paid')
        if payment_from_date:
            all_payments = all_payments.filter(date_paid__date__gte=payment_from_date)
        if payment_to_date:
            all_payments = all_payments.filter(date_paid__date__lte=payment_to_date)

        for p in all_payments:
            all_payments_data.append({
                'date': p.date_paid,
                'fee_name': p.fee.fee_name,
                'class_name': tc.ClassName.class_name or 'Unnamed Class',
                'academic_year': tc.academicclassyear.academic_year_name if tc.academicclassyear else 'N/A',
                'amount': p.amount_paid,
                'description': p.description or '-',
                'payer_account_no': p.payer_account_no or '-',
                'is_online': False,
            })

        discounts = Discount.objects.filter(student=student, teacherclass=tc).select_related('fee')

        total_discount = sum(d.discount_amount for d in discounts) or Decimal('0.00')
        class_financial_data['total_discount'] = total_discount
        total_discount_all += total_discount

        for fee_assignment in student_fees:
            fee = fee_assignment.fee
            payments = all_payments.filter(fee=fee)
            manual_paid_amount = sum(p.amount_paid for p in payments) or Decimal('0.00')
            paid_amount = manual_paid_amount
            discount = next((d for d in discounts if d.fee == fee), None)
            discount_amount = discount.discount_amount if discount else Decimal('0.00')
            adjusted_amount = fee_assignment.amount_required - discount_amount

            status = 'Completed' if paid_amount >= adjusted_amount else 'Pending'

            fee_data = {
                'id': fee.id,
                'fee_name': fee.fee_name,
                'amount_required': adjusted_amount,
                'discount': discount_amount,
                'paid': paid_amount,
                'balance': adjusted_amount - paid_amount,
                'status': status
            }

            class_financial_data['fees'].append(fee_data)
            class_financial_data['total_required'] += adjusted_amount
            class_financial_data['total_paid'] += paid_amount
            class_financial_data['total_balance'] += (adjusted_amount - paid_amount)

            total_required_all += adjusted_amount
            total_paid_all += paid_amount
            total_balance_all += (adjusted_amount - paid_amount)

        financial_data.append(class_financial_data)
    all_payments_data.sort(key=lambda entry: entry["date"] or timezone.now(), reverse=True)

    # Attendance data
    attendance_data = []
    current_date = timezone.now().date()
    current_month = current_date.month
    current_year = current_date.year
    days_in_month = calendar.monthrange(current_year, current_month)[1]
    date_headers = [date(current_year, current_month, day) for day in range(1, days_in_month + 1)]

    for student in filtered_students:
        tc = student.teacherclass
        attendances = StudentAttendance.objects.filter(
            student=student, date__in=date_headers
        ).values('date', 'status')

        att_dict = {att['date']: att['status'] for att in attendances}

        class_att_data = []
        present_count = 0
        total_days = 0
        for day in date_headers:
            if day > current_date:
                status = '-'
            else:
                status = att_dict.get(day, 'absent')
                if status == 'present':
                    present_count += 1
                total_days += 1
                status = 'P' if status == 'present' else 'A'
            class_att_data.append({'date': day, 'status': status})

        absent_count = total_days - present_count
        att_rate = round((present_count / total_days * 100), 2) if total_days > 0 else 0

        class_att = {
            'id': tc.id,
            'class_name': tc.ClassName.class_name or 'Unnamed Class',
            'academic_year': tc.academicclassyear.academic_year_name if tc.academicclassyear else 'N/A',
            'month': calendar.month_name[current_month],
            'year': current_year,
            'attendance_data': class_att_data,
            'present_count': present_count,
            'absent_count': absent_count,
            'total_days': total_days,
            'attendance_rate': att_rate
        }
        attendance_data.append(class_att)

    # Student info from first profile
    first_student = student_profiles.first()

    # Chat Notifications Support
    unread_count = ChatMessage.objects.filter(receiver=request.user, is_read=False).count()

    from finance.views import _fetch_gateway_payments_by_token, _resolve_payment_tracking, _sync_online_payfee

    payment_records = []
    gateway_by_token = _fetch_gateway_payments_by_token(limit=200)
    total_paid_amount = Decimal("0.00")
    total_incomplete_amount = Decimal("0.00")
    payment_fee_ids = list(payment_qs.values_list("fee_id", flat=True))
    payment_class_ids = list(payment_qs.values_list("teacherclass_id", flat=True))
    student_fee_map = {
        (assignment.student_id, assignment.fee_id, assignment.teacherclass_id): assignment.amount_required
        for assignment in StudentFee.objects.filter(
            student__in=filtered_students,
            fee_id__in=payment_fee_ids,
            teacherclass_id__in=payment_class_ids,
        ).only("student_id", "fee_id", "teacherclass_id", "amount_required")
    }
    discount_map = {
        (discount.student_id, discount.fee_id, discount.teacherclass_id): discount.discount_amount
        for discount in Discount.objects.filter(
            student__in=filtered_students,
            fee_id__in=payment_fee_ids,
            teacherclass_id__in=payment_class_ids,
        ).only("student_id", "fee_id", "teacherclass_id", "discount_amount")
    }
    online_required_total = Decimal("0.00")
    online_paid_total = Decimal("0.00")
    online_balance_total = Decimal("0.00")
    for payment in payment_qs:
        tracking = _resolve_payment_tracking(payment, gateway_by_token)
        latest_billpay = tracking["latest_billpay"]
        total_paid_amount += payment.amount_paid
        total_incomplete_amount += max(payment.amount_due - payment.amount_paid, Decimal("0.00"))
        fee_key = (payment.student_id, payment.fee_id, payment.teacherclass_id)
        base_required = student_fee_map.get(fee_key, payment.amount_due)
        discount_amount = discount_map.get(fee_key, Decimal("0.00"))
        adjusted_required = base_required - discount_amount
        balance_amount = max(adjusted_required - payment.amount_paid, Decimal("0.00"))
        status_label = "Completed" if balance_amount <= 0 else "Pending"
        show_paid_amount = (
            payment.amount_paid
            if tracking["payment_status"] == "paid" and tracking["transaction_status"] == "completed"
            else Decimal("0.00")
        )
        online_required_total += adjusted_required
        online_paid_total += show_paid_amount
        online_balance_total += balance_amount

        payment_records.append(
            {
                "id": payment.id,
                "fee_id": payment.fee_id,
                "student_id": payment.student_id,
                "teacherclass_id": payment.teacherclass_id,
                "fee_name": payment.fee.fee_name if payment.fee else "-",
                "class_name": payment.teacherclass.ClassName.class_name if payment.teacherclass and payment.teacherclass.ClassName else "-",
                "amount_due": payment.amount_due,
                "amount_paid": payment.amount_paid,
                "amount_required": adjusted_required,
                "discount": discount_amount,
                "balance": balance_amount,
                "fee_status": status_label,
                "show_paid_amount": show_paid_amount,
                "status": tracking["payment_status"],
                "request_status": tracking["request_status"],
                "transaction_status": tracking["transaction_status"],
                "transaction_completed_at": tracking["transaction_completed_at"],
                "bill_pay_number": (latest_billpay.bill_pay_number or latest_billpay.payment_token) if latest_billpay else "",
                "payment_token": latest_billpay.payment_token if latest_billpay else "",
                "notify_student_account": payment.notify_student_account,
            }
        )
    total_paid_amount = total_paid_all
    total_incomplete_amount = max(total_required_all - total_paid_all, Decimal("0.00"))

    segment_map = {
        (segment.student_id, segment.fee_name_id, segment.teacherclass_id): segment
        for segment in PaymentSegment.objects.filter(
            student__in=filtered_students,
            fee_name_id__in=payment_fee_ids,
            teacherclass_id__in=payment_class_ids,
        ).prefetch_related("transactions")
    }

    segment_completed_statuses = [PaymentSegmentTransaction.TX_COMPLETED, PaymentSegmentTransaction.TX_SUCCESS]
    for payment_record in payment_records:
        key = (payment_record.get("student_id"), payment_record.get("fee_id"), payment_record.get("teacherclass_id"))
        segment = segment_map.get(key)
        if segment:
            segment_transactions = list(segment.transactions.filter(tx_status__in=segment_completed_statuses).order_by("-created_at"))
            completed_segment_total = sum((tx.amount for tx in segment_transactions), Decimal("0.00"))
            segment_remaining = max(segment.amount_required - completed_segment_total, Decimal("0.00"))
            payment_record["segment_total_paid"] = completed_segment_total
            payment_record["segment_remaining"] = segment_remaining
            payment_record["segment_status"] = "complete" if segment_remaining <= 0 else "pending"
            latest_segment_tx = segment_transactions[0] if segment_transactions else None
            payment_record["segment_billpay"] = latest_segment_tx.payment_token if latest_segment_tx else ""
            payment_record["segment_payment_times"] = [tx.created_at for tx in segment_transactions]
        else:
            payment_record["segment_total_paid"] = Decimal("0.00")
            payment_record["segment_remaining"] = payment_record.get("amount_required", Decimal("0.00"))
            payment_record["segment_status"] = "pending"
            payment_record["segment_billpay"] = ""
            payment_record["segment_payment_times"] = []
        payment_record["segment_receipt_url"] = reverse("student_fee_receipt_pdf", args=[payment_record.get("fee_id")])

    context = {
        'student': {
            'fullName': first_student.fullName or first_student.user.username,
            'indexNumber': first_student.indexNumber,
            'sex': first_student.sex,
            'contact': first_student.contact,
            'photo': first_student.photo
        },
        'academic': {'classes': academic_data},
        'financial': {
            'classes': financial_data,
            'total_required': total_required_all,
            'total_paid': total_paid_all,
            'total_balance': total_balance_all,
            'total_discount': total_discount_all,
            'all_payments': all_payments_data,
            'payment_summary': {
                'total_paid_amount': total_paid_amount,
                'total_incomplete_amount': total_incomplete_amount,
                'balance_amount': total_balance_all,
            },
            'payment_filters': {
                'from': payment_from,
                'to': payment_to,
            },
            'online_payment_summary': {
                'total_required': online_required_total,
                'total_paid': online_paid_total,
                'total_balance': online_balance_total,
            },
        },
        'attendance': {'classes': attendance_data},
        'display': DisplayModel.objects.filter(user=manager).first(),
        'subjects': subjects,
        'unique_levels': unique_levels,
        'unique_examinations': unique_examinations,
        'unique_classes': unique_classes,
        'class_filters': class_ids,
        'grading_filter': grading_filter,
        'examination_filter': examination_filter,
        'rank_by': rank_by,
        # Notifications
        'unread_count': unread_count,
        'online_payments': payment_records,
    }

    return render(request, 'student_profile.html', context)

@login_required
def student_fee_receipt_pdf(request, fee_id):
    if not request.user.is_student:
        return redirect('login_view')

    student_profiles = Student.objects.filter(user=request.user).select_related(
        'teacherclass__ClassName', 'teacherclass__academicclassyear', 'manager'
    )
    if not student_profiles.exists():
        return redirect('login_view')

    from finance.models import Fee, StudentPayment, PaymentTransaction, Discount, StudentFee, PayFee

    fee = get_object_or_404(Fee, id=fee_id)
    assignment = StudentFee.objects.filter(
        student__in=student_profiles, fee=fee
    ).select_related('student', 'teacherclass', 'fee').first()
    if not assignment:
        messages.error(request, "No fee assignment found for this student.")
        return redirect('student_profile')

    student = assignment.student
    teacherclass = assignment.teacherclass
    discount = Discount.objects.filter(student=student, fee=fee).first()
    discount_amount = discount.discount_amount if discount else Decimal("0.00")
    adjusted_required = assignment.amount_required - discount_amount
    total_paid = PayFee.objects.filter(student=student, fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal("0.00")
    balance = adjusted_required - total_paid

    payment_record = StudentPayment.objects.filter(student=student, fee=fee, teacherclass=teacherclass).prefetch_related("transactions").first()
    latest_billpay = (
        payment_record.transactions.filter(method=PaymentTransaction.METHOD_BILLPAY).order_by("-created_at").first()
        if payment_record
        else None
    )
    bill_pay_number = "-"
    if latest_billpay:
        bill_pay_number = latest_billpay.bill_pay_number or latest_billpay.payment_token or "-"

    response = HttpResponse(content_type='application/pdf')
    filename = f"receipt_{student.indexNumber}_{fee.fee_name}.pdf".replace(" ", "_")
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    doc = SimpleDocTemplate(response, pagesize=A4, topMargin=1.5*cm, bottomMargin=1.5*cm)
    elements = []
    styles = getSampleStyleSheet()
    header_style = ParagraphStyle('Header', parent=styles['Heading1'], alignment=1, fontSize=16)
    body_style = ParagraphStyle('Body', parent=styles['BodyText'], fontSize=10)

    elements.append(Paragraph("Student Fee Receipt", header_style))
    elements.append(Spacer(1, 0.4*cm))
    elements.append(Paragraph(f"<b>Student:</b> {student.fullName}", body_style))
    elements.append(Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style))
    elements.append(Paragraph(f"<b>Fee:</b> {fee.fee_name}", body_style))
    elements.append(Paragraph(f"<b>Bill Pay Number:</b> {bill_pay_number}", body_style))
    elements.append(Spacer(1, 0.4*cm))

    table_data = [
        ["Required", "Discount", "Paid", "Balance", "Status"],
        [
            f"{adjusted_required:.2f}",
            f"{discount_amount:.2f}",
            f"{total_paid:.2f}",
            f"{balance:.2f}",
            "Complete" if balance <= 0 else "Pending",
        ],
    ]
    table = Table(table_data, colWidths=[4 * cm, 3 * cm, 3 * cm, 3 * cm, 3 * cm])
    table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
        ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
    ]))
    elements.append(table)
    elements.append(Spacer(1, 0.4*cm))
    elements.append(Paragraph(f"Generated on {timezone.now().strftime('%Y-%m-%d %H:%M')}", body_style))

    doc.build(elements)
    return response


@login_required
def student_all_fees_receipt_pdf(request):
    if not request.user.is_student:
        return redirect('login_view')

    student_profiles = Student.objects.filter(user=request.user).select_related(
        'teacherclass__ClassName', 'teacherclass__academicclassyear', 'manager'
    )
    if not student_profiles.exists():
        return redirect('login_view')

    from finance.models import StudentPayment, PaymentTransaction, Discount, StudentFee, PayFee

    response = HttpResponse(content_type='application/pdf')
    filename = f"receipt_all_fees_{student_profiles.first().indexNumber}.pdf".replace(" ", "_")
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    doc = SimpleDocTemplate(response, pagesize=A4, topMargin=1.5*cm, bottomMargin=1.5*cm)
    elements = []
    styles = getSampleStyleSheet()
    header_style = ParagraphStyle('Header', parent=styles['Heading1'], alignment=1, fontSize=16)
    body_style = ParagraphStyle('Body', parent=styles['BodyText'], fontSize=9)

    elements.append(Paragraph("Student Fee Receipt (All Fees)", header_style))
    elements.append(Spacer(1, 0.4*cm))

    for student in student_profiles:
        elements.append(Paragraph(f"<b>Student:</b> {student.fullName}", body_style))
        elements.append(Paragraph(f"<b>Class:</b> {student.teacherclass.ClassName.class_name}", body_style))
        elements.append(Spacer(1, 0.2*cm))

        student_fees = StudentFee.objects.filter(student=student, teacherclass=student.teacherclass).select_related('fee')
        payment_map = {
            payment.fee_id: payment
            for payment in StudentPayment.objects.filter(
                student=student,
                teacherclass=student.teacherclass,
                fee__in=student_fees.values("fee_id"),
            ).prefetch_related("transactions")
        }

        table_data = [["Fee", "Required", "Paid", "Balance", "Bill Pay", "Status"]]
        total_required = Decimal("0.00")
        total_paid = Decimal("0.00")
        for sf in student_fees:
            fee = sf.fee
            discount = Discount.objects.filter(student=student, fee=fee).first()
            discount_amount = discount.discount_amount if discount else Decimal("0.00")
            adjusted_required = sf.amount_required - discount_amount
            paid_amount = PayFee.objects.filter(student=student, fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal("0.00")
            balance = adjusted_required - paid_amount

            payment_record = payment_map.get(fee.id)
            latest_billpay = (
                payment_record.transactions.filter(method=PaymentTransaction.METHOD_BILLPAY).order_by("-created_at").first()
                if payment_record
                else None
            )
            bill_pay_number = "-"
            if latest_billpay:
                bill_pay_number = latest_billpay.bill_pay_number or latest_billpay.payment_token or "-"

            table_data.append([
                fee.fee_name,
                f"{adjusted_required:.2f}",
                f"{paid_amount:.2f}",
                f"{balance:.2f}",
                bill_pay_number,
                "Complete" if balance <= 0 else "Pending",
            ])
            total_required += adjusted_required
            total_paid += paid_amount

        table_data.append([
            "TOTAL",
            f"{total_required:.2f}",
            f"{total_paid:.2f}",
            f"{(total_required - total_paid):.2f}",
            "-",
            "-",
        ])

        table = Table(table_data, colWidths=[5.5 * cm, 3 * cm, 3 * cm, 3 * cm, 4 * cm, 2.5 * cm])
        table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#d0d9e5')),
        ]))
        elements.append(table)
        elements.append(Spacer(1, 0.5*cm))

    elements.append(Paragraph(f"Generated on {timezone.now().strftime('%Y-%m-%d %H:%M')}", body_style))
    doc.build(elements)
    return response
@login_required
def change_profile_photo(request):
    if not request.user.is_student:
        messages.error(request, "You are not authorized to perform this action.")
        return redirect('student_profile')

    try:
        student = Student.objects.get(user=request.user)
    except Student.DoesNotExist:
        messages.error(request, "Student profile not found.")
        return redirect('student_profile')

    if request.method == 'POST':
        if 'photo' in request.FILES:
            student.photo = request.FILES['photo']
            student.save()
            messages.success(request, "Profile photo updated successfully.")
        else:
            messages.error(request, "Please select an image file.")
        return redirect('student_profile')

    # If not POST, redirect back to profile (shouldn't happen with form)
    return redirect('student_profile')

@effective_user_decorator
@login_required
def send_single_student_sms(request):
    # Check for SmsConfiguration existence first
    try:
        sms_data = SmsConfiguration.objects.get(user=request.effective_user)
    except SmsConfiguration.DoesNotExist:
        logger.error("No SMS configuration found for user")
        messages.error(request, "No sms configuration")
        return render(request, 'send_single_student_sms.html', {
            'teacher_classes': TeacherClass.objects.filter(user=request.effective_user).order_by('ClassName'),
            'students': Student.objects.none(),
            'selected_class_id': None
        })

    teacher_classes = TeacherClass.objects.filter(user=request.effective_user,academicclassyear__active_year=True).order_by('ClassName')
    description = DisplayModel.objects.filter(user=request.effective_user).last()
    url_required = sms_data.url_required
    source_address = sms_data.source_addr
    username_required = sms_data.username
    pswd = sms_data.pswd

    # Get selected class_id from GET parameters
    class_id = request.GET.get('class_id', '')
    selected_class_id = class_id if class_id and class_id.strip() else None

    # Filter students
    students = Student.objects.filter(
        Q(user=request.effective_user) | Q(manager=request.effective_user)
    )
    if selected_class_id:
        try:
            students = students.filter(teacherclass__id=selected_class_id)
            logger.debug(f"Found {students.count()} students for class_id={selected_class_id}")
        except ValueError:
            logger.error(f"Invalid class_id: {class_id}")
            messages.error(request, "Invalid class ID selected.")
            students = Student.objects.none()

    if request.method == 'POST':
        try:
            # Get student IDs from hidden input (joined by commas)
            student_ids_str = request.POST.get('student_ids_hidden', '')
            message = request.POST.get('message')

            # Convert comma-separated string to list
            student_ids = student_ids_str.split(',') if student_ids_str else []

            if not student_ids or not message:
                logger.error(f"Missing data: student_ids={student_ids}, message={message}")
                messages.error(request, "Please select at least one student and enter a message.")
                return render(request, 'send_single_student_sms.html', {
                    'teacher_classes': teacher_classes,
                    'students': students,
                    'selected_class_id': selected_class_id
                })

            # Fetch students
            students_to_message = Student.objects.filter(
                Q(id__in=student_ids) & (Q(user=request.effective_user) | Q(manager=request.effective_user))
            )
            if not students_to_message.exists():
                logger.error(f"No valid students found for IDs: {student_ids}")
                messages.error(request, "No valid students selected.")
                return render(request, 'send_single_student_sms.html', {
                    'teacher_classes': teacher_classes,
                    'students': students,
                    'selected_class_id': selected_class_id
                })

            success_count = 0
            for student in students_to_message:
                if not student.contact or not isinstance(student.contact, int) or student.contact < 255000000000:
                    logger.warning(f"Invalid contact for {student.fullName}: {student.contact}")
                    messages.error(request, f"Invalid or missing contact number for {student.fullName}.")
                    continue

                dest_addr = str(student.contact)
                logger.info(f"Sending SMS to {student.fullName} at {dest_addr}")

                sms_content = f"{description.header if description else 'Message'},\n{message}\n.."

                payload = {
                    "source_addr": source_address,
                    "encoding": 0,
                    "message": sms_content,
                    "recipients": [
                        {
                            "recipient_id": student.id,
                            "dest_addr": dest_addr
                        }
                    ]
                }

                response = requests.post(url_required, json=payload, auth=HTTPBasicAuth(username_required, pswd))

                if response.status_code == 200:
                    logger.info(f"SMS sent successfully to {student.fullName}")
                    messages.success(request, f"Message sent successfully to {student.fullName}!")
                    success_count += 1
                else:
                    logger.error(f"Failed to send SMS to {student.fullName}. Error: {response.text}")
                    messages.error(request, f"Failed to send message to {student.fullName}. Error: {response.text}")

            if success_count == len(student_ids):
                messages.success(request, "Messages sent successfully to all selected students!")
            elif success_count > 0:
                messages.warning(request, f"Messages sent to {success_count} of {len(student_ids)} selected students.")

        except Exception as e:
            logger.error(f"Error sending SMS: {str(e)}")
            messages.error(request, f"Error: {str(e)}")

        return render(request, 'send_single_student_sms.html', {
            'teacher_classes': teacher_classes,
            'students': students,
            'selected_class_id': selected_class_id
        })

    return render(request, 'send_single_student_sms.html', {
        'teacher_classes': teacher_classes,
        'students': students,
        'selected_class_id': selected_class_id
    })
    
@login_required
def search_students(request):
    query = request.GET.get('q', '')
    class_id = request.GET.get('class_id', '')
    
    logger.debug(f"Search students: user={request.user.username}, query={query}, class_id={class_id}")

    # Start with students where the user is either the 'user' or 'manager'
    students = Student.objects.filter(
        Q(user=request.user) | Q(manager=request.user)
    )
    
    # Log all students before class filter
    logger.debug(f"Students before class filter: {students.count()}")

    # Filter by class if provided
    if class_id and class_id.strip():
        try:
            students = students.filter(teacherclass__id=class_id)
            logger.debug(f"Students after class filter: {students.count()}")
        except ValueError:
            logger.error(f"Invalid class_id: {class_id}")
            return JsonResponse({'students': [], 'error': 'Invalid class ID'})

    # Filter by search query (fullName or indexNumber)
    if query:
        students = students.filter(
            Q(fullName__icontains=query) | 
            Q(indexNumber__icontains=query)
        )
    
    logger.debug(f"Final students found: {students.count()}")

    students_data = [
        {
            'id': student.id,
            'fullName': student.fullName or 'Unnamed Student',
            'indexNumber': student.indexNumber or 'No Index',
            'className': student.teacherclass.ClassName if student.teacherclass else 'No Class'
        }
        for student in students
    ]
    
    return JsonResponse({'students': students_data})



@csrf_exempt  # Using CSRF token in headers, so exempting CSRF check here
@require_POST
def update_merge_selection(request):
    try:
        # Parse JSON body from the request
        data = json.loads(request.body)
        upload_id = data.get('upload_id')
        for_merging_pdf = data.get('for_merging_pdf')

        # Validate inputs
        if upload_id is None or for_merging_pdf is None:
            return JsonResponse({'success': False, 'error': 'Missing upload_id or for_merging_pdf'}, status=400)

        # Get and update the TermMarksUpload instance
        upload = TermMarksUpload.objects.get(id=upload_id)
        upload.for_merging_pdf = for_merging_pdf
        upload.save()

        return JsonResponse({'success': True}, status=200)

    except TermMarksUpload.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Upload not found'}, status=404)
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'Invalid JSON'}, status=400)
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)
