from django.shortcuts import render, redirect, get_object_or_404
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from .models import ExaminationName, TeacherSubject

@login_required
def select_examination(request, teacher_subject_id):
    teacher_subject = get_object_or_404(TeacherSubject, id=teacher_subject_id, teacher=request.user)
    examinations = ExaminationName.objects.filter(user=request.user)
    
    if not examinations.exists():
        messages.error(request, "No examination names available. Please create one first.")
        return redirect('examination_create')
    
    if request.method == 'POST':
        exam_id = request.POST.get('examination_id')
        if exam_id:
            try:
                examination = ExaminationName.objects.get(id=exam_id, user=request.user)
                request.session['selected_examination_id'] = exam_id
                request.session['selected_examination_name'] = examination.exam_name
                return redirect('fill_marks', teacher_subject_id=teacher_subject_id)
            except ExaminationName.DoesNotExist:
                messages.error(request, "Invalid examination selected.")
    
    context = {
        'teacher_subject': teacher_subject,
        'examinations': examinations,
    }
    return render(request, 'select_examination.html', context)

@login_required
def change_examination(request, teacher_subject_id):
    if 'selected_examination_id' in request.session:
        del request.session['selected_examination_id']
        del request.session['selected_examination_name']
    return redirect('select_examination', teacher_subject_id=teacher_subject_id)
    

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import render, get_object_or_404
from django.db.models import Sum, Avg, Q
from django.http import JsonResponse
from .models import TeacherClass, GradingModel, ExaminationName, Student, Subject, Mark, ExcludeSubject, RequiredSubject, SmsConfiguration, DisplayModel
import requests
from requests.auth import HTTPBasicAuth
import logging
from django.db.models import Prefetch
from django.db.models import Q as models_Q
from .decorators import effective_user_decorator

@effective_user_decorator
def all_student_marks(request, class_ids=None, examination_name_id=None):
    from django.db.models import Q, Sum, Avg
    from django.db.models import Prefetch
    import logging
    logger = logging.getLogger(__name__)

    def get_grade(mark_value, grade_thresholds, is_primary):
        if mark_value is None:
            return '-'
        for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
            if mark_value >= threshold:
                return letter_grade
        return 'E' if is_primary else 'F'

    classes = TeacherClass.objects.filter(
        user=request.effective_user,
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear').order_by('ClassName__class_name')

    grades = GradingModel.objects.filter(user=request.effective_user)
    primary_grades = grades.filter(is_primary=True)
    o_level_grades = grades.filter(is_primary=False, is_advance=False)
    a_level_grades = grades.filter(is_advance=True)
    display = DisplayModel.objects.filter(user=request.effective_user)
    examination_names = ExaminationName.objects.filter(user=request.effective_user)

    if request.method == 'POST' or class_ids:
        class_ids_input = request.POST.getlist('class_id')
        class_ids = class_ids_input if class_ids_input else (class_ids.split(',') if class_ids else [])
        class_ids = [cid for cid in class_ids if cid]
        grade_id = request.POST.get('grade_id')
        report_id = request.POST.get('report_id')
        examination_name_id = request.POST.get('examination_id', examination_name_id)

        if not class_ids or not grade_id or not examination_name_id:
            messages.error(request, "Invalid selection: At least one class, grade, or examination must be selected.")
            return render(request, 'grading_system.html', {
                'grades': grades,
                'primary_grades': primary_grades,
                'o_level_grades': o_level_grades,
                'a_level_grades': a_level_grades,
                'display': display,
                'classes': classes,
                'examination_names': examination_names
            })

        # Validate classes
        teacherclasses_qs = TeacherClass.objects.filter(
            id__in=class_ids, 
            user=request.effective_user, 
            academicclassyear__active_year=True
        ).select_related('ClassName')
        if teacherclasses_qs.count() != len(set(class_ids)):
            messages.error(request, "One or more selected classes are invalid or inaccessible.")
            return render(request, 'all_student_marks.html', {
                'grades': grades,
                'primary_grades': primary_grades,
                'o_level_grades': o_level_grades,
                'a_level_grades': a_level_grades,
                'display': display,
                'classes': classes,
                'examination_names': examination_names,
                'teacherclasses': None
            })

        teacherclasses = teacherclasses_qs
        # Store examination_name_id in session for download_pdf
        request.session['selected_examination_id'] = examination_name_id
        examination_name = get_object_or_404(ExaminationName, id=examination_name_id, user=request.effective_user)
        grading_required = get_object_or_404(GradingModel, id=grade_id, user=request.effective_user)
        report_display = DisplayModel.objects.filter(id=report_id, user=request.effective_user).first() if report_id and DisplayModel.objects.filter(id=report_id, user=request.effective_user).exists() else None

        # Determine level based on grading_required
        is_primary = grading_required.is_primary
        if is_primary:
            level = 'Primary'
        elif grading_required.is_advance:
            level = 'Alevel'
        else:
            level = 'Olevel'
        
        # Fetch filtered subjects using RequiredSubject across all classes
        required_subjects = RequiredSubject.objects.filter(user=request.effective_user, level=level, teacherclass__in=teacherclasses)
        subject_ids = list(set(required_subjects.values_list('subject_id', flat=True)))
        subjects = Subject.objects.filter(id__in=subject_ids, user=request.effective_user)

        if not subjects.exists():
            logger.warning(f"No subjects found for selected TeacherClasses at level {level}")
            messages.warning(request, f"No subjects defined for selected classes at {level}. Add subjects to proceed.")

        # Set exclude_subjects for O-level and A-level
        exclude_subjects = set()
        if not is_primary:
            exclude_subjects = set(ExcludeSubject.objects.filter(user=request.effective_user).values_list('exclude_subject_id', flat=True))

        # Fetch composite if A-level
        composite = None
        component_ids_set = set()
        if grading_required.is_advance:
            composite = CompositeSubject.objects.filter(user=request.effective_user).first()
            if composite:
                component_ids_set = set(composite.subjects.values_list('id', flat=True))

        # Determine display subjects and subjects_list
        if composite and composite.allow_to_use:
            display_subjects_qs = subjects.exclude(id__in=component_ids_set)
            subjects_list = [
                {
                    'id': s.id,
                    'nameSubject': s.nameSubject,
                    'is_excluded': s.id in exclude_subjects
                }
                for s in display_subjects_qs
            ]
            if component_ids_set & set(subject_ids):
                subjects_list.append({
                    'id': 'composite',
                    'nameSubject': composite.subject_name,
                    'is_excluded': False
                })
        else:
            display_subjects_qs = subjects
            subjects_list = [
                {
                    'id': s.id,
                    'nameSubject': s.nameSubject,
                    'is_excluded': s.id in exclude_subjects
                }
                for s in display_subjects_qs
            ]

        # Set grade_thresholds and other configs
        if is_primary:
            grade_thresholds = {
                grading_required.grade_a: 'A',
                grading_required.grade_b: 'B',
                grading_required.grade_c: 'C',
                grading_required.grade_d: 'D',
                grading_required.grade_f: 'E'
            }
            grade_points = {}  # Not used for primary
            min_subjects_for_division = None
        elif grading_required.is_advance:
            grade_thresholds = {
                grading_required.grade_a: 'A',
                grading_required.grade_b: 'B',
                grading_required.grade_c: 'C',
                grading_required.grade_d: 'D',
                grading_required.grade_e: 'E',
                grading_required.grade_s: 'S',
                grading_required.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
            min_subjects_for_division = 3
        else:  # O-level
            grade_thresholds = {
                grading_required.grade_a: 'A',
                grading_required.grade_b: 'B',
                grading_required.grade_c: 'C',
                grading_required.grade_d: 'D',
                grading_required.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
            min_subjects_for_division = 7

        # Filter marks by examinationname
        students = Student.objects.filter(teacherclass__in=teacherclasses).prefetch_related(
            Prefetch('marks', queryset=Mark.objects.filter(subject__in=subjects, examinationname=examination_name).select_related('subject'))
        )
        if not students.exists():
            logger.warning(f"No students found for selected TeacherClasses")
            messages.warning(request, f"No students enrolled in the selected classes.")

        students_marks_evaluation = Student.objects.filter(teacherclass__in=teacherclasses).annotate(
            total_marks=Sum('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination_name)),
            average_marks=Avg('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination_name))
        )

        marks_evaluation_dict = {
            s.id: {
                'total_marks': s.total_marks or 0,
                'average_marks': s.average_marks or 0
            } for s in students_marks_evaluation
        }

        division_thresholds = [
            {'max': grading_required.division_1, 'label': 'I'},
            {'max': grading_required.division_2, 'label': 'II'},
            {'max': grading_required.division_3, 'label': 'III'},
            {'max': grading_required.division_4, 'label': 'IV'},
            {'max': float('inf'), 'label': '0'}
        ]

        student_data = []
        for student in students:
            student_marks = []
            all_grades = []
            grades_for_division = []

            # Get all marks for this student as dict for easy access
            student_marks_dict = {
                m.subject_id: m.marks for m in student.marks.filter(examinationname=examination_name)
            }

            # Process display subjects
            for subject in display_subjects_qs:
                mark_value = student_marks_dict.get(subject.id)
                grade = get_grade(mark_value, grade_thresholds, is_primary)
                student_marks.append({
                    'subject': subject.id,
                    'subject_name': subject.nameSubject,
                    'mark': mark_value,
                    'grade': grade,
                    'is_excluded': subject.id in exclude_subjects
                })
                all_grades.append(grade)
                # Append to grades_for_division only if not primary, not excluded, and not a component when !allow_to_use
                if not is_primary and subject.id not in exclude_subjects:
                    if not (composite and not composite.allow_to_use and subject.id in component_ids_set):
                        grades_for_division.append(grade)

            # Handle composite logic
            if grading_required.is_advance and composite:
                if composite.allow_to_use:
                    # Composite as single display subject with average
                    component_marks_values = [student_marks_dict.get(sid) for sid in component_ids_set if student_marks_dict.get(sid) is not None]
                    avg_mark = round(sum(component_marks_values) / len(component_marks_values), 2) if component_marks_values else None
                    composite_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                    student_marks.append({
                        'subject': 'composite',
                        'subject_name': composite.subject_name,
                        'mark': avg_mark,
                        'grade': composite_grade,
                        'is_excluded': False
                    })
                    all_grades.append(composite_grade)
                    grades_for_division.append(composite_grade)
                else:
                    # Components displayed individually, but single grade for division
                    component_marks_values = [student_marks_dict.get(sid) for sid in component_ids_set if student_marks_dict.get(sid) is not None]
                    if component_marks_values:
                        avg_mark = round(sum(component_marks_values) / len(component_marks_values), 2)
                        group_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                        grades_for_division.append(group_grade)
                    else:
                        grades_for_division.append('-')

            logger.debug(f"Student {student.fullName} marks: {student_marks}")

            has_valid_marks = any(m is not None for m in student_marks_dict.values())

            # Calculate division if not primary
            if is_primary:
                division = "-"
                total_points = "-"
            else:
                filtered_grades = [g for g in grades_for_division if g != '-']
                num_valid_subjects = len(filtered_grades)

                if num_valid_subjects < min_subjects_for_division:
                    division = "Inc"
                    total_points = 0
                else:
                    sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:min_subjects_for_division]
                    total_points = sum(grade_points[g] for g in sorted_grades)
                    division = 'IV'
                    for threshold in division_thresholds:
                        if total_points <= threshold['max']:
                            division = threshold['label']
                            break

            student_average = marks_evaluation_dict.get(student.id, {}).get('average_marks', 0)
            overall_grade = '-'
            if student_average > 0:
                for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
                    if student_average >= threshold:
                        overall_grade = letter_grade
                        break
                if overall_grade == '-':
                    overall_grade = 'E' if is_primary else 'F'

            student_data.append({
                'id': student.id,
                'fullName': student.fullName,
                'sex': student.sex,
                'indexNumber': student.indexNumber,
                'marks': student_marks,
                'total_marks': marks_evaluation_dict.get(student.id, {}).get('total_marks', 0),
                'average_marks': student_average,
                'grade': overall_grade,
                'division': division,
                'total_points': total_points,
                'has_valid_marks': has_valid_marks,
                'teacherclass': {
                    'id': student.teacherclass.id,
                    'ClassName': student.teacherclass.ClassName.class_name or "Unnamed Class"
                }
            })

        # Sort students: complete first, then by average descending
        student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))
        for position, student in enumerate(student_data, 1):
            student['position'] = position

        empty_colspan = 9 + len(subjects_list) * 2 + (0 if is_primary else 2)

        context = {
            'students': student_data,
            'subjects': subjects_list,
            'display': [report_display] if report_display else display[:1],
            'teacherclasses': teacherclasses,
            'selected_classes': [tc.ClassName.class_name or "Unnamed Class" for tc in teacherclasses],
            'classes': classes,
            'grades': grades,
            'primary_grades': primary_grades,
            'o_level_grades': o_level_grades,
            'a_level_grades': a_level_grades,
            'examination_names': examination_names,
            'selected_examination': examination_name,
            'grading_required': grading_required,
            'exclude_subjects': list(exclude_subjects),
            'is_primary': is_primary,
            'empty_colspan': empty_colspan,
            'selected_class_ids': class_ids,
        }
        logger.debug(f"Context prepared: {len(student_data)} students, {len(subjects_list)} display subjects")
        return render(request, 'all_student_marks.html', context)

    return render(request, 'grading_system.html', {
        'grades': grades,
        'primary_grades': primary_grades,
        'o_level_grades': o_level_grades,
        'a_level_grades': a_level_grades,
        'display': display,
        'classes': classes,
        'examination_names': examination_names,
        'teacherclasses': None  # Ensure teacherclasses is None when no class is selected
    })
@effective_user_decorator
@login_required
def filter_class_results(request):
    from django.db.models import Q, Sum, Avg
    import logging
    from django.http import JsonResponse
    logger = logging.getLogger(__name__)

    def get_grade(mark_value, grade_thresholds, is_primary):
        if mark_value is None:
            return '-'
        for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
            if mark_value >= threshold:
                return letter_grade
        return 'E' if is_primary else 'F'

    if request.method != 'POST' or not request.headers.get('X-Requested-With') == 'XMLHttpRequest':
        return JsonResponse({'error': 'Invalid request'}, status=400)

    class_ids_str = request.POST.get('class_id', '')
    class_ids = [int(cid) for cid in class_ids_str.split(',') if cid.strip()]
    grade_id = request.POST.get('grade_id')
    examination_id = request.POST.get('examination_id')

    if not class_ids or not grade_id or not examination_id:
        return JsonResponse({'error': 'Classes, grade, or examination not specified'}, status=400)

    # Validate objects
    try:
        teacherclasses_qs = TeacherClass.objects.filter(
            id__in=class_ids, 
            user=request.effective_user, 
            academicclassyear__active_year=True
        ).select_related('ClassName')
        if teacherclasses_qs.count() != len(set(class_ids)):
            raise ValueError("Invalid classes")
        teacherclasses = teacherclasses_qs
        grading_required = get_object_or_404(GradingModel, id=grade_id, user=request.effective_user)
        examination = get_object_or_404(ExaminationName, id=examination_id, user=request.effective_user)
    except Exception as e:
        logger.error(f"Error fetching objects: {str(e)}")
        return JsonResponse({'error': 'Invalid classes, grade, or examination'}, status=400)

    is_primary = grading_required.is_primary

    # Determine level
    if is_primary:
        level = 'Primary'
    elif grading_required.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'

    # Fetch filtered subjects
    required_subjects = RequiredSubject.objects.filter(user=request.effective_user, level=level, teacherclass__in=teacherclasses)
    subject_ids = list(set(required_subjects.values_list('subject_id', flat=True)))
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.effective_user)

    subjects_warning = None
    if not subjects.exists():
        logger.warning(f"No subjects found for selected TeacherClasses at level {level}")
        subjects_warning = f"No subjects defined for selected classes at {level}."

    # Fetch exclude_subjects for non-primary
    exclude_subjects = set()
    if not is_primary:
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.effective_user).values_list('exclude_subject_id', flat=True))

    # Fetch composite if A-level
    composite = None
    component_ids_set = set()
    if grading_required.is_advance:
        composite = CompositeSubject.objects.filter(user=request.effective_user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))

    # Determine display subjects and subjects_data
    if composite and composite.allow_to_use:
        display_subjects_qs = subjects.exclude(id__in=component_ids_set)
        subjects_data = [
            {
                'id': s.id,
                'nameSubject': s.nameSubject,
                'is_excluded': s.id in exclude_subjects
            }
            for s in display_subjects_qs
        ]
        if component_ids_set & set(subject_ids):
            subjects_data.append({
                'id': 'composite',
                'nameSubject': composite.subject_name,
                'is_excluded': False
            })
    else:
        display_subjects_qs = subjects
        subjects_data = [
            {
                'id': s.id,
                'nameSubject': s.nameSubject,
                'is_excluded': s.id in exclude_subjects
            }
            for s in display_subjects_qs
        ]

    # Grading logic
    if is_primary:
        grade_thresholds = {
            grading_required.grade_a: 'A',
            grading_required.grade_b: 'B',
            grading_required.grade_c: 'C',
            grading_required.grade_d: 'D',
            grading_required.grade_f: 'E'
        }
        grade_points = {}
        min_subjects_for_division = None
    elif grading_required.is_advance:
        grade_thresholds = {
            grading_required.grade_a: 'A',
            grading_required.grade_b: 'B',
            grading_required.grade_c: 'C',
            grading_required.grade_d: 'D',
            grading_required.grade_e: 'E',
            grading_required.grade_s: 'S',
            grading_required.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
    else:
        grade_thresholds = {
            grading_required.grade_a: 'A',
            grading_required.grade_b: 'B',
            grading_required.grade_c: 'C',
            grading_required.grade_d: 'D',
            grading_required.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7

    division_thresholds = [
        {'max': grading_required.division_1, 'label': 'I'},
        {'max': grading_required.division_2, 'label': 'II'},
        {'max': grading_required.division_3, 'label': 'III'},
        {'max': grading_required.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    # Fetch students and marks
    students = Student.objects.filter(teacherclass__in=teacherclasses).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(subject__in=subjects, examinationname=examination).select_related('subject'))
    )

    students_warning = None
    if not students.exists():
        logger.warning(f"No students found for selected TeacherClasses")
        students_warning = f"No students enrolled in the selected classes."

    students_marks_evaluation = Student.objects.filter(teacherclass__in=teacherclasses).annotate(
        total_marks=Sum('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination)),
        average_marks=Avg('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination))
    )

    marks_evaluation_dict = {
        s.id: {
            'total_marks': s.total_marks or 0,
            'average_marks': s.average_marks or 0
        } for s in students_marks_evaluation
    }

    # Prepare student data
    student_data = []
    for student in students:
        student_marks = []
        grades_for_division = []
        has_valid_marks = False

        # Get all marks for this student as dict for easy access
        student_marks_dict = {
            m.subject_id: m.marks for m in student.marks.filter(examinationname=examination)
        }
        has_valid_marks = any(m is not None for m in student_marks_dict.values())

        # Process display subjects
        for subject in display_subjects_qs:
            mark_value = student_marks_dict.get(subject.id)
            grade = get_grade(mark_value, grade_thresholds, is_primary)
            student_marks.append({
                'subject': subject.id,
                'subject_name': subject.nameSubject,
                'mark': mark_value,
                'grade': grade,
                'is_excluded': subject.id in exclude_subjects
            })
            # Append to grades_for_division only if not primary, not excluded, and not a component when !allow_to_use
            if not is_primary and subject.id not in exclude_subjects:
                if not (composite and not composite.allow_to_use and subject.id in component_ids_set):
                    grades_for_division.append(grade)

        # Handle composite logic
        if grading_required.is_advance and composite:
            if composite.allow_to_use:
                # Composite as single display subject with average
                component_marks_values = [student_marks_dict.get(sid) for sid in component_ids_set if student_marks_dict.get(sid) is not None]
                avg_mark = round(sum(component_marks_values) / len(component_marks_values), 2) if component_marks_values else None
                composite_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                student_marks.append({
                    'subject': 'composite',
                    'subject_name': composite.subject_name,
                    'mark': avg_mark,
                    'grade': composite_grade,
                    'is_excluded': False
                })
                grades_for_division.append(composite_grade)
            else:
                # Components displayed individually, but single grade for division
                component_marks_values = [student_marks_dict.get(sid) for sid in component_ids_set if student_marks_dict.get(sid) is not None]
                if component_marks_values:
                    avg_mark = round(sum(component_marks_values) / len(component_marks_values), 2)
                    group_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                    grades_for_division.append(group_grade)
                else:
                    grades_for_division.append('-')

        # Calculate division
        if is_primary:
            division = "-"
            total_points = "-"
        else:
            filtered_grades = [g for g in grades_for_division if g != '-']
            num_valid_subjects = len(filtered_grades)

            if num_valid_subjects < min_subjects_for_division:
                division = "Inc"
                total_points = 0
            else:
                sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:min_subjects_for_division]
                total_points = sum(grade_points[g] for g in sorted_grades)
                division = 'IV'
                for threshold in division_thresholds:
                    if total_points <= threshold['max']:
                        division = threshold['label']
                        break

        student_average = marks_evaluation_dict.get(student.id, {}).get('average_marks', 0)
        overall_grade = '-'
        if student_average > 0:
            for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
                if student_average >= threshold:
                    overall_grade = letter_grade
                    break
            if overall_grade == '-':
                overall_grade = 'E' if is_primary else 'F'

        student_data.append({
            'id': student.id,
            'fullName': student.fullName or 'Unnamed Student',
            'sex': student.sex or '-',
            'indexNumber': student.indexNumber or '-',
            'marks': student_marks,
            'total_marks': marks_evaluation_dict.get(student.id, {}).get('total_marks', 0),
            'average_marks': student_average,
            'grade': overall_grade,
            'division': division,
            'total_points': total_points,
            'has_valid_marks': has_valid_marks,
            'teacherclass': {
                'id': student.teacherclass.id,
                'ClassName': student.teacherclass.ClassName.class_name or 'Unnamed Class'
            }
        })

    student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))
    for position, student in enumerate(student_data, 1):
        student['position'] = position

    # Prepare subjects data for JSON response
    empty_colspan = 9 + len(subjects_data) * 2 + (0 if is_primary else 2)

    selected_classes = [tc.ClassName.class_name or 'Unnamed Class' for tc in teacherclasses]
    grading_level = 'Primary' if is_primary else ('A-Level' if grading_required.is_advance else 'O-Level')

    response_data = {
        'selected_classes': selected_classes,
        'grading_level': grading_level,
        'examination_name': examination.exam_name or 'Unnamed Examination',
        'students': student_data,
        'subjects': subjects_data,
        'exclude_subjects': list(exclude_subjects),
        'is_primary': is_primary,
        'empty_colspan': empty_colspan,
        'class_ids': class_ids_str,
        'grade_id': grade_id,
        'examination_id': examination_id,
        'success': True
    }

    # Add warnings if present
    if subjects_warning:
        response_data['warning'] = subjects_warning
    if students_warning:
        response_data['warning'] = (response_data.get('warning', '') + ' ' + students_warning).strip()

    return JsonResponse(response_data, status=200)
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib import messages
from django.contrib.auth.decorators import login_required
from .decorators import effective_user_decorator

@effective_user_decorator
@login_required
def fill_marks(request, teacher_subject_id):
    # Use effective_user from decorator
    effective_user = request.effective_user

    # 1. Check if an examination name is selected
    examination_name_id = request.session.get('selected_examination_id')
    if not examination_name_id:
        messages.error(request, "Please select an examination first.")
        return redirect('select_examination_name', teacher_subject_id=teacher_subject_id)

    # 2. Get the TeacherSubject assignment
    teacher_subject = get_object_or_404(
        TeacherSubject,
        id=teacher_subject_id
    )

    # 3. Determine who is allowed to fill marks:
    #    - The assigned teacher
    #    - OR the creator (effective_user) who created this assignment
    allowed = False
    assigned_teacher = teacher_subject.teacher
    creator = teacher_subject.user  # The one who created the assignment

    if request.user == assigned_teacher.user:
        allowed = True  # The teacher himself
    elif effective_user == creator:
        allowed = True  # The creator (admin/manager)

    if not allowed:
        messages.error(request, "You do not have permission to fill marks for this subject.")
        return redirect('teacher_dashboard')

    # 4. Validate examination belongs to the creator
    try:
        examination_name = ExaminationName.objects.get(
            id=examination_name_id,
            user=creator  # Must belong to the creator
        )
    except ExaminationName.DoesNotExist:
        messages.error(request, "Selected examination is invalid or not accessible.")
        if 'selected_examination_id' in request.session:
            del request.session['selected_examination_id']
        return redirect('select_examination_name', teacher_subject_id=teacher_subject_id)

    # 5. Get class and validate active academic year
    current_teacher_class = teacher_subject.teacherclass
    try:
        academic_class_year = current_teacher_class.academicclassyear
        if not academic_class_year or not academic_class_year.active_year:
            messages.error(request, "This class is not linked to an active academic year.")
            return redirect('teacher_dashboard')
    except AttributeError:
        messages.error(request, "No academic year associated with this class.")
        return redirect('teacher_dashboard')

    # 6. Get students enrolled in this class + subject
    student_subjects = StudentSubject.objects.filter(
        teacherclass=current_teacher_class,
        subject=teacher_subject.subject
    ).prefetch_related('student')

    if student_subjects.exists():
        student_ids = set()
        for ss in student_subjects:
            student_ids.update(ss.student.values_list('id', flat=True))
        students = Student.objects.filter(
            id__in=student_ids,
            teacherclass=current_teacher_class
        ).select_related('user').order_by('fullName')
    else:
        students = Student.objects.none()

    # 7. Fetch existing marks
    student_marks = {
        mark.student_id: mark.marks for mark in Mark.objects.filter(
            teacherclass=current_teacher_class,
            subject=teacher_subject.subject,
            examinationname=examination_name,
            student__in=students
        )
    }

    saved_marks = Mark.objects.filter(
        teacherclass=current_teacher_class,
        subject=teacher_subject.subject,
        examinationname=examination_name,
        student__in=students
    ).select_related('student').order_by('student__fullName')

    # 8. Handle POST (save marks)
    if request.method == 'POST':
        if teacher_subject.is_restricted:
            messages.error(request, "Marks entry is restricted for this subject.")
            return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

        for student in students:
            mark_value = request.POST.get(f'marks_{student.id}')
            if mark_value is not None:
                mark_value = mark_value.strip()
                if mark_value == '':
                    continue  # Skip empty
                try:
                    mark_value = float(mark_value)
                    if not (0 <= mark_value <= 100):
                        raise ValueError("Marks must be between 0 and 100.")
                    Mark.objects.update_or_create(
                        teacherclass=current_teacher_class,
                        subject=teacher_subject.subject,
                        examinationname=examination_name,
                        student=student,
                        defaults={
                            'marks': mark_value,
                            'user': request.user  # Actual user who entered
                        }
                    )
                except ValueError as e:
                    messages.error(request, f"Invalid mark for {student.fullName}: {e}")
                    return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

        messages.success(
            request,
            f"Marks saved successfully for {teacher_subject.subject.nameSubject} "
            f"in {current_teacher_class.ClassName.class_name}."
        )
        return redirect('teacher_dashboard')

    # 9. Render template
    context = {
        'teacher_subject': teacher_subject,
        'students': students,
        'student_marks': student_marks,
        'saved_marks': saved_marks,
        'examination_name': examination_name,
        'academic_class_year': academic_class_year,
        'current_teacher_class': current_teacher_class,
        'is_creator': effective_user == creator,
        'assigned_teacher': assigned_teacher,
    }
    return render(request, 'fill_marks.html', context)
