import logging

logger = logging.getLogger(__name__)
@effective_user_decorator
@login_required
def top_and_bottom_students(request):
    """
    Displays the top and bottom 10 students, either for a selected class or for all classes
    managed by the user and their subordinates, with actual class positions, based on RequiredSubject.
    """
    current_user = request.effective_user

    # Fetch all relevant user IDs
    subordinate_user_ids = Teacher.objects.filter(created_by=current_user).values_list('user_id', flat=True)
    all_user_ids = list(subordinate_user_ids) + [current_user.id]

    # Fetch classes, examinations, and display model
    teacher_classes = TeacherClass.objects.filter(
        user_id__in=all_user_ids, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')
    examinations = ExaminationName.objects.filter(user_id__in=all_user_ids)
    display = DisplayModel.objects.filter(user=current_user).first()

    # Get user selections from query parameters
    selected_class_id = request.GET.get('class_id')
    selected_exam_id = request.GET.get('examination_id')

    context = {
        'teacher_classes': teacher_classes,
        'examinations': examinations,
        'selected_class': None,
        'selected_examination': None,
        'top_students': [],
        'bottom_students': [],
        'class_data': {},
        'display': display,
        'no_subjects_configured': False,
    }

    if selected_exam_id:
        context['selected_examination'] = examinations.filter(id=selected_exam_id).first()

    if selected_class_id:
        # Single Class View
        selected_class = teacher_classes.filter(id=selected_class_id).first()
        context['selected_class'] = selected_class
        
        if selected_class:
            # Get required subjects specific to this class
            required_subjects = RequiredSubject.objects.filter(user=current_user, teacherclass=selected_class)
            
            if not required_subjects.exists():
                context['no_subjects_configured'] = True
                logger.info(f"No required subjects configured for class {selected_class.ClassName}")
                return render(request, 'top_bottom_students.html', context)
            
            required_subject_ids = required_subjects.values_list('subject_id', flat=True)
            
            # Base query for marks, filtered by class-specific required subjects
            marks_query = Mark.objects.filter(
                user_id__in=all_user_ids,
                subject__id__in=required_subject_ids,
                teacherclass=selected_class
            ).select_related('student', 'teacherclass', 'examinationname')
            
            # Apply examination filter if selected
            if selected_exam_id:
                marks_query = marks_query.filter(examinationname_id=selected_exam_id)
            
            # Calculate average marks for each student and sort by average
            student_averages = marks_query.values(
                'student__id',
                'student__fullName',
                'student__sex',
                'student__indexNumber'
            ).annotate(
                avg_mark=Avg('marks')
            ).order_by('-avg_mark')

            # Assign actual positions
            ranked_students = []
            for position, student in enumerate(student_averages, 1):
                ranked_students.append({
                    'position': position,
                    'student__id': student['student__id'],
                    'student__fullName': student['student__fullName'],
                    'student__sex': student['student__sex'],
                    'student__indexNumber': student['student__indexNumber'],
                    'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                })

            context['top_students'] = ranked_students[:10]
            context['bottom_students'] = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])
            logger.debug(f"Processed {len(ranked_students)} students for class {selected_class.ClassName}")
    else:
        # All Classes View
        class_data = {}
        for teacher_class in teacher_classes:
            # Get required subjects specific to this class
            required_subjects = RequiredSubject.objects.filter(user=current_user, teacherclass=teacher_class)
            
            if not required_subjects.exists():
                logger.info(f"No required subjects configured for class {teacher_class.ClassName} - skipping")
                continue
            
            required_subject_ids = required_subjects.values_list('subject_id', flat=True)
            
            # Base query for marks, filtered by class-specific required subjects
            marks_query = Mark.objects.filter(
                user_id__in=all_user_ids,
                subject__id__in=required_subject_ids,
                teacherclass=teacher_class
            ).select_related('student', 'teacherclass', 'examinationname')
            
            # Apply examination filter if selected
            if selected_exam_id:
                marks_query = marks_query.filter(examinationname_id=selected_exam_id)
            
            # Calculate average marks for each student and sort by average
            student_averages = marks_query.values(
                'student__id',
                'student__fullName',
                'student__sex',
                'student__indexNumber'
            ).annotate(
                avg_mark=Avg('marks')
            ).order_by('-avg_mark')

            ranked_students = []
            for position, student in enumerate(student_averages, 1):
                ranked_students.append({
                    'position': position,
                    'student__id': student['student__id'],
                    'student__fullName': student['student__fullName'],
                    'student__sex': student['student__sex'],
                    'student__indexNumber': student['student__indexNumber'],
                    'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                })

            top = ranked_students[:10]
            bottom = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])

            if top or bottom:
                class_data[teacher_class] = {
                    'top_students': top,
                    'bottom_students': bottom
                }
                logger.debug(f"Processed {len(ranked_students)} students for class {teacher_class.ClassName}")
        context['class_data'] = class_data
        if not class_data:
            context['no_subjects_configured'] = True
        
    return render(request, 'top_bottom_students.html', context)

from django.db.models import Avg
@effective_user_decorator
@login_required
def top_and_bottom_students(request):
    """
    Displays the top and bottom 10 students, either for a selected class or for all classes
    managed by the user and their subordinates, with actual class positions, based on RequiredSubject.
    Supports single class, multiple classes (combined), or all classes.
    """
    current_user = request.effective_user

    # Fetch all relevant user IDs
    subordinate_user_ids = Teacher.objects.filter(created_by=current_user).values_list('user_id', flat=True)
    all_user_ids = list(subordinate_user_ids) + [current_user.id]

    # Fetch classes, examinations, and display model
    teacher_classes = TeacherClass.objects.filter(
        user_id__in=all_user_ids, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')
    examinations = ExaminationName.objects.filter(user_id__in=all_user_ids)
    display = DisplayModel.objects.filter(user=current_user).first()

    # Get user selections from query parameters
    class_ids = request.GET.getlist('class_id')
    selected_class_ids = [int(cid) for cid in class_ids] if class_ids else []
    selected_exam_id = request.GET.get('examination_id')

    context = {
        'teacher_classes': teacher_classes,
        'examinations': examinations,
        'selected_class': None,
        'selected_classes': None,
        'selected_examination': None,
        'top_students': [],
        'bottom_students': [],
        'class_data': {},
        'selected_class_ids': selected_class_ids,
        'display': display,
        'no_subjects_configured': False,
        'class_ids_str': '',
    }

    if selected_exam_id:
        context['selected_examination'] = examinations.filter(id=selected_exam_id).first()

    if class_ids:
        selected_classes_qs = teacher_classes.filter(id__in=selected_class_ids)
        if selected_classes_qs.exists():
            if len(selected_class_ids) == 1:
                # Single Class View
                selected_class = selected_classes_qs.first()
                context['selected_class'] = selected_class
                
                # Get required subjects specific to this class
                required_subjects = RequiredSubject.objects.filter(user=current_user, teacherclass=selected_class)
                
                if not required_subjects.exists():
                    context['no_subjects_configured'] = True
                    logger.info(f"No required subjects configured for class {selected_class.ClassName}")
                    return render(request, 'top_bottom_students.html', context)
                
                required_subject_ids = required_subjects.values_list('subject_id', flat=True)
                
                # Base query for marks, filtered by class-specific required subjects
                marks_query = Mark.objects.filter(
                    user_id__in=all_user_ids,
                    subject__id__in=required_subject_ids,
                    teacherclass=selected_class
                ).select_related('student', 'teacherclass', 'examinationname')
                
                # Apply examination filter if selected
                if selected_exam_id:
                    marks_query = marks_query.filter(examinationname_id=selected_exam_id)
                
                # Calculate average marks for each student and sort by average
                student_averages = marks_query.values(
                    'student__id',
                    'student__fullName',
                    'student__sex',
                    'student__indexNumber'
                ).annotate(
                    avg_mark=Avg('marks')
                ).order_by('-avg_mark')

                # Assign actual positions
                ranked_students = []
                for position, student in enumerate(student_averages, 1):
                    ranked_students.append({
                        'position': position,
                        'student__id': student['student__id'],
                        'student__fullName': student['student__fullName'],
                        'student__sex': student['student__sex'],
                        'student__indexNumber': student['student__indexNumber'],
                        'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                    })

                context['top_students'] = ranked_students[:10]
                context['bottom_students'] = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])
                logger.debug(f"Processed {len(ranked_students)} students for class {selected_class.ClassName}")
            else:
                # Multiple Classes Combined View
                context['selected_classes'] = selected_classes_qs
                context['class_ids_str'] = ','.join(class_ids)
                
                # Get union of required subjects across selected classes
                required_subjects = RequiredSubject.objects.filter(
                    user=current_user, 
                    teacherclass__in=selected_classes_qs
                ).distinct()
                
                if not required_subjects.exists():
                    context['no_subjects_configured'] = True
                    logger.info(f"No required subjects configured for selected classes")
                    return render(request, 'top_bottom_students.html', context)
                
                required_subject_ids = required_subjects.values_list('subject_id', flat=True).distinct()
                
                # Base query for marks, filtered by union subjects and selected classes
                marks_query = Mark.objects.filter(
                    user_id__in=all_user_ids,
                    subject__id__in=required_subject_ids,
                    teacherclass__in=selected_classes_qs
                ).select_related('student', 'teacherclass__ClassName', 'examinationname')
                
                # Apply examination filter if selected
                if selected_exam_id:
                    marks_query = marks_query.filter(examinationname_id=selected_exam_id)
                
                # Calculate average marks for each student and sort by average
                student_averages = marks_query.values(
                    'student__id',
                    'student__fullName',
                    'student__sex',
                    'student__indexNumber',
                    'student__teacherclass__ClassName__class_name'
                ).annotate(
                    avg_mark=Avg('marks')
                ).order_by('-avg_mark')

                # Assign actual positions across combined classes
                ranked_students = []
                for position, student in enumerate(student_averages, 1):
                    ranked_students.append({
                        'position': position,
                        'student__id': student['student__id'],
                        'student__fullName': student['student__fullName'],
                        'student__sex': student['student__sex'],
                        'student__indexNumber': student['student__indexNumber'],
                        'student__class_name': student['student__teacherclass__ClassName__class_name'],
                        'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                    })

                context['top_students'] = ranked_students[:10]
                context['bottom_students'] = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])
                logger.debug(f"Processed {len(ranked_students)} students across {len(selected_classes_qs)} classes")
        else:
            # Invalid classes selected
            messages.warning(request, "Invalid classes selected.")
    else:
        # All Classes View (per class)
        class_data = {}
        for teacher_class in teacher_classes:
            # Get required subjects specific to this class
            required_subjects = RequiredSubject.objects.filter(user=current_user, teacherclass=teacher_class)
            
            if not required_subjects.exists():
                logger.info(f"No required subjects configured for class {teacher_class.ClassName} - skipping")
                continue
            
            required_subject_ids = required_subjects.values_list('subject_id', flat=True)
            
            # Base query for marks, filtered by class-specific required subjects
            marks_query = Mark.objects.filter(
                user_id__in=all_user_ids,
                subject__id__in=required_subject_ids,
                teacherclass=teacher_class
            ).select_related('student', 'teacherclass', 'examinationname')
            
            # Apply examination filter if selected
            if selected_exam_id:
                marks_query = marks_query.filter(examinationname_id=selected_exam_id)
            
            # Calculate average marks for each student and sort by average
            student_averages = marks_query.values(
                'student__id',
                'student__fullName',
                'student__sex',
                'student__indexNumber'
            ).annotate(
                avg_mark=Avg('marks')
            ).order_by('-avg_mark')

            ranked_students = []
            for position, student in enumerate(student_averages, 1):
                ranked_students.append({
                    'position': position,
                    'student__id': student['student__id'],
                    'student__fullName': student['student__fullName'],
                    'student__sex': student['student__sex'],
                    'student__indexNumber': student['student__indexNumber'],
                    'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                })

            top = ranked_students[:10]
            bottom = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])

            if top or bottom:
                class_data[teacher_class] = {
                    'top_students': top,
                    'bottom_students': bottom
                }
                logger.debug(f"Processed {len(ranked_students)} students for class {teacher_class.ClassName}")
        context['class_data'] = class_data
        if not class_data:
            context['no_subjects_configured'] = True
        
    return render(request, 'top_bottom_students.html', context)
from django.shortcuts import get_object_or_404
from django.contrib.auth.decorators import login_required
from django.http import HttpResponse
from django.db.models import Avg
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.graphics.charts.barcharts import VerticalBarChart
from reportlab.graphics.shapes import Drawing, String
from datetime import datetime
import logging

logger = logging.getLogger(__name__)

@login_required
def download_top_and_bottom_students_pdf(request, class_id=None, examination_id=None):
    current_user = request.user

    # Fetch all relevant user IDs
    from rps_app.models import Teacher  # Adjust import as needed
    subordinate_user_ids = Teacher.objects.filter(created_by=current_user).values_list('user_id', flat=True)
    all_user_ids = list(subordinate_user_ids) + [current_user.id]

    # Handle class_ids for multiple classes (combined)
    class_ids_str = request.GET.get('class_ids') if request.GET else None
    if class_ids_str:
        # Multiple classes combined
        class_id_list = [int(cid.strip()) for cid in class_ids_str.split(',') if cid.strip()]
        if not class_id_list:
            return HttpResponse("Invalid class IDs", status=400)
        from rps_app.models import TeacherClass
        teacher_classes = TeacherClass.objects.filter(
            id__in=class_id_list,
            user=current_user,
            academicclassyear__active_year=True
        ).select_related('ClassName', 'academicclassyear')
        if len(teacher_classes) != len(class_id_list):
            return HttpResponse("Some classes not found or unauthorized", status=403)
        is_combined = True
    elif class_id:
        # Single class
        from rps_app.models import TeacherClass
        teacher_classes = [get_object_or_404(TeacherClass, id=class_id, user=current_user, academicclassyear__active_year=True)]
        is_combined = False
    else:
        # All classes
        from rps_app.models import TeacherClass
        teacher_classes = TeacherClass.objects.filter(user=current_user, academicclassyear__active_year=True)
        is_combined = False

    # Fetch examination if provided
    from rps_app.models import ExaminationName
    examination = None
    if examination_id:
        examination = get_object_or_404(ExaminationName, id=examination_id, user=current_user)

    response = HttpResponse(content_type='application/pdf')
    if is_combined:
        combined_class_names = '_'.join([tc.ClassName.class_name.replace(' ', '_') for tc in teacher_classes if tc.ClassName.class_name])
        filename = f"top_bottom_combined_{combined_class_names}"
    else:
        filename = "top_bottom_students"
        if class_id and examination_id:
            filename += f"_{class_id}_{examination_id}"
        elif class_id:
            filename += f"_class_{class_id}_all_exams"
        elif examination_id:
            filename += f"_all_classes_exam_{examination_id}"
        else:
            filename += "_all"
    if examination and not is_combined:
        filename += f"_{examination.exam_name.replace(' ', '_')}"
    response['Content-Disposition'] = f'attachment; filename="{filename}.pdf"'

    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=20, leftMargin=20, topMargin=20, bottomMargin=20)
    elements = []
    styles = getSampleStyleSheet()

    # Center the title style
    title_style = styles['Title']
    title_style.alignment = TA_CENTER

    # Header (adjusted for case)
    header_text = "Top and Bottom 10 Students Performance"
    if is_combined:
        selected_classes_str = ', '.join([tc.ClassName.class_name or 'Unnamed Class' for tc in teacher_classes])
        header_text += f" (Combined Classes: {selected_classes_str})"
    elif not class_id and not examination_id:
        header_text += " (All Classes, All Examinations)"
    elif not class_id:
        header_text += " (All Classes)"
    elif not examination_id:
        header_text += " (All Examinations)"
    elements.append(Paragraph(header_text, title_style))
    elements.append(Spacer(1, 12))

    no_data = True  # Flag to check if any data is found

    if is_combined:
        # Combined logic for multiple classes
        # Get union of required subjects across selected classes
        from rps_app.models import RequiredSubject
        required_subjects = RequiredSubject.objects.filter(
            user=current_user,
            teacherclass__in=teacher_classes
        ).distinct('subject_id')

        if not required_subjects.exists():
            elements.append(Paragraph("No required subjects configured for the selected classes.", styles['Normal']))
        else:
            required_subject_ids = list(required_subjects.values_list('subject_id', flat=True).distinct())

            # Base query for marks across selected classes and union subjects
            from rps_app.models import Mark
            marks_query = Mark.objects.filter(
                user_id__in=all_user_ids,
                subject__id__in=required_subject_ids,
                teacherclass__in=teacher_classes,
            ).select_related('student', 'teacherclass__ClassName', 'examinationname')

            # Filter by examination if provided
            if examination:
                marks_query = marks_query.filter(examinationname=examination)

            # Calculate average marks for each student and sort by average
            student_averages = marks_query.values(
                'student__id',
                'student__fullName',
                'student__sex',
                'student__indexNumber',
                'student__teacherclass__ClassName__class_name'
            ).annotate(
                avg_mark=Avg('marks')
            ).order_by('-avg_mark')

            if student_averages.exists():
                no_data = False

                # Assign actual positions
                ranked_students = []
                for position, student in enumerate(student_averages, 1):
                    ranked_students.append({
                        'position': position,
                        'student__id': student['student__id'],
                        'student__fullName': student['student__fullName'],
                        'student__sex': student['student__sex'],
                        'student__indexNumber': student['student__indexNumber'],
                        'student__class_name': student['student__teacherclass__ClassName__class_name'],
                        'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                    })

                top_students = ranked_students[:10]
                bottom_students = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])

                # Top Students Table (with Class column for combined)
                if top_students:
                    elements.append(Paragraph("Top 10 Students (Combined)", styles['Heading2']))
                    table_data = [["Rank", "Name", "Sex", "Class", "Index Number", "Average Mark"]]
                    for student in top_students:
                        row = [
                            str(student['position']),
                            student['student__fullName'] or "Unnamed",
                            student['student__sex'] or "-",
                            student['student__class_name'] or "-",
                            student['student__indexNumber'] or "-",
                            f"{student['avg_mark']:.2f}"
                        ]
                        table_data.append(row)

                    table = Table(table_data, colWidths=[40, 150, 40, 100, 80, 70])
                    table.setStyle(TableStyle([
                        ('GRID', (0, 0), (-1, -1), 1, colors.black),
                        ('BACKGROUND', (0, 0), (-1, 0), colors.darkblue),
                        ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                        ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ]))
                    elements.append(table)
                    elements.append(Spacer(1, 12))

                # Bottom Students Table (with Class column for combined)
                if bottom_students:
                    elements.append(Paragraph("Bottom 10 Students (Combined)", styles['Heading2']))
                    table_data = [["Rank", "Name", "Sex", "Class", "Index Number", "Average Mark"]]
                    for student in bottom_students:
                        row = [
                            str(student['position']),
                            student['student__fullName'] or "Unnamed",
                            student['student__sex'] or "-",
                            student['student__class_name'] or "-",
                            student['student__indexNumber'] or "-",
                            f"{student['avg_mark']:.2f}"
                        ]
                        table_data.append(row)

                    table = Table(table_data, colWidths=[40, 150, 40, 100, 80, 70])
                    table.setStyle(TableStyle([
                        ('GRID', (0, 0), (-1, -1), 1, colors.black),
                        ('BACKGROUND', (0, 0), (-1, 0), colors.darkblue),
                        ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                        ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ]))
                    elements.append(table)
                    elements.append(Spacer(1, 24))

                # Chart for Top Students (Average Marks) - only add if top_students exist
                if top_students:
                    drawing = Drawing(400, 200)
                    bc = VerticalBarChart()
                    bc.x = 50
                    bc.y = 30
                    bc.height = 150
                    bc.width = 300
                    bc.data = [[student['avg_mark'] for student in top_students]]
                    bc.strokeColor = colors.black
                    bc.valueAxis.valueMin = 0
                    bc.valueAxis.valueMax = 100
                    bc.valueAxis.valueStep = 10
                    bc.categoryAxis.labels.boxAnchor = 'n'
                    bc.categoryAxis.categoryNames = [
                        (s['student__fullName'][:8] + '..') if len(s['student__fullName']) > 10 else s['student__fullName'] 
                        for s in top_students
                    ]
                    bc.bars[0].fillColor = colors.green
                    drawing.add(bc)
                    title = String(200, 180, "Top Students Average Marks (%)")
                    title.fontSize = 12
                    title.textAnchor = 'middle'
                    drawing.add(title)
                    elements.append(drawing)
                    elements.append(Spacer(1, 12))
    else:
        # Original logic for single class or all classes
        for teacherclass in teacher_classes:
            # Add class-specific header
            class_name = teacherclass.ClassName.class_name or 'Unnamed Class'
            elements.append(Paragraph(f"Class: {class_name}", styles['Normal']))
            if examination:
                elements.append(Paragraph(f"Examination: {examination.exam_name}", styles['Normal']))
            else:
                elements.append(Paragraph("Examination: All Examinations", styles['Normal']))
            elements.append(Spacer(1, 12))

            # Get required subjects specific to this class
            from rps_app.models import RequiredSubject
            required_subjects = RequiredSubject.objects.filter(user=current_user, teacherclass=teacherclass)
            
            if not required_subjects.exists():
                logger.warning(f"No required subjects configured for class {teacherclass.ClassName}")
                elements.append(Paragraph(f"No required subjects configured for {class_name}.", styles['Normal']))
                elements.append(Spacer(1, 12))
                continue
            
            required_subject_ids = required_subjects.values_list('subject_id', flat=True)
            
            # Base query for marks, filtered by class-specific required subjects
            from rps_app.models import Mark
            marks_query = Mark.objects.filter(
                user_id__in=all_user_ids,
                subject__id__in=required_subject_ids,
                teacherclass=teacherclass,
            ).select_related('student', 'teacherclass', 'examinationname')
            
            # Filter by examination if provided
            if examination:
                marks_query = marks_query.filter(examinationname=examination)
            
            # Calculate average marks for each student and sort by average
            student_averages = marks_query.values(
                'student__id',
                'student__fullName',
                'student__sex',
                'student__indexNumber'
            ).annotate(
                avg_mark=Avg('marks')
            ).order_by('-avg_mark')

            if not student_averages.exists():
                elements.append(Paragraph(f"No student performance data found for {class_name}.", styles['Normal']))
                elements.append(Spacer(1, 12))
                continue

            no_data = False

            # Assign actual positions
            ranked_students = []
            for position, student in enumerate(student_averages, 1):
                ranked_students.append({
                    'position': position,
                    'student__id': student['student__id'],
                    'student__fullName': student['student__fullName'],
                    'student__sex': student['student__sex'],
                    'student__indexNumber': student['student__indexNumber'],
                    'avg_mark': round(student['avg_mark'], 2) if student['avg_mark'] is not None else 0.00
                })

            top_students = ranked_students[:10]
            bottom_students = sorted(ranked_students[-10:], key=lambda x: x['avg_mark'])

            # Top Students Table
            if top_students:
                elements.append(Paragraph("Top 10 Students", styles['Heading2']))
                table_data = [["Rank", "Name", "Sex", "Index Number", "Average Mark"]]
                for student in top_students:
                    row = [
                        str(student['position']),
                        student['student__fullName'] or "Unnamed",
                        student['student__sex'] or "-",
                        student['student__indexNumber'] or "-",
                        f"{student['avg_mark']:.2f}"
                    ]
                    table_data.append(row)

                table = Table(table_data, colWidths=[40, 180, 50, 100, 80])
                table.setStyle(TableStyle([
                    ('GRID', (0, 0), (-1, -1), 1, colors.black),
                    ('BACKGROUND', (0, 0), (-1, 0), colors.darkblue),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ]))
                elements.append(table)
                elements.append(Spacer(1, 12))

            # Bottom Students Table
            if bottom_students:
                elements.append(Paragraph("Bottom 10 Students", styles['Heading2']))
                table_data = [["Rank", "Name", "Sex", "Index Number", "Average Mark"]]
                for student in bottom_students:
                    row = [
                        str(student['position']),
                        student['student__fullName'] or "Unnamed",
                        student['student__sex'] or "-",
                        student['student__indexNumber'] or "-",
                        f"{student['avg_mark']:.2f}"
                    ]
                    table_data.append(row)

                table = Table(table_data, colWidths=[40, 180, 50, 100, 80])
                table.setStyle(TableStyle([
                    ('GRID', (0, 0), (-1, -1), 1, colors.black),
                    ('BACKGROUND', (0, 0), (-1, 0), colors.darkblue),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ]))
                elements.append(table)
                elements.append(Spacer(1, 24))

            # Chart for Top Students (Average Marks) - only add if single class for simplicity
            if class_id and top_students:
                drawing = Drawing(400, 200)
                bc = VerticalBarChart()
                bc.x = 50
                bc.y = 30
                bc.height = 150
                bc.width = 300
                bc.data = [[student['avg_mark'] for student in top_students]]
                bc.strokeColor = colors.black
                bc.valueAxis.valueMin = 0
                bc.valueAxis.valueMax = 100
                bc.valueAxis.valueStep = 10
                bc.categoryAxis.labels.boxAnchor = 'n'
                bc.categoryAxis.categoryNames = [
                    (s['student__fullName'][:10] + '..') if len(s['student__fullName']) > 12 else s['student__fullName'] 
                    for s in top_students
                ]
                bc.bars[0].fillColor = colors.green
                drawing.add(bc)
                title = String(200, 180, "Top Students Average Marks (%)")
                title.fontSize = 12
                title.textAnchor = 'middle'
                drawing.add(title)
                elements.append(drawing)
                elements.append(Spacer(1, 12))

            elements.append(Spacer(1, 24))  # Space between classes

    if no_data:
        elements.append(Paragraph("No student performance data found across all selected criteria.", styles['Normal']))

    elements.append(Spacer(1, 12))
    elements.append(Paragraph(f"Generated on: {datetime.now().strftime('%Y-%m-%d %H:%M')}", styles['Normal']))
    doc.build(elements)
    return response


