@login_required
def download_full_report(request, class_id, grade_id, report_id=''):
    import gc
    from collections import defaultdict
    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    # Fetch core objects with optimized queries
    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    display = DisplayModel.objects.filter(id=report_id, user=request.user).first() if report_id else DisplayModel.objects.filter(user=request.user).first()

    # Validate examination IDs
    examination_ids = request.POST.getlist('exams')
    if not examination_ids:
        messages.error(request, "No examinations selected.")
        return redirect('all_student_marks')

    examination_names = ExaminationName.objects.filter(id__in=examination_ids, user=request.user)
    if not examination_names.exists():
        messages.error(request, "No valid examinations found for the selected IDs.")
        return redirect('all_student_marks')

    # Fetch subjects and required subjects
    if grading.is_primary:
        level = 'Primary'
    elif grading.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'
    required_subjects = RequiredSubject.objects.filter(user=request.user, level=level, teacherclass_id=class_id)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')

    # CompositeSubject logic for A-level
    composite = None
    component_ids_set = set()
    display_subjects_qs = subjects
    subjects_list_template = []  # Will be populated per exam if needed
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects_qs = subjects.exclude(id__in=component_ids_set)
            else:
                display_subjects_qs = subjects

    # Fetch students with optimized prefetching
    students = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch(
            'marks',
            queryset=Mark.objects.filter(
                subject__in=subjects,
                examinationname__in=examination_names
            ).select_related('subject', 'examinationname', 'user').prefetch_related('user__teacher_profile'),
            to_attr='prefetched_marks'
        ),
        'assigned_fees__fee', 'payfee__fee', 'student_focus__student_fcs'
    )

    # Validate teacher profile
    try:
        teacher_profile = Teacher.objects.get(user=request.user)
        creator = teacher_profile.created_by or request.user
    except Teacher.DoesNotExist:
        messages.error(request, "Your account is not linked to a valid teacher profile.")
        return redirect('teacher_dashboard')

    if not creator:
        messages.error(request, "You are not authorized to download reports.")
        return redirect('teacher_dashboard')

    # Fetch teacher names for marks
    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname__in=examination_names).select_related('user')
    user_ids = {mark.user_id for mark in all_marks if mark.user_id}
    teacher_map = {teacher.user_id: teacher.teacherName or teacher.user.username 
                   for teacher in Teacher.objects.filter(user__in=user_ids)}

    # Set grade_thresholds and other configs
    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E'
        }
        grade_points = {}  # Not used for primary
        exclude_subjects = set()
        min_subjects_for_division = None
        has_division = False
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
        min_subjects_for_division = 3
        has_division = True
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
        min_subjects_for_division = 7
        has_division = True

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    def get_grade(mark_value, grade_thresholds_dict, is_primary):
        if mark_value is None or mark_value == 0:
            return '-'
        for threshold, grade in sorted(grade_thresholds_dict.items(), reverse=True):
            if mark_value >= threshold:
                return grade
        return 'E' if is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'), 'B': colors.HexColor('#17a2b8'), 'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'), 'E': colors.HexColor('#fd7e14'), 'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'), '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent', 'B': 'Very Good', 'C': 'Good', 'D': 'Pass',
            'F': 'Fail', '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = min_subjects_for_division
        if num_valid_subjects < req_subs:
            return "Inc", 0
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    # Initialize PDF response
    response = HttpResponse(content_type='application/pdf')
    exam_suffix = "_selected_exams" if examination_names.count() > 1 else examination_names.first().exam_name.replace(' ', '_')
    filename = f"full_report_{teacherclass.ClassName.class_name or 'Unnamed_Class'}_{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    # Set up document with optimized margins
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []

    # Define consistent styles
    styles = getSampleStyleSheet()
    header_style = ParagraphStyle(name='Heading1', parent=styles['Heading1'], fontSize=12, alignment=TA_CENTER)
    subheader_style = ParagraphStyle(name='Heading2', parent=styles['Heading2'], fontSize=10, alignment=TA_CENTER)
    body_style = ParagraphStyle(name='BodyText', parent=styles['BodyText'], fontSize=7, alignment=TA_CENTER)
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=8)
    discount_style = ParagraphStyle(name='Discount', parent=styles['BodyText'], fontSize=8, textColor=colors.red, spaceAfter=4)
    summary_style = ParagraphStyle(name='Summary', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=8, spaceAfter=4)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=5, alignment=TA_CENTER, leading=6)

    # Define page numbering function
    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text=f"Page {page_num}")
        canvas.restoreState()

    # Load images once to optimize memory
    icon = None
    if display and display.image and os.path.exists(display.image.path) and os.access(display.image.path, os.R_OK):
        try:
            with PILImage.open(display.image.path) as img:
                img.verify()
            icon = RLImage(display.image.path, width=2*cm, height=2*cm)
            icon.hAlign = 'CENTER'
        except Exception as e:
            logger.error(f"Error loading DisplayModel image: {str(e)}")

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    sig_img = None
    stamp_img = None
    if source_doc:
        if source_doc.extracted_signature and os.path.exists(source_doc.extracted_signature.path):
            try:
                with PILImage.open(source_doc.extracted_signature.path) as img:
                    img.verify()
                sig_img = RLImage(source_doc.extracted_signature.path, width=3*cm, height=1.5*cm)
                sig_img.hAlign = 'LEFT'
            except Exception as e:
                logger.error(f"Error loading signature: {str(e)}")
        if source_doc.extracted_stamp and os.path.exists(source_doc.extracted_stamp.path):
            try:
                with PILImage.open(source_doc.extracted_stamp.path) as img:
                    img.verify()
                stamp_img = RLImage(source_doc.extracted_stamp.path, width=2.5*cm, height=2.5*cm)
                stamp_img.hAlign = 'RIGHT'
            except Exception as e:
                logger.error(f"Error loading stamp: {str(e)}")

    # Add header
    header_text = display.header if display else f"Full Academic and Financial Report for {teacherclass.ClassName.class_name or 'Unnamed Class'}"
    elements.append(Paragraph(header_text, header_style))
    elements.append(Spacer(1, 0.3*cm))
    academic_year = teacherclass.academicclassyear.academic_year_name if teacherclass.academicclassyear else 'N/A'
    exam_names = ", ".join(exam.exam_name for exam in examination_names)
    elements.append(Paragraph(display.body if display else f"Comprehensive Summary for {exam_names} - {academic_year}", subheader_style))
    elements.append(Spacer(1, 0.3*cm))
    if icon:
        elements.append(icon)
        elements.append(Spacer(1, 0.3*cm))

    # Check for data availability to prevent empty pages
    if not students.exists() or not subjects.exists() or not examination_names.exists():
        elements.append(Paragraph("No data available for this class or examinations.", body_style))
    else:
        # Process student data with optimization
        student_data_list = []
        for student in students:
            total_marks_per_exam = {}
            average_marks_per_exam = {}
            for examination_name in examination_names:
                exam_marks = [m for m in student.prefetched_marks if m.examinationname_id == examination_name.id]
                total_marks_per_exam[examination_name.id] = sum(m.marks for m in exam_marks) or 0
                count = len(exam_marks)
                average_marks_per_exam[examination_name.id] = (sum(m.marks for m in exam_marks) / count) if count > 0 else 0
            student_data_list.append({
                'student': student,
                'total_marks_per_exam': total_marks_per_exam,
                'average_marks_per_exam': average_marks_per_exam
            })
            del total_marks_per_exam, average_marks_per_exam  # Cleanup
        gc.collect()

        # Class-level academic summary for each examination
        total_students = len(student_data_list)
        exam_positions = {}
        for exam_idx, examination_name in enumerate(examination_names):
            if exam_idx > 0:
                elements.append(PageBreak())
            elements.append(Paragraph(f"Academic Results - {examination_name.exam_name}", subheader_style))
            elements.append(Spacer(1, 0.2*cm))

            # Prepare subjects_list for this exam (composite logic)
            subjects_list = []
            is_composite_active = grading.is_advance and composite and composite.allow_to_use
            for subj in display_subjects_qs:
                subjects_list.append({
                    'id': subj.id,
                    'nameSubject': subj.nameSubject,
                    'is_excluded': subj.id in exclude_subjects
                })
            if is_composite_active:
                subjects_list.append({
                    'id': 'composite',
                    'nameSubject': composite.subject_name,
                    'is_excluded': False
                })

            # Calculate student rankings
            student_totals = []
            for student_data in student_data_list:
                student = student_data['student']
                total_marks = student_data['total_marks_per_exam'].get(examination_name.id, 0)
                average_marks = student_data['average_marks_per_exam'].get(examination_name.id, 0)
                exam_marks = [m for m in student.prefetched_marks if m.examinationname_id == examination_name.id]
                student_marks_dict = {m.subject_id: m.marks for m in exam_marks}
                grades_for_division = []
                for subj_info in subjects_list:
                    if subj_info['id'] == 'composite':
                        component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                        valid_component_marks = [pm for pm in component_marks if pm > 0]
                        if valid_component_marks:
                            avg_mark = sum(valid_component_marks) / len(valid_component_marks)
                            composite_grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                            grades_for_division.append(composite_grade)
                        continue
                    subj_id = subj_info['id']
                    mark_value = student_marks_dict.get(subj_id, 0)
                    grade = get_grade(mark_value, grade_thresholds, grading.is_primary)
                    if not subj_info['is_excluded']:
                        grades_for_division.append(grade)
                # For allow_to_use=False, add averaged composite grade if components exist
                if grading.is_advance and composite and not composite.allow_to_use:
                    component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                    valid_component_marks = [pm for pm in component_marks if pm > 0]
                    if valid_component_marks:
                        avg_mark = sum(valid_component_marks) / len(valid_component_marks)
                        composite_grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                        # Insert as one entry (treat group as single for division)
                        grades_for_division.append(composite_grade)
                has_valid_marks = any(grade != '-' for grade in grades_for_division)
                student_totals.append((student, total_marks, average_marks, has_valid_marks, grades_for_division))
            student_totals.sort(key=lambda x: (-x[3], -x[1]))  # Sort by has_valid_marks, then total_marks

            # Store positions
            for pos, (student, _, _, _, _) in enumerate(student_totals, 1):
                exam_positions[(examination_name.id, student.id)] = pos

            # Build multi-level header
            header_row1 = [
                'Pos', 
                'Student Name', 
                'Sex', 
                'Index No'
            ]
            for s in subjects_list:
                header_row1.append(s['nameSubject'])
                header_row1.append('')  # Placeholder for span

            header_row1 += ['Total', 'Avg', 'Grade', 'Pos']
            if has_division:
                header_row1 += ['Div', 'Pts']

            header_row2 = ['', '', '', '']  # Empty for first four columns
            for _ in subjects_list:
                header_row2.append('M')
                header_row2.append('G')
            header_row2 += ['', '', '', '']
            if has_division:
                header_row2 += ['', '']

            table_data = [header_row1, header_row2]

            # Add spans for subject names in header_row1
            subject_start_col = 4
            table_style_commands = [
                ('SPAN', (0, 0), (0, 1)),  # Pos spans two rows
                ('SPAN', (1, 0), (1, 1)),  # Student Name
                ('SPAN', (2, 0), (2, 1)),  # Sex
                ('SPAN', (3, 0), (3, 1)),  # Index No
            ]
            for i in range(len(subjects_list)):
                start_col = subject_start_col + i * 2
                table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))  # Subject spans two columns

            subject_end_col = subject_start_col + len(subjects_list) * 2 - 1
            table_style_commands += [
                ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),  # Total
                ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),  # Avg
                ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),  # Grade
                ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),  # Pos
            ]
            if has_division:
                table_style_commands += [
                    ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),  # Div
                    ('SPAN', (subject_end_col + 6, 0), (subject_end_col + 6, 1)),  # Pts
                ]

            for i, (student, total_marks, average_marks, has_valid_marks, grades_for_division) in enumerate(student_totals, 1):
                row = [str(i), student.fullName or 'Unnamed', student.sex or '-', student.indexNumber or '-']
                student_marks_dict = {m.subject_id: m.marks for m in [mm for mm in student.prefetched_marks if mm.examinationname_id == examination_name.id]}
                for subj_info in subjects_list:
                    if subj_info['id'] == 'composite':
                        component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                        valid_component_marks = [pm for pm in component_marks if pm > 0]
                        mark_value = round(sum(valid_component_marks) / len(valid_component_marks), 2) if valid_component_marks else 0
                        grade = get_grade(mark_value, grade_thresholds, grading.is_primary)
                    else:
                        subj_id = subj_info['id']
                        mark_value = student_marks_dict.get(subj_id, 0)
                        grade = get_grade(mark_value, grade_thresholds, grading.is_primary)
                    mark_str = f"{mark_value:.2f}" if mark_value > 0 else '-'
                    row.append(mark_str)
                    row.append(grade)
                division, total_points = get_division(grades_for_division)
                row.extend([
                    f"{total_marks:.2f}" if total_marks > 0 else '-',
                    f"{average_marks:.2f}" if average_marks > 0 else '-',
                    get_grade(average_marks, grade_thresholds, grading.is_primary), str(i)
                ])
                if has_division:
                    row.extend([
                        division,
                        str(total_points) if total_points > 0 else '-'
                    ])
                table_data.append(row)

            page_width = A4[0] - 30
            num_final_cols = 4 + (2 if has_division else 0)
            base_width = page_width / (4 + len(subjects_list) * 2 + num_final_cols)
            col_widths = (
                [base_width * 0.5] +  # Pos
                [base_width * 2.5] +  # Name
                [base_width * 0.5] +  # Sex
                [base_width * 1.8] +  # Index
                [base_width * 0.45, base_width * 0.45] * len(subjects_list) +  # Mark, Grade
                [base_width * 0.6] * 4  # Total, Avg, Grade, Pos
            )
            if has_division:
                col_widths += [base_width * 0.6] * 2  # Div, Pts

            summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
            summary_table_style = TableStyle([
                ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
                ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTSIZE', (0, 0), (-1, -1), 5),
                ('LEADING', (0, 0), (-1, -1), 6),
                ('BOX', (0, 0), (-1, -1), 1, colors.black),
                ('LEFTPADDING', (0, 0), (-1, -1), 4),
                ('RIGHTPADDING', (0, 0), (-1, -1), 4),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ] + table_style_commands)

            # Apply grade colors per cell
            for row_idx, row in enumerate(table_data[2:], start=2):  # Start from body rows
                for subj_idx in range(len(subjects_list)):
                    grade_col = 4 + subj_idx * 2 + 1  # Grade column for this subject
                    grade = row[grade_col]
                    color = get_grade_color(grade)
                    summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                    summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

            summary_table.setStyle(summary_table_style)
            elements.append(KeepTogether(summary_table))
            elements.append(Spacer(1, 0.3*cm))

        # Individual student reports
        remark_ranges = RemarkRange.objects.filter(user=request.user)
        for student_idx, student_data in enumerate(student_data_list):
            if student_idx > 0:
                elements.append(PageBreak())
            student = student_data['student']
            student_elements = []

            # Student header
            header_row = [
                icon or Paragraph("", body_style),
                [
                    Paragraph(f"Academic and Financial Report for {student.fullName or 'Unnamed Student'}", header_style),
                    Spacer(1, 0.1*cm),
                    Paragraph(f"Class: {teacherclass.ClassName.class_name} | Academic Year: {academic_year}", subheader_style),
                    Spacer(1, 0.1*cm),
                    Paragraph(f"Examinations: {exam_names}", body_style)
                ],
                Paragraph(f"Student {student_idx + 1} of {total_students}", footer_style)
            ]
            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))
            student_elements.append(header_table)
            student_elements.append(Spacer(1, 0.3*cm))

            # Student information
            info_data = [
                [Paragraph("STUDENT INFORMATION", bold_style), "", Paragraph("ACADEMIC SUMMARY", bold_style)],
                [Paragraph(f"<b>Name:</b> {student.fullName or 'Unnamed'}", body_style), "",
                 Paragraph(f"<b>Examinations:</b> {exam_names}", body_style)],
                [Paragraph(f"<b>Index Number:</b> {student.indexNumber or '-'}", body_style), "",
                 Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style)],
                [Paragraph(f"<b>Gender:</b> {student.sex or '-'}", body_style), "",
                 Paragraph(f"<b>Academic Year:</b> {academic_year}", body_style)]
            ]
            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))
            student_elements.append(info_table)
            student_elements.append(Spacer(1, 0.3*cm))

            # Academic performance per examination
            for exam_idx, examination_name in enumerate(examination_names):
                if exam_idx > 0:
                    student_elements.append(Spacer(1, 0.3*cm))
                student_elements.append(Paragraph(f"Examination: {examination_name.exam_name}", subheader_style))
                student_elements.append(Spacer(1, 0.2*cm))

                # Prepare subjects_list for this exam
                subjects_list = []
                is_composite_active = grading.is_advance and composite and composite.allow_to_use
                for subj in display_subjects_qs:
                    subjects_list.append({
                        'id': subj.id,
                        'nameSubject': subj.nameSubject,
                        'is_excluded': subj.id in exclude_subjects
                    })
                if is_composite_active:
                    subjects_list.append({
                        'id': 'composite',
                        'nameSubject': composite.subject_name,
                        'is_excluded': False
                    })

                # Fetch marks and teacher names
                exam_marks = [m for m in student.prefetched_marks if m.examinationname_id == examination_name.id]
                student_marks_dict = {m.subject_id: m.marks for m in exam_marks}
                all_teachers_set = set(teacher_map.get(m.user_id, m.user.username if m.user else '-') for m in exam_marks)
                teachers_display = ', '.join(sorted(all_teachers_set)) if all_teachers_set else '-'
                student_elements.append(Paragraph(f"Data Entered/Modified By: {teachers_display}", bold_style))
                student_elements.append(Spacer(1, 0.2*cm))

                # Marks table
                marks_data = [['Subject', 'Mark', 'Grade', 'Teacher', 'Remarks']]
                grades_for_division = []
                subject_marks_per_subject = defaultdict(list)
                for mark in exam_marks:
                    subject_marks_per_subject[mark.subject_id].append(mark)
                for subj_info in subjects_list:
                    subj_id = subj_info['id']
                    if subj_id == 'composite':
                        component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                        valid_component_marks = [pm for pm in component_marks if pm > 0]
                        if valid_component_marks:
                            subject_total = round(sum(valid_component_marks) / len(valid_component_marks), 2)
                            grade = get_grade(subject_total, grade_thresholds, grading.is_primary)
                            # Collect unique teachers for composite components
                            teachers_set = set()
                            for sid in component_ids_set:
                                subj_marks = subject_marks_per_subject[sid]
                                for m in subj_marks:
                                    teachers_set.add(teacher_map.get(m.user_id, m.user.username if m.user else '-'))
                            teachers_display_sub = ', '.join(sorted(teachers_set)) if teachers_set else '-'
                            if subject_total > 0 and teachers_display_sub != '-':
                                remark = get_remark(grade)
                                grade_color = get_grade_color(grade)
                                marks_data.append([
                                    Paragraph(subj_info['nameSubject'] or 'Unnamed', table_text_style),
                                    Paragraph(f"{subject_total:.2f}", small_style),
                                    Paragraph(grade, ParagraphStyle(name=f'Grade{grade}', parent=small_style, textColor=grade_color)),
                                    Paragraph(teachers_display_sub, table_text_style),
                                    Paragraph(remark, table_text_style)
                                ])
                            if not subj_info['is_excluded']:
                                grades_for_division.append(grade)
                        continue
                    subject_marks = subject_marks_per_subject[subj_id]
                    if subject_marks:  # Only if marks exist (teacher != '-')
                        subject_total = sum(m.marks for m in subject_marks)
                        grade = get_grade(subject_total, grade_thresholds, grading.is_primary)
                        teacher_names_set = set()
                        for m in subject_marks:
                            if m.user:
                                teacher_name = teacher_map.get(m.user_id, m.user.username)
                                teacher_names_set.add(teacher_name)
                        teachers_display_sub = ', '.join(teacher_names_set) if teacher_names_set else '-'
                        if subject_total > 0 and teachers_display_sub != '-':
                            remark = get_remark(grade)
                            grade_color = get_grade_color(grade)
                            marks_data.append([
                                Paragraph(subj_info['nameSubject'] or 'Unnamed', table_text_style),
                                Paragraph(f"{subject_total:.2f}", small_style),
                                Paragraph(grade, ParagraphStyle(name=f'Grade{grade}', parent=small_style, textColor=grade_color)),
                                Paragraph(teachers_display_sub, table_text_style),
                                Paragraph(remark, table_text_style)
                            ])
                        # Append to grades_for_division only if not primary, not excluded, and marks exist
                        if not grading.is_primary and not subj_info['is_excluded']:
                            grades_for_division.append(grade)
                # For allow_to_use=False, add averaged composite grade if components exist
                if grading.is_advance and composite and not composite.allow_to_use:
                    component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                    valid_component_marks = [pm for pm in component_marks if pm > 0]
                    if valid_component_marks:
                        avg_mark = sum(valid_component_marks) / len(valid_component_marks)
                        composite_grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                        grades_for_division.append(composite_grade)
                del subject_marks_per_subject  # Cleanup

                # Only add "No subjects" row if not primary grading (for primary, just show empty table if no marks)
                if len(marks_data) == 1 and not grading.is_primary:
                    marks_data.append([
                        Paragraph('No subjects with marks available', table_text_style),
                        Paragraph('-', small_style),
                        Paragraph('-', small_style),
                        Paragraph('-', table_text_style),
                        Paragraph('-', table_text_style)
                    ])

                page_width = A4[0] - 30
                col_widths = [page_width * 0.35, page_width * 0.15, page_width * 0.15, page_width * 0.20, page_width * 0.15]
                marks_table = Table(marks_data, colWidths=col_widths, repeatRows=1)
                marks_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
                ]))
                student_elements.append(marks_table)
                student_elements.append(Spacer(1, 0.2*cm))

                # Academic summary
                total_marks = student_data['total_marks_per_exam'].get(examination_name.id, 0)
                average_marks = student_data['average_marks_per_exam'].get(examination_name.id, 0)
                overall_grade = get_grade(average_marks, grade_thresholds, grading.is_primary)
                division, total_points = get_division(grades_for_division)
                pos = exam_positions.get((examination_name.id, student.id), '-')
                if has_division:
                    summary_data = [
                        [
                            Paragraph(f"Total Marks: {total_marks:.2f}" if total_marks > 0 else 'Total Marks: -', bold_style),
                            Paragraph(f"Average: {average_marks:.2f}" if average_marks > 0 else 'Average: -', bold_style),
                            Paragraph(f"Overall Grade: {overall_grade}", bold_style)
                        ],
                        [
                            Paragraph(f"Division: {division}", bold_style),
                            Paragraph(f"Total Points: {total_points if total_points > 0 else '-'}", bold_style),
                            Paragraph(f"Position: {pos}/{total_students}", bold_style)
                        ]
                    ]
                else:
                    summary_data = [
                        [
                            Paragraph(f"Total Marks: {total_marks:.2f}" if total_marks > 0 else 'Total Marks: -', bold_style),
                            Paragraph(f"Average: {average_marks:.2f}" if average_marks > 0 else 'Average: -', bold_style),
                            Paragraph(f"Overall Grade: {overall_grade}<br/>Position: {pos}/{total_students}", bold_style)
                        ]
                    ]
                summary_col_widths = [page_width * 0.33, page_width * 0.33, page_width * 0.34]
                summary_table = Table(summary_data, colWidths=summary_col_widths)
                summary_table.setStyle(TableStyle([
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('ALIGN', (0, 0), (-1, -1), 'LEFT'),
                    ('LEFTPADDING', (0, 0), (-1, -1), 5),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 5),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                    ('FONTNAME', (0, 0), (-1, -1), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                ]))
                student_elements.append(summary_table)
                student_elements.append(Spacer(1, 0.2*cm))

                # General remark
                remark = "No remark available"
                for r_range in remark_ranges:
                    if r_range.contains(average_marks or 0):
                        remark = r_range.remark
                        break
                student_elements.append(Paragraph(f"General Comment: {remark}", ParagraphStyle(
                    name='Comment', parent=body_style, fontSize=9, textColor=colors.HexColor('#2c3e50'),
                    backColor=colors.HexColor('#f8f9fa'), borderPadding=8, alignment=TA_LEFT
                )))
                student_elements.append(Spacer(1, 0.3*cm))

            # Fee report (NO CHANGES)
            student_elements.append(Paragraph("Fee Report", subheader_style))
            student_elements.append(Spacer(1, 0.2*cm))
            student_fees = student.assigned_fees.all()
            discounts = Discount.objects.filter(student=student, teacherclass=teacherclass).select_related('fee')
            payments = student.payfee.all().order_by('-date_paid')
            student_focus = student.student_focus.first()
            initial_payment = Decimal('0.00')
            if student_focus:
                student_registration = StudentRegistration.objects.filter(studentfocus=student_focus).first()
                if student_registration and student_registration.initial_payment:
                    initial_payment = student_registration.initial_payment

            if not student_fees.exists():
                student_elements.append(Paragraph("No fees assigned.", body_style))
                student_elements.append(Spacer(1, 0.2*cm))
            else:
                col_widths_fees = [page_width * 0.25, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.15]
                fee_data = [['Fee Name', 'Required', 'Discount', 'Adjusted', 'Paid', 'Balance', 'Status']]
                total_required = total_paid_all = total_discounted = total_balance = Decimal('0.00')
                for sf in student_fees:
                    fee = sf.fee
                    discount = discounts.filter(fee=fee).first()
                    discount_amount = discount.discount_amount if discount else Decimal('0.00')
                    adjusted_required = sf.amount_required - discount_amount
                    total_paid = payments.filter(fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal('0.00')
                    balance = adjusted_required - total_paid
                    status = 'Paid' if balance <= 0 else 'Pending'
                    fee_data.append([
                        Paragraph(fee.fee_name, body_style),
                        Paragraph(f"{sf.amount_required:.2f}", body_style),
                        Paragraph(f"{discount_amount:.2f}", body_style),
                        Paragraph(f"{adjusted_required:.2f}", body_style),
                        Paragraph(f"{total_paid:.2f}", body_style),
                        Paragraph(f"{balance:.2f}", body_style),
                        Paragraph(status, body_style)
                    ])
                    total_required += adjusted_required
                    total_paid_all += total_paid
                    total_balance += balance
                    total_discounted += discount_amount

                fee_data.append([
                    Paragraph('TOTAL', bold_style),
                    Paragraph(f"{total_required:.2f}", bold_style),
                    Paragraph(f"{total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_required:.2f}", bold_style),
                    Paragraph(f"{total_paid_all:.2f}", bold_style),
                    Paragraph(f"{total_balance:.2f}", bold_style),
                    Paragraph('', bold_style)
                ])

                fee_table = Table(fee_data, colWidths=col_widths_fees, repeatRows=1)
                fee_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -2), colors.HexColor('#f0f4f8')),
                    ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                    ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#d0d9e5')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(fee_table)
                summary = f"Total Required: {total_required:.2f} | Total Discount: {total_discounted:.2f} | Total Paid: {total_paid_all:.2f} | Total Balance: {total_balance:.2f} | Initial Payment: {initial_payment:.2f}"
                student_elements.append(Paragraph(summary, discount_style if total_discounted > 0 else summary_style))
                student_elements.append(Spacer(1, 0.2*cm))

                # Payment records
                student_elements.append(Paragraph("Payment Records", subheader_style))
                payment_data = [['Fee Name', 'Date', 'Amount', 'Payer Account', 'Description']]
                for payment in payments:
                    payment_data.append([
                        Paragraph(payment.fee.fee_name, body_style),
                        Paragraph(payment.date_paid.strftime('%Y-%m-%d') if payment.date_paid else '-', body_style),
                        Paragraph(f"{payment.amount_paid:.2f}", body_style),
                        Paragraph(payment.payer_account_no or '-', body_style),
                        Paragraph(payment.description or '-', body_style)
                    ])
                if not payments.exists():
                    payment_data.append(['No payment records found', '-', '-', '-', '-'])

                payment_table = Table(payment_data, colWidths=[page_width * 0.25, page_width * 0.15, page_width * 0.15, page_width * 0.25, page_width * 0.25], repeatRows=1)
                payment_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -1), colors.HexColor('#f0f4f8')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(payment_table)
                student_elements.append(Spacer(1, 0.3*cm))

            # Signature and stamp
            signature_row = []
            if sig_img:
                signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            
            signature_row.append(Spacer(1, 2*cm))
            
            if stamp_img:
                signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            
            signature_table = Table([signature_row], colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))
            
            student_elements.append(signature_table)
            student_elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

            elements.append(KeepTogether(student_elements))

        # General fee report (NO CHANGES)
        has_fees = any(student.assigned_fees.exists() for student in students)
        if has_fees:
            elements.append(PageBreak())
            elements.append(Paragraph("General Fee Report", subheader_style))
            elements.append(Spacer(1, 0.3*cm))
            for i, student_data in enumerate(student_data_list):
                if i > 0:
                    elements.append(PageBreak())
                student = student_data['student']
                student_elements = []
                discounts = Discount.objects.filter(student=student, teacherclass=teacherclass).select_related('fee')
                has_discount = discounts.exists()
                student_label = f"Student: {student.fullName or 'Unnamed'} (Index: {student.indexNumber or '-'})" + \
                               (f" <font color='red'>*Discounted*</font>" if has_discount else "")
                student_elements.append(Paragraph(student_label, subheader_style))
                student_elements.append(Spacer(1, 0.2*cm))

                student_fees = student.assigned_fees.all()
                if not student_fees.exists():
                    student_elements.append(Paragraph("No fees assigned.", body_style))
                    student_elements.append(Spacer(1, 0.2*cm))
                    elements.append(KeepTogether(student_elements))
                    continue

                fee_data = [['Fee Name', 'Required', 'Discount', 'Adjusted', 'Paid', 'Balance', 'Status']]
                total_required = total_paid_all = total_discounted = total_balance = Decimal('0.00')
                payments = student.payfee.all()
                for sf in student_fees:
                    fee = sf.fee
                    discount = discounts.filter(fee=fee).first()
                    discount_amount = discount.discount_amount if discount else Decimal('0.00')
                    adjusted_required = sf.amount_required - discount_amount
                    total_paid = payments.filter(fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal('0.00')
                    balance = adjusted_required - total_paid
                    status = 'Paid' if balance <= 0 else 'Pending'
                    fee_data.append([
                        Paragraph(fee.fee_name, body_style),
                        Paragraph(f"{sf.amount_required:.2f}", body_style),
                        Paragraph(f"{discount_amount:.2f}", body_style),
                        Paragraph(f"{adjusted_required:.2f}", body_style),
                        Paragraph(f"{total_paid:.2f}", body_style),
                        Paragraph(f"{balance:.2f}", body_style),
                        Paragraph(status, body_style)
                    ])
                    total_required += adjusted_required
                    total_paid_all += total_paid
                    total_balance += balance
                    total_discounted += discount_amount

                fee_data.append([
                    Paragraph('TOTAL', bold_style),
                    Paragraph(f"{total_required:.2f}", bold_style),
                    Paragraph(f"{total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_required:.2f}", bold_style),
                    Paragraph(f"{total_paid_all:.2f}", bold_style),
                    Paragraph(f"{total_balance:.2f}", bold_style),
                    Paragraph('', bold_style)
                ])

                fee_table = Table(fee_data, colWidths=[page_width * 0.25, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.15], repeatRows=1)
                fee_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -2), colors.HexColor('#f0f4f8')),
                    ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                    ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#d0d9e5')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(fee_table)
                summary = f"Total Required: {total_required:.2f} | Total Discount: {total_discounted:.2f} | Total Paid: {total_paid_all:.2f} | Total Balance: {total_balance:.2f} | Initial Payment: {initial_payment:.2f}"
                student_elements.append(Paragraph(summary, discount_style if total_discounted > 0 else summary_style))
                student_elements.append(Spacer(1, 0.2*cm))

                elements.append(KeepTogether(student_elements))

    # Final footer
    elements.append(Spacer(1, 0.3*cm))
    elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

    # Generate PDF
    logger.debug(f"Memory usage before PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        logger.debug(f"Memory usage after PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
        messages.success(request, 'Full report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')


@login_required
def download_combined_pdf(request, class_id, grade_id, report_id='', examination_name_id=None):
    import gc
    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    display = DisplayModel.objects.filter(id=report_id, user=request.user).first() if report_id else DisplayModel.objects.filter(user=request.user).first()
    
    examination_name_id = request.POST.get('examination_id', examination_name_id or request.session.get('selected_examination_id'))
    if not examination_name_id:
        messages.error(request, "No examination selected.")
        return redirect('all_student_marks')
    
    examination_name = get_object_or_404(ExaminationName, id=examination_name_id, user=request.user)
    
    if not hasattr(request, 'creator') or not request.creator:
        logger.warning(f"Creator not set for user {request.user.username} in download_combined_pdf, defaulting to user")
        creator = request.user
    else:
        creator = request.creator
        logger.debug(f"Generating PDF for user {request.user.username}, creator {creator.username}")

    if grading.is_primary:
        level = 'Primary'
    elif grading.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'
    required_subjects = RequiredSubject.objects.filter(user=request.user, level=level,teacherclass_id=class_id)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')

    # CompositeSubject logic for A-level
    composite = None
    component_ids_set = set()
    display_subjects_qs = subjects
    subjects_list_template = []  # Will be populated
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects_qs = subjects.exclude(id__in=component_ids_set)
            else:
                display_subjects_qs = subjects

    mark_filter = models_Q(subject__in=subjects, examinationname=examination_name)
    
    students = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(mark_filter).select_related('subject', 'examinationname', 'user'), to_attr='prefetched_marks'),
        Prefetch('assigned_fees', queryset=StudentFee.objects.filter(teacherclass=teacherclass).select_related('fee')),
        Prefetch('payfee', queryset=PayFee.objects.select_related('fee')),
        Prefetch('student_focus', queryset=StudentFocus.objects.prefetch_related('student_fcs'))
    )

    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname=examination_name).select_related('user')
    user_ids = {mark.user_id for mark in all_marks if mark.user_id}
    teacher_map = {teacher.user_id: teacher.teacherName or teacher.user.username 
                   for teacher in Teacher.objects.filter(user__in=user_ids)}
    
    response = HttpResponse(content_type='application/pdf')
    exam_suffix = f"_{examination_name.exam_name.replace(' ', '_')}"
    filename = f"combined_report_{teacherclass.ClassName.class_name or 'Unnamed_Class'}{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=8)
    discount_style = ParagraphStyle(name='Discount', parent=styles['BodyText'], fontSize=9, textColor=colors.red, spaceAfter=4)
    summary_style = ParagraphStyle(name='Summary', parent=styles['BodyText'], fontSize=9, fontName='Helvetica-Bold', spaceAfter=4)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=6, alignment=TA_CENTER, leading=7)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 6

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    # Set grade_thresholds and other configs
    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E'
        }
        grade_points = {}  # Not used for primary
        exclude_subjects = set()
        min_subjects_for_division = None
        has_division = False
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
        min_subjects_for_division = 3
        has_division = True
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
        min_subjects_for_division = 7
        has_division = True

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    def get_grade(mark_value, grade_thresholds_dict, is_primary):
        if mark_value is None or mark_value == 0:
            return '-'
        for threshold, grade in sorted(grade_thresholds_dict.items(), reverse=True):
            if mark_value >= threshold:
                return grade
        return 'E' if is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent',
            'B': 'Very Good',
            'C': 'Good',
            'D': 'Pass',
            'F': 'Fail',
            '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = min_subjects_for_division
        if num_valid_subjects < req_subs:
            return "Inc", '-'
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    header_text = display.header if display else f"Combined Report for {teacherclass.ClassName.class_name or 'Unnamed Class'} - {examination_name.exam_name}"
    elements.append(Paragraph(header_text, header_style))
    elements.append(Spacer(1, 0.3*cm))
    academic_year = teacherclass.academicclassyear.academic_year_name if teacherclass.academicclassyear else 'N/A'
    elements.append(Paragraph(display.body if display else f"Academic and Financial Summary - {teacherclass.ClassName.class_name} ({academic_year})", subheader_style))
    elements.append(Spacer(1, 0.3*cm))

    if display and display.image:
        try:
            icon = RLImage(display.image.path, width=2*cm, height=2*cm)
            icon.hAlign = 'CENTER'
            elements.append(icon)
            elements.append(Spacer(1, 0.3*cm))
        except Exception as e:
            logger.error(f"Error loading DisplayModel image: {e}")

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.filter(user=request.user)

    if not students.exists() or not subjects.exists():
        elements.append(Paragraph("No data available for this class.", body_style))
    else:
        # Prepare subjects_list
        subjects_list = []
        is_composite_active = grading.is_advance and composite and composite.allow_to_use
        for subj in display_subjects_qs:
            subjects_list.append({
                'id': subj.id,
                'nameSubject': subj.nameSubject,
                'is_excluded': subj.id in exclude_subjects
            })
        if is_composite_active:
            subjects_list.append({
                'id': 'composite',
                'nameSubject': composite.subject_name,
                'is_excluded': False
            })

        elements.append(Paragraph("Academic Results", subheader_style))
        student_data = []
        for student in students:
            exam_marks = [m for m in student.prefetched_marks]
            student_marks_dict = {m.subject_id: m.marks for m in exam_marks}
            total_marks = sum(student_marks_dict.values()) or 0
            count = len([v for v in student_marks_dict.values() if v > 0])
            average_marks = (total_marks / count) if count > 0 else 0
            marks_list = []
            grades_for_division = []
            subject_marks_per_subject = defaultdict(list)
            for m in exam_marks:
                subject_marks_per_subject[m.subject_id].append(m)
            for subj_info in subjects_list:
                subj_id = subj_info['id']
                if subj_id == 'composite':
                    component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                    valid_component_marks = [pm for pm in component_marks if pm > 0]
                    if valid_component_marks:
                        subject_total = round(sum(valid_component_marks) / len(valid_component_marks), 2)
                        grade = get_grade(subject_total, grade_thresholds, grading.is_primary)
                        # Collect unique teachers for composite
                        teachers_set = set()
                        for sid in component_ids_set:
                            subj_marks = subject_marks_per_subject[sid]
                            for m in subj_marks:
                                teachers_set.add(teacher_map.get(m.user_id, m.user.username if m.user else '-'))
                        teachers_display = ', '.join(teachers_set) if teachers_set else '-'
                        marks_list.append({
                            'subject_id': subj_id,
                            'subject_name': subj_info['nameSubject'],
                            'mark': subject_total,
                            'grade': grade,
                            'is_excluded': subj_info['is_excluded'],
                            'teacher_name': teachers_display
                        })
                        if not subj_info['is_excluded']:
                            grades_for_division.append(grade)
                    continue
                subject_marks = subject_marks_per_subject[subj_id]
                subject_total = sum(m.marks for m in subject_marks) if subject_marks else 0
                if subject_marks:  # Only if marks exist (teacher != '-')
                    grade = get_grade(subject_total, grade_thresholds, grading.is_primary)
                    teacher_names = set()
                    for m in subject_marks:
                        if m.user:
                            teacher_name = teacher_map.get(m.user_id, m.user.username)
                            teacher_names.add(teacher_name)
                    teachers_display = ', '.join(teacher_names) if teacher_names else '-'
                    marks_list.append({
                        'subject_id': subj_id,
                        'subject_name': subj_info['nameSubject'],
                        'mark': subject_total,
                        'grade': grade,
                        'is_excluded': subj_info['is_excluded'],
                        'teacher_name': teachers_display
                    })
                    # Append to grades_for_division only if not primary, not excluded, and marks exist
                    if not grading.is_primary and not subj_info['is_excluded']:
                        grades_for_division.append(grade)
            # For allow_to_use=False, add averaged composite grade if components exist
            if grading.is_advance and composite and not composite.allow_to_use:
                component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                valid_component_marks = [pm for pm in component_marks if pm > 0]
                if valid_component_marks:
                    avg_mark = sum(valid_component_marks) / len(valid_component_marks)
                    composite_grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                    grades_for_division.append(composite_grade)
            del subject_marks_per_subject  # Clean up per student
            division, total_points = get_division(grades_for_division)
            student_data.append({
                'student_obj': student,  # Add the actual Student object
                'id': student.id,
                'fullName': student.fullName or 'Unnamed Student',
                'sex': student.sex or '-',
                'indexNumber': student.indexNumber or '-',
                'marks': marks_list,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'grade': get_grade(average_marks, grade_thresholds, grading.is_primary),
                'division': division,
                'total_points': total_points,
                'has_valid_marks': any(grade != '-' for grade in grades_for_division)
            })
            del marks_list, grades_for_division  # Additional cleanup
        # Sort by has_valid_marks desc, then average_marks desc
        student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))
        gc.collect()

        total_students = len(student_data)

        # CLASS PERFORMANCE SUMMARY section
        elements.append(Paragraph("Academic Results", subheader_style))
        elements.append(Spacer(1, 0.3*cm))

        # Build multi-level header conditionally (exclude Div/Pts for primary)
        header_row1 = [
            'Pos', 
            'Student Name', 
            'Sex', 
            'Index No'
        ]
        for s in subjects_list:
            header_row1.append(s['nameSubject'])
            header_row1.append('')  # Placeholder for span

        header_row1 += ['Total', 'Avg', 'Grade', 'Pos']
        if has_division:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '']  # Empty for first four columns
        for _ in subjects_list:
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '', '']
        if has_division:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans for subject names in header_row1
        subject_start_col = 4
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),  # Pos spans two rows
            ('SPAN', (1, 0), (1, 1)),  # Student Name
            ('SPAN', (2, 0), (2, 1)),  # Sex
            ('SPAN', (3, 0), (3, 1)),  # Index No
        ]
        for i in range(len(subjects_list)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))  # Subject spans two columns

        subject_end_col = subject_start_col + len(subjects_list) * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),  # Total
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),  # Avg
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),  # Grade
            ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),  # Pos
        ]
        if has_division:
            table_style_commands += [
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),  # Div
                ('SPAN', (subject_end_col + 6, 0), (subject_end_col + 6, 1)),  # Pts
            ]

        for i, student_dict in enumerate(student_data, 1):
            row = [
                str(i), 
                student_dict['fullName'], 
                student_dict['sex'], 
                student_dict['indexNumber']
            ]
            # Reconstruct student_marks_dict for row building
            exam_marks = [m for m in student_dict['student_obj'].prefetched_marks]
            student_marks_dict = {m.subject_id: m.marks for m in exam_marks}
            for subj_info in subjects_list:
                if subj_info['id'] == 'composite':
                    component_marks = [student_marks_dict.get(sid, 0) for sid in component_ids_set]
                    valid_component_marks = [pm for pm in component_marks if pm > 0]
                    mark_value = round(sum(valid_component_marks) / len(valid_component_marks), 2) if valid_component_marks else 0
                    grade = get_grade(mark_value, grade_thresholds, grading.is_primary)
                else:
                    subj_id = subj_info['id']
                    mark_value = student_marks_dict.get(subj_id, 0)
                    grade = get_grade(mark_value, grade_thresholds, grading.is_primary)
                mark_str = f"{mark_value:.2f}" if mark_value > 0 else '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student_dict['total_marks']:.2f}" if student_dict['total_marks'] > 0 else '-',
                f"{student_dict['average_marks']:.2f}" if student_dict['average_marks'] > 0 else '-',
                student_dict['grade'],
                str(i)
            ])
            if has_division:
                total_pts_display = str(student_dict['total_points']) if student_dict['total_points'] != '-' else '-'
                row.extend([
                    student_dict['division'],
                    total_pts_display
                ])
            table_data.append(row)

        # Calculate column widths (exclude Div/Pts for primary)
        available_width = A4[0] - 30
        num_final_cols = 4 + (2 if has_division else 0)
        base_width = available_width / (4 + len(subjects_list) * 2 + num_final_cols)  # Adjust for columns
        col_widths = (
            [base_width * 0.5] +  # Pos
            [base_width * 2.5] +  # Name
            [base_width * 0.5] +  # Sex
            [base_width * 1.8] +  # Index
            [base_width * 0.7, base_width * 0.6] * len(subjects_list) +  # Mark, Grade
            [base_width * 0.8] * 4  # Total, Avg, Grade, Pos
        )
        if has_division:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors per cell
        for row_idx, row in enumerate(table_data[2:], start=2):  # Start from body rows
            for subj_idx in range(len(subjects_list)):
                grade_col = 4 + subj_idx * 2 + 1  # Grade column for this subject
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 0.3*cm))
        elements.append(PageBreak())

        total_students = len(student_data)
        for i, student_dict in enumerate(student_data, 1):
            if i > 1:
                elements.append(PageBreak())
            
            # Individual report header
            individual_header = []
            
            # Header with school logo and info
            header_row = []
            if display and display.image:
                try:
                    school_icon = RLImage(display.image.path, width=2*cm, height=2*cm)
                    school_icon.hAlign = 'CENTER'
                    header_row.append(school_icon)
                except Exception as e:
                    logger.error(f"Error loading DisplayModel image: {str(e)}")
                    header_row.append(Paragraph("", body_style))
            else:
                header_row.append(Paragraph("", body_style))
            
            center_content = [
                Paragraph(f"Report Form FOR: {student_dict['fullName']}", header_style),
                Spacer(1, 0.3*cm),
                Paragraph(f"{teacherclass.ClassName.class_name} • {examination_name.exam_name}", subheader_style),
                Spacer(1, 0.2*cm),
                Paragraph(f"Academic Year: {academic_year}", body_style)
            ]
            
            header_row.append(center_content)
            header_row.append(Paragraph(f"Page {i} of {total_students}", footer_style))
            
            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))
            
            elements.append(header_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # Student information section with modern card-like appearance (exclude division for primary)
            left_column = [
                Paragraph("STUDENT INFORMATION", bold_style),
                Paragraph(f"<b>Name:</b> {student_dict['fullName']}", body_style),
                Paragraph(f"<b>Index Number:</b> {student_dict['indexNumber']}", body_style),
                Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style),
            ]
            right_column = [
                Paragraph("ACADEMIC SUMMARY", bold_style),
                Paragraph(f"<b>Total Marks:</b> {student_dict['total_marks']:.0f}" if student_dict['total_marks'] > 0 else "<b>Total Marks:</b> -", body_style),
                Paragraph(f"<b>Average:</b> {student_dict['average_marks']:.1f}" if student_dict['average_marks'] > 0 else "<b>Average:</b> -", body_style),
                Paragraph(f"<b>Overall Grade:</b> {student_dict['grade']}", body_style),
            ]
            
            if grading.is_primary:
                # For primary, append gender to the class paragraph
                left_column[3] = Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}<br/><b>Gender:</b> {student_dict['sex']}", body_style)
            else:
                # For non-primary, add separate rows for gender and division
                left_column.append(Paragraph(f"<b>Gender:</b> {student_dict['sex']}", body_style))
                right_column.append(Paragraph(f"<b>Division:</b> {student_dict['division']}", body_style))
            
            info_data = []
            for l, r in zip(left_column, right_column):
                info_data.append([
                    l,
                    "",
                    r
                ])
            
            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))
            
            elements.append(info_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # Subject performance table
            elements.append(Paragraph("SUBJECT PERFORMANCE DETAILS", subheader_style))
            elements.append(Spacer(1, 0.3*cm))
            
            marks_header = [
                Paragraph('SUBJECT', table_text_style),
                Paragraph('MARK', table_text_style),
                Paragraph('GRADE', table_text_style),
                Paragraph('TEACHER', table_text_style),
                Paragraph('REMARKS', table_text_style)
            ]
            
            marks_table_data = [marks_header]
            valid_marks = [m for m in student_dict['marks'] if m['mark'] > 0 and m['teacher_name'] != '-']
            
            for mark_info in valid_marks:
                grade_color = get_grade_color(mark_info['grade'])
                remark = get_remark(mark_info['grade'])
                
                grade_style = ParagraphStyle(
                    name=f'IndividualGrade{mark_info["grade"]}',
                    parent=table_text_style,
                    textColor=grade_color,
                    fontName='Helvetica-Bold',
                    alignment=TA_CENTER
                )
                
                row = [
                    Paragraph(mark_info['subject_name'], table_text_style),
                    Paragraph(f"{mark_info['mark']:.1f}", table_text_style),
                    Paragraph(mark_info['grade'], grade_style),
                    Paragraph(mark_info['teacher_name'], table_text_style),
                    Paragraph(remark, table_text_style)
                ]
                marks_table_data.append(row)
            
            # Only add "No subjects" row if not primary grading (for primary, just show empty table if no marks)
            if len(valid_marks) == 0 and not grading.is_primary:
                marks_table_data.append([
                    Paragraph('No subjects with marks available', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style)
                ])
            
            marks_table = Table(marks_table_data, colWidths=[5.5*cm, 2*cm, 2*cm, 3.5*cm, 3*cm], repeatRows=1)
            marks_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#dee2e6')),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 7),
                ('LEADING', (0, 0), (-1, -1), 8),
                ('ROWBACKGROUNDS', (1, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
            ]))
            
            elements.append(marks_table)
            elements.append(Spacer(1, 0.8*cm))
            
            # Performance summary with modern cards (exclude point summary for primary)
            performance_data = [
                [
                    Paragraph("CLASS RANKING", bold_style),
                ],
                [
                    Paragraph(f"Position: {i} of {total_students}", body_style),
                ]
            ]
            if has_division:
                performance_data[0].insert(1, Paragraph("POINT SUMMARY", bold_style))
                total_pts_display = str(student_dict['total_points']) if student_dict['total_points'] != '-' else '-'
                performance_data[1].insert(1, Paragraph(f"Total Points: {total_pts_display}", body_style))
            performance_data[0].append(Paragraph("ATTENDANCE STATUS", bold_style))
            performance_data[1].append(Paragraph("Regular", body_style))
            
            if has_division:
                col_widths_perf = [4*cm, 4*cm, 4*cm]
            else:
                col_widths_perf = [6*cm, 6*cm]
            
            performance_table = Table(performance_data, colWidths=col_widths_perf)
            performance_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 6),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
            ]))
            
            elements.append(performance_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # General comment with highlighted background
            avg = student_dict['average_marks'] or 0
            remark = "No remark available"
            if remark_ranges:
                for r_range in remark_ranges:
                    if r_range.contains(avg):
                        remark = r_range.remark
                        break
            else:
                remark = get_remark(get_grade(avg, grade_thresholds, grading.is_primary))  # Fallback to grade-based remark
            
            comment_style = ParagraphStyle(
                name='Comment',
                parent=body_style,
                fontSize=9,
                textColor=colors.HexColor('#f8f9fa'),
                backColor=colors.HexColor('#f8f9fa'),
                borderPadding=8,
                alignment=TA_CENTER
            )
            
            elements.append(Paragraph(f"<b>General Comment:</b> {remark}", comment_style))
            elements.append(Spacer(1, 0.8*cm))
            
            # Fee report (NO CHANGES)
            elements.append(Paragraph("Fee Report", subheader_style))
            elements.append(Spacer(1, 0.2*cm))
            student_obj = student_dict['student_obj']  # Use the actual Student object
            student_fees = student_obj.assigned_fees.all()
            discounts = Discount.objects.filter(student=student_obj, teacherclass=teacherclass).select_related('fee')
            payments = student_obj.payfee.all().order_by('-date_paid')
            student_focus = student_obj.student_focus.first()
            initial_payment = Decimal('0.00')
            if student_focus:
                student_registration = StudentRegistration.objects.filter(studentfocus=student_focus).first()
                if student_registration and student_registration.initial_payment:
                    initial_payment = student_registration.initial_payment

            if not student_fees.exists():
                elements.append(Paragraph("No fees assigned.", body_style))
                elements.append(Spacer(1, 0.2*cm))
            else:
                col_widths_fees = [(A4[0]-30) * 0.25, (A4[0]-30) * 0.12, (A4[0]-30) * 0.12, (A4[0]-30) * 0.12, (A4[0]-30) * 0.12, (A4[0]-30) * 0.12, (A4[0]-30) * 0.15]
                fee_data = [['Fee Name', 'Required', 'Discount', 'Adjusted', 'Paid', 'Balance', 'Status']]
                total_required = total_paid_all = total_discounted = total_balance = Decimal('0.00')
                for sf in student_fees:
                    fee = sf.fee
                    discount = discounts.filter(fee=fee).first()
                    discount_amount = discount.discount_amount if discount else Decimal('0.00')
                    adjusted_required = sf.amount_required - discount_amount
                    total_paid = payments.filter(fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal('0.00')
                    balance = adjusted_required - total_paid
                    status = 'Paid' if balance <= 0 else 'Pending'
                    fee_data.append([
                        Paragraph(fee.fee_name, body_style),
                        Paragraph(f"{sf.amount_required:.2f}", body_style),
                        Paragraph(f"{discount_amount:.2f}", body_style),
                        Paragraph(f"{adjusted_required:.2f}", body_style),
                        Paragraph(f"{total_paid:.2f}", body_style),
                        Paragraph(f"{balance:.2f}", body_style),
                        Paragraph(status, body_style)
                    ])
                    total_required += adjusted_required
                    total_paid_all += total_paid
                    total_balance += balance
                    total_discounted += discount_amount

                fee_data.append([
                    Paragraph('TOTAL', bold_style),
                    Paragraph(f"{total_required:.2f}", bold_style),
                    Paragraph(f"{total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_required:.2f}", bold_style),
                    Paragraph(f"{total_paid_all:.2f}", bold_style),
                    Paragraph(f"{total_balance:.2f}", bold_style),
                    Paragraph('', bold_style)
                ])

                fee_table = Table(fee_data, colWidths=col_widths_fees, repeatRows=1)
                fee_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -2), colors.HexColor('#f0f4f8')),
                    ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                    ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#d0d9e5')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                elements.append(fee_table)
                summary = f"Total Required: {total_required:.2f} | Total Discount: {total_discounted:.2f} | Total Paid: {total_paid_all:.2f} | Total Balance: {total_balance:.2f} | Initial Payment: {initial_payment:.2f}"
                elements.append(Paragraph(summary, discount_style if total_discounted > 0 else summary_style))
                elements.append(Spacer(1, 0.2*cm))

                # Payment records
                elements.append(Paragraph("Payment Records", subheader_style))
                payment_data = [['Fee Name', 'Date', 'Amount', 'Payer Account', 'Description']]
                for payment in payments:
                    payment_data.append([
                        Paragraph(payment.fee.fee_name, body_style),
                        Paragraph(payment.date_paid.strftime('%Y-%m-%d') if payment.date_paid else '-', body_style),
                        Paragraph(f"{payment.amount_paid:.2f}", body_style),
                        Paragraph(payment.payer_account_no or '-', body_style),
                        Paragraph(payment.description or '-', body_style)
                    ])
                if not payments.exists():
                    payment_data.append(['No payment records found', '-', '-', '-', '-'])

                payment_table = Table(payment_data, colWidths=[(A4[0]-30) * 0.25, (A4[0]-30) * 0.15, (A4[0]-30) * 0.15, (A4[0]-30) * 0.25, (A4[0]-30) * 0.25], repeatRows=1)
                payment_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f0f4f8')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (1, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -1), colors.HexColor('#f0f4f8')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                elements.append(payment_table)
                elements.append(Spacer(1, 0.2*cm))
            
            # Signature section with modern layout (always show if available)
            signature_data = []
            signature_row = []
            
            if source_doc and source_doc.extracted_signature and os.path.exists(source_doc.extracted_signature.path):
                try:
                    with PILImage.open(source_doc.extracted_signature.path) as img:
                        img.verify()
                    sig_img = RLImage(source_doc.extracted_signature.path, width=3*cm, height=1.5*cm)
                    sig_img.hAlign = 'LEFT'
                    signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
                except Exception as e:
                    logger.error(f"Error loading signature: {str(e)}")
                    signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            
            signature_row.append(Spacer(1, 2*cm))
            
            if source_doc and source_doc.extracted_stamp and os.path.exists(source_doc.extracted_stamp.path):
                try:
                    with PILImage.open(source_doc.extracted_stamp.path) as img:
                        img.verify()
                    stamp_img = RLImage(source_doc.extracted_stamp.path, width=2.5*cm, height=2.5*cm)
                    stamp_img.hAlign = 'RIGHT'
                    signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
                except Exception as e:
                    logger.error(f"Error loading stamp: {str(e)}")
                    signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            
            signature_data.append(signature_row)
            
            signature_table = Table(signature_data, colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))
            
            elements.append(signature_table)
            elements.append(Paragraph(f"Generated on: {current_time}", footer_style))
            elements.append(Spacer(1, 0.3*cm))

    elements.append(Spacer(1, 0.3*cm))
    elements.append(Paragraph(f"Generated on: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}", footer_style))
    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        messages.success(request, 'Combined report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')
