def download_ca_result_pdf(request, class_id, grade_id, report_id=None):
    import gc
    from collections import defaultdict
    from django.db.models import Q, Sum, Avg
    from reportlab.lib.utils import ImageReader
    from PIL import Image as PILImage
    import pandas as pd
    from reportlab.lib.colors import HexColor
    from datetime import datetime
    import psutil
    import os
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether, PageBreak
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from reportlab.lib.units import cm
    from reportlab.lib import colors
    from reportlab.platypus import Image as RLImage  # Assuming RLImage is aliased to reportlab.platypus.Image
    from django.http import HttpResponse
    from django.shortcuts import redirect, get_object_or_404
    from django.contrib import messages
    from .models import TeacherClass, GradingModel, DisplayModel, RequiredSubject, Subject, ExaminationName, Student, Mark, Teacher, ExcludeSubject, SourceDocument, RemarkRange, CompositeSubject  # Adjust imports as per your models
    from django.db.models import Prefetch
    from reportlab.lib.pagesizes import A4

    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    exams = request.POST.getlist('exams')
    if not exams:
        messages.error(request, "No examinations selected.")
        return redirect('all_student_marks')

    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    display = DisplayModel.objects.filter(id=report_id, user=request.user).first() if report_id else DisplayModel.objects.filter(user=request.user).first()

    level = 'Primary' if grading.is_primary else 'Alevel' if grading.is_advance else 'Olevel'
    required_subjects = RequiredSubject.objects.filter(user=request.user, teacherclass_id=class_id, level=level)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')
    examination_names = ExaminationName.objects.filter(id__in=exams, user=request.user)

    # CompositeSubject logic for A-level
    display_subjects = subjects
    subjects_for_table = [{'id': s.id, 'nameSubject': s.nameSubject} for s in subjects]
    composite = None
    component_ids_set = set()
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects = subjects.exclude(id__in=component_ids_set)
                subjects_for_table = [{'id': s.id, 'nameSubject': s.nameSubject} for s in display_subjects]
                subjects_for_table.append({'id': 'composite', 'nameSubject': composite.subject_name})
            # else: use all subjects_for_table as is

    # Prefetch students with marks
    students_marks_evaluation = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch(
            'marks',
            queryset=Mark.objects.filter(
                examinationname__in=examination_names,
                subject__in=subjects
            ).select_related('user', 'subject', 'examinationname').prefetch_related('user__teacher_profile'),
            to_attr='prefetched_marks'
        )
    ).annotate(
        total_marks=Sum('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname__in=examination_names)),
        average_marks=Avg('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname__in=examination_names))
    ).select_related('teacherclass')

    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname__in=examination_names).select_related('user')
    teacher_map = {}
    for mark in all_marks:
        if mark.user_id:
            teacher = Teacher.objects.filter(user=mark.user).first()
            teacher_map[mark.user_id] = teacher.teacherName or mark.user.username if teacher else mark.user.username

    # Set exclude_subjects for non-primary
    exclude_subjects = set()
    if not grading.is_primary:
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))

    # Set grade_thresholds and other configs
    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'E'
        }
        grade_points = {}  # Not used for primary
        min_subjects_for_division = None
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    # Initialize PDF response
    response = HttpResponse(content_type='application/pdf')
    exam_suffix = "_".join(examination_names.values_list('exam_name', flat=True)).replace(' ', '_')
    filename = f"ca_result_{teacherclass.ClassName.class_name or 'Unnamed_Class'}_{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=9)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=5, alignment=TA_CENTER, leading=6)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 7

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    def get_grade(mark, grade_thresholds, is_primary):
        if mark is None or pd.isna(mark):
            return '-'
        for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
            if mark >= threshold:
                return grade
        return 'E' if is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent',
            'B': 'Very Good',
            'C': 'Good',
            'D': 'Pass',
            'F': 'Fail',
            '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = min_subjects_for_division
        if num_valid_subjects < req_subs:
            return "Inc", '-'
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    # Load images once outside the loop
    icon = None
    if display and display.image:
        image_path = display.image.path
        logger.debug(f"Checking image file: {image_path}")
        if os.path.exists(image_path) and os.access(image_path, os.R_OK):
            try:
                with PILImage.open(image_path) as img:
                    img.verify()
                logger.debug(f"Image verified successfully: {image_path}")
                icon = RLImage(image_path, width=2*cm, height=2*cm)
                icon.hAlign = 'CENTER'
                logger.debug(f"Successfully loaded image: {image_path}")
            except Exception as e:
                logger.error(f"Error loading DisplayModel image: {str(e)}")

    # Fetch source_doc to populate signature and stamp
    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()

    sig_img = None
    stamp_img = None
    if source_doc:
        sig_path = source_doc.extracted_signature.path if source_doc.extracted_signature else None
        if sig_path and os.path.exists(sig_path) and os.access(sig_path, os.R_OK):
            try:
                with PILImage.open(sig_path) as img:
                    img.verify()
                sig_img = RLImage(sig_path, width=3*cm, height=1.5*cm)
                sig_img.hAlign = 'LEFT'
            except Exception as e:
                logger.error(f"Error loading signature: {str(e)}")

        stamp_path = source_doc.extracted_stamp.path if source_doc.extracted_stamp else None
        if stamp_path and os.path.exists(stamp_path) and os.access(stamp_path, os.R_OK):
            try:
                with PILImage.open(stamp_path) as img:
                    img.verify()
                stamp_img = RLImage(stamp_path, width=2.5*cm, height=2.5*cm)
                stamp_img.hAlign = 'RIGHT'
            except Exception as e:
                logger.error(f"Error loading stamp: {str(e)}")

    # Header
    header_elements = []
    header_text = display.header if display else f"CA Based Results for {teacherclass.ClassName.class_name or 'Unnamed Class'} - {', '.join(examination_names.values_list('exam_name', flat=True))}"
    header_elements.append(Paragraph(header_text, header_style))
    header_elements.append(Spacer(1, 4))
    header_elements.append(Paragraph(display.body if display else f"Final Assessment Summary - {teacherclass.ClassName.class_name}", subheader_style))
    header_elements.append(Spacer(1, 8))

    if icon:
        header_elements.append(icon)
        header_elements.append(Spacer(1, 0.5*cm))

    elements.extend(header_elements)

    if not students_marks_evaluation.exists() or not subjects.exists() or not examination_names.exists():
        no_data_style = ParagraphStyle(
            name='NoData',
            parent=styles['BodyText'],
            fontSize=10,
            textColor=colors.red,
            alignment=TA_CENTER,
            spaceAfter=12,
            fontName='Helvetica-Bold'
        )
        elements.append(Paragraph("No academic data available for this class or examinations.", no_data_style))
    else:
        student_data = []
        for student in students_marks_evaluation:
            has_any_marks = len(student.prefetched_marks) > 0
            total_marks = student.total_marks if has_any_marks else None
            average_marks = student.average_marks if has_any_marks else None
            marks_list = []
            grades_for_division = []
            subject_marks_per_subject = defaultdict(list)
            for m in student.prefetched_marks:
                subject_marks_per_subject[m.subject_id].append(m)
            for subj in subjects_for_table:
                subject_id = subj['id']
                if subject_id == 'composite':
                    # Compute composite
                    component_marks = []
                    component_teachers = set()
                    for comp_id in component_ids_set:
                        subject_marks = subject_marks_per_subject.get(comp_id, [])
                        if subject_marks:
                            subj_total = sum(m.marks for m in subject_marks)
                            component_marks.append(subj_total)
                            for m in subject_marks:
                                if m.user:
                                    teacher_profile = getattr(m.user, 'teacher_profile', None)
                                    teacher_name = teacher_profile.teacherName or m.user.username if teacher_profile and hasattr(teacher_profile, 'teacherName') else m.user.username
                                    component_teachers.add(teacher_name)
                    if component_marks:
                        avg_mark = round(sum(component_marks) / len(component_marks), 2)
                        grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                        teachers_display = ', '.join(component_teachers) if component_teachers else '-'
                    else:
                        avg_mark = None
                        grade = '-'
                        teachers_display = '-'
                    is_excluded = False
                    marks_list.append({
                        'subject_id': 'composite',
                        'subject_name': subj['nameSubject'],
                        'mark': avg_mark,
                        'grade': grade,
                        'is_excluded': is_excluded,
                        'teacher_name': teachers_display
                    })
                    if not grading.is_primary and not is_excluded:
                        grades_for_division.append(grade)
                else:
                    # Normal subject
                    subject_marks = subject_marks_per_subject.get(subject_id, [])
                    if subject_marks:
                        subject_total = sum(m.marks for m in subject_marks)
                    else:
                        subject_total = None
                    grade = get_grade(subject_total, grade_thresholds, grading.is_primary)
                    teacher_names = set()
                    for m in subject_marks:
                        if m.user:
                            teacher_profile = getattr(m.user, 'teacher_profile', None)
                            teacher_name = teacher_profile.teacherName or m.user.username if teacher_profile and hasattr(teacher_profile, 'teacherName') else m.user.username
                            teacher_names.add(teacher_name)
                    teachers_display = ', '.join(teacher_names) if teacher_names else '-'
                    is_excluded = subject_id in exclude_subjects
                    marks_list.append({
                        'subject_id': subject_id,
                        'subject_name': subj['nameSubject'],
                        'mark': subject_total,
                        'grade': grade,
                        'is_excluded': is_excluded,
                        'teacher_name': teachers_display
                    })
                    if not grading.is_primary and not is_excluded:
                        grades_for_division.append(grade)
                    del subject_marks  # Clean up
            # If allow_to_use=False, add composite grade to division if applicable
            if composite and not composite.allow_to_use and not grading.is_primary and component_ids_set:
                component_marks_for_div = []
                for comp_id in component_ids_set:
                    comp_subj = next((s for s in marks_list if s['subject_id'] == comp_id), None)
                    if comp_subj and comp_subj['mark'] is not None:
                        component_marks_for_div.append(comp_subj['mark'])
                if component_marks_for_div:
                    avg_mark_div = round(sum(component_marks_for_div) / len(component_marks_for_div), 2)
                    composite_grade_div = get_grade(avg_mark_div, grade_thresholds, grading.is_primary)
                    grades_for_division.append(composite_grade_div)
            division, total_points = get_division(grades_for_division)
            overall_grade = get_grade(average_marks, grade_thresholds, grading.is_primary) if has_any_marks else '-'
            has_valid_marks = any(g != '-' for g in grades_for_division)
            student_data.append({
                'id': student.id,
                'fullName': student.fullName or 'Unnamed Student',
                'sex': student.sex or '-',
                'indexNumber': student.indexNumber or '-',
                'marks': marks_list,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'grade': overall_grade,
                'division': division,
                'total_points': total_points,
                'has_valid_marks': has_valid_marks
            })
            del subject_marks_per_subject  # Clean up per student
            del marks_list, grades_for_division  # Additional cleanup

        # Sort by has_valid_marks desc, then average_marks desc
        student_data.sort(key=lambda x: (-x['has_valid_marks'], -(x['average_marks'] or 0)))
        del students_marks_evaluation  # Clean up
        gc.collect()

        total_students = len(student_data)

        # CLASS PERFORMANCE SUMMARY section
        elements.append(Paragraph("CA Based Academic Results (Sum)", subheader_style))

        # Build multi-level header conditionally (exclude Div/Pts for primary)
        header_row1 = [
            'Pos', 
            'Student Name', 
            'Sex', 
            'Index No'
        ]
        for s in subjects_for_table:
            header_row1.append(s['nameSubject'])
            header_row1.append('')  # Placeholder for span

        header_row1 += ['Total', 'Avg', 'Grade']
        has_division = not grading.is_primary
        if has_division:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '']  # Empty for first four columns
        for _ in subjects_for_table:
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '']
        if has_division:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans for subject names in header_row1
        subject_start_col = 4
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),  # Pos spans two rows
            ('SPAN', (1, 0), (1, 1)),  # Student Name
            ('SPAN', (2, 0), (2, 1)),  # Sex
            ('SPAN', (3, 0), (3, 1)),  # Index No
        ]
        for i in range(len(subjects_for_table)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))  # Subject spans two columns

        subject_end_col = subject_start_col + len(subjects_for_table) * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),  # Total
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),  # Avg
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),  # Grade
        ]
        if has_division:
            table_style_commands += [
                ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),  # Div
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),  # Pts
            ]

        for i, student in enumerate(student_data, 1):
            row = [
                str(i), 
                student['fullName'], 
                student['sex'], 
                student['indexNumber']
            ]
            for subj in subjects_for_table:
                mark_info = next((m for m in student['marks'] if m['subject_id'] == subj['id']), None)
                if mark_info and mark_info['mark'] is not None:
                    mark_str = f"{mark_info['mark']:.2f}"
                    grade = mark_info['grade']
                else:
                    mark_str = '-'
                    grade = '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student['total_marks']:.2f}" if student['total_marks'] is not None else '-',
                f"{student['average_marks']:.2f}" if student['average_marks'] is not None else '-',
                student['grade'],
            ])
            if has_division:
                row.extend([
                    student['division'],
                    str(student['total_points']) if student['total_points'] != '-' else '-'
                ])
            table_data.append(row)

        # Calculate column widths (exclude Div/Pts for primary)
        available_width = A4[0] - 30
        num_final_cols = 3 + (2 if has_division else 0)
        base_width = available_width / (4 + len(subjects_for_table) * 2 + num_final_cols)  # Adjust for columns
        col_widths = (
            [base_width * 0.6] +  # Pos
            [base_width * 2.6] +  # Name
            [base_width * 0.6] +  # Sex
            [base_width * 1.9] +  # Index
            [base_width * 0.8, base_width * 0.6] * len(subjects_for_table) +  # Mark, Grade
            [base_width * 0.9] * 3  # Total, Avg, Grade
        )
        if has_division:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors per cell
        for row_idx, row in enumerate(table_data[2:], start=2):  # Start from body rows
            for subj_idx in range(len(subjects_for_table)):
                grade_col = 4 + subj_idx * 2 + 1  # Grade column for this subject
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 10))

        # Individual Student Reports
        total_students = len(student_data)
        
        # Fetch remark_ranges
        remark_ranges = RemarkRange.objects.filter(user=request.user)
        
        for i, student in enumerate(student_data, 1):
            elements.append(PageBreak())
            
            # Individual report header
            individual_header = []
            
            # Header with school logo and info
            header_row = []
            if icon:
                header_row.append(icon)
            else:
                header_row.append(Paragraph("", body_style))
            
            center_content = [
                Paragraph(f"CA BASED REPORT FORM FOR: {student['fullName']}", header_style),
                Spacer(1, 0.2*cm),
                Paragraph(f"{teacherclass.ClassName.class_name} • {', '.join(examination_names.values_list('exam_name', flat=True))}", subheader_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Academic Year: {datetime.now().year}", body_style)
            ]
            
            header_row.append(center_content)
            header_row.append(Paragraph(f"Page {i} of {total_students}", footer_style))
            
            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))
            
            elements.append(header_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # Student information section with modern card-like appearance (exclude division for primary)
            left_column = [
                Paragraph("STUDENT INFORMATION", bold_style),
                Paragraph(f"<b>Name:</b> {student['fullName']}", body_style),
                Paragraph(f"<b>Index Number:</b> {student['indexNumber']}", body_style),
                Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style),
            ]
            right_column = [
                Paragraph("ACADEMIC SUMMARY", bold_style),
                Paragraph(f"<b>Total Marks:</b> {student['total_marks']:.0f}" if student['total_marks'] is not None else "<b>Total Marks:</b> -", body_style),
                Paragraph(f"<b>Average:</b> {student['average_marks']:.1f}" if student['average_marks'] is not None else "<b>Average:</b> -", body_style),
                Paragraph(f"<b>Overall Grade:</b> {student['grade']}", body_style),
            ]
            
            if grading.is_primary:
                # For primary, append gender to the class paragraph
                left_column[3] = Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}<br/><b>Gender:</b> {student['sex']}", body_style)
            else:
                # For non-primary, add separate rows for gender and division
                left_column.append(Paragraph(f"<b>Gender:</b> {student['sex']}", body_style))
                right_column.append(Paragraph(f"<b>Division:</b> {student['division']}", body_style))
            
            info_data = []
            for l, r in zip(left_column, right_column):
                info_data.append([
                    l,
                    "",
                    r
                ])
            
            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))
            
            elements.append(info_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # Subject performance table
            elements.append(Paragraph("SUBJECT PERFORMANCE DETAILS (SUM)", subheader_style))
            elements.append(Spacer(1, 0.3*cm))
            
            marks_header = [
                Paragraph('SUBJECT', table_text_style),
                Paragraph('MARK', table_text_style),
                Paragraph('GRADE', table_text_style),
                Paragraph('TEACHER', table_text_style),
                Paragraph('REMARKS', table_text_style)
            ]
            
            marks_table_data = [marks_header]
            valid_marks = [m for m in student['marks'] if m['mark'] is not None and m['mark'] > 0 and m['teacher_name'] != '-']
            
            for mark_info in valid_marks:
                grade_color = get_grade_color(mark_info['grade'])
                remark = get_remark(mark_info['grade'])
                
                grade_style = ParagraphStyle(
                    name=f'IndividualGrade{mark_info["grade"]}',
                    parent=table_text_style,
                    textColor=grade_color,
                    fontName='Helvetica-Bold',
                    alignment=TA_CENTER
                )
                
                row = [
                    Paragraph(mark_info['subject_name'], table_text_style),
                    Paragraph(f"{mark_info['mark']:.1f}", table_text_style),
                    Paragraph(mark_info['grade'], grade_style),
                    Paragraph(mark_info['teacher_name'], table_text_style),
                    Paragraph(remark, table_text_style)
                ]
                marks_table_data.append(row)
            
            if len(valid_marks) == 0:
                marks_table_data.append([
                    Paragraph('No subjects with marks available', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style)
                ])
            
            marks_table = Table(marks_table_data, colWidths=[5.5*cm, 2*cm, 2*cm, 3.5*cm, 3*cm], repeatRows=1)
            marks_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 7),
                ('LEADING', (0, 0), (-1, -1), 8),
                ('ROWBACKGROUNDS', (1, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
            ]))
            
            elements.append(marks_table)
            elements.append(Spacer(1, 0.8*cm))
            
            # Performance summary with modern cards (exclude point summary for primary)
            performance_data = [
                [
                    Paragraph("CLASS RANKING", bold_style),
                ],
                [
                    Paragraph(f"Position: {i} of {total_students}", body_style),
                ]
            ]
            if has_division:
                performance_data[0].insert(1, Paragraph("POINT SUMMARY", bold_style))
                performance_data[1].insert(1, Paragraph(f"Total Points: {student['total_points']}", body_style))
            performance_data[0].append(Paragraph("ATTENDANCE STATUS", bold_style))
            performance_data[1].append(Paragraph("Regular", body_style))
            
            if has_division:
                col_widths_perf = [4*cm, 4*cm, 4*cm]
            else:
                col_widths_perf = [6*cm, 6*cm]
            
            performance_table = Table(performance_data, colWidths=col_widths_perf)
            performance_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 6),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
            ]))
            
            elements.append(performance_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # General comment with highlighted background
            avg = student['average_marks'] or 0
            remark = "No remark available"
            if remark_ranges:
                for r_range in remark_ranges:
                    if r_range.contains(avg):
                        remark = r_range.remark
                        break
            else:
                remark = get_remark(get_grade(avg, grade_thresholds, grading.is_primary))  # Fallback to grade-based remark
            
            comment_style = ParagraphStyle(
                name='Comment',
                parent=body_style,
                fontSize=9,
                textColor=colors.HexColor('#2c3e50'),
                backColor=colors.HexColor('#f8f9fa'),
                borderPadding=8,
                alignment=TA_CENTER
            )
            
            elements.append(Paragraph(f"<b>General Comment:</b> {remark}", comment_style))
            elements.append(Spacer(1, 0.8*cm))
            
            # Signature section with modern layout (always show if available)
            signature_data = []
            signature_row = []
            
            if sig_img:
                signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            
            signature_row.append(Spacer(1, 2*cm))
            
            if stamp_img:
                signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            
            signature_data.append(signature_row)
            
            signature_table = Table(signature_data, colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))
            
            elements.append(signature_table)
            elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

    logger.debug(f"Memory usage before PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        logger.debug(f"Memory usage after PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
        messages.success(request, 'CA based results report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')
from django.contrib.auth.decorators import login_required
from django.views.decorators.csrf import csrf_exempt
from django.http import HttpResponse
from django.shortcuts import get_object_or_404, redirect
from django.contrib import messages
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether, Image as RLImage, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER, TA_LEFT
from django.db.models import Sum, Avg, Q as models_Q
from decimal import Decimal
from reportlab.lib.units import cm, inch
import logging
from PIL import Image as PILImage
from datetime import datetime
import pandas as pd

from django.http import HttpResponse
from django.shortcuts import get_object_or_404, redirect
from django.contrib import messages
from django.views.decorators.csrf import csrf_exempt
from django.contrib.auth.decorators import login_required
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER, TA_LEFT
from reportlab.lib.units import cm
import logging
import os
from PIL import Image as PILImage
from reportlab.platypus import Image as RLImage
import psutil
from datetime import datetime
import pandas as pd
from .models import TeacherClass, GradingModel, DisplayModel, ExaminationName, RequiredSubject, Subject, Student, Mark, ExcludeSubject, SourceDocument, RemarkRange, Teacher
from django.db.models import Q as models_Q, Sum, Avg, Prefetch

logger = logging.getLogger(__name__)
@csrf_exempt
@login_required
def download_final_result_pdf(request, class_id, grade_id, report_id=None):
    from django.db.models import Q, Sum, Avg
    from django.db.models import Prefetch
    import psutil
    from datetime import datetime
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from reportlab.lib.units import cm
    from reportlab.platypus import Image as RLImage
    from PIL import Image as PILImage
    import os
    import pandas as pd  # Assuming pd.isna is used
    import gc
    from collections import defaultdict
    from .models import TeacherClass, GradingModel, DisplayModel, ExaminationName, RequiredSubject, Subject, Student, Mark, ExcludeSubject, SourceDocument, RemarkRange, Teacher, CompositeSubject

    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    exams = request.POST.getlist('exams')
    if not exams:
        messages.error(request, "No examinations selected.")
        return redirect('all_student_marks')

    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    display = DisplayModel.objects.filter(id=report_id, user=request.user).first() if report_id else DisplayModel.objects.filter(user=request.user).first()

    if grading.is_primary:
        level = 'Primary'
    elif grading.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'
    required_subjects = RequiredSubject.objects.filter(user=request.user, level=level, teacherclass_id=class_id)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')

    # CompositeSubject logic for A-level
    display_subjects = subjects
    subjects_for_table = [{'id': s.id, 'nameSubject': s.nameSubject} for s in subjects]
    composite = None
    component_ids_set = set()
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects = subjects.exclude(id__in=component_ids_set)
                subjects_for_table = [{'id': s.id, 'nameSubject': s.nameSubject} for s in display_subjects]
                subjects_for_table.append({'id': 'composite', 'nameSubject': composite.subject_name})
            # else: use all subjects_for_table as is

    examination_names = ExaminationName.objects.filter(id__in=exams, user=request.user)
    mark_filter = Q(subject__in=subjects, examinationname__in=examination_names)

    students_marks_evaluation = Student.objects.filter(teacherclass=teacherclass).annotate(
        total_marks=Sum('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname__in=examination_names)),
        average_marks=Avg('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname__in=examination_names))
    ).prefetch_related(
        Prefetch(
            'marks',
            queryset=Mark.objects.filter(
                subject__in=subjects,
                examinationname__in=examination_names
            ).select_related('subject', 'examinationname', 'user').prefetch_related('user__teacher_profile'),
            to_attr='prefetched_marks'
        )
    ).select_related('teacherclass')

    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname__in=examination_names).select_related('user')
    teacher_map = {}
    for mark in all_marks:
        if mark.user_id:
            teacher = Teacher.objects.filter(user=mark.user).first()
            teacher_map[mark.user_id] = teacher.teacherName or mark.user.username if teacher else mark.user.username

    # Set exclude_subjects for non-primary
    exclude_subjects = set()
    if not grading.is_primary:
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))

    # Set grade_thresholds and other configs
    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'E'
        }
        grade_points = {}  # Not used for primary
        min_subjects_for_division = None
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.filter(user=request.user)

    response = HttpResponse(content_type='application/pdf')
    exam_suffix = "_".join(examination_names.values_list('exam_name', flat=True)).replace(' ', '_')
    filename = f"final_result_{teacherclass.ClassName.class_name or 'Unnamed_Class'}_{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []

    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=9)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=5, alignment=TA_CENTER, leading=6)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 7

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    def get_grade(mark, grade_thresholds, is_primary):
        if mark is None or pd.isna(mark):
            return '-'
        for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
            if mark >= threshold:
                return grade
        return 'E' if is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent',
            'B': 'Very Good',
            'C': 'Good',
            'D': 'Pass',
            'F': 'Fail',
            '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = min_subjects_for_division
        if num_valid_subjects < req_subs:
            return "Inc", 0
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    has_division = not grading.is_primary

    # Load images once outside the loop
    icon = None
    if display and display.image:
        image_path = display.image.path
        logger.debug(f"Checking image file: {image_path}")
        if os.path.exists(image_path) and os.access(image_path, os.R_OK):
            try:
                with PILImage.open(image_path) as img:
                    img.verify()
                logger.debug(f"Image verified successfully: {image_path}")
                icon = RLImage(image_path, width=2*cm, height=2*cm)
                icon.hAlign = 'CENTER'
                logger.debug(f"Successfully loaded image: {image_path}")
            except Exception as e:
                logger.error(f"Error loading DisplayModel image: {str(e)}")

    sig_img = None
    stamp_img = None
    if source_doc:
        sig_path = source_doc.extracted_signature.path if source_doc.extracted_signature else None
        if sig_path and os.path.exists(sig_path) and os.access(sig_path, os.R_OK):
            try:
                with PILImage.open(sig_path) as img:
                    img.verify()
                sig_img = RLImage(sig_path, width=3*cm, height=1.5*cm)
                sig_img.hAlign = 'LEFT'
            except Exception as e:
                logger.error(f"Error loading signature: {str(e)}")

        stamp_path = source_doc.extracted_stamp.path if source_doc.extracted_stamp else None
        if stamp_path and os.path.exists(stamp_path) and os.access(stamp_path, os.R_OK):
            try:
                with PILImage.open(stamp_path) as img:
                    img.verify()
                stamp_img = RLImage(stamp_path, width=2.5*cm, height=2.5*cm)
                stamp_img.hAlign = 'RIGHT'
            except Exception as e:
                logger.error(f"Error loading stamp: {str(e)}")

    # Header
    header_elements = []
    header_text = display.header if display else f"Final Results for {teacherclass.ClassName.class_name or 'Unnamed Class'} - {', '.join(examination_names.values_list('exam_name', flat=True))}"
    header_elements.append(Paragraph(header_text, header_style))
    header_elements.append(Spacer(1, 4))
    header_elements.append(Paragraph(display.body if display else f"Final Assessment Summary - {teacherclass.ClassName.class_name}", subheader_style))
    header_elements.append(Spacer(1, 8))

    if icon:
        header_elements.append(icon)
        header_elements.append(Spacer(1, 0.5*cm))

    elements.extend(header_elements)

    if not students_marks_evaluation.exists() or not subjects.exists() or not examination_names.exists():
        no_data_style = ParagraphStyle(
            name='NoData',
            parent=styles['BodyText'],
            fontSize=10,
            textColor=colors.red,
            alignment=TA_CENTER,
            spaceAfter=12,
            fontName='Helvetica-Bold'
        )
        elements.append(Paragraph("No academic data available for this class or examinations.", no_data_style))
    else:
        student_data = []
        for student in students_marks_evaluation:
            total_marks = student.total_marks or 0
            average_marks = student.average_marks or 0
            marks_list = []
            grades_for_division = []
            subject_marks_per_subject = defaultdict(list)
            for m in student.prefetched_marks:
                subject_marks_per_subject[m.subject_id].append(m)
            for subj in subjects_for_table:
                subject_id = subj['id']
                if subject_id == 'composite':
                    # Compute composite
                    component_marks = []
                    component_teachers = set()
                    for comp_id in component_ids_set:
                        subject_marks = subject_marks_per_subject.get(comp_id, [])
                        if subject_marks:
                            comp_avg = sum(m.marks for m in subject_marks) / len(subject_marks)
                            component_marks.append(round(comp_avg, 2))
                            for m in subject_marks:
                                if m.user_id:
                                    teacher_name = teacher_map.get(m.user_id, m.user.username)
                                    component_teachers.add(teacher_name)
                    if component_marks:
                        avg_mark = round(sum(component_marks) / len(component_marks), 2)
                        grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                        teachers_display = ', '.join(component_teachers) if component_teachers else '-'
                    else:
                        avg_mark = None
                        grade = '-'
                        teachers_display = '-'
                    is_excluded = False
                    marks_list.append({
                        'subject_id': 'composite',
                        'subject_name': subj['nameSubject'],
                        'mark': avg_mark,
                        'grade': grade,
                        'is_excluded': is_excluded,
                        'teacher_name': teachers_display
                    })
                    if not grading.is_primary and not is_excluded:
                        grades_for_division.append(grade)
                else:
                    # Normal subject
                    subject_marks = subject_marks_per_subject.get(subject_id, [])
                    if subject_marks:
                        avg_mark = round(sum(m.marks for m in subject_marks) / len(subject_marks), 2)
                    else:
                        avg_mark = None
                    grade = get_grade(avg_mark, grade_thresholds, grading.is_primary)
                    teacher_names = set()
                    for mark in subject_marks:
                        if mark.user_id:
                            teacher_names.add(teacher_map.get(mark.user_id, mark.user.username))
                    teacher_name = ', '.join(teacher_names) if teacher_names else '-'
                    is_excluded = subject_id in exclude_subjects
                    marks_list.append({
                        'subject_id': subject_id,
                        'subject_name': subj['nameSubject'],
                        'mark': avg_mark,
                        'grade': grade,
                        'is_excluded': is_excluded,
                        'teacher_name': teacher_name
                    })
                    if not grading.is_primary and not is_excluded:
                        grades_for_division.append(grade)
            # If allow_to_use=False, add composite grade to division if applicable
            if composite and not composite.allow_to_use and not grading.is_primary and component_ids_set:
                component_marks_for_div = []
                for comp_id in component_ids_set:
                    comp_subj = next((s for s in marks_list if s['subject_id'] == comp_id), None)
                    if comp_subj and comp_subj['mark'] is not None:
                        component_marks_for_div.append(comp_subj['mark'])
                if component_marks_for_div:
                    avg_mark_div = round(sum(component_marks_for_div) / len(component_marks_for_div), 2)
                    composite_grade_div = get_grade(avg_mark_div, grade_thresholds, grading.is_primary)
                    grades_for_division.append(composite_grade_div)
            division, total_points = get_division(grades_for_division)

            has_valid_marks = any(grade != '-' for grade in grades_for_division)

            student_data.append({
                'id': student.id,
                'fullName': student.fullName or 'Unnamed Student',
                'sex': student.sex or '-',
                'indexNumber': student.indexNumber or '-',
                'marks': marks_list,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'grade': get_grade(average_marks, grade_thresholds, grading.is_primary),
                'division': division,
                'total_points': total_points,
                'has_valid_marks': has_valid_marks
            })

        # Sort by has_valid_marks desc, then average_marks desc
        student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))

        # CLASS PERFORMANCE SUMMARY section
        elements.append(Paragraph("Final Academic Results (Average)", subheader_style))

        # Build multi-level header conditionally
        header_row1 = ['Pos', 'Student Name', 'Sex', 'Index No']
        for s in subjects_for_table:
            header_row1.append(s['nameSubject'])
            header_row1.append('')  # Placeholder for span
        header_row1 += ['Total', 'Avg', 'Grade', 'Pos']
        if has_division:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '']  # Empty for first four columns
        for _ in subjects_for_table:
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '', '']
        if has_division:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans for subject names in header_row1
        subject_start_col = 4
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),  # Pos spans two rows
            ('SPAN', (1, 0), (1, 1)),  # Student Name
            ('SPAN', (2, 0), (2, 1)),  # Sex
            ('SPAN', (3, 0), (3, 1)),  # Index No
        ]
        for i in range(len(subjects_for_table)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))  # Subject spans two columns

        subject_end_col = subject_start_col + len(subjects_for_table) * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),  # Total
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),  # Avg
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),  # Grade
            ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),  # Pos
        ]
        if has_division:
            table_style_commands += [
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),  # Div
                ('SPAN', (subject_end_col + 6, 0), (subject_end_col + 6, 1)),  # Pts
            ]

        for i, student in enumerate(student_data, 1):
            row = [str(i), student['fullName'], student['sex'], student['indexNumber']]
            for subj in subjects_for_table:
                mark_info = next((m for m in student['marks'] if m['subject_id'] == subj['id']), None)
                if mark_info and mark_info['mark'] is not None:
                    mark_str = f"{mark_info['mark']:.2f}"
                    grade = mark_info['grade']
                else:
                    mark_str = '-'
                    grade = '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student['total_marks']:.2f}" if student['total_marks'] > 0 else '-',
                f"{student['average_marks']:.2f}" if student['average_marks'] > 0 else '-',
                student['grade'],
                str(i),
            ])
            if has_division:
                row.extend([
                    student['division'],
                    str(student['total_points']) if student['total_points'] != '-' else '-'
                ])
            table_data.append(row)

        # Calculate column widths
        available_width = A4[0] - 30  # 15mm margins on each side
        num_final_cols = 4 + (2 if has_division else 0)
        base_width = available_width / (4 + len(subjects_for_table) * 2 + num_final_cols)  # Base on original logical columns
        col_widths = (
            [base_width * 0.5] +  # Pos
            [base_width * 2.5] +  # Student Name
            [base_width * 0.5] +  # Sex
            [base_width * 1.6] +  # Index No
            [base_width * 0.6, base_width * 0.5] * len(subjects_for_table) +  # Mark and Grade for each subject
            [base_width * 0.8] * 4  # Total, Avg, Grade, Pos
        )
        if has_division:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors per cell
        for row_idx, row in enumerate(table_data[2:], start=2):  # Start from body rows
            for subj_idx in range(len(subjects_for_table)):
                grade_col = 4 + subj_idx * 2 + 1  # Grade column for this subject
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 10))

        # Individual Student Reports (unchanged from original)
        total_students = len(student_data)
        for i, student in enumerate(student_data, 1):
            elements.append(PageBreak())

            # Individual report header
            individual_header = []
            header_row = []
            if icon:
                header_row.append(icon)
            else:
                header_row.append(Paragraph("", body_style))

            center_content = [
                Paragraph(f"FINAL REPORT FORM FOR: {student['fullName']}", header_style),
                Spacer(1, 0.2*cm),
                Paragraph(f"{teacherclass.ClassName.class_name} • {', '.join(examination_names.values_list('exam_name', flat=True))}", subheader_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Academic Year: {datetime.now().year}", body_style)
            ]

            header_row.append(center_content)
            header_row.append(Paragraph(f"Page {i} of {total_students}", footer_style))

            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))

            elements.append(header_table)
            elements.append(Spacer(1, 0.5*cm))

            # Student information section with modern card-like appearance
            left_column = [
                Paragraph("STUDENT INFORMATION", bold_style),
                Paragraph(f"<b>Name:</b> {student['fullName']}", body_style),
                Paragraph(f"<b>Index Number:</b> {student['indexNumber']}", body_style),
                Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style),
            ]
            right_column = [
                Paragraph("ACADEMIC SUMMARY", bold_style),
                Paragraph(f"<b>Total Marks:</b> {student['total_marks']:.0f}" if student['total_marks'] > 0 else "<b>Total Marks:</b> -", body_style),
                Paragraph(f"<b>Average:</b> {student['average_marks']:.1f}" if student['average_marks'] > 0 else "<b>Average:</b> -", body_style),
                Paragraph(f"<b>Overall Grade:</b> {student['grade']}", body_style),
            ]

            if grading.is_primary:
                # For primary, append gender to the class paragraph
                left_column[3] = Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}<br/><b>Gender:</b> {student['sex']}", body_style)
            else:
                # For non-primary, add separate rows for gender and division
                left_column.append(Paragraph(f"<b>Gender:</b> {student['sex']}", body_style))
                right_column.append(Paragraph(f"<b>Division:</b> {student['division']}", body_style))

            info_data = []
            for l, r in zip(left_column, right_column):
                info_data.append([
                    l,
                    "",
                    r
                ])

            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))

            elements.append(info_table)
            elements.append(Spacer(1, 0.5*cm))

            # Subject performance table
            elements.append(Paragraph("SUBJECT PERFORMANCE DETAILS (AVERAGE)", subheader_style))
            elements.append(Spacer(1, 0.3*cm))

            marks_header = [
                Paragraph('SUBJECT', table_text_style),
                Paragraph('MARK', table_text_style),
                Paragraph('GRADE', table_text_style),
                Paragraph('TEACHER', table_text_style),
                Paragraph('REMARKS', table_text_style)
            ]

            marks_table_data = [marks_header]
            valid_marks = [m for m in student['marks'] if m['grade'] != '-']

            for mark_info in valid_marks:
                grade_color = get_grade_color(mark_info['grade'])
                remark = get_remark(mark_info['grade'])

                grade_style = ParagraphStyle(
                    name=f'IndividualGrade{mark_info["grade"]}',
                    parent=table_text_style,
                    textColor=grade_color,
                    fontName='Helvetica-Bold',
                    alignment=TA_CENTER
                )

                row = [
                    Paragraph(mark_info['subject_name'], table_text_style),
                    Paragraph(f"{mark_info['mark']:.1f}", table_text_style),
                    Paragraph(mark_info['grade'], grade_style),
                    Paragraph(mark_info['teacher_name'], table_text_style),
                    Paragraph(remark, table_text_style)
                ]
                marks_table_data.append(row)

            if len(valid_marks) == 0:
                marks_table_data.append([
                    Paragraph('No subjects with marks available', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style)
                ])

            marks_table = Table(marks_table_data, colWidths=[5.5*cm, 2*cm, 2*cm, 3.5*cm, 3*cm], repeatRows=1)
            marks_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 7),
                ('LEADING', (0, 0), (-1, -1), 8),
                ('ROWBACKGROUNDS', (1, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
            ]))

            elements.append(marks_table)
            elements.append(Spacer(1, 0.8*cm))

            # Performance summary with modern cards
            if has_division:
                performance_data = [
                    [
                        Paragraph("CLASS RANKING", bold_style),
                        Paragraph("POINT SUMMARY", bold_style),
                        Paragraph("ATTENDANCE STATUS", bold_style)
                    ],
                    [
                        Paragraph(f"Position: {i} of {total_students}", body_style),
                        Paragraph(f"Total Points: {student['total_points']}", body_style),
                        Paragraph("Regular", body_style)
                    ]
                ]
                col_widths_perf = [4*cm, 4*cm, 4*cm]
            else:
                performance_data = [
                    [
                        Paragraph("CLASS RANKING", bold_style),
                        Paragraph("ATTENDANCE STATUS", bold_style)
                    ],
                    [
                        Paragraph(f"Position: {i} of {total_students}", body_style),
                        Paragraph("Regular", body_style)
                    ]
                ]
                col_widths_perf = [6*cm, 6*cm]

            performance_table = Table(performance_data, colWidths=col_widths_perf)
            performance_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 6),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
            ]))

            elements.append(performance_table)
            elements.append(Spacer(1, 0.5*cm))

            # General comment
            avg = student['average_marks'] or 0
            remark = "No remark available"
            for r_range in remark_ranges:
                if r_range.contains(avg):
                    remark = r_range.remark
                    break

            comment_style = ParagraphStyle(
                name='Comment',
                parent=body_style,
                fontSize=9,
                textColor=colors.HexColor('#2c3e50'),
                backColor=colors.HexColor('#f8f9fa'),
                borderPadding=8,
                alignment=TA_CENTER
            )

            elements.append(Paragraph(f"<b>General Comment:</b> {remark}", comment_style))
            elements.append(Spacer(1, 0.8*cm))

            # Signature section
            signature_data = []
            signature_row = []

            if sig_img:
                signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])

            signature_row.append(Spacer(1, 2*cm))

            if stamp_img:
                signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])

            signature_data.append(signature_row)

            signature_table = Table(signature_data, colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))

            elements.append(signature_table)
            elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

    logger.debug(f"Memory usage before PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        logger.debug(f"Memory usage after PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
        messages.success(request, 'Final results report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')
from django.contrib.auth.decorators import login_required
from django.http import HttpResponse
from django.shortcuts import get_object_or_404, redirect
from django.contrib import messages
from django.views.decorators.csrf import csrf_exempt
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, KeepTogether, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from django.db.models import Sum, Avg, Q as models_Q
from django.db.models import Prefetch
from datetime import datetime
import logging


from datetime import datetime
current_time = datetime.now()
from datetime import datetime
from collections import defaultdict
from decimal import Decimal
