@csrf_exempt
@login_required
def download_ca_result_financial_pdf(request, class_id, grade_id):
    exam_ids = request.POST.getlist('exams')
    if not exam_ids:
        messages.error(request, "No examinations selected.")
        return redirect('all_student_marks')

    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    examination_names = ExaminationName.objects.filter(id__in=exam_ids, user=request.user)
    if not examination_names.exists():
        messages.error(request, "No examinations found for the selected IDs.")
        return redirect('all_student_marks')

    display = DisplayModel.objects.filter(user=request.user).first()
    creator = getattr(request, 'creator', request.user)
    if not creator:
        try:
            teacher_profile = Teacher.objects.get(user=request.user)
            creator = teacher_profile.created_by or request.user
        except Teacher.DoesNotExist:
            messages.error(request, "Your account is not linked to a valid teacher profile.")
            return redirect('teacher_dashboard')

    if grading.is_primary:
        level = 'Primary'
        has_division = False
        exclude_subjects = set()
    else:
        level = 'Alevel' if grading.is_advance else 'Olevel'
        has_division = True
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))

    required_subjects = RequiredSubject.objects.filter(user=request.user, teacherclass_id=class_id, level=level)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')

    # CompositeSubject integration for A-Level
    composite = None
    component_ids_set = set()
    composite_info = None
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))

    students = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(subject__in=subjects, examinationname__in=examination_names).select_related('subject', 'examinationname', 'user'), to_attr='prefetched_marks'),
        Prefetch('assigned_fees', queryset=StudentFee.objects.filter(teacherclass=teacherclass).select_related('fee')),
        Prefetch('payfee', queryset=PayFee.objects.select_related('fee')),
        Prefetch('discount_set', queryset=Discount.objects.filter(teacherclass=teacherclass).select_related('fee')),
        Prefetch('student_focus', queryset=StudentFocus.objects.prefetch_related('student_fcs'))
    )

    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname__in=examination_names).select_related('user')
    user_ids = {mark.user_id for mark in all_marks if mark.user_id}
    teacher_map = {teacher.user_id: teacher.teacherName or teacher.user.username 
                   for teacher in Teacher.objects.filter(user__in=user_ids)}

    response = HttpResponse(content_type='application/pdf')
    exam_suffix = "_".join(examination_names.values_list('exam_name', flat=True)).replace(' ', '_')
    filename = f"ca_result_financial_{teacherclass.ClassName.class_name or 'Unnamed_Class'}_{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=8)
    discount_style = ParagraphStyle(name='Discount', parent=styles['BodyText'], fontSize=9, textColor=colors.red, spaceAfter=4)
    summary_style = ParagraphStyle(name='Summary', parent=styles['BodyText'], fontSize=9, fontName='Helvetica-Bold', spaceAfter=4)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=6, alignment=TA_CENTER, leading=7)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 6

    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E'
        }
        grade_points = {}
        min_subjects_for_division = None
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A', grading.grade_b: 'B', grading.grade_c: 'C', grading.grade_d: 'D',
            grading.grade_e: 'E', grading.grade_s: 'S', grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A', grading.grade_b: 'B', grading.grade_c: 'C', grading.grade_d: 'D', grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    def get_grade(mark):
        if mark is None:
            return '-'
        for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
            if mark >= threshold:
                return grade
        return 'E' if grading.is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent', 'B': 'Very Good', 'C': 'Good', 'D': 'Pass',
            'F': 'Fail', '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            if 'S' in grade_thresholds.values():
                remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = min_subjects_for_division
        if num_valid_subjects < req_subs:
            return "Inc", '-'
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    header_text = display.header if display else f"CA-Based Academic and Financial Report for {teacherclass.ClassName.class_name or 'Unnamed Class'}"
    elements.append(Paragraph(header_text, header_style))
    elements.append(Spacer(1, 0.3*cm))
    academic_year = teacherclass.academicclassyear.academic_year_name if teacherclass.academicclassyear else 'N/A'
    exam_names = ", ".join(exam.exam_name for exam in examination_names)
    elements.append(Paragraph(display.body if display else f"CA-Based Summary for {exam_names} - {teacherclass.ClassName.class_name} ({academic_year})", subheader_style))
    elements.append(Spacer(1, 0.3*cm))

    if display and display.image and os.path.exists(display.image.path):
        try:
            with PILImage.open(display.image.path) as img:
                img.verify()
            icon = RLImage(display.image.path, width=2*cm, height=2*cm)
            icon.hAlign = 'CENTER'
            elements.append(icon)
            elements.append(Spacer(1, 0.3*cm))
        except Exception as e:
            logger.error(f"Error loading DisplayModel image: {e}")

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.filter(user=request.user)

    if not students.exists() or not subjects.exists() or not examination_names.exists():
        elements.append(Paragraph("No data available for this class or examinations.", body_style))
    else:
        # Process student data
        student_data_list = []
        for student in students:
            all_marks_list = [m for m in student.prefetched_marks]
            total_marks = sum(m.marks for m in all_marks_list) or 0
            count = len(all_marks_list)
            average_marks = (total_marks / count) if count > 0 else 0
            subject_marks_per_subject = defaultdict(list)
            for m in all_marks_list:
                subject_marks_per_subject[m.subject_id].append(m)

            # Compute composite_info if applicable
            composite_local_info = None
            local_grades_for_division = []
            if grading.is_advance and composite:
                non_excluded_components = [cid for cid in component_ids_set if cid not in exclude_subjects]
                component_subject_marks_dict = {cid: subject_marks_per_subject.get(cid, []) for cid in non_excluded_components}
                component_aggregates = []
                all_teachers_set = set()
                for cid, sm in component_subject_marks_dict.items():
                    if sm:
                        agg = sum(m.marks for m in sm)  # CA: sum
                        component_aggregates.append(agg)
                        for m in sm:
                            if m.user_id in teacher_map:
                                all_teachers_set.add(teacher_map[m.user_id])
                if component_aggregates:
                    composite_agg = sum(component_aggregates) / len(component_aggregates)
                    composite_grade = get_grade(composite_agg)
                    teachers_display = ', '.join(sorted(all_teachers_set)) if all_teachers_set else '-'
                    composite_local_info = {'agg': composite_agg, 'grade': composite_grade, 'teachers': teachers_display}
                    local_grades_for_division.append(composite_grade)

            # Build grades_for_division for non-component subjects
            for subject in subjects:
                if subject.id in component_ids_set:
                    continue
                subject_marks = subject_marks_per_subject.get(subject.id, [])
                if subject_marks:
                    subject_total = sum(m.marks for m in subject_marks)  # CA: sum
                    grade = get_grade(subject_total)
                    if subject.id not in exclude_subjects:
                        local_grades_for_division.append(grade)

            # Determine display_subjects
            if composite and composite.allow_to_use:
                display_subjects_local = subjects.exclude(id__in=component_ids_set)
            else:
                display_subjects_local = subjects

            # Build marks_list
            marks_list_local = []
            for subject in display_subjects_local:
                subject_marks = subject_marks_per_subject.get(subject.id, [])
                if subject_marks:
                    subject_total = sum(m.marks for m in subject_marks)  # CA: sum
                    grade = get_grade(subject_total)
                    teacher_names = set()
                    for m in subject_marks:
                        if m.user_id in teacher_map:
                            teacher_names.add(teacher_map[m.user_id])
                    teachers_display = ', '.join(sorted(teacher_names)) if teacher_names else '-'
                    marks_list_local.append({
                        'subject_id': str(subject.id),
                        'subject_name': subject.nameSubject,
                        'mark': subject_total,
                        'grade': grade,
                        'is_excluded': subject.id in exclude_subjects,
                        'teacher_name': teachers_display
                    })

            # Add composite to marks_list if applicable
            if grading.is_advance and composite and composite.allow_to_use and composite_local_info:
                marks_list_local.append({
                    'subject_id': 'composite',
                    'subject_name': composite.subject_name,
                    'mark': round(composite_local_info['agg'], 2),
                    'grade': composite_local_info['grade'],
                    'is_excluded': False,
                    'teacher_name': composite_local_info['teachers']
                })

            division, total_points = get_division(local_grades_for_division)
            has_valid_marks = len(marks_list_local) > 0
            student_data_list.append({
                'student': student,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'marks': marks_list_local,
                'grade': get_grade(average_marks),
                'division': division,
                'total_points': total_points,
                'has_valid_marks': has_valid_marks
            })

        # Sort students
        student_data_list.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))

        total_students = len(student_data_list)

        # Class-level academic summary
        elements.append(Paragraph("CA-Based Academic Results", subheader_style))
        elements.append(Spacer(1, 0.2*cm))

        # Determine display for table
        display_subjects_table = subjects.exclude(id__in=component_ids_set) if composite and composite.allow_to_use else subjects
        num_subject_cols = len(display_subjects_table) + (1 if composite and composite.allow_to_use else 0)

        # Build multi-level header
        header_row1 = [
            'Pos', 
            'Student Name', 
            'Sex', 
            'Index No'
        ]
        for s in display_subjects_table:
            header_row1.append(s.nameSubject)
            header_row1.append('')  # Placeholder for span
        if composite and composite.allow_to_use:
            header_row1.append(composite.subject_name)
            header_row1.append('')

        header_row1 += ['Total', 'Avg', 'Grade', 'Pos']
        if has_division:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '']  # Empty for first four columns
        for _ in range(num_subject_cols):
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '', '']
        if has_division:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans
        subject_start_col = 4
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),
            ('SPAN', (1, 0), (1, 1)),
            ('SPAN', (2, 0), (2, 1)),
            ('SPAN', (3, 0), (3, 1)),
        ]
        for i in range(len(display_subjects_table)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))
        if composite and composite.allow_to_use:
            start_col = subject_start_col + len(display_subjects_table) * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))

        subject_end_col = subject_start_col + num_subject_cols * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),
            ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),
        ]
        if has_division:
            table_style_commands += [
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),
                ('SPAN', (subject_end_col + 6, 0), (subject_end_col + 6, 1)),
            ]

        exam_positions = {}
        for pos, student_data in enumerate(student_data_list, 1):
            exam_positions[student_data['student'].id] = pos

        for i, student_data in enumerate(student_data_list, 1):
            row = [str(i), student_data['student'].fullName or 'Unnamed', student_data['student'].sex or '-', student_data['student'].indexNumber or '-']
            subject_mark_infos = {m['subject_id']: m for m in student_data['marks']}
            for s in display_subjects_table:
                mark_info = subject_mark_infos.get(str(s.id), {'mark': 0, 'grade': '-'})
                mark_str = f"{mark_info['mark']:.2f}" if mark_info['mark'] > 0 else '-'
                grade = mark_info['grade'] if mark_info['mark'] > 0 else '-'
                row.append(mark_str)
                row.append(grade)
            if composite and composite.allow_to_use:
                c_info = subject_mark_infos.get('composite', {'mark': 0, 'grade': '-'})
                mark_str = f"{c_info['mark']:.2f}" if c_info['mark'] > 0 else '-'
                grade = c_info['grade'] if c_info['mark'] > 0 else '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student_data['total_marks']:.2f}" if student_data['total_marks'] > 0 else '-',
                f"{student_data['average_marks']:.2f}" if student_data['average_marks'] > 0 else '-',
                student_data['grade'],
                str(i)
            ])
            if has_division:
                total_pts_display = str(student_data['total_points']) if student_data['total_points'] != '-' else '-'
                row.extend([
                    student_data['division'],
                    total_pts_display
                ])
            table_data.append(row)

        page_width = A4[0] - 30
        num_final_cols = 4 + (2 if has_division else 0)
        base_width = page_width / (4 + num_subject_cols * 2 + num_final_cols)
        col_widths = (
            [base_width * 0.5] +  # Pos
            [base_width * 2.5] +  # Name
            [base_width * 0.5] +  # Sex
            [base_width * 1.8] +  # Index
            [base_width * 0.6, base_width * 0.5] * num_subject_cols +  # Mark, Grade
            [base_width * 0.8] * 4  # Total, Avg, Grade, Pos
        )
        if has_division:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors using range
        for row_idx, row in enumerate(table_data[2:], start=2):
            for subj_idx in range(num_subject_cols):
                grade_col = 4 + subj_idx * 2 + 1
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 0.3*cm))
        elements.append(PageBreak())

        # Individual student reports
        for student_idx, student_data in enumerate(student_data_list):
            if student_idx > 0:
                elements.append(PageBreak())
            student = student_data['student']
            student_elements = []

            # Student header
            header_row = []
            if display and display.image and os.path.exists(display.image.path):
                try:
                    with PILImage.open(display.image.path) as img:
                        img.verify()
                    school_icon = RLImage(display.image.path, width=2*cm, height=2*cm)
                    school_icon.hAlign = 'CENTER'
                    header_row.append(school_icon)
                except Exception as e:
                    logger.error(f"Error loading DisplayModel image: {str(e)}")
                    header_row.append(Paragraph("", body_style))
            else:
                header_row.append(Paragraph("", body_style))

            center_content = [
                Paragraph(f"CA-Based Report for {student.fullName or 'Unnamed Student'}", header_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Class: {teacherclass.ClassName.class_name} | Academic Year: {academic_year}", subheader_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Examinations: {exam_names}", body_style)
            ]

            header_row.append(center_content)
            header_row.append(Paragraph(f"Student {student_idx + 1} of {total_students}", footer_style))

            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))
            student_elements.append(header_table)
            student_elements.append(Spacer(1, 0.3*cm))

            # Student information
            info_data = [
                [Paragraph("STUDENT INFORMATION", bold_style), "", Paragraph("ACADEMIC SUMMARY", bold_style)],
                [Paragraph(f"<b>Name:</b> {student.fullName or 'Unnamed'}", body_style), "",
                 Paragraph(f"<b>Examinations:</b> {exam_names}", body_style)],
                [Paragraph(f"<b>Index Number:</b> {student.indexNumber or '-'}", body_style), "",
                 Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style)],
                [Paragraph(f"<b>Gender:</b> {student.sex or '-'}", body_style), "",
                 Paragraph(f"<b>Academic Year:</b> {academic_year}", body_style)]
            ]
            if has_division:
                info_data[3][2] = Paragraph(f"<b>Academic Year:</b> {academic_year}<br/><b>Division:</b> {student_data['division']}", body_style)
            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))
            student_elements.append(info_table)
            student_elements.append(Spacer(1, 0.3*cm))

            # Fetch marks and teacher names for overall
            student_marks = [m for m in student.prefetched_marks]
            teacher_names = {teacher_map.get(mark.user_id, mark.user.username if mark.user else '-') for mark in student_marks if mark.user_id in teacher_map}
            teachers_display = ', '.join(sorted(teacher_names)) if teacher_names else '-'
            student_elements.append(Paragraph(f"Data Entered/Modified By: {teachers_display}", bold_style))
            student_elements.append(Spacer(1, 0.2*cm))

            # Rebuild subject_marks_per_subject for individual
            subject_marks_per_subject_individual = defaultdict(list)
            for mark in student_marks:
                subject_marks_per_subject_individual[mark.subject_id].append(mark)

            # Compute composite_info for individual (same as above)
            composite_individual_info = None
            individual_grades_for_division = []
            if grading.is_advance and composite:
                non_excluded_components = [cid for cid in component_ids_set if cid not in exclude_subjects]
                component_subject_marks_dict = {cid: subject_marks_per_subject_individual.get(cid, []) for cid in non_excluded_components}
                component_aggregates = []
                all_teachers_set = set()
                for cid, sm in component_subject_marks_dict.items():
                    if sm:
                        agg = sum(m.marks for m in sm)  # CA: sum
                        component_aggregates.append(agg)
                        for m in sm:
                            if m.user_id in teacher_map:
                                all_teachers_set.add(teacher_map[m.user_id])
                if component_aggregates:
                    composite_agg = sum(component_aggregates) / len(component_aggregates)
                    composite_grade = get_grade(composite_agg)
                    teachers_display = ', '.join(sorted(all_teachers_set)) if all_teachers_set else '-'
                    composite_individual_info = {'agg': composite_agg, 'grade': composite_grade, 'teachers': teachers_display}
                    individual_grades_for_division.append(composite_grade)

            # Build grades_for_division for non-components in individual
            for subject in subjects:
                if subject.id in component_ids_set:
                    continue
                subject_marks_local = subject_marks_per_subject_individual.get(subject.id, [])
                if subject_marks_local:
                    subject_total_local = sum(m.marks for m in subject_marks_local)  # CA
                    grade = get_grade(subject_total_local)
                    if subject.id not in exclude_subjects:
                        individual_grades_for_division.append(grade)

            # Determine display_subjects for individual
            display_subjects_individual = subjects.exclude(id__in=component_ids_set) if composite and composite.allow_to_use else subjects

            # Marks table
            valid_marks = []
            for subject in display_subjects_individual:
                subject_marks_local = subject_marks_per_subject_individual.get(subject.id, [])
                if subject_marks_local:
                    subject_total_local = sum(m.marks for m in subject_marks_local)  # CA
                    grade = get_grade(subject_total_local)
                    teacher_names_set = set()
                    for m in subject_marks_local:
                        if m.user_id in teacher_map:
                            teacher_name = teacher_map[m.user_id]
                            teacher_names_set.add(teacher_name)
                    teachers_display_sub = ', '.join(sorted(teacher_names_set)) if teacher_names_set else '-'
                    if subject_total_local > 0 and teachers_display_sub != '-':
                        remark = get_remark(grade)
                        grade_color = get_grade_color(grade)
                        valid_marks.append({
                            'subject': subject,
                            'mark': subject_total_local,
                            'grade': grade,
                            'teacher': teachers_display_sub,
                            'remark': remark,
                            'grade_color': grade_color
                        })

            # Add composite to valid_marks if applicable
            if grading.is_advance and composite and composite.allow_to_use and composite_individual_info and composite_individual_info['agg'] > 0 and composite_individual_info['teachers'] != '-':
                remark = get_remark(composite_individual_info['grade'])
                grade_color = get_grade_color(composite_individual_info['grade'])
                class DummySubject:
                    def __init__(self, name):
                        self.nameSubject = name
                dummy_sub = DummySubject(composite.subject_name)
                valid_marks.append({
                    'subject': dummy_sub,
                    'mark': round(composite_individual_info['agg'], 2),
                    'grade': composite_individual_info['grade'],
                    'teacher': composite_individual_info['teachers'],
                    'remark': remark,
                    'grade_color': grade_color
                })

            if not valid_marks:
                student_elements.append(Paragraph("No marks available for this student in the selected examinations.", body_style))
            else:
                marks_data = [['Subject', 'Mark', 'Grade', 'Teacher', 'Remarks']]
                for vm in valid_marks:
                    grade_style = ParagraphStyle(name=f'Grade{vm["grade"]}', parent=small_style, textColor=vm['grade_color'])
                    marks_data.append([
                        Paragraph(vm['subject'].nameSubject or 'Unnamed', table_text_style),
                        Paragraph(f"{vm['mark']:.2f}", small_style),
                        Paragraph(vm['grade'], grade_style),
                        Paragraph(vm['teacher'], table_text_style),
                        Paragraph(vm['remark'], table_text_style)
                    ])

                page_width = A4[0] - 30
                col_widths = [page_width * 0.35, page_width * 0.15, page_width * 0.15, page_width * 0.20, page_width * 0.15]
                marks_table = Table(marks_data, colWidths=col_widths, repeatRows=1)
                marks_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
                ]))
                student_elements.append(marks_table)
            student_elements.append(Spacer(1, 0.2*cm))

            # Academic summary
            overall_grade = student_data['grade']
            division = student_data['division']
            total_points = student_data['total_points']
            pos = exam_positions.get(student.id, '-')
            if has_division:
                summary_data = [
                    [
                        Paragraph(f"Total Marks: {student_data['total_marks']:.2f}" if student_data['total_marks'] > 0 else 'Total Marks: -', bold_style),
                        Paragraph(f"Average: {student_data['average_marks']:.2f}" if student_data['average_marks'] > 0 else 'Average: -', bold_style),
                        Paragraph(f"Overall Grade: {overall_grade}", bold_style)
                    ],
                    [
                        Paragraph(f"Division: {division}", bold_style),
                        Paragraph(f"Total Points: {total_points if total_points != '-' else '-'}", bold_style),
                        Paragraph(f"Position: {pos}/{total_students}", bold_style)
                    ]
                ]
            else:
                summary_data = [
                    [
                        Paragraph(f"Total Marks: {student_data['total_marks']:.2f}" if student_data['total_marks'] > 0 else 'Total Marks: -', bold_style),
                        Paragraph(f"Average: {student_data['average_marks']:.2f}" if student_data['average_marks'] > 0 else 'Average: -', bold_style),
                        Paragraph(f"Overall Grade: {overall_grade}<br/>Position: {pos}/{total_students}", bold_style)
                    ]
                ]
            summary_col_widths = [page_width * 0.33, page_width * 0.33, page_width * 0.34]
            summary_table = Table(summary_data, colWidths=summary_col_widths)
            summary_table.setStyle(TableStyle([
                ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                ('ALIGN', (0, 0), (-1, -1), 'LEFT'),
                ('LEFTPADDING', (0, 0), (-1, -1), 5),
                ('RIGHTPADDING', (0, 0), (-1, -1), 5),
                ('TOPPADDING', (0, 0), (-1, -1), 2),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ('FONTNAME', (0, 0), (-1, -1), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 6),
                ('LEADING', (0, 0), (-1, -1), 7),
            ]))
            student_elements.append(summary_table)
            student_elements.append(Spacer(1, 0.2*cm))

            # General remark
            remark = "No remark available"
            for r_range in remark_ranges:
                if r_range.contains(student_data['average_marks'] or 0):
                    remark = r_range.remark
                    break
            student_elements.append(Paragraph(f"General Comment: {remark}", ParagraphStyle(
                name='Comment', parent=body_style, fontSize=9, textColor=colors.HexColor('#2c3e50'),
                backColor=colors.HexColor('#f8f9fa'), borderPadding=8, alignment=TA_LEFT
            )))
            student_elements.append(Spacer(1, 0.3*cm))

            # Fee report (no changes)
            student_elements.append(Paragraph("Fee Report", subheader_style))
            student_elements.append(Spacer(1, 0.2*cm))
            student_fees = student.assigned_fees.all()
            discounts = student.discount_set.filter(teacherclass=teacherclass).select_related('fee')
            payments = student.payfee.all().order_by('-date_paid')
            student_focus = student.student_focus.first()
            initial_payment = Decimal('0.00')
            if student_focus:
                student_registration = StudentRegistration.objects.filter(studentfocus=student_focus).first()
                if student_registration and student_registration.initial_payment:
                    initial_payment = student_registration.initial_payment

            if not student_fees.exists():
                student_elements.append(Paragraph("No fees assigned.", body_style))
                student_elements.append(Spacer(1, 0.2*cm))
            else:
                col_widths_fees = [page_width * 0.25, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.15]
                fee_data = [['Fee Name', 'Required', 'Discount', 'Adjusted', 'Paid', 'Balance', 'Status']]
                total_original = total_paid_all = total_discounted = total_balance = Decimal('0.00')
                for sf in student_fees:
                    fee = sf.fee
                    discount = discounts.filter(fee=fee).first()
                    discount_amount = discount.discount_amount if discount else Decimal('0.00')
                    original_required = sf.amount_required
                    adjusted_required = original_required - discount_amount
                    total_paid = payments.filter(fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal('0.00')
                    balance = adjusted_required - total_paid
                    status = 'Paid' if balance <= 0 else 'Pending'
                    fee_data.append([
                        Paragraph(fee.fee_name, body_style),
                        Paragraph(f"{original_required:.2f}", body_style),
                        Paragraph(f"{discount_amount:.2f}", body_style),
                        Paragraph(f"{adjusted_required:.2f}", body_style),
                        Paragraph(f"{total_paid:.2f}", body_style),
                        Paragraph(f"{balance:.2f}", body_style),
                        Paragraph(status, body_style)
                    ])
                    total_original += original_required
                    total_paid_all += total_paid
                    total_balance += balance
                    total_discounted += discount_amount

                fee_data.append([
                    Paragraph('TOTAL', bold_style),
                    Paragraph(f"{total_original:.2f}", bold_style),
                    Paragraph(f"{total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_original - total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_paid_all:.2f}", bold_style),
                    Paragraph(f"{total_balance:.2f}", bold_style),
                    Paragraph('', bold_style)
                ])

                fee_table = Table(fee_data, colWidths=col_widths_fees, repeatRows=1)
                fee_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -2), colors.HexColor('#f0f4f8')),
                    ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                    ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#d0d9e5')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(fee_table)
                summary = f"Total Required: {total_original:.2f} | Total Discount: {total_discounted:.2f} | Total Paid: {total_paid_all:.2f} | Total Balance: {total_balance:.2f} | Initial Payment: {initial_payment:.2f}"
                student_elements.append(Paragraph(summary, discount_style if total_discounted > 0 else summary_style))
                student_elements.append(Spacer(1, 0.2*cm))

                # Payment records
                student_elements.append(Paragraph("Payment Records", subheader_style))
                payment_data = [['Fee Name', 'Date', 'Amount', 'Payer Account', 'Description']]
                for payment in payments:
                    payment_data.append([
                        Paragraph(payment.fee.fee_name, body_style),
                        Paragraph(payment.date_paid.strftime('%Y-%m-%d') if payment.date_paid else '-', body_style),
                        Paragraph(f"{payment.amount_paid:.2f}", body_style),
                        Paragraph(payment.payer_account_no or '-', body_style),
                        Paragraph(payment.description or '-', body_style)
                    ])
                if not payments.exists():
                    payment_data.append(['No payment records found', '-', '-', '-', '-'])

                payment_table = Table(payment_data, colWidths=[page_width * 0.25, page_width * 0.15, page_width * 0.15, page_width * 0.25, page_width * 0.25], repeatRows=1)
                payment_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -1), colors.HexColor('#f0f4f8')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(payment_table)
                student_elements.append(Spacer(1, 0.3*cm))

            # Signature and stamp
            signature_row = []
            if source_doc and source_doc.extracted_signature and os.path.exists(source_doc.extracted_signature.path):
                try:
                    with PILImage.open(source_doc.extracted_signature.path) as img:
                        img.verify()
                    sig_img = RLImage(source_doc.extracted_signature.path, width=3*cm, height=1.5*cm)
                    sig_img.hAlign = 'LEFT'
                    signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
                except Exception as e:
                    logger.error(f"Error loading signature: {str(e)}")
                    signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])

            signature_row.append(Spacer(1, 2*cm))

            if source_doc and source_doc.extracted_stamp and os.path.exists(source_doc.extracted_stamp.path):
                try:
                    with PILImage.open(source_doc.extracted_stamp.path) as img:
                        img.verify()
                    stamp_img = RLImage(source_doc.extracted_stamp.path, width=2.5*cm, height=2.5*cm)
                    stamp_img.hAlign = 'RIGHT'
                    signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
                except Exception as e:
                    logger.error(f"Error loading stamp: {str(e)}")
                    signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])

            signature_table = Table([signature_row], colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))

            student_elements.append(signature_table)
            student_elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

            elements.append(KeepTogether(student_elements))

    elements.append(Spacer(1, 0.3*cm))
    elements.append(Paragraph(f"Generated on: {current_time}", footer_style))
    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        messages.success(request, 'CA-Based Academic and Financial report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')


@csrf_exempt
@login_required
def download_final_result_financial_pdf(request, class_id, grade_id):
    exam_ids = request.POST.getlist('exams')
    if not exam_ids:
        messages.error(request, "No examinations selected.")
        return redirect('all_student_marks')

    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    examination_names = ExaminationName.objects.filter(id__in=exam_ids, user=request.user)
    if not examination_names.exists():
        messages.error(request, "No examinations found for the selected IDs.")
        return redirect('all_student_marks')

    display = DisplayModel.objects.filter(user=request.user).first()
    creator = getattr(request, 'creator', request.user)
    if not creator:
        try:
            teacher_profile = Teacher.objects.get(user=request.user)
            creator = teacher_profile.created_by or request.user
        except Teacher.DoesNotExist:
            messages.error(request, "Your account is not linked to a valid teacher profile.")
            return redirect('teacher_dashboard')

    if grading.is_primary:
        level = 'Primary'
        has_division = False
        exclude_subjects = set()
    else:
        level = 'Alevel' if grading.is_advance else 'Olevel'
        has_division = True
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))

    required_subjects = RequiredSubject.objects.filter(user=request.user, level=level, teacherclass_id=class_id)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')

    # CompositeSubject integration for A-Level
    composite = None
    component_ids_set = set()
    composite_info = None
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))

    students = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(subject__in=subjects, examinationname__in=examination_names).select_related('subject', 'examinationname', 'user'), to_attr='prefetched_marks'),
        Prefetch('assigned_fees', queryset=StudentFee.objects.filter(teacherclass=teacherclass).select_related('fee')),
        Prefetch('payfee', queryset=PayFee.objects.select_related('fee')),
        Prefetch('discount_set', queryset=Discount.objects.filter(teacherclass=teacherclass).select_related('fee')),
        Prefetch('student_focus', queryset=StudentFocus.objects.prefetch_related('student_fcs'))
    )

    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname__in=examination_names).select_related('user')
    user_ids = {mark.user_id for mark in all_marks if mark.user_id}
    teacher_map = {teacher.user_id: teacher.teacherName or teacher.user.username 
                   for teacher in Teacher.objects.filter(user__in=user_ids)}

    response = HttpResponse(content_type='application/pdf')
    exam_suffix = "_".join(examination_names.values_list('exam_name', flat=True)).replace(' ', '_')
    filename = f"final_result_financial_{teacherclass.ClassName.class_name or 'Unnamed_Class'}_{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=8)
    discount_style = ParagraphStyle(name='Discount', parent=styles['BodyText'], fontSize=9, textColor=colors.red, spaceAfter=4)
    summary_style = ParagraphStyle(name='Summary', parent=styles['BodyText'], fontSize=9, fontName='Helvetica-Bold', spaceAfter=4)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=6, alignment=TA_CENTER, leading=7)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 6

    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E'
        }
        grade_points = {}
        min_subjects_for_division = None
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A', grading.grade_b: 'B', grading.grade_c: 'C', grading.grade_d: 'D',
            grading.grade_e: 'E', grading.grade_s: 'S', grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A', grading.grade_b: 'B', grading.grade_c: 'C', grading.grade_d: 'D', grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    def get_grade(mark):
        if mark is None:
            return '-'
        for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
            if mark >= threshold:
                return grade
        return 'E' if grading.is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent', 'B': 'Very Good', 'C': 'Good', 'D': 'Pass',
            'F': 'Fail', '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            if 'S' in grade_thresholds.values():
                remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = min_subjects_for_division
        if num_valid_subjects < req_subs:
            return "Inc", '-'
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    header_text = display.header if display else f"Final Academic and Financial Report for {teacherclass.ClassName.class_name or 'Unnamed Class'}"
    elements.append(Paragraph(header_text, header_style))
    elements.append(Spacer(1, 0.3*cm))
    academic_year = teacherclass.academicclassyear.academic_year_name if teacherclass.academicclassyear else 'N/A'
    exam_names = ", ".join(exam.exam_name for exam in examination_names)
    elements.append(Paragraph(display.body if display else f"Final Summary for {exam_names} - {teacherclass.ClassName.class_name} ({academic_year})", subheader_style))
    elements.append(Spacer(1, 0.3*cm))

    if display and display.image and os.path.exists(display.image.path):
        try:
            with PILImage.open(display.image.path) as img:
                img.verify()
            icon = RLImage(display.image.path, width=2*cm, height=2*cm)
            icon.hAlign = 'CENTER'
            elements.append(icon)
            elements.append(Spacer(1, 0.3*cm))
        except Exception as e:
            logger.error(f"Error loading DisplayModel image: {e}")

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.filter(user=request.user)

    if not students.exists() or not subjects.exists() or not examination_names.exists():
        elements.append(Paragraph("No data available for this class or examinations.", body_style))
    else:
        # Process student data
        student_data_list = []
        for student in students:
            all_marks_list = [m for m in student.prefetched_marks]
            total_marks = sum(m.marks for m in all_marks_list) or 0
            count = len(all_marks_list)
            average_marks = (total_marks / count) if count > 0 else 0
            subject_marks_per_subject = defaultdict(list)
            for m in all_marks_list:
                subject_marks_per_subject[m.subject_id].append(m)

            # Compute composite_info if applicable (for final: avg)
            composite_local_info = None
            local_grades_for_division = []
            if grading.is_advance and composite:
                non_excluded_components = [cid for cid in component_ids_set if cid not in exclude_subjects]
                component_subject_marks_dict = {cid: subject_marks_per_subject.get(cid, []) for cid in non_excluded_components}
                component_aggregates = []
                all_teachers_set = set()
                for cid, sm in component_subject_marks_dict.items():
                    if sm:
                        agg = sum(m.marks for m in sm) / len(sm) if sm else 0  # Final: avg
                        component_aggregates.append(agg)
                        for m in sm:
                            if m.user_id in teacher_map:
                                all_teachers_set.add(teacher_map[m.user_id])
                if component_aggregates:
                    composite_agg = sum(component_aggregates) / len(component_aggregates)
                    composite_grade = get_grade(composite_agg)
                    teachers_display = ', '.join(sorted(all_teachers_set)) if all_teachers_set else '-'
                    composite_local_info = {'agg': composite_agg, 'grade': composite_grade, 'teachers': teachers_display}
                    local_grades_for_division.append(composite_grade)

            # Build grades_for_division for non-component subjects
            for subject in subjects:
                if subject.id in component_ids_set:
                    continue
                subject_marks = subject_marks_per_subject.get(subject.id, [])
                if subject_marks:
                    subject_avg = sum(m.marks for m in subject_marks) / len(subject_marks) if subject_marks else 0  # Final: avg
                    grade = get_grade(subject_avg)
                    if subject.id not in exclude_subjects:
                        local_grades_for_division.append(grade)

            # Determine display_subjects
            if composite and composite.allow_to_use:
                display_subjects_local = subjects.exclude(id__in=component_ids_set)
            else:
                display_subjects_local = subjects

            # Build marks_list
            marks_list_local = []
            for subject in display_subjects_local:
                subject_marks = subject_marks_per_subject.get(subject.id, [])
                if subject_marks:
                    subject_avg = sum(m.marks for m in subject_marks) / len(subject_marks) if subject_marks else 0  # Final: avg
                    grade = get_grade(subject_avg)
                    teacher_names = set()
                    for m in subject_marks:
                        if m.user_id in teacher_map:
                            teacher_names.add(teacher_map[m.user_id])
                    teachers_display = ', '.join(sorted(teacher_names)) if teacher_names else '-'
                    marks_list_local.append({
                        'subject_id': str(subject.id),
                        'subject_name': subject.nameSubject,
                        'mark': subject_avg,
                        'grade': grade,
                        'is_excluded': subject.id in exclude_subjects,
                        'teacher_name': teachers_display
                    })

            # Add composite to marks_list if applicable
            if grading.is_advance and composite and composite.allow_to_use and composite_local_info:
                marks_list_local.append({
                    'subject_id': 'composite',
                    'subject_name': composite.subject_name,
                    'mark': round(composite_local_info['agg'], 2),
                    'grade': composite_local_info['grade'],
                    'is_excluded': False,
                    'teacher_name': composite_local_info['teachers']
                })

            division, total_points = get_division(local_grades_for_division)
            has_valid_marks = len(marks_list_local) > 0
            student_data_list.append({
                'student': student,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'marks': marks_list_local,
                'grade': get_grade(average_marks),
                'division': division,
                'total_points': total_points,
                'has_valid_marks': has_valid_marks
            })

        # Sort students
        student_data_list.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))

        total_students = len(student_data_list)

        # Class-level academic summary
        elements.append(Paragraph("Final Academic Results", subheader_style))
        elements.append(Spacer(1, 0.2*cm))

        # Determine display for table
        display_subjects_table = subjects.exclude(id__in=component_ids_set) if composite and composite.allow_to_use else subjects
        num_subject_cols = len(display_subjects_table) + (1 if composite and composite.allow_to_use else 0)

        # Build multi-level header
        header_row1 = [
            'Pos', 
            'Student Name', 
            'Sex', 
            'Index No'
        ]
        for s in display_subjects_table:
            header_row1.append(s.nameSubject)
            header_row1.append('')  # Placeholder for span
        if composite and composite.allow_to_use:
            header_row1.append(composite.subject_name)
            header_row1.append('')

        header_row1 += ['Total', 'Avg', 'Grade', 'Pos']
        if has_division:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '']  # Empty for first four columns
        for _ in range(num_subject_cols):
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '', '']
        if has_division:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans
        subject_start_col = 4
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),
            ('SPAN', (1, 0), (1, 1)),
            ('SPAN', (2, 0), (2, 1)),
            ('SPAN', (3, 0), (3, 1)),
        ]
        for i in range(len(display_subjects_table)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))
        if composite and composite.allow_to_use:
            start_col = subject_start_col + len(display_subjects_table) * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))

        subject_end_col = subject_start_col + num_subject_cols * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),
            ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),
        ]
        if has_division:
            table_style_commands += [
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),
                ('SPAN', (subject_end_col + 6, 0), (subject_end_col + 6, 1)),
            ]

        exam_positions = {}
        for pos, student_data in enumerate(student_data_list, 1):
            exam_positions[student_data['student'].id] = pos

        for i, student_data in enumerate(student_data_list, 1):
            row = [str(i), student_data['student'].fullName or 'Unnamed', student_data['student'].sex or '-', student_data['student'].indexNumber or '-']
            subject_mark_infos = {m['subject_id']: m for m in student_data['marks']}
            for s in display_subjects_table:
                mark_info = subject_mark_infos.get(str(s.id), {'mark': 0, 'grade': '-'})
                mark_str = f"{mark_info['mark']:.2f}" if mark_info['mark'] > 0 else '-'
                grade = mark_info['grade'] if mark_info['mark'] > 0 else '-'
                row.append(mark_str)
                row.append(grade)
            if composite and composite.allow_to_use:
                c_info = subject_mark_infos.get('composite', {'mark': 0, 'grade': '-'})
                mark_str = f"{c_info['mark']:.2f}" if c_info['mark'] > 0 else '-'
                grade = c_info['grade'] if c_info['mark'] > 0 else '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student_data['total_marks']:.2f}" if student_data['total_marks'] > 0 else '-',
                f"{student_data['average_marks']:.2f}" if student_data['average_marks'] > 0 else '-',
                student_data['grade'],
                str(i)
            ])
            if has_division:
                total_pts_display = str(student_data['total_points']) if student_data['total_points'] != '-' else '-'
                row.extend([
                    student_data['division'],
                    total_pts_display
                ])
            table_data.append(row)

        page_width = A4[0] - 30
        num_final_cols = 4 + (2 if has_division else 0)
        base_width = page_width / (4 + num_subject_cols * 2 + num_final_cols)
        col_widths = (
            [base_width * 0.5] +  # Pos
            [base_width * 2.5] +  # Name
            [base_width * 0.5] +  # Sex
            [base_width * 1.5] +  # Index
            [base_width * 0.7, base_width * 0.5] * num_subject_cols +  # Mark, Grade (wider for final)
            [base_width * 0.8] * 4  # Total, Avg, Grade, Pos
        )
        if has_division:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors using range
        for row_idx, row in enumerate(table_data[2:], start=2):
            for subj_idx in range(num_subject_cols):
                grade_col = 4 + subj_idx * 2 + 1
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 0.3*cm))
        elements.append(PageBreak())

        # Individual student reports
        for student_idx, student_data in enumerate(student_data_list):
            if student_idx > 0:
                elements.append(PageBreak())
            student = student_data['student']
            student_elements = []

            # Student header
            header_row = []
            if display and display.image and os.path.exists(display.image.path):
                try:
                    with PILImage.open(display.image.path) as img:
                        img.verify()
                    school_icon = RLImage(display.image.path, width=2*cm, height=2*cm)
                    school_icon.hAlign = 'CENTER'
                    header_row.append(school_icon)
                except Exception as e:
                    logger.error(f"Error loading DisplayModel image: {str(e)}")
                    header_row.append(Paragraph("", body_style))
            else:
                header_row.append(Paragraph("", body_style))

            center_content = [
                Paragraph(f"Final Report for {student.fullName or 'Unnamed Student'}", header_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Class: {teacherclass.ClassName.class_name} | Academic Year: {academic_year}", subheader_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Examinations: {exam_names}", body_style)
            ]

            header_row.append(center_content)
            header_row.append(Paragraph(f"Student {student_idx + 1} of {total_students}", footer_style))

            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))
            student_elements.append(header_table)
            student_elements.append(Spacer(1, 0.3*cm))

            # Student information
            info_data = [
                [Paragraph("STUDENT INFORMATION", bold_style), "", Paragraph("ACADEMIC SUMMARY", bold_style)],
                [Paragraph(f"<b>Name:</b> {student.fullName or 'Unnamed'}", body_style), "",
                 Paragraph(f"<b>Examinations:</b> {exam_names}", body_style)],
                [Paragraph(f"<b>Index Number:</b> {student.indexNumber or '-'}", body_style), "",
                 Paragraph(f"<b>Class:</b> {teacherclass.ClassName.class_name}", body_style)],
                [Paragraph(f"<b>Gender:</b> {student.sex or '-'}", body_style), "",
                 Paragraph(f"<b>Academic Year:</b> {academic_year}", body_style)]
            ]
            if has_division:
                info_data[3][2] = Paragraph(f"<b>Academic Year:</b> {academic_year}<br/><b>Division:</b> {student_data['division']}", body_style)
            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))
            student_elements.append(info_table)
            student_elements.append(Spacer(1, 0.3*cm))

            # Fetch marks and teacher names for overall
            student_marks = [m for m in student.prefetched_marks]
            teacher_names = {teacher_map.get(mark.user_id, mark.user.username if mark.user else '-') for mark in student_marks if mark.user_id in teacher_map}
            teachers_display = ', '.join(sorted(teacher_names)) if teacher_names else '-'
            student_elements.append(Paragraph(f"Data Entered/Modified By: {teachers_display}", bold_style))
            student_elements.append(Spacer(1, 0.2*cm))

            # Rebuild subject_marks_per_subject for individual
            subject_marks_per_subject_individual = defaultdict(list)
            for mark in student_marks:
                subject_marks_per_subject_individual[mark.subject_id].append(mark)

            # Compute composite_info for individual (for final: avg)
            composite_individual_info = None
            individual_grades_for_division = []
            if grading.is_advance and composite:
                non_excluded_components = [cid for cid in component_ids_set if cid not in exclude_subjects]
                component_subject_marks_dict = {cid: subject_marks_per_subject_individual.get(cid, []) for cid in non_excluded_components}
                component_aggregates = []
                all_teachers_set = set()
                for cid, sm in component_subject_marks_dict.items():
                    if sm:
                        agg = sum(m.marks for m in sm) / len(sm) if sm else 0  # Final: avg
                        component_aggregates.append(agg)
                        for m in sm:
                            if m.user_id in teacher_map:
                                all_teachers_set.add(teacher_map[m.user_id])
                if component_aggregates:
                    composite_agg = sum(component_aggregates) / len(component_aggregates)
                    composite_grade = get_grade(composite_agg)
                    teachers_display = ', '.join(sorted(all_teachers_set)) if all_teachers_set else '-'
                    composite_individual_info = {'agg': composite_agg, 'grade': composite_grade, 'teachers': teachers_display}
                    individual_grades_for_division.append(composite_grade)

            # Build grades_for_division for non-components in individual
            for subject in subjects:
                if subject.id in component_ids_set:
                    continue
                subject_marks_local = subject_marks_per_subject_individual.get(subject.id, [])
                if subject_marks_local:
                    subject_avg_local = sum(m.marks for m in subject_marks_local) / len(subject_marks_local) if subject_marks_local else 0  # Final
                    grade = get_grade(subject_avg_local)
                    if subject.id not in exclude_subjects:
                        individual_grades_for_division.append(grade)

            # Determine display_subjects for individual
            display_subjects_individual = subjects.exclude(id__in=component_ids_set) if composite and composite.allow_to_use else subjects

            # Marks table
            valid_marks = []
            for subject in display_subjects_individual:
                subject_marks_local = subject_marks_per_subject_individual.get(subject.id, [])
                if subject_marks_local:
                    subject_avg_local = sum(m.marks for m in subject_marks_local) / len(subject_marks_local) if subject_marks_local else 0  # Final
                    grade = get_grade(subject_avg_local)
                    teacher_names_set = set()
                    for m in subject_marks_local:
                        if m.user_id in teacher_map:
                            teacher_name = teacher_map[m.user_id]
                            teacher_names_set.add(teacher_name)
                    teachers_display_sub = ', '.join(sorted(teacher_names_set)) if teacher_names_set else '-'
                    if subject_avg_local > 0 and teachers_display_sub != '-':
                        remark = get_remark(grade)
                        grade_color = get_grade_color(grade)
                        valid_marks.append({
                            'subject': subject,
                            'mark': subject_avg_local,
                            'grade': grade,
                            'teacher': teachers_display_sub,
                            'remark': remark,
                            'grade_color': grade_color
                        })

            # Add composite to valid_marks if applicable
            if grading.is_advance and composite and composite.allow_to_use and composite_individual_info and composite_individual_info['agg'] > 0 and composite_individual_info['teachers'] != '-':
                remark = get_remark(composite_individual_info['grade'])
                grade_color = get_grade_color(composite_individual_info['grade'])
                class DummySubject:
                    def __init__(self, name):
                        self.nameSubject = name
                dummy_sub = DummySubject(composite.subject_name)
                valid_marks.append({
                    'subject': dummy_sub,
                    'mark': round(composite_individual_info['agg'], 2),
                    'grade': composite_individual_info['grade'],
                    'teacher': composite_individual_info['teachers'],
                    'remark': remark,
                    'grade_color': grade_color
                })

            if not valid_marks:
                student_elements.append(Paragraph("No marks available for this student in the selected examinations.", body_style))
            else:
                marks_data = [['Subject', 'Mark', 'Grade', 'Teacher', 'Remarks']]
                for vm in valid_marks:
                    grade_style = ParagraphStyle(name=f'Grade{vm["grade"]}', parent=small_style, textColor=vm['grade_color'])
                    marks_data.append([
                        Paragraph(vm['subject'].nameSubject or 'Unnamed', table_text_style),
                        Paragraph(f"{vm['mark']:.2f}", small_style),
                        Paragraph(vm['grade'], grade_style),
                        Paragraph(vm['teacher'], table_text_style),
                        Paragraph(vm['remark'], table_text_style)
                    ])

                page_width = A4[0] - 30
                col_widths = [page_width * 0.35, page_width * 0.15, page_width * 0.15, page_width * 0.20, page_width * 0.15]
                marks_table = Table(marks_data, colWidths=col_widths, repeatRows=1)
                marks_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
                ]))
                student_elements.append(marks_table)
            student_elements.append(Spacer(1, 0.2*cm))

            # Academic summary
            overall_grade = student_data['grade']
            division = student_data['division']
            total_points = student_data['total_points']
            pos = exam_positions.get(student.id, '-')
            if has_division:
                summary_data = [
                    [
                        Paragraph(f"Total Marks: {student_data['total_marks']:.2f}" if student_data['total_marks'] > 0 else 'Total Marks: -', bold_style),
                        Paragraph(f"Average: {student_data['average_marks']:.2f}" if student_data['average_marks'] > 0 else 'Average: -', bold_style),
                        Paragraph(f"Overall Grade: {overall_grade}", bold_style)
                    ],
                    [
                        Paragraph(f"Division: {division}", bold_style),
                        Paragraph(f"Total Points: {total_points if total_points != '-' else '-'}", bold_style),
                        Paragraph(f"Position: {pos}/{total_students}", bold_style)
                    ]
                ]
            else:
                summary_data = [
                    [
                        Paragraph(f"Total Marks: {student_data['total_marks']:.2f}" if student_data['total_marks'] > 0 else 'Total Marks: -', bold_style),
                        Paragraph(f"Average: {student_data['average_marks']:.2f}" if student_data['average_marks'] > 0 else 'Average: -', bold_style),
                        Paragraph(f"Overall Grade: {overall_grade}<br/>Position: {pos}/{total_students}", bold_style)
                    ]
                ]
            summary_col_widths = [page_width * 0.33, page_width * 0.33, page_width * 0.34]
            summary_table = Table(summary_data, colWidths=summary_col_widths)
            summary_table.setStyle(TableStyle([
                ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                ('ALIGN', (0, 0), (-1, -1), 'LEFT'),
                ('LEFTPADDING', (0, 0), (-1, -1), 5),
                ('RIGHTPADDING', (0, 0), (-1, -1), 5),
                ('TOPPADDING', (0, 0), (-1, -1), 2),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ('FONTNAME', (0, 0), (-1, -1), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 6),
                ('LEADING', (0, 0), (-1, -1), 7),
            ]))
            student_elements.append(summary_table)
            student_elements.append(Spacer(1, 0.2*cm))

            # General remark
            remark = "No remark available"
            for r_range in remark_ranges:
                if r_range.contains(student_data['average_marks'] or 0):
                    remark = r_range.remark
                    break
            student_elements.append(Paragraph(f"General Comment: {remark}", ParagraphStyle(
                name='Comment', parent=body_style, fontSize=9, textColor=colors.HexColor('#2c3e50'),
                backColor=colors.HexColor('#f8f9fa'), borderPadding=8, alignment=TA_LEFT
            )))
            student_elements.append(Spacer(1, 0.3*cm))

            # Fee report (no changes)
            student_elements.append(Paragraph("Fee Report", subheader_style))
            student_elements.append(Spacer(1, 0.2*cm))
            student_fees = student.assigned_fees.all()
            discounts = student.discount_set.filter(teacherclass=teacherclass).select_related('fee')
            payments = student.payfee.all().order_by('-date_paid')
            student_focus = student.student_focus.first()
            initial_payment = Decimal('0.00')
            if student_focus:
                student_registration = StudentRegistration.objects.filter(studentfocus=student_focus).first()
                if student_registration and student_registration.initial_payment:
                    initial_payment = student_registration.initial_payment

            if not student_fees.exists():
                student_elements.append(Paragraph("No fees assigned.", body_style))
                student_elements.append(Spacer(1, 0.2*cm))
            else:
                col_widths_fees = [page_width * 0.25, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.12, page_width * 0.15]
                fee_data = [['Fee Name', 'Required', 'Discount', 'Adjusted', 'Paid', 'Balance', 'Status']]
                total_original = total_paid_all = total_discounted = total_balance = Decimal('0.00')
                for sf in student_fees:
                    fee = sf.fee
                    discount = discounts.filter(fee=fee).first()
                    discount_amount = discount.discount_amount if discount else Decimal('0.00')
                    original_required = sf.amount_required
                    adjusted_required = original_required - discount_amount
                    total_paid = payments.filter(fee=fee).aggregate(total=Sum('amount_paid'))['total'] or Decimal('0.00')
                    balance = adjusted_required - total_paid
                    status = 'Paid' if balance <= 0 else 'Pending'
                    fee_data.append([
                        Paragraph(fee.fee_name, body_style),
                        Paragraph(f"{original_required:.2f}", body_style),
                        Paragraph(f"{discount_amount:.2f}", body_style),
                        Paragraph(f"{adjusted_required:.2f}", body_style),
                        Paragraph(f"{total_paid:.2f}", body_style),
                        Paragraph(f"{balance:.2f}", body_style),
                        Paragraph(status, body_style)
                    ])
                    total_original += original_required
                    total_paid_all += total_paid
                    total_balance += balance
                    total_discounted += discount_amount

                fee_data.append([
                    Paragraph('TOTAL', bold_style),
                    Paragraph(f"{total_original:.2f}", bold_style),
                    Paragraph(f"{total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_original - total_discounted:.2f}", bold_style),
                    Paragraph(f"{total_paid_all:.2f}", bold_style),
                    Paragraph(f"{total_balance:.2f}", bold_style),
                    Paragraph('', bold_style)
                ])

                fee_table = Table(fee_data, colWidths=col_widths_fees, repeatRows=1)
                fee_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -2), colors.HexColor('#f0f4f8')),
                    ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                    ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#d0d9e5')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(fee_table)
                summary = f"Total Required: {total_original:.2f} | Total Discount: {total_discounted:.2f} | Total Paid: {total_paid_all:.2f} | Total Balance: {total_balance:.2f} | Initial Payment: {initial_payment:.2f}"
                student_elements.append(Paragraph(summary, discount_style if total_discounted > 0 else summary_style))
                student_elements.append(Spacer(1, 0.2*cm))

                # Payment records
                student_elements.append(Paragraph("Payment Records", subheader_style))
                payment_data = [['Fee Name', 'Date', 'Amount', 'Payer Account', 'Description']]
                for payment in payments:
                    payment_data.append([
                        Paragraph(payment.fee.fee_name, body_style),
                        Paragraph(payment.date_paid.strftime('%Y-%m-%d') if payment.date_paid else '-', body_style),
                        Paragraph(f"{payment.amount_paid:.2f}", body_style),
                        Paragraph(payment.payer_account_no or '-', body_style),
                        Paragraph(payment.description or '-', body_style)
                    ])
                if not payments.exists():
                    payment_data.append(['No payment records found', '-', '-', '-', '-'])

                payment_table = Table(payment_data, colWidths=[page_width * 0.25, page_width * 0.15, page_width * 0.15, page_width * 0.25, page_width * 0.25], repeatRows=1)
                payment_table.setStyle(TableStyle([
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#4a69bd')),
                    ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, 0), 8),
                    ('FONTSIZE', (0, 1), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 7),
                    ('BACKGROUND', (0, 1), (-1, -1), colors.HexColor('#f0f4f8')),
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3),
                    ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 2),
                    ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
                ]))
                student_elements.append(payment_table)
                student_elements.append(Spacer(1, 0.3*cm))

            # Signature and stamp
            signature_row = []
            if source_doc and source_doc.extracted_signature and os.path.exists(source_doc.extracted_signature.path):
                try:
                    with PILImage.open(source_doc.extracted_signature.path) as img:
                        img.verify()
                    sig_img = RLImage(source_doc.extracted_signature.path, width=3*cm, height=1.5*cm)
                    sig_img.hAlign = 'LEFT'
                    signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
                except Exception as e:
                    logger.error(f"Error loading signature: {str(e)}")
                    signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])

            signature_row.append(Spacer(1, 2*cm))

            if source_doc and source_doc.extracted_stamp and os.path.exists(source_doc.extracted_stamp.path):
                try:
                    with PILImage.open(source_doc.extracted_stamp.path) as img:
                        img.verify()
                    stamp_img = RLImage(source_doc.extracted_stamp.path, width=2.5*cm, height=2.5*cm)
                    stamp_img.hAlign = 'RIGHT'
                    signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
                except Exception as e:
                    logger.error(f"Error loading stamp: {str(e)}")
                    signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])

            signature_table = Table([signature_row], colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))

            student_elements.append(signature_table)
            student_elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

            elements.append(KeepTogether(student_elements))

    elements.append(Spacer(1, 0.3*cm))
    elements.append(Paragraph(f"Generated on: {current_time}", footer_style))
    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        messages.success(request, 'Final Academic and Financial report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib import messages
from django.contrib.auth.decorators import login_required
from .models import TeacherSubject, Student, Mark, ExaminationName, Teacher, StudentSubject
import pandas as pd
from django.http import HttpResponse
from io import BytesIO


@login_required
def upload_marks(request, teacher_subject_id):
    try:
        teacher_profile = request.user.teacher_profile.get()
    except Teacher.DoesNotExist:
        messages.error(request, "Teacher profile not found. Contact your administrator.")
        return redirect('teacher_dashboard')

    teacher_subject = get_object_or_404(
        TeacherSubject,
        id=teacher_subject_id,
        teacher=teacher_profile
    )

    examination_name_id = request.session.get('selected_examination_id')
    if not examination_name_id:
        messages.error(request, "Please select an examination first.")
        return redirect('select_examination_name', teacher_subject_id=teacher_subject_id)

    try:
        examination_name = ExaminationName.objects.get(
            id=examination_name_id,
            user=teacher_profile.created_by
        )
    except ExaminationName.DoesNotExist:
        messages.error(request, "Selected examination name is invalid.")
        if 'selected_examination_id' in request.session:
            del request.session['selected_examination_id']
        return redirect('select_examination_name', teacher_subject_id=teacher_subject_id)

    current_teacher_class = teacher_subject.teacherclass
    try:
        academic_class_year = current_teacher_class.academicclassyear
        if not academic_class_year.active_year:
            messages.error(request, f"The academic year '{academic_class_year.academic_year_name}' for this class is not active.")
            return redirect('teacher_dashboard')
    except AttributeError:
        messages.error(request, "No academic year associated with this class.")
        return redirect('teacher_dashboard')

    student_subjects = StudentSubject.objects.filter(
        teacherclass=current_teacher_class,
        subject=teacher_subject.subject,
        teacherclass__academicclassyear__active_year=True
    )

    if student_subjects.exists():
        student_ids = set()
        for student_subject in student_subjects:
            student_ids.update(student_subject.student.values_list('id', flat=True))
        students = Student.objects.filter(
            id__in=student_ids,
            teacherclass=current_teacher_class,
            teacherclass__academicclassyear__active_year=True
        ).select_related('user').order_by('fullName')
    else:
        students = Student.objects.none()

    student_marks = {
        mark.student_id: mark.marks for mark in Mark.objects.filter(
            teacherclass=current_teacher_class,
            subject=teacher_subject.subject,
            examinationname=examination_name,
            student__in=students,
            teacherclass__academicclassyear__active_year=True
        )
    }

    saved_marks = Mark.objects.filter(
        teacherclass=current_teacher_class,
        subject=teacher_subject.subject,
        examinationname=examination_name,
        student__in=students,
        teacherclass__academicclassyear__active_year=True
    ).select_related('student').order_by('student__fullName')

    if request.GET.get('download_template'):
        # Generate Excel template with existing marks if available
        data = {
            'Student Name': [student.fullName or 'Unnamed Student' for student in students],
            'Index Number': [student.indexNumber or 'N/A' for student in students],
            'Mark': [student_marks.get(student.id, '') for student in students]  # Populate with existing marks or empty
        }
        df = pd.DataFrame(data)
        
        # Create Excel file in memory
        output = BytesIO()
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, index=False, sheet_name='Marks')
        
        # Prepare response
        output.seek(0)
        response = HttpResponse(
            content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            content=output.read()
        )
        filename = f"marks_template_{teacher_subject.subject.nameSubject}_{examination_name.exam_name}.xlsx"
        response['Content-Disposition'] = f'attachment; filename="{filename}"'
        return response

    if request.method == 'POST':
        if teacher_subject.is_restricted:
            messages.error(request, "Marks for this subject are restricted.")
            return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

        if 'excel_file' not in request.FILES:
            messages.error(request, "No file uploaded.")
            return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

        excel_file = request.FILES['excel_file']
        if not excel_file.name.endswith(('.xlsx', '.xls')):
            messages.error(request, "Please upload a valid Excel file (.xlsx or .xls).")
            return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

        try:
            df = pd.read_excel(excel_file)
            required_columns = ['Student Name', 'Index Number', 'Mark']
            if not all(col in df.columns for col in required_columns):
                messages.error(request, "Excel file must contain 'Student Name', 'Index Number', and 'Mark' columns.")
                return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

            # Validate and process marks
            student_index_map = {student.indexNumber: student for student in students if student.indexNumber}
            for index, row in df.iterrows():
                index_number = str(row['Index Number']).strip()
                mark_value = row['Mark']

                if pd.isna(mark_value):
                    continue  # Skip rows with empty marks

                try:
                    mark_value = float(mark_value)
                    if not (0 <= mark_value <= 100):
                        raise ValueError("Marks must be between 0 and 100.")
                except (ValueError, TypeError):
                    messages.error(request, f"Invalid mark for Index Number {index_number}: Must be a number between 0 and 100.")
                    continue

                student = student_index_map.get(index_number)
                if not student:
                    messages.error(request, f"No student found with Index Number {index_number}.")
                    continue

                Mark.objects.update_or_create(
                    teacherclass=current_teacher_class,
                    subject=teacher_subject.subject,
                    examinationname=examination_name,
                    student=student,
                    defaults={
                        'marks': mark_value,
                        'user': request.user
                    }
                )

            messages.success(request, "Marks uploaded successfully!")
            return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

        except Exception as e:
            messages.error(request, f"Error processing Excel file: {str(e)}")
            return redirect('fill_marks', teacher_subject_id=teacher_subject_id)

    context = {
        'teacher_subject': teacher_subject,
        'students': students,
        'student_marks': student_marks,
        'saved_marks': saved_marks,
        'examination_name': examination_name,
        'academic_class_year': academic_class_year,
        'current_teacher_class': current_teacher_class,
    }
    return render(request, 'fill_marks.html', context)




