def determine_grade(mark, grading):
    thresholds = grading.get_thresholds()
    if not thresholds:
        return 'F'  # Or handle empty case as needed
    
    sorted_thresholds = sorted(thresholds.items(), key=lambda x: x[0], reverse=True)
    for threshold, grade in sorted_thresholds:
        if mark >= threshold:
            return grade
    
    # Fallback to lowest grade (matches primary 'E' or O/A 'F')
    lowest_grade = list(thresholds.values())[-1] if thresholds else 'F'
    return lowest_grade


@effective_user_decorator
@login_required
def teacher_profile(request):
    # --------------------------------------------------------------
    # 1. Use effective_user from decorator (creator or self)
    # --------------------------------------------------------------
    effective_user = request.effective_user

    # --------------------------------------------------------------
    # 2. Get the Teacher profile safely
    # --------------------------------------------------------------
    try:
        teacher = Teacher.objects.get(user=request.user)
    except Teacher.DoesNotExist:
        messages.error(request, "Teacher profile not found.")
        return redirect('home')

    # Creator is the one who created this teacher
    creator = teacher.created_by if teacher.created_by else request.user

    # --------------------------------------------------------------
    # 3. Allow access: teacher himself OR creator
    # --------------------------------------------------------------
    if request.user != teacher.user and effective_user != creator:
        messages.error(request, "Access denied. You can only view your own profile or profiles you created.")
        return redirect('home')

    # Use creator for all data (unless superuser)
    data_owner = request.user if request.user.is_superuser else creator

    # --------------------------------------------------------------
    # 4. Email verification status
    # --------------------------------------------------------------
    is_email_verified = EmailVerificationOTP.objects.filter(
        user=request.user, is_verified=True, purpose='verification'
    ).exists()

    # --------------------------------------------------------------
    # 5. Examination Names (created by data_owner)
    # --------------------------------------------------------------
    exams = ExaminationName.objects.filter(user=data_owner).order_by('-id')

    # --------------------------------------------------------------
    # 6. GET Filters
    # --------------------------------------------------------------
    class_filter = request.GET.get('class_filter')
    grading_filter = request.GET.get('grading_filter', 'O LEVEL')
    examination_filter = request.GET.get('examination_filter')
    rank_by = request.GET.get('rank_by', 'class')  # class, stream, all

    # Default exam
    if not examination_filter and exams.exists():
        examination_filter = exams.first().id
    selected_exam = ExaminationName.objects.filter(id=examination_filter, user=data_owner).first() if examination_filter else None

    # --------------------------------------------------------------
    # 7. Assigned Classes (for dropdown)
    # --------------------------------------------------------------
    assigned_classes = TeacherClass.objects.filter(
        teachersubject__teacher=teacher
    ).distinct().select_related('ClassName', 'academicclassyear').order_by('ClassName__class_name')

    unique_levels = ['PRIMARY', 'O LEVEL', 'A LEVEL']

    # --------------------------------------------------------------
    # 8. Teacher Subjects (filtered by class)
    # --------------------------------------------------------------
    teacher_subjects_qs = TeacherSubject.objects.filter(
        teacher=teacher
    ).select_related('subject', 'teacherclass', 'teacherclass__academicclassyear', 'teacherclass__ClassName')

    if class_filter:
        teacher_subjects_qs = teacher_subjects_qs.filter(teacherclass_id=class_filter)

    teacher_subjects = teacher_subjects_qs

    # --------------------------------------------------------------
    # 9. Subjects & Total Students
    # --------------------------------------------------------------
    subjects = Subject.objects.filter(
        teachersubject__teacher=teacher,
        teachersubject__teacherclass_id=class_filter if class_filter else None
    ).distinct()

    total_students = Student.objects.filter(
        subject_enrollments__subject__in=subjects,
        subject_enrollments__teacherclass__in=[ts.teacherclass for ts in teacher_subjects]
    ).distinct().count()

    # --------------------------------------------------------------
    # 10. Grading System
    # --------------------------------------------------------------
    is_primary = grading_filter == 'PRIMARY'
    is_advance = grading_filter == 'A LEVEL'

    grading_kwargs = {'user': data_owner}
    if is_primary:
        grading_kwargs.update({'is_primary': True, 'is_advance': False})
    elif is_advance:
        grading_kwargs.update({'is_primary': False, 'is_advance': True})
    else:
        grading_kwargs.update({'is_primary': False, 'is_advance': False})

    selected_grading = GradingModel.objects.filter(**grading_kwargs).first()
    if not selected_grading:
        selected_grading = GradingModel.objects.filter(user=data_owner, is_primary=False, is_advance=False).first()

    level = grading_filter
    performance_label = 'Average Marks' if is_primary else 'GPA'

    # Grade thresholds
    grade_points = {}
    all_grades = []
    if selected_grading:
        if is_primary:
            thresholds = {selected_grading.grade_a: 'A', selected_grading.grade_b: 'B',
                          selected_grading.grade_c: 'C', selected_grading.grade_d: 'D',
                          selected_grading.grade_f: 'E'}
            all_grades = ['A', 'B', 'C', 'D', 'E']
        elif is_advance:
            thresholds = {selected_grading.grade_a: 'A', selected_grading.grade_b: 'B',
                          selected_grading.grade_c: 'C', selected_grading.grade_d: 'D',
                          selected_grading.grade_e: 'E', selected_grading.grade_s: 'S',
                          selected_grading.grade_f: 'F'}
            grade_points = {'A': 1.0, 'B': 2.0, 'C': 3.0, 'D': 4.0, 'E': 5.0, 'S': 6.0, 'F': 7.0}
            all_grades = ['A', 'B', 'C', 'D', 'E', 'S', 'F']
        else:
            thresholds = {selected_grading.grade_a: 'A', selected_grading.grade_b: 'B',
                          selected_grading.grade_c: 'C', selected_grading.grade_d: 'D',
                          selected_grading.grade_f: 'F'}
            grade_points = {'A': 1.0, 'B': 2.0, 'C': 3.0, 'D': 4.0, 'F': 5.0}
            all_grades = ['A', 'B', 'C', 'D', 'F']

    def determine_grade(mark, grading):
        for threshold, grade in sorted(thresholds.items(), reverse=True):
            if mark >= threshold:
                return grade
        return list(thresholds.values())[-1]

    # --------------------------------------------------------------
    # 11. Pool for Ranking
    # --------------------------------------------------------------
    pool_classes = []
    selected_class_obj = None
    if class_filter:
        selected_class_obj = TeacherClass.objects.get(id=class_filter)
        pool_classes = [selected_class_obj.id]
        if rank_by != 'class':
            has_stream = TeacherClassStream.objects.filter(teacherclass=selected_class_obj).exists()
            if has_stream:
                if rank_by == 'all':
                    pool_classes = list(TeacherClass.objects.filter(teacherclassstream__isnull=False).values_list('id', flat=True))
                else:
                    stream = TeacherClassStream.objects.filter(teacherclass=selected_class_obj).first()
                    if stream:
                        pool_classes = list(stream.teacherclass.values_list('id', flat=True))
    else:
        pool_classes = [ts.teacherclass.id for ts in teacher_subjects]

    # --------------------------------------------------------------
    # 12. Per-Subject Stats
    # --------------------------------------------------------------
    for ts in teacher_subjects:
        ts.grade_counts = {g: 0 for g in all_grades}
        ts.gpa = 0.0
        ts.average_marks = 0.0
        ts.enrolled_count = Student.objects.filter(
            subject_enrollments__subject=ts.subject,
            subject_enrollments__teacherclass=ts.teacherclass
        ).distinct().count()
        ts.student_count = 0

        if selected_grading and selected_exam:
            marks_qs = Mark.objects.filter(
                subject=ts.subject,
                teacherclass=ts.teacherclass,
                examinationname=selected_exam
            )
            if marks_qs.exists():
                marks_list = list(marks_qs.values_list('marks', flat=True))
                student_ids = marks_qs.values_list('student', flat=True).distinct()
                ts.student_count = len(student_ids)
                if marks_list:
                    if is_primary:
                        ts.average_marks = round(sum(marks_list) / len(marks_list), 2)
                        grades = [determine_grade(m, selected_grading) for m in marks_list]
                    else:
                        grades = [determine_grade(m, selected_grading) for m in marks_list]
                        points = [grade_points.get(g, 5.0) for g in grades]
                        ts.gpa = round(sum(points) / len(points), 2)
                    ts.grade_counts = dict(Counter(grades))
                    for g in all_grades:
                        ts.grade_counts.setdefault(g, 0)

    # --------------------------------------------------------------
    # 13. Exam Average
    # --------------------------------------------------------------
    num_subjects_with_data = sum(1 for ts in teacher_subjects if ts.student_count > 0)
    exam_average = exam_average_gpa = 0.0
    if num_subjects_with_data > 0:
        if is_primary:
            exam_average = round(sum(ts.average_marks for ts in teacher_subjects if ts.student_count > 0) / num_subjects_with_data, 2)
        else:
            exam_average_gpa = round(sum(ts.gpa for ts in teacher_subjects if ts.student_count > 0) / num_subjects_with_data, 2)

    # --------------------------------------------------------------
    # 14. All Exams Average
    # --------------------------------------------------------------
    all_exams_average = 0.0
    if exams.exists() and selected_grading and teacher_subjects:
        total_sum = num_all_exams = 0
        for exam in exams:
            exam_sum = num_exam_subjects = 0
            for ts in teacher_subjects:
                marks_qs = Mark.objects.filter(
                    subject=ts.subject,
                    teacherclass=ts.teacherclass,
                    examinationname=exam
                )
                if marks_qs.exists():
                    marks_list = list(marks_qs.values_list('marks', flat=True))
                    if marks_list:
                        if is_primary:
                            avg = sum(marks_list) / len(marks_list)
                        else:
                            grades = [determine_grade(m, selected_grading) for m in marks_list]
                            points = [grade_points.get(g, 5.0) for g in grades]
                            avg = sum(points) / len(points)
                        exam_sum += avg
                        num_exam_subjects += 1
            if num_exam_subjects > 0:
                total_sum += exam_sum / num_exam_subjects
                num_all_exams += 1
        all_exams_average = round(total_sum / num_all_exams, 2) if num_all_exams > 0 else 0.0

    # --------------------------------------------------------------
    # 15. Teacher Rank in Pool
    # --------------------------------------------------------------
    teacher_position = total_teachers_in_pool = None
    if class_filter and examination_filter and selected_grading:
        pool_teachers = TeacherSubject.objects.filter(
            teacherclass_id__in=pool_classes
        ).values_list('teacher', flat=True).distinct()

        teachers_performance = []
        for other_teacher_id in pool_teachers:
            other_teacher = Teacher.objects.get(id=other_teacher_id)
            other_ts = TeacherSubject.objects.filter(teacher=other_teacher, teacherclass_id__in=pool_classes)
            if other_ts.exists():
                perf_sum = num_subjects = 0
                for ots in other_ts:
                    marks_qs = Mark.objects.filter(
                        subject=ots.subject,
                        teacherclass=ots.teacherclass,
                        examinationname=selected_exam
                    )
                    if marks_qs.exists():
                        marks_list = list(marks_qs.values_list('marks', flat=True))
                        if marks_list:
                            if is_primary:
                                perf = sum(marks_list) / len(marks_list)
                            else:
                                grades = [determine_grade(m, selected_grading) for m in marks_list]
                                points = [grade_points.get(g, 5.0) for g in grades]
                                perf = sum(points) / len(points)
                            perf_sum += perf
                            num_subjects += 1
                if num_subjects > 0:
                    teachers_performance.append((other_teacher, perf_sum / num_subjects))

        if is_primary:
            sorted_teachers = sorted(teachers_performance, key=lambda x: x[1], reverse=True)
        else:
            sorted_teachers = sorted(teachers_performance, key=lambda x: x[1])

        total_teachers_in_pool = len(sorted_teachers)
        teacher_avg = exam_average if is_primary else exam_average_gpa
        for pos, (t, perf) in enumerate(sorted_teachers, 1):
            if t.id == teacher.id:
                teacher_position = pos
                break

    # --------------------------------------------------------------
    # 16. Chart Data
    # --------------------------------------------------------------
    performance_values = [ts.average_marks if is_primary else ts.gpa for ts in teacher_subjects]
    gpa_chart = {
        'labels': [f"{ts.subject.nameSubject} ({ts.teacherclass.ClassName.class_name})" for ts in teacher_subjects],
        'data': [float(v) for v in performance_values]
    }

    # --------------------------------------------------------------
    # 17. Attendance
    # --------------------------------------------------------------
    attendance_records = StaffAttendance.objects.filter(teacher=teacher).order_by('-date')
    attendance_by_date = {att.date: att for att in attendance_records}

    today = date.today()
    min_date = attendance_records.first().date if attendance_records else today.replace(day=1)
    max_date = attendance_records.last().date if attendance_records else today

    current_date = min_date.replace(day=1)
    monthly_details = []
    while current_date <= max_date:
        year, month_num = current_date.year, current_date.month
        _, num_days = calendar.monthrange(year, month_num)
        month_str = current_date.strftime('%B %Y')

        days = []
        present = absent = 0
        for day_num in range(1, num_days + 1):
            day_date = date(year, month_num, day_num)
            att = attendance_by_date.get(day_date)
            if att:
                status = att.status
                if status == 'present': present += 1
                elif status == 'absent': absent += 1
            else:
                status = 'absent' if day_date <= today else '-'
                if status == 'absent': absent += 1
            days.append({
                'day': day_num, 'date': day_date, 'status': status,
                'check_in': att.check_in_time if att else None,
                'check_out': att.check_out_time if att else None,
            })

        monthly_details.append({
            'month_str': month_str, 'year': year, 'month_num': month_num,
            'days': days, 'present': present, 'absent': absent,
            'total': present + absent
        })
        next_month = month_num + 1
        next_year = year + (next_month > 12)
        current_date = date(next_year, next_month % 13 or 1, 1)

    monthly_details.sort(key=lambda m: datetime.strptime(m['month_str'], '%B %Y'), reverse=True)

    overall_present = sum(1 for att in attendance_records if att.status == 'present')
    overall_absent = sum(1 for att in attendance_records if att.status == 'absent')

    attendance = {
        'present_count': overall_present,
        'absent_count': overall_absent,
        'total_days': len(attendance_records),
        'attendance_data': attendance_records,
    }

    # --------------------------------------------------------------
    # 18. Display
    # --------------------------------------------------------------
    display = DisplayModel.objects.filter(user=data_owner).last()

    # --------------------------------------------------------------
    # 19. POST: Save Marks (Creator & Teacher)
    # --------------------------------------------------------------
    if request.method == 'POST':
        active_year = AcademicClassYear.objects.filter(active_year=True).first()
        if not active_year:
            messages.error(request, "No active academic year.")
            return redirect('teacher_profile')

        active_ts = TeacherSubject.objects.filter(
            teacher=teacher,
            teacherclass__academicclassyear=active_year
        )
        if class_filter:
            active_ts = active_ts.filter(teacherclass_id=class_filter)

        active_subjects = Subject.objects.filter(
            teachersubject__in=active_ts
        ).distinct()

        students = Student.objects.filter(
            subject_enrollments__subject__in=active_subjects,
            subject_enrollments__teacherclass__academicclassyear=active_year
        ).distinct().select_related('user').order_by('fullName')
        if class_filter:
            students = students.filter(subject_enrollments__teacherclass_id=class_filter)

        exam_id = request.session.get('selected_examination_id')
        if not exam_id:
            messages.error(request, "Please select an examination.")
            return redirect('select_examination_name', teacher_subject_id=active_ts.first().id if active_ts.exists() else 0)

        try:
            exam = ExaminationName.objects.get(id=exam_id, user=data_owner)
        except ExaminationName.DoesNotExist:
            messages.error(request, "Invalid examination.")
            del request.session['selected_examination_id']
            return redirect('teacher_profile')

        saved = False
        for student in students:
            for subject in active_subjects:
                key = f'marks_{student.id}_{subject.id}'
                value = request.POST.get(key, '').strip()
                if value:
                    ts = TeacherSubject.objects.filter(
                        teacher=teacher, subject=subject,
                        teacherclass__academicclassyear=active_year
                    ).first()
                    if ts and not ts.is_restricted:
                        try:
                            mark = float(value)
                            if 0 <= mark <= 100:
                                Mark.objects.update_or_create(
                                    student=student,
                                    subject=subject,
                                    teacherclass=ts.teacherclass,
                                    examinationname=exam,
                                    defaults={'marks': mark, 'user': request.user}
                                )
                                saved = True
                            else:
                                messages.error(request, f"Mark for {student.fullName} in {subject.nameSubject} must be 0–100.")
                        except ValueError:
                            messages.error(request, f"Invalid mark for {student.fullName}.")

        if saved:
            messages.success(request, "Marks saved successfully!")
        return redirect(request.path + '?' + request.META.get('QUERY_STRING', ''))

    # --------------------------------------------------------------
    # 20. Chat Notifications
    # --------------------------------------------------------------
    unread_count = ChatMessage.objects.filter(receiver=request.user, is_read=False).count()
    recent_messages = list(ChatMessage.objects.filter(receiver=request.user)
                          .select_related('sender').order_by('-timestamp')[:5])

    # --------------------------------------------------------------
    # 21. Context
    # --------------------------------------------------------------
    context = {
        'teacher': teacher,
        'teacher_subjects': teacher_subjects,
        'subjects': subjects,
        'assigned_classes': assigned_classes,
        'total_students': total_students,
        'is_primary': is_primary,
        'exam_average': exam_average if is_primary else None,
        'exam_average_gpa': exam_average_gpa if not is_primary else None,
        'all_exams_average': all_exams_average,
        'gpa_chart': {
            'labels': json.dumps(gpa_chart['labels'], cls=DjangoJSONEncoder),
            'data': json.dumps(gpa_chart['data'], cls=DjangoJSONEncoder)
        },
        'teacher_position': teacher_position,
        'total_teachers_in_class': total_teachers_in_pool,
        'selected_class': selected_class_obj,
        'performance_label': performance_label,
        'all_grades': all_grades,
        'attendance': attendance,
        'monthly_attendance': monthly_details,
        'display': display,
        'is_verified': is_email_verified,
        'exams': exams,
        'selected_exam': selected_exam,
        'unique_levels': unique_levels,
        'class_filter': class_filter,
        'grading_filter': grading_filter,
        'examination_filter': examination_filter,
        'rank_by': rank_by,
        'unread_count': unread_count,
        'recent_messages': recent_messages,
        'is_creator': effective_user == creator,
    }

    return render(request, 'teacher_profile.html', context)

def determine_grade(mark, grading):
    thresholds = grading.get_thresholds()
    if not thresholds:
        return 'F'  # Or handle empty case as needed
    
    sorted_thresholds = sorted(thresholds.items(), key=lambda x: x[0], reverse=True)
    for threshold, grade in sorted_thresholds:
        if mark >= threshold:
            return grade
    
    # Fallback to lowest grade (matches primary 'E' or O/A 'F')
    lowest_grade = list(thresholds.values())[-1] if thresholds else 'F'
    return lowest_grade

@login_required
def change_teacher_photo(request):
    if request.method == 'POST':
        try:
            teacher = Teacher.objects.get(user=request.user)
            if 'photo' in request.FILES:
                teacher.photo = request.FILES['photo']
                teacher.save()
                # Optionally save face encoding if needed
                if teacher.photo:
                    teacher.save_face_encoding()
                messages.success(request, "Profile photo updated successfully.")
            else:
                messages.error(request, "No photo selected.")
        except ObjectDoesNotExist:
            messages.error(request, "Teacher profile not found.")
        return redirect('teacher_profile')  # Redirect to profile after POST
    # For GET: Redirect to profile (avoids 403)
    return redirect('teacher_profile')



