from django.shortcuts import render, get_object_or_404, redirect
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from django.db import transaction
from django.db.models import Q
import logging

logger = logging.getLogger(__name__)
@effective_user_decorator
@login_required
def composite_subjects_view(request):
    """
    View to list, create, and manage composite subjects for the current user.
    Since CompositeSubject is OneToOne with User, there will be at most one per user.
    Handles creation via POST.
    """
    # Query the user's composite subject (0 or 1)
    composite_subjects = CompositeSubject.objects.filter(user=request.effective_user)
    subjects = Subject.objects.filter(user=request.effective_user)
    
    # Retrieve last selected values from session for form pre-filling
    last_subject_name = request.session.get('last_composite_subject_name')
    last_allow_to_use = request.session.get('last_allow_to_use', False)
    selected_subjects = request.session.get('last_selected_subjects', [])
    
    if request.method == 'POST' and 'create' in request.POST:
        logger.debug(f"Create POST data: {request.POST}")
        subject_name = request.POST.get('subject_name')
        allow_to_use = request.POST.get('allow_to_use') == 'on'
        selected_subject_ids = request.POST.getlist('subjects')  # Multiple subjects
        
        if subject_name and selected_subject_ids:
            try:
                with transaction.atomic():
                    # Check if already exists; if so, treat as update (but for now, prevent duplicate creation)
                    if composite_subjects.exists():
                        messages.error(request, "You already have a composite subject. Use the update feature.")
                        logger.warning(f"Attempt to create duplicate composite for user {request.effective_user.username}")
                    else:
                        composite = CompositeSubject(
                            user=request.effective_user,
                            subject_name=subject_name,
                            allow_to_use=allow_to_use
                        )
                        composite.save()
                        # Add selected subjects
                        for sub_id in selected_subject_ids:
                            subject = Subject.objects.get(id=sub_id, user=request.effective_user)
                            composite.subjects.add(subject)
                        messages.success(request, f"Composite subject '{subject_name}' created successfully with {len(selected_subject_ids)} subjects!")
                        logger.info(f"Created composite subject {subject_name} for user {request.effective_user.username}")
                        
                        # Store last selected values in session
                        request.session['last_composite_subject_name'] = subject_name
                        request.session['last_allow_to_use'] = allow_to_use
                        request.session['last_selected_subjects'] = selected_subject_ids
                        request.session.modified = True
                
                return redirect('composite_subjects')
            except Subject.DoesNotExist:
                messages.error(request, "One or more selected subjects do not exist or you do not have permission.")
                logger.error(f"Selected subject not found for user {request.effective_user.username}")
            except Exception as e:
                messages.error(request, f"Error creating composite subject: {str(e)}")
                logger.error(f"Error creating composite subject: {str(e)}", exc_info=True)
        else:
            messages.error(request, "Please provide a subject name and select at least one subject.")
            logger.warning(f"Invalid create data: subject_name={subject_name}, subjects={selected_subject_ids}")
    
    context = {
        'composite_subjects': list(composite_subjects),  # Convert to list for template
        'subjects': subjects,
        'last_subject_name': last_subject_name,
        'last_allow_to_use': last_allow_to_use,
        'last_selected_subjects': selected_subjects,
    }
    return render(request, 'composite_subjects.html', context)

@effective_user_decorator
@login_required
def update_composite_subject(request, id):
    """
    View to update an existing composite subject.
    """
    composite_subject = get_object_or_404(CompositeSubject, id=id, user=request.effective_user)
    subjects = Subject.objects.filter(user=request.effective_user)
    
    if request.method == 'POST':
        logger.debug(f"Update POST data: {request.POST}")
        subject_name = request.POST.get('subject_name')
        allow_to_use = request.POST.get('allow_to_use') == 'on'
        selected_subject_ids = request.POST.getlist('subjects')  # Multiple subjects
        
        if subject_name and selected_subject_ids:
            try:
                with transaction.atomic():
                    # Update fields
                    composite_subject.subject_name = subject_name
                    composite_subject.allow_to_use = allow_to_use
                    composite_subject.save()
                    
                    # Clear existing subjects and add new ones
                    composite_subject.subjects.clear()
                    for sub_id in selected_subject_ids:
                        subject = Subject.objects.get(id=sub_id, user=request.effective_user)
                        composite_subject.subjects.add(subject)
                    
                    messages.success(request, f"Composite subject '{subject_name}' updated successfully!")
                    logger.info(f"Updated composite subject {id} for user {request.effective_user.username}")
                    
                    # Store last selected values in session
                    request.session['last_composite_subject_name'] = subject_name
                    request.session['last_allow_to_use'] = allow_to_use
                    request.session['last_selected_subjects'] = selected_subject_ids
                    request.session.modified = True
                
                return redirect('composite_subjects')
            except Subject.DoesNotExist:
                messages.error(request, "One or more selected subjects do not exist or you do not have permission.")
                logger.error(f"Selected subject not found for user {request.effective_user.username}")
            except Exception as e:
                messages.error(request, f"Error updating composite subject: {str(e)}")
                logger.error(f"Error updating composite subject {id}: {str(e)}", exc_info=True)
        else:
            messages.error(request, "Please provide a subject name and select at least one subject.")
            logger.warning(f"Invalid update data: subject_name={subject_name}, subjects={selected_subject_ids}")
    
    # Pre-select current subjects for the form
    current_subject_ids = [str(s.id) for s in composite_subject.subjects.all()]
    
    context = {
        'composite_subject': composite_subject,
        'subjects': subjects,
        'current_subject_ids': current_subject_ids,
    }
    return render(request, 'update_composite_subject.html', context)


@effective_user_decorator
@login_required
def delete_composite_subject(request, id):
    """
    View to delete a composite subject with confirmation.
    """
    composite_subject = get_object_or_404(CompositeSubject, id=id, user=request.effective_user)
    
    if request.method == 'POST':
        try:
            with transaction.atomic():
                subject_name = composite_subject.subject_name
                composite_subject.delete()
                messages.success(request, f"Composite subject '{subject_name}' deleted successfully!")
                logger.info(f"Deleted composite subject {subject_name} by {request.effective_user.username}")
            
            # Clear session values
            request.session.pop('last_composite_subject_name', None)
            request.session.pop('last_allow_to_use', None)
            request.session.pop('last_selected_subjects', None)
            request.session.modified = True
            
            return redirect('composite_subjects')
        except Exception as e:
            messages.error(request, f"Error deleting composite subject: {str(e)}")
            logger.error(f"Error deleting composite subject {id}: {str(e)}", exc_info=True)
    
    context = {
        'composite_subject': composite_subject,
    }
    return render(request, 'delete_composite_subject.html', context)



