@login_required
def chat_list(request):
    user = request.user
    class_filter = request.GET.get('class_id')

    # -------------------------------------------------
    # BULK MESSAGE (unchanged)
    # -------------------------------------------------
    if request.method == 'POST':
        selected_ids = request.POST.getlist('selected_students')
        message = request.POST.get('bulk_message', '').strip()
        bulk_file = request.FILES.get('bulk_file')
        if selected_ids and (message or bulk_file):
            sent_count = 0
            for sid in selected_ids:
                try:
                    s_user = get_object_or_404(User, id=int(sid))
                    if s_user != user:
                        ChatMessage.objects.create(
                            sender=user,
                            receiver=s_user,
                            message=message or None,
                            file=bulk_file,
                            is_read=False
                        )
                        sent_count += 1
                except Exception:
                    continue
            if sent_count:
                messages.success(request, f"Sent to {sent_count} student(s).")
            else:
                messages.error(request, "No valid students selected.")
        else:
            messages.error(request, "Message or file required.")

        redirect_url = reverse('chat_list')
        if class_filter:
            redirect_url += f'?class_id={class_filter}'
        return redirect(redirect_url)

    # -------------------------------------------------
    # ROLE & MANAGER DETERMINATION
    # -------------------------------------------------
    teacher_profile = Teacher.objects.filter(user=user).first()
    student_profile = Student.objects.filter(user=user).first()

    if teacher_profile:
        role = 'teacher'
        # teacher’s manager = the user who created him (or himself if superuser)
        manager = teacher_profile.created_by if not user.is_superuser else user
    elif student_profile:
        role = 'student'
        manager = student_profile.manager or user
    else:
        # superuser or pure manager → treat as manager
        role = 'manager'
        manager = user

    # -------------------------------------------------
    # PARTNER HELPER
    # -------------------------------------------------
    managers = []
    staff    = []
    students = []
    teacher_classes = []
    unread_count = 0

    def add_partner(partner_user, name, avatar=None, partner_type=None, teacherclass=None):
        nonlocal unread_count
        if partner_user == user:
            return None
        qs = ChatMessage.objects.filter(
            Q(sender=user, receiver=partner_user) |
            Q(sender=partner_user, receiver=user)
        ).order_by('-timestamp')
        partner = {
            'user': partner_user,
            'name': name,
            'avatar': avatar,
            'type': partner_type,
            'teacherclass': teacherclass,
            'last_message': None,
            'unread_count': 0
        }
        if qs.exists():
            last = qs.first()
            partner['last_message'] = last.timestamp.strftime('%H:%M')
            unread = qs.filter(receiver=user, is_read=False).count()
            partner['unread_count'] = unread
            unread_count += unread
        return partner

    # -------------------------------------------------
    # 1. MANAGER TAB – only for non-managers
    # -------------------------------------------------
    if role != 'manager' and manager != user:
        mgr = add_partner(
            partner_user=manager,
            name=manager.get_full_name() or manager.username,
            partner_type='manager'
        )
        if mgr:
            managers.append(mgr)

    # -------------------------------------------------
    # 2. STAFF TAB – Teachers created by the *manager*
    # -------------------------------------------------
    # Determine who is the "manager" for staff lookup
    staff_manager = user if role == 'manager' else manager

    for t in Teacher.objects.filter(created_by=staff_manager).exclude(user=user):
        p = add_partner(
            t.user,
            t.teacherName or t.user.username,
            avatar=t.photo,
            partner_type='staff'
        )
        if p:
            staff.append(p)

    # -------------------------------------------------
    # 3. STUDENTS TAB – Students in any TeacherClass created by the *manager*
    # -------------------------------------------------
    # Determine manager for class lookup
    class_manager = user if role == 'manager' else manager

    # All TeacherClass objects created by this manager
    manager_classes = TeacherClass.objects.filter(user=class_manager).distinct()
    class_ids = manager_classes.values_list('id', flat=True)

    # Optional class filter
    qs = Student.objects.filter(teacherclass__id__in=class_ids).exclude(user=user)
    if class_filter:
        qs = qs.filter(teacherclass_id=class_filter)

    for s in qs:
        p = add_partner(
            s.user,
            s.fullName or s.user.username,
            partner_type='student',
            teacherclass=s.teacherclass
        )
        if p:
            students.append(p)

    # Class dropdown for filtering
    teacher_classes = manager_classes

    # -------------------------------------------------
    # TAB PERSISTENCE
    # -------------------------------------------------
    tab = request.GET.get('tab', '')
    if tab not in ['manager', 'staff', 'students']:
        tab = 'staff' if staff else ('students' if students else 'manager')

    # -------------------------------------------------
    # CONTEXT
    # -------------------------------------------------
    context = {
        'managers': managers,
        'staff': staff,
        'students': students,
        'teacher_classes': teacher_classes,
        'selected_class_id': class_filter,
        'unread_count': unread_count,
        'role': role,
        'tab': tab,
    }
    return render(request, 'chat_list.html', context)
@login_required
def chat_room(request, receiver_username):
    user = request.user
    if not user.is_authenticated:
        messages.error(request, "Chat is only available for students and teachers.")
        return redirect('login_view')
    receiver = get_object_or_404(User, username=receiver_username)
    if receiver == user:
        messages.error(request, "You cannot chat with yourself.")
        return redirect('chat_list')
    # Authorization: relaxed for managers/staff/students without restrictions within the system
    is_authorized = False
    if user.is_student:
        student_profiles = Student.objects.filter(user=user)
        if student_profiles.exists():
            manager = student_profiles.first().manager
            is_authorized = (
                receiver == manager or
                Teacher.objects.filter(created_by=manager, user=receiver).exists() or
                Student.objects.filter(user=receiver, teacherclass__in=student_profiles.values_list('teacherclass', flat=True)).exists()
            )
    else:
        teacher_profile = Teacher.objects.filter(user=user).first()
        if teacher_profile:
            mgr = teacher_profile.created_by
            is_authorized = (
                (mgr and receiver == mgr) or
                Teacher.objects.filter(created_by=mgr, user=receiver).exists() or
                Student.objects.filter(teacherclass__teachersubject__teacher=teacher_profile, user=receiver).exists() or
                Student.objects.filter(manager=user, user=receiver).exists() or
                Teacher.objects.filter(created_by=user, user=receiver).exists()
            )
        else:
            # Treat as manager
            is_authorized = (
                Student.objects.filter(manager=user, user=receiver).exists() or
                Teacher.objects.filter(created_by=user, user=receiver).exists()
            )
    if not is_authorized:
        messages.error(request, "You can only chat with authorized contacts.")
        return redirect('chat_list')
    # Room creation
    if user.id < receiver.id:
        user1_id = user.id
        user2_id = receiver.id
    else:
        user1_id = receiver.id
        user2_id = user.id
    room, created = ChatRoom.objects.get_or_create(
        user1_id=user1_id,
        user2_id=user2_id
    )
    # In views.py → chat_room()




    messages_list = ChatMessage.objects.filter(
        Q(sender=user, receiver=receiver) | Q(sender=receiver, receiver=user)
    ).prefetch_related(
        Prefetch('reactions', queryset=MessageReaction.objects.all())
    ).order_by('timestamp')
    # Mark as read
    unread_msgs = messages_list.filter(receiver=user, is_read=False)
    unread_msgs.update(is_read=True)
    context = {
        'receiver': receiver,
        'receiver_name': receiver.get_full_name() or receiver.username,
        'messages': messages_list,
        'room_name': room.room_name,
    }
    return render(request, 'chat_room.html', context)

