from .decorators import effective_user_decorator  # <-- your decorator


@login_required
@effective_user_decorator
def manage_teacher_permissions(request):
    """
    Display all teachers that belong to the effective user
    (superuser sees all their own, sub-teachers see only those created under them).
    """
    teachers = Teacher.objects.filter(
        created_by=request.effective_user
    ).select_related('user', 'userpermission')  # prefetch permissions for the template

    context = {
        'teachers': teachers,
    }
    return render(request, 'manage_teacher_permissions.html', context)


@login_required
@effective_user_decorator
def update_teacher_permissions(request):
    """
    Bulk-apply the same permission set to all selected teachers.
    Uses request.effective_user so only teachers belonging to the creator can be modified.
    """
    if request.method != 'POST':
        messages.error(request, 'Invalid request method.')
        return HttpResponseRedirect(request.META.get('HTTP_REFERER', '/'))

    selected_ids = request.POST.getlist('selected_teachers')
    if not selected_ids:
        messages.warning(request, 'No teachers selected. Please select at least one teacher.')
        return HttpResponseRedirect(request.META.get('HTTP_REFERER', '/'))

    try:
        teacher_ids = [int(tid) for tid in selected_ids]
    except ValueError:
        messages.error(request, 'Invalid teacher selection.')
        return HttpResponseRedirect(request.META.get('HTTP_REFERER', '/'))

    # Security: ensure all selected teachers actually belong to the effective user
    valid_teachers = Teacher.objects.filter(
        id__in=teacher_ids,
        created_by=request.effective_user
    )

    if valid_teachers.count() != len(teacher_ids):
        messages.error(request, 'You can only modify permissions for teachers you created.')
        return HttpResponseRedirect(request.META.get('HTTP_REFERER', '/'))

    # Build permission dictionary from POST data (checkboxes)
    permission_data = {
        'can_view_attendance': 'can_view_attendance' in request.POST,
        'can_view_registration': 'can_view_registration' in request.POST,
        'can_view_settings': 'can_view_settings' in request.POST,
        'can_view_output': 'can_view_output' in request.POST,
        'can_view_crm': 'can_view_crm' in request.POST,
        'can_manage_home_enquiries': 'can_manage_home_enquiries' in request.POST,

        # Settings permissions
        'can_modify_grading_system': 'can_modify_grading_system' in request.POST,
        'can_modify_display': 'can_modify_display' in request.POST,
        'can_modify_teacher_subject': 'can_modify_teacher_subject' in request.POST,
        'can_modify_student_subject': 'can_modify_student_subject' in request.POST,
        'can_modify_excluded_subject': 'can_modify_excluded_subject' in request.POST,
        'can_modify_subject_settings': 'can_modify_subject_settings' in request.POST,
        'can_modify_stamp_and_signature': 'can_modify_stamp_and_signature' in request.POST,
        'can_modify_comments': 'can_modify_comments' in request.POST,
        'can_modify_composite_subject': 'can_modify_composite_subject' in request.POST,

        # Registration permissions
        'can_modify_academic_year': 'can_modify_academic_year' in request.POST,
        'can_modify_venue': 'can_modify_venue' in request.POST,
        'can_modify_examination': 'can_modify_examination' in request.POST,
        'can_modify_subjects': 'can_modify_subjects' in request.POST,
        'can_modify_students': 'can_modify_students' in request.POST,
        'can_manage_student_applications': 'can_manage_student_applications' in request.POST,
        'can_modify_staff': 'can_modify_staff' in request.POST,
        'can_manage_student_id': 'can_manage_student_id' in request.POST,

        # Attendance permissions
        'can_open_staff_attendance': 'can_open_staff_attendance' in request.POST,
        'can_open_student_attendance': 'can_open_student_attendance' in request.POST,
        'can_search_student': 'can_search_student' in request.POST,
        'can_retreve_student': 'can_retreve_student' in request.POST,

        # Output permissions
        'can_view_best_student': 'can_view_best_student' in request.POST,
        'can_view_results': 'can_view_results' in request.POST,
        'can_view_subject_analysis': 'can_view_subject_analysis' in request.POST,
        'can_view_grade_analysis': 'can_view_grade_analysis' in request.POST,
        'can_view_division_analysis': 'can_view_division_analysis' in request.POST,

        # Transport permissions
        'can_view_transport': 'can_view_transport' in request.POST,
        'can_manage_vehicle': 'can_manage_vehicle' in request.POST,
        'can_manage_route': 'can_manage_route' in request.POST,
        'can_manage_fuel': 'can_manage_fuel' in request.POST,
        'can_manage_maintenance': 'can_manage_maintenance' in request.POST,
        'can_manage_expense': 'can_manage_expense' in request.POST,
        'can_view_transport_dashboard': 'can_view_transport_dashboard' in request.POST,
    }

    updated_count = 0
    created_count = 0

    for teacher in valid_teachers:
        perm, created = UserPermission.objects.get_or_create(
            teacher=teacher,
            defaults={'user': request.effective_user}  # link to the creator/main account
        )
        if created:
            created_count += 1

        for field, value in permission_data.items():
            setattr(perm, field, value)

        perm.save()
        updated_count += 1

    # Success message
    msg = f'Permissions updated for {updated_count} teacher(s).'
    if created_count:
        msg += f' New permission records created for {created_count} teacher(s).'
    messages.success(request, msg)

    return HttpResponseRedirect(request.META.get('HTTP_REFERER', '/'))


def can_manage_home_enquiries(user):
    return has_teacher_permission(user, 'can_manage_home_enquiries')


@effective_user_decorator
@login_required
def home_enquiry_list(request):
    if not can_manage_home_enquiries(request.user):
        return HttpResponseForbidden("You do not have permission to manage home enquiries.")

    from website.models import HomeEnquirySubmission

    enquiries = HomeEnquirySubmission.objects.select_related('contacted_by').order_by('-created_at')
    status = request.GET.get('status', '').strip()
    q = request.GET.get('q', '').strip()

    if status == 'contacted':
        enquiries = enquiries.filter(is_contacted=True)
    elif status == 'not_contacted':
        enquiries = enquiries.filter(is_contacted=False)

    if q:
        enquiries = enquiries.filter(
            Q(full_name__icontains=q)
            | Q(phone_number__icontains=q)
            | Q(email__icontains=q)
            | Q(location__icontains=q)
            | Q(description__icontains=q)
            | Q(contact_notes__icontains=q)
        )

    return render(request, 'home_enquiries/list.html', {
        'enquiries': enquiries,
        'selected_status': status,
        'q': q,
    })


@effective_user_decorator
@login_required
def home_enquiry_update(request, pk):
    if not can_manage_home_enquiries(request.user):
        return HttpResponseForbidden("You do not have permission to manage home enquiries.")
    if request.method != 'POST':
        return redirect('home_enquiries')

    from website.models import HomeEnquirySubmission

    enquiry = get_object_or_404(HomeEnquirySubmission, pk=pk)
    was_contacted = enquiry.is_contacted
    enquiry.is_contacted = request.POST.get('is_contacted') == 'on'
    enquiry.contact_notes = request.POST.get('contact_notes', '').strip() or None

    if enquiry.is_contacted:
        if not was_contacted or not enquiry.contacted_at:
            enquiry.contacted_at = timezone.now()
        enquiry.contacted_by = request.user
    else:
        enquiry.contacted_at = None
        enquiry.contacted_by = None

    enquiry.save(update_fields=['is_contacted', 'contact_notes', 'contacted_at', 'contacted_by', 'updated_at'])
    messages.success(request, 'Home enquiry contact status updated.')
    return redirect('home_enquiries')

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import render, redirect

@login_required
def lock_account(request,username):
    username=request.user.username
    if request.method == 'POST':
        user = request.user
        user.is_active = False
        user.is_staff = False
        user.is_superuser = False
        # Remove all role flags
        user.is_teacher = False
        user.is_student = False
        user.save()

        messages.warning(
            request,
            'Your account has been locked. Contact the system administrator to regain access.'
        )
        return redirect('login_view')

    return render(request, 'lock_account.html')

