def _build_entity_forms(config, related_field, instance_obj):
    sections = []
    for key, item in config.items():
        form_class = item['form']
        if item['multiple']:
            records = list(item['model'].objects.filter(**{related_field: instance_obj}).order_by('-id'))
            form = form_class()
            sections.append({
                'key': key,
                'title': item['title'],
                'form': form,
                'records': records,
                'multiple': True,
            })
        else:
            related_instance = item['model'].objects.filter(**{related_field: instance_obj}).first()
            form = form_class(instance=related_instance)
            sections.append({
                'key': key,
                'title': item['title'],
                'form': form,
                'record': related_instance,
                'multiple': False,
            })
    return sections


@effective_user_decorator
@login_required
def generate_student_index_number(request):
    class_id = request.GET.get('class_id')
    teacherclass = None
    if class_id:
        teacherclass = TeacherClass.objects.filter(id=class_id, user=request.effective_user).select_related('ClassName', 'academicclassyear').first()
    elif TeacherClass.objects.filter(user=request.effective_user, academicclassyear__active_year=True).exists():
        teacherclass = TeacherClass.objects.filter(user=request.effective_user, academicclassyear__active_year=True).select_related('ClassName', 'academicclassyear').first()

    if not teacherclass:
        return JsonResponse({'success': False, 'message': 'No class available for index generation.'}, status=400)

    return JsonResponse({'success': True, 'index_number': generate_student_index_number_for_class(request.effective_user, teacherclass)})


@effective_user_decorator
@login_required
@require_POST
def update_short_course_validity(request, student_id):
    student = get_object_or_404(
        Student.objects.select_related('academic_information'),
        id=student_id,
        manager__in=[request.effective_user, request.user],
    )
    academic_info = _student_academic_info(student)
    if not academic_info:
        academic_info = StudentAcademicInformation.objects.create(
            student=student,
            **build_student_academic_prefill(student),
        )

    if academic_info.academic_level not in SHORT_COURSE_ACADEMIC_LEVELS:
        return JsonResponse({'success': False, 'message': 'This student is not in a short course.'}, status=400)

    try:
        validity_months = int(request.POST.get('validity_months', ''))
    except (TypeError, ValueError):
        validity_months = None
    if validity_months not in SHORT_COURSE_VALIDITY_CHOICES:
        return JsonResponse({'success': False, 'message': 'Select 3, 6, or 12 months.'}, status=400)

    academic_info.short_course_validity_months = validity_months
    academic_info.save(update_fields=['short_course_validity_months', 'updated_at'])
    _, expiry_date = _resolve_student_issued_expiry_dates(student)
    return JsonResponse({
        'success': True,
        'validity_months': validity_months,
        'expiry_text': expiry_date.strftime('%d %b %Y'),
    })


