@effective_user_decorator
@login_required
def student_id_card_pdf_view(request, student_id):
    student = get_object_or_404(
        Student.objects.select_related(
            'teacherclass__ClassName',
            'teacherclass__academicclassyear',
            'academic_information',
        ),
        id=student_id,
        manager__in=[request.effective_user, request.user],
    )

    appearance_defaults = _get_student_id_appearance_setting(request, student)
    global_settings = _student_id_global_settings_to_dict(
        _get_student_id_global_setting(_student_id_owner_user(request, student)),
        request=request,
    )
    id_settings = _parse_student_id_settings_from_request(request, appearance_defaults, global_settings)
    issued_date, expiry_date = _resolve_student_issued_expiry_dates(student)
    registration_number = _resolve_student_registration_number(student)
    issued_date_text = issued_date.strftime('%d %b %Y')
    expiry_text = expiry_date.strftime('%d %b %Y')
    qr_payload_text = _build_student_id_qr_payload(
        student=student,
        registration_number=registration_number,
        issued_date_text=issued_date_text,
        expiry_text=expiry_text,
    )
    qr_target_text = _build_student_id_qr_target(
        request=request,
        student=student,
        registration_number=registration_number,
        issued_date_text=issued_date_text,
        expiry_text=expiry_text,
    )

    response = HttpResponse(content_type='application/pdf')
    safe_name = slugify(student.fullName or student.indexNumber or f"student-{student.id}") or f"student-{student.id}"
    response['Content-Disposition'] = f'attachment; filename="student_id_{safe_name}.pdf"'
    pdf = pdf_canvas.Canvas(response, pagesize=A4)

    page_w, page_h = A4
    card_w, card_h = (85.6 * mm, 54 * mm) if id_settings['card_design'] == 'horizontal' else (54 * mm, 85.6 * mm)
    gap = 10 * mm

    if id_settings['print_layout'] == 'single':
        total_w = (2 * card_w) + gap
        start_x = max((page_w - total_w) / 2, 8 * mm)
        y = (page_h - card_h) / 2
        front_origin = (start_x, y)
        back_origin = (start_x + card_w + gap, y)
        page_mode = 'single'
    else:
        front_origin = ((page_w - card_w) / 2, (page_h - card_h) / 2)
        back_origin = front_origin
        page_mode = 'multiple'

    signature_img = _resolve_student_id_signature_rl_image(request, student, width=28 * mm, height=8 * mm)
    qr_size = (12 * mm) * id_settings['qr_scale']
    qr_img = _build_student_id_qr_rl_image(qr_target_text, width=qr_size, height=qr_size)

    logo_img = None
    if id_settings.get('logo_data'):
        logo_img = _build_rl_image_from_data_url(id_settings['logo_data'], width=11 * mm, height=11 * mm)
    if not logo_img and id_settings.get('global_logo_path'):
        logo_img = _build_rl_image_from_path(id_settings['global_logo_path'], width=11 * mm, height=11 * mm)
    if not logo_img:
        logo_path = finders.find('BRITISH_LOGO.png')
        logo_img = _build_rl_image_from_path(logo_path, width=11 * mm, height=11 * mm)

    student_photo_path = student.photo.path if getattr(student, 'photo', None) else None
    class_name = getattr(getattr(student, 'teacherclass', None), 'ClassName', None)
    class_name = getattr(class_name, 'class_name', None) or '-'

    def _draw_image_cover(image_path, x, y, width, height, background_color=colors.white):
        """Center-crop image to the box (cover) for stable photo placement."""
        if not image_path or not os.path.exists(image_path) or not os.access(image_path, os.R_OK):
            pdf.setFillColor(background_color)
            pdf.rect(x, y, width, height, stroke=0, fill=1)
            return False
        try:
            from reportlab.lib.utils import ImageReader

            with PILImage.open(image_path) as img:
                img = img.convert('RGB')
                src_w, src_h = img.size
                target_ratio = float(width) / float(height)
                src_ratio = float(src_w) / float(src_h)

                if src_ratio > target_ratio:
                    crop_w = int(src_h * target_ratio)
                    crop_h = src_h
                    left = max((src_w - crop_w) // 2, 0)
                    top = 0
                else:
                    crop_w = src_w
                    crop_h = int(src_w / target_ratio)
                    left = 0
                    top = max((src_h - crop_h) // 2, 0)

                cropped = img.crop((left, top, left + crop_w, top + crop_h)).resize(
                    (max(int(width), 1), max(int(height), 1)),
                    PILImage.Resampling.LANCZOS if hasattr(PILImage, 'Resampling') else PILImage.LANCZOS,
                )
                img_reader = ImageReader(cropped)
                pdf.drawImage(img_reader, x, y, width=width, height=height, mask='auto')
                return True
        except Exception:
            pdf.setFillColor(background_color)
            pdf.rect(x, y, width, height, stroke=0, fill=1)
            return False

    def _draw_card_shell(origin_x, origin_y, width, height):
        pdf.setFillColor(colors.white)
        pdf.roundRect(origin_x, origin_y, width, height, 3 * mm, stroke=0, fill=1)

    def _rl_color(hex_color):
        return colors.HexColor(hex_color)

    def draw_horizontal_front(origin_x, origin_y):
        _draw_card_shell(origin_x, origin_y, card_w, card_h)
        header_h = 14 * mm
        body_h = card_h - header_h
        body_y = origin_y
        header_y = origin_y + body_h

        pdf.setFillColor(colors.HexColor(id_settings['horizontal_front_header_color']))
        pdf.roundRect(origin_x, header_y, card_w, header_h, 3 * mm, stroke=0, fill=1)
        pdf.setFillColor(_rl_color(id_settings['horizontal_front_primary_color']))
        pdf.rect(origin_x, body_y, card_w, body_h + 1.2 * mm, stroke=0, fill=1)
        pdf.setStrokeColor(_rl_color(id_settings['horizontal_front_border_color']))
        pdf.setLineWidth(0.55 * mm)
        pdf.roundRect(origin_x + 0.8 * mm, origin_y + 0.8 * mm, card_w - 1.6 * mm, card_h - 1.6 * mm, 2.6 * mm, stroke=1, fill=0)
        pdf.setStrokeColor(_rl_color(id_settings['horizontal_front_inner_border_color']))
        pdf.setLineWidth(0.28 * mm)
        pdf.roundRect(origin_x + 1.8 * mm, origin_y + 1.8 * mm, card_w - 3.6 * mm, card_h - 3.6 * mm, 2 * mm, stroke=1, fill=0)

        # Base geometry zones
        photo_base_x = origin_x + 3.2 * mm
        photo_base_y = body_y + 4.5 * mm
        photo_base_w = 22 * mm
        photo_base_h = 30 * mm

        qr_base_w = qr_size
        qr_base_h = qr_size
        qr_right_margin = 4.2 * mm
        qr_base_x = origin_x + card_w - qr_base_w - qr_right_margin
        qr_base_y = body_y + ((body_h - qr_base_h) / 2)

        content_base_x = photo_base_x + photo_base_w + 2.8 * mm
        content_base_y = body_y + body_h - 7.4 * mm

        # Header
        if logo_img:
            logo_w = 11 * mm * id_settings['logo_scale']
            logo_h = 11 * mm * id_settings['logo_scale']
            logo_x = origin_x + 3 * mm + id_settings['logo_x_mm']
            logo_y = origin_y + card_h - 12.5 * mm + id_settings['logo_y_mm']
            logo_img.drawWidth = logo_w
            logo_img.drawHeight = logo_h
            logo_img.wrapOn(pdf, logo_w, logo_h)
            logo_img.drawOn(pdf, logo_x, logo_y)

        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 8)
        pdf.drawString(origin_x + 16 * mm, origin_y + card_h - 7 * mm, "THE BRITISH SECONDARY SCHOOL")
        pdf.setFont("Helvetica", 6)
        pdf.drawString(origin_x + 16 * mm, origin_y + card_h - 10 * mm, "STUDENT IDENTIFICATION CARD")

        # Photo block
        photo_w = photo_base_w * id_settings['photo_scale']
        photo_h = photo_base_h * id_settings['photo_scale']
        photo_x = photo_base_x + id_settings['photo_x_mm']
        photo_y = photo_base_y + id_settings['photo_y_mm']
        pdf.setFillColor(colors.white)
        pdf.roundRect(photo_x - 0.8 * mm, photo_y - 0.8 * mm, photo_w + 1.6 * mm, photo_h + 1.6 * mm, 1.8 * mm, stroke=0, fill=1)
        _draw_image_cover(student_photo_path, photo_x, photo_y, photo_w, photo_h)

        # QR block
        if qr_img:
            qr_x = qr_base_x + id_settings['qr_x_mm']
            qr_y = qr_base_y + id_settings['qr_y_mm']
            pdf.setFillColor(colors.white)
            pdf.roundRect(qr_x - 0.8 * mm, qr_y - 0.8 * mm, qr_base_w + 1.6 * mm, qr_base_h + 1.6 * mm, 1.6 * mm, stroke=0, fill=1)
            qr_img.wrapOn(pdf, qr_base_w, qr_base_h)
            qr_img.drawOn(pdf, qr_x, qr_y)

        # Text block
        content_x = content_base_x + id_settings['content_x_mm']
        content_y = body_y + body_h - 5.6 * mm + id_settings['content_y_mm']
        max_name_width = (qr_base_x - 3.6 * mm) - content_x
        student_name = student.fullName or "Unnamed Student"
        panel_x = content_x - 1.5 * mm
        panel_y = max(body_y + 2.4 * mm, content_y - 26.4 * mm)
        panel_w = max_name_width + 3.8 * mm
        panel_h = min(31.6 * mm, body_h - 4.8 * mm)
        pdf.setFillColor(_rl_color(id_settings['horizontal_front_panel_color']))
        pdf.roundRect(panel_x, panel_y, panel_w, panel_h, 1.8 * mm, stroke=0, fill=1)
        pdf.setFillColor(_rl_color(id_settings['horizontal_front_text_color']))
        name_font_size = max(7.5, min(11.5, id_settings['name_size_px'] * 0.57))
        pdf.setFont("Helvetica-Bold", name_font_size)
        if pdf.stringWidth(student_name, "Helvetica-Bold", name_font_size) > max_name_width:
            while name_font_size > 7.0 and pdf.stringWidth(student_name, "Helvetica-Bold", name_font_size) > max_name_width:
                name_font_size -= 0.2
            pdf.setFont("Helvetica-Bold", name_font_size)
        pdf.drawString(content_x, content_y, student_name)

        detail_color = _rl_color(id_settings['horizontal_front_text_color'])
        label_color = _rl_color(_mix_color(id_settings['horizontal_front_text_color'], id_settings['horizontal_front_panel_color'], 0.32))

        def draw_pdf_stacked_detail(label, value, x, y, width):
            text = str(value)
            pdf.setFillColor(label_color)
            pdf.setFont("Helvetica-Bold", 4.25)
            pdf.drawString(x, y, label.upper())
            value_font_size = 5.25
            while value_font_size > 3.8 and pdf.stringWidth(text, "Helvetica-Bold", value_font_size) > width:
                value_font_size -= 0.15
            pdf.setFillColor(detail_color)
            pdf.setFont("Helvetica-Bold", value_font_size)
            pdf.drawString(x, y - 2.15 * mm, text)

        detail_top = content_y - 5.4 * mm
        col_gap = 3.2 * mm
        col_w = (max_name_width - col_gap) / 2
        row_gap = 6.9 * mm
        draw_pdf_stacked_detail("ID", student.indexNumber or '-', content_x, detail_top, max_name_width)
        draw_pdf_stacked_detail("Class", class_name, content_x, detail_top - row_gap, col_w)
        draw_pdf_stacked_detail("Reg No", registration_number, content_x + col_w + col_gap, detail_top - row_gap, col_w)
        draw_pdf_stacked_detail("Issued", issued_date_text, content_x, detail_top - (row_gap * 2), col_w)
        draw_pdf_stacked_detail("Expiry", expiry_text, content_x + col_w + col_gap, detail_top - (row_gap * 2), col_w)

    def draw_horizontal_back(origin_x, origin_y):
        _draw_card_shell(origin_x, origin_y, card_w, card_h)
        top_h = 28 * mm
        back_border = colors.HexColor(id_settings['horizontal_back_accent_color'])
        pdf.setFillColor(colors.HexColor(id_settings['horizontal_back_top_color']))
        pdf.roundRect(origin_x, origin_y + card_h - top_h, card_w, top_h, 3 * mm, stroke=0, fill=1)
        pdf.setFillColor(colors.white)
        pdf.rect(origin_x, origin_y, card_w, card_h - top_h + 1.2 * mm, stroke=0, fill=1)
        pdf.setStrokeColor(back_border)
        pdf.setLineWidth(0.55 * mm)
        pdf.roundRect(origin_x + 0.8 * mm, origin_y + 0.8 * mm, card_w - 1.6 * mm, card_h - 1.6 * mm, 2.6 * mm, stroke=1, fill=0)
        pdf.setStrokeColor(colors.HexColor(id_settings['horizontal_back_inner_border_color']))
        pdf.setLineWidth(0.24 * mm)
        pdf.roundRect(origin_x + 1.8 * mm, origin_y + 1.8 * mm, card_w - 3.6 * mm, card_h - 3.6 * mm, 2 * mm, stroke=1, fill=0)
        pdf.setFillColor(colors.Color(1, 1, 1, alpha=0.10))
        pdf.roundRect(origin_x + 2 * mm, origin_y + 2 * mm, 8 * mm, 4.8 * mm, 1.2 * mm, stroke=0, fill=1)

        pdf.setFillColor(colors.white)
        pdf.setFont("Helvetica-Bold", 9)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 7 * mm, "THE BRITISH SECONDARY SCHOOL")
        pdf.setFont("Helvetica", 6)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 10.5 * mm, "P.O.Box 32536, Dar es salaam, Tanzania")
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 13.8 * mm, "0655400420 | 0755400420")
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 17 * mm, "info@britishschool.ac.tz")

        pdf.setFillColor(colors.HexColor(id_settings['horizontal_back_accent_color']))
        pdf.setFont("Helvetica", 6)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 16.5 * mm, "If found, return to The British School office.")
        pdf.setFont("Helvetica-Bold", 6.5)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 10.8 * mm, "Principal Signature:")
        if signature_img:
            signature_img.wrapOn(pdf, 28 * mm, 8 * mm)
            signature_img.drawOn(pdf, origin_x + (card_w - 28 * mm) / 2, origin_y + 2.3 * mm)
        else:
            pdf.setFont("Helvetica", 6.5)
            pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 4.8 * mm, "p-signature")

    def draw_vertical_front(origin_x, origin_y):
        _draw_card_shell(origin_x, origin_y, card_w, card_h)
        top_color = colors.HexColor(id_settings['vertical_front_top_color'])
        bottom_color = colors.HexColor(id_settings['vertical_front_bottom_color'])
        accent_color = colors.HexColor(id_settings['vertical_front_accent_color'])

        pdf.setFillColor(top_color)
        pdf.roundRect(origin_x, origin_y, card_w, card_h, 3 * mm, stroke=0, fill=1)
        pdf.setFillColor(bottom_color)
        pdf.rect(origin_x, origin_y, card_w, 32 * mm, stroke=0, fill=1)
        pdf.setStrokeColor(accent_color)
        pdf.setLineWidth(0.55 * mm)
        pdf.roundRect(origin_x + 1.1 * mm, origin_y + 1.1 * mm, card_w - 2.2 * mm, card_h - 2.2 * mm, 2.4 * mm, stroke=1, fill=0)
        pdf.setStrokeColor(colors.HexColor(id_settings['vertical_front_accent_color']))
        pdf.setLineWidth(0.28 * mm)
        pdf.roundRect(origin_x + 2 * mm, origin_y + 2 * mm, card_w - 4 * mm, card_h - 4 * mm, 1.8 * mm, stroke=1, fill=0)
        pdf.saveState()
        pdf.setFillColor(colors.Color(1, 1, 1, alpha=0.14))
        pdf.roundRect(origin_x + card_w - 9.4 * mm, origin_y + card_h - 6.4 * mm, 8 * mm, 4.6 * mm, 1.4 * mm, stroke=0, fill=1)
        pdf.roundRect(origin_x + 1.4 * mm, origin_y + card_h - 27 * mm, 8 * mm, 4.6 * mm, 1.4 * mm, stroke=0, fill=1)
        pdf.restoreState()

        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 8)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 8 * mm, "THE BRITISH SCHOOL")
        pdf.setFont("Helvetica", 6)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 11 * mm, "STUDENT IDENTIFICATION CARD")

        photo_x = origin_x + (card_w - (24 * mm)) / 2 + id_settings['photo_x_mm']
        photo_y = origin_y + card_h - 41 * mm + id_settings['photo_y_mm']
        photo_w = 24 * mm * id_settings['photo_scale']
        photo_h = 26 * mm * id_settings['photo_scale']
        pdf.setFillColor(colors.HexColor(id_settings['photo_bg_color']))
        pdf.roundRect(photo_x, photo_y, photo_w, photo_h, 1.6 * mm, stroke=0, fill=1)
        _draw_image_cover(student_photo_path, photo_x, photo_y, photo_w, photo_h, background_color=colors.HexColor(id_settings['photo_bg_color']))

        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", id_settings['name_size_px'] * 0.58)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 44 * mm, student.fullName or "Unnamed Student")
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica", 6.5)
        content_x = origin_x + 4 * mm + id_settings['content_x_mm']
        content_y = origin_y + 27.2 * mm + id_settings['content_y_mm']
        lines = [
            f"ID: {student.indexNumber or '-'}",
            f"Class: {class_name}",
            f"Reg No: {registration_number}",
            f"Join: {issued_date_text}",
            f"Expire: {expiry_text}",
        ]
        for idx, line in enumerate(lines):
            pdf.drawString(content_x, content_y - (idx * 4.7 * mm), line)

    def draw_vertical_back(origin_x, origin_y):
        _draw_card_shell(origin_x, origin_y, card_w, card_h)
        back_border = colors.HexColor(id_settings['vertical_back_accent_color'])
        pdf.setFillColor(colors.HexColor(id_settings['vertical_back_top_color']))
        pdf.roundRect(origin_x, origin_y, card_w, card_h, 3 * mm, stroke=0, fill=1)
        pdf.setFillColor(colors.HexColor(id_settings['vertical_back_bottom_color']))
        pdf.rect(origin_x, origin_y, card_w, 41 * mm, stroke=0, fill=1)
        pdf.setStrokeColor(back_border)
        pdf.setLineWidth(0.55 * mm)
        pdf.roundRect(origin_x + 0.8 * mm, origin_y + 0.8 * mm, card_w - 1.6 * mm, card_h - 1.6 * mm, 2.4 * mm, stroke=1, fill=0)
        pdf.setStrokeColor(colors.HexColor(id_settings['vertical_back_inner_border_color']))
        pdf.setLineWidth(0.24 * mm)
        pdf.roundRect(origin_x + 1.8 * mm, origin_y + 1.8 * mm, card_w - 3.6 * mm, card_h - 3.6 * mm, 1.8 * mm, stroke=1, fill=0)
        pdf.setFillColor(colors.Color(1, 1, 1, alpha=0.12))
        pdf.roundRect(origin_x + card_w - 9.5 * mm, origin_y + card_h - 6.8 * mm, 7.3 * mm, 4.8 * mm, 1.3 * mm, stroke=0, fill=1)
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 9)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 10 * mm, "THE BRITISH SCHOOL")
        pdf.setFont("Helvetica", 6)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 14 * mm, "Student Affairs & Administration")
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 19 * mm, "P.O.Box 32536 • Dar es salaam")
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + card_h - 22.5 * mm, "0655400420 | 0755400420")
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica", 6.2)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 48 * mm, "This card remains school property.")
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 44.5 * mm, "Return to administration if found.")
        vertical_qr_size = min(max(18.5 * mm * id_settings['qr_scale'], 16 * mm), 22 * mm)
        qr_zone_top = origin_y + 19 * mm
        qr_zone_bottom = origin_y + 41.5 * mm
        qr_x = origin_x + ((card_w - vertical_qr_size) / 2) + id_settings['qr_x_mm']
        qr_y = qr_zone_top + ((qr_zone_bottom - qr_zone_top - vertical_qr_size) / 2) + id_settings['qr_y_mm']
        qr_x = min(max(qr_x, origin_x + 8 * mm), origin_x + card_w - vertical_qr_size - 8 * mm)
        qr_y = min(max(qr_y, qr_zone_top), qr_zone_bottom - vertical_qr_size)
        if qr_img:
            pdf.setFillColor(colors.white)
            pdf.roundRect(qr_x - 1.1 * mm, qr_y - 1.1 * mm, vertical_qr_size + 2.2 * mm, vertical_qr_size + 2.2 * mm, 2 * mm, stroke=0, fill=1)
            qr_img.drawWidth = vertical_qr_size
            qr_img.drawHeight = vertical_qr_size
            qr_img.wrapOn(pdf, vertical_qr_size, vertical_qr_size)
            qr_img.drawOn(pdf, qr_x, qr_y)
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 6.6)
        pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 13 * mm, "Principal Signature")
        if signature_img:
            signature_img.wrapOn(pdf, 28 * mm, 8 * mm)
            signature_img.drawOn(pdf, origin_x + (card_w - 28 * mm) / 2, origin_y + 4 * mm)
        else:
            pdf.setFont("Helvetica", 6.5)
            pdf.drawCentredString(origin_x + (card_w / 2), origin_y + 7.2 * mm, "p-signature")

    if id_settings['card_design'] == 'vertical':
        draw_vertical_front(*front_origin)
    else:
        draw_horizontal_front(*front_origin)

    if page_mode == 'multiple':
        pdf.showPage()
    if id_settings['card_design'] == 'vertical':
        draw_vertical_back(*back_origin)
    else:
        draw_horizontal_back(*back_origin)

    pdf.save()
    return response


@effective_user_decorator
@login_required
def student_id_card_png_view(request, student_id):
    student = get_object_or_404(
        Student.objects.select_related(
            'teacherclass__ClassName',
            'teacherclass__academicclassyear',
            'academic_information',
        ),
        id=student_id,
        manager__in=[request.effective_user, request.user],
    )

    appearance_defaults = _get_student_id_appearance_setting(request, student)
    global_settings = _student_id_global_settings_to_dict(
        _get_student_id_global_setting(_student_id_owner_user(request, student)),
        request=request,
    )
    id_settings = _parse_student_id_settings_from_request(request, appearance_defaults, global_settings)
    _log_student_id_effective_settings('png', id_settings)
    side = request.GET.get('side')
    if side not in ['front', 'back']:
        side = None
    issued_date, expiry_date = _resolve_student_issued_expiry_dates(student)
    registration_number = _resolve_student_registration_number(student)
    issued_date_text = issued_date.strftime('%d %b %Y')
    expiry_text = expiry_date.strftime('%d %b %Y')
    qr_target_text = _build_student_id_qr_target(
        request=request,
        student=student,
        registration_number=registration_number,
        issued_date_text=issued_date_text,
        expiry_text=expiry_text,
    )

    png_image = _build_student_id_png(
        request=request,
        student=student,
        id_settings=id_settings,
        qr_target_text=qr_target_text,
        registration_number=registration_number,
        issued_date_text=issued_date_text,
        expiry_text=expiry_text,
        side=side,
    )
    buffer = BytesIO()
    png_image.save(buffer, format='PNG', optimize=False, compress_level=4)
    safe_name = slugify(student.fullName or student.indexNumber or f"student-{student.id}") or f"student-{student.id}"
    side_suffix = f"_{side}" if side else ""
    response = HttpResponse(buffer.getvalue(), content_type='image/png')
    response['Content-Disposition'] = f'attachment; filename="student_id_{safe_name}{side_suffix}.png"'
    return response


