@effective_user_decorator
@login_required
@transaction.atomic
def student_id_settings(request):
    if not getattr(request.effective_user, 'is_teacher', False):
        messages.error(request, "You are not authorized to manage ID settings.")
        return redirect('teacher_dashboard')

    settings_url = f"{reverse('student_id_settings')}#student-id-settings-form"
    _ensure_default_student_id_appearance_settings(request.effective_user)
    global_setting = _get_student_id_global_setting(request.effective_user)
    if request.method == 'POST':
        action_values = request.POST.getlist('action')
        action = action_values[-1] if action_values else 'save_settings'
        if request.POST.get('reset_branding') == '1':
            action = 'reset_branding'
        logger.info(
            "Student ID settings POST received",
            extra={
                'student_id_settings_action': action,
                'student_id_settings_action_values': action_values,
                'student_id_settings_user_id': request.effective_user.id,
                'student_id_settings_has_logo_upload': bool(request.FILES.get('logo')),
            },
        )
        if action == 'reset_appearance':
            StudentIDAppearanceSetting.objects.filter(user=request.effective_user).delete()
            _ensure_default_student_id_appearance_settings(request.effective_user)
            messages.success(request, "Student ID appearance defaults were reset.")
            return redirect(settings_url)
        elif action == 'reset_branding':
            if global_setting:
                global_setting.logo.delete(save=False)
                for field in STUDENT_ID_GLOBAL_NUMERIC_FIELDS:
                    setattr(global_setting, field, None)
                global_setting.apply_layout_adjustments_horizontal = STUDENT_ID_GLOBAL_DEFAULTS['apply_layout_adjustments_horizontal']
                global_setting.apply_layout_adjustments_vertical = STUDENT_ID_GLOBAL_DEFAULTS['apply_layout_adjustments_vertical']
                global_setting.save()
            messages.success(request, "Student ID branding defaults were reset.")
            return redirect(settings_url)
        elif action != 'save_settings':
            logger.warning(
                "Unknown Student ID settings action; treating POST as save",
                extra={
                    'student_id_settings_action': action,
                    'student_id_settings_action_values': action_values,
                    'student_id_settings_user_id': request.effective_user.id,
                },
            )

        save_errors = []
        if global_setting:
            if request.POST.get('clear_logo') == 'on':
                global_setting.logo.delete(save=False)
                global_setting.logo = None
            elif request.FILES.get('logo'):
                global_setting.logo = request.FILES['logo']

            size_groups = {
                'logo_size': ['horizontal_logo_size', 'vertical_logo_size'],
                'header_size': ['horizontal_header_size', 'vertical_header_size'],
                'title_size': ['horizontal_title_size', 'vertical_title_size'],
                'subtitle_size': ['horizontal_subtitle_size', 'vertical_subtitle_size'],
            }
            percent_groups = {
                'title_x_percent': ['horizontal_title_x_percent', 'vertical_title_x_percent'],
                'title_y_percent': ['horizontal_title_y_percent', 'vertical_title_y_percent'],
                'subtitle_x_percent': ['horizontal_subtitle_x_percent', 'vertical_subtitle_x_percent'],
                'subtitle_y_percent': ['horizontal_subtitle_y_percent', 'vertical_subtitle_y_percent'],
            }
            parsed_branding_values = {}
            branding_limits = {}
            for group in size_groups:
                branding_limits[group] = (STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX)
                for field in size_groups[group]:
                    branding_limits[field] = (STUDENT_ID_BRANDING_SIZE_MIN, STUDENT_ID_BRANDING_SIZE_MAX)
            for group in percent_groups:
                branding_limits[group] = (STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX)
                for field in percent_groups[group]:
                    branding_limits[field] = (STUDENT_ID_BRANDING_PERCENT_MIN, STUDENT_ID_BRANDING_PERCENT_MAX)

            for field, (minimum, maximum) in branding_limits.items():
                raw = request.POST.get(field, '').strip()
                if raw == '':
                    parsed_branding_values[field] = None
                    continue
                try:
                    parsed_branding_values[field] = max(minimum, min(maximum, float(raw)))
                except (TypeError, ValueError):
                    save_errors.append(f"{field.replace('_', ' ').title()} must be a valid number.")

            for base_field, orientation_fields in {**size_groups, **percent_groups}.items():
                setattr(global_setting, base_field, parsed_branding_values.get(base_field))
                base_value = parsed_branding_values.get(base_field)
                for field in orientation_fields:
                    value = parsed_branding_values.get(field)
                    if value is None:
                        setattr(global_setting, field, None)
                        continue
                    inherited_value = base_value
                    if inherited_value is None:
                        inherited_value = STUDENT_ID_GLOBAL_DEFAULTS[field]
                    if abs(float(value) - float(inherited_value)) < 0.001:
                        setattr(global_setting, field, None)
                    else:
                        setattr(global_setting, field, value)
            global_setting.apply_layout_adjustments_horizontal = request.POST.get('apply_layout_adjustments_horizontal') == 'on'
            global_setting.apply_layout_adjustments_vertical = request.POST.get('apply_layout_adjustments_vertical') == 'on'
            global_setting.save()

        valid_levels = [value for value, _ in STUDENT_ACADEMIC_LEVEL_CHOICES]
        valid_groups = {value for value, _ in STUDENT_ID_GROUP_CHOICES}
        for academic_level in valid_levels:
            defaults = _default_student_id_appearance_for_level(academic_level)
            setting, _ = StudentIDAppearanceSetting.objects.get_or_create(
                user=request.effective_user,
                academic_level=academic_level,
                defaults=defaults,
            )
            field_key = _student_id_settings_field_key(academic_level)
            group = request.POST.get(f'group_{field_key}', setting.group)
            if group in valid_groups:
                setting.group = group
            else:
                save_errors.append(f"{academic_level} has an invalid group selection.")
            setting.use_badge = request.POST.get(f'use_badge_{field_key}') == 'on'
            setting.badge_text = request.POST.get(f'badge_text_{field_key}', '').strip()[:50]
            for field in [
                'front_header_color', 'front_body_color', 'front_accent_color', 'front_text_color',
                'back_header_color', 'back_body_color', 'back_accent_color', 'back_text_color',
            ]:
                if field == 'front_text_color':
                    setting.front_text_color = '#111111'
                    continue
                color = request.POST.get(f'{field}_{field_key}', '').strip()
                if re.fullmatch(r'#[0-9A-Fa-f]{6}', color):
                    setattr(setting, field, color)
                else:
                    save_errors.append(f"{academic_level} {field.replace('_', ' ')} must be a valid color.")
            setting.save()
        if save_errors:
            messages.error(request, "Some ID settings were not saved correctly: " + " ".join(save_errors))
            return redirect(settings_url)
        messages.success(request, "Student ID appearance settings saved.")
        return redirect(settings_url)

    settings_rows = StudentIDAppearanceSetting.objects.filter(user=request.effective_user).order_by('id')
    rows_by_level = {row.academic_level: row for row in settings_rows}
    rows = [rows_by_level[level] for level, _ in STUDENT_ACADEMIC_LEVEL_CHOICES if level in rows_by_level]
    for row in rows:
        row.field_key = _student_id_settings_field_key(row.academic_level)
    global_settings = _student_id_global_settings_to_dict(global_setting, request=request, apply_layout_scopes=False)
    return render(request, 'student_id_settings.html', {
        'settings_rows': rows,
        'global_setting': global_setting,
        'global_settings': global_settings,
        'academic_level_choices': STUDENT_ACADEMIC_LEVEL_CHOICES,
        'group_choices': STUDENT_ID_GROUP_CHOICES,
    })


