def public_student_id_details(request, token):
    """
    Public no-login student details view intended for ID-card QR scans.
    """
    try:
        payload = signing.loads(token, salt=PUBLIC_QR_SALT, max_age=60 * 60 * 24 * 365 * 3)
    except signing.BadSignature:
        return render(request, 'public/student_id_qr_details.html', {'message': 'Invalid or expired student link.'})

    student = _safe_student_lookup_from_public_token(payload)

    if not student:
        return render(request, 'public/student_id_qr_details.html', {
            'message': 'We could not match this student ID link to an active student record. Please contact the school office for help.',
        })

    class_name = getattr(getattr(student.teacherclass, 'ClassName', None), 'class_name', '-') or '-'
    issued_date, expiry_date = _resolve_student_issued_expiry_dates(student)
    context = {
        'school_name': 'THE BRITISH SCHOOL',
        'student': student,
        'student_name': student.fullName or '-',
        'student_index': student.indexNumber or '-',
        'class_name': class_name,
        'registration_number': _resolve_student_registration_number(student),
        'issued_date_text': issued_date.strftime('%d %b %Y'),
        'expiry_text': expiry_date.strftime('%d %b %Y'),
    }
    return render(request, 'public/student_id_qr_details.html', context)


def public_student_qr_result(request):
    token = request.GET.get('token') or request.POST.get('token')
    if not token:
        return render(request, 'public/student_qr_result.html', {'message': 'Invalid result link.'})

    try:
        payload = signing.loads(token, salt=PUBLIC_QR_SALT, max_age=60 * 60 * 24 * 365 * 3)
    except signing.BadSignature:
        return render(request, 'public/student_qr_result.html', {'message': 'Invalid or expired QR link.'})

    anchor_student = Student.objects.filter(id=payload.get('sid'), manager_id=payload.get('mid')).select_related('manager', 'teacherclass__ClassName', 'teacherclass__academicclassyear').first()
    if not anchor_student:
        return render(request, 'public/student_qr_result.html', {'message': 'Student record not found.'})

    candidates = Student.objects.filter(manager_id=anchor_student.manager_id).filter(
        Q(indexNumber=anchor_student.indexNumber) | Q(user_id=anchor_student.user_id)
    ).select_related('teacherclass__ClassName', 'teacherclass__academicclassyear').distinct()
    class_options = list(candidates)

    selected_class_id = request.GET.get('class_id') or request.POST.get('class_id')
    selected_exam_id = request.GET.get('examination_id') or request.POST.get('examination_id')
    selected_grade_id = request.GET.get('grade_id') or request.POST.get('grade_id')

    selected_student = anchor_student
    if selected_class_id:
        selected_student = candidates.filter(teacherclass_id=selected_class_id).first() or anchor_student

    exams = ExaminationName.objects.filter(user=anchor_student.manager).order_by('exam_name')
    grades = GradingModel.objects.filter(user=anchor_student.manager)
    context = {
        'token': token,
        'student': selected_student,
        'school_name': 'THE BRITISH SCHOOL',
        'registration_number': _resolve_student_registration_number(selected_student),
        'class_options': class_options,
        'exam_options': exams,
        'grade_options': grades,
        'selected_class_id': int(selected_student.teacherclass_id) if selected_student.teacherclass_id else None,
        'selected_exam_id': int(selected_exam_id) if selected_exam_id and str(selected_exam_id).isdigit() else None,
        'selected_grade_id': int(selected_grade_id) if selected_grade_id and str(selected_grade_id).isdigit() else None,
    }

    if selected_exam_id and selected_grade_id:
        selected_exam = exams.filter(id=selected_exam_id).first()
        selected_grade = grades.filter(id=selected_grade_id).first()
        if not selected_exam or not selected_grade:
            context['message'] = 'Please select valid examination and grading system.'
            return render(request, 'public/student_qr_result.html', context)

        result_payload = _compute_student_result_context(
            anchor_student.manager,
            selected_student,
            selected_student.teacherclass,
            selected_exam,
            selected_grade,
            all_user_ids=[anchor_student.manager_id],
        )
        if result_payload.get('error'):
            context['message'] = result_payload['error']
        else:
            context.update(result_payload)
            context['selected_exam'] = selected_exam
            context['selected_grade'] = selected_grade
            download_query = urlencode({
                'token': token,
                'class_id': selected_student.teacherclass_id,
                'examination_id': selected_exam.id,
                'grade_id': selected_grade.id,
            })
            context['download_url'] = reverse('public_student_qr_report_download') + f'?{download_query}'

    return render(request, 'public/student_qr_result.html', context)


def public_student_qr_report_download(request):
    token = request.GET.get('token')
    class_id = request.GET.get('class_id')
    examination_id = request.GET.get('examination_id')
    grade_id = request.GET.get('grade_id')
    if not all([token, class_id, examination_id, grade_id]):
        return HttpResponse("Missing parameters.", status=400)

    try:
        payload = signing.loads(token, salt=PUBLIC_QR_SALT, max_age=60 * 60 * 24 * 365 * 3)
    except signing.BadSignature:
        return HttpResponse("Invalid or expired QR link.", status=400)

    anchor_student = Student.objects.filter(id=payload.get('sid'), manager_id=payload.get('mid')).first()
    if not anchor_student:
        return HttpResponse("Student not found.", status=404)

    candidate_students = Student.objects.filter(manager_id=anchor_student.manager_id).filter(
        Q(indexNumber=anchor_student.indexNumber) | Q(user_id=anchor_student.user_id)
    )
    selected_student = candidate_students.filter(teacherclass_id=class_id).first()
    if not selected_student:
        return HttpResponse("Invalid class selection for student.", status=403)

    selected_exam = get_object_or_404(ExaminationName, id=examination_id, user=anchor_student.manager)
    selected_grade = get_object_or_404(GradingModel, id=grade_id, user=anchor_student.manager)
    result_payload = _compute_student_result_context(
        anchor_student.manager,
        selected_student,
        selected_student.teacherclass,
        selected_exam,
        selected_grade,
        all_user_ids=[anchor_student.manager_id],
    )
    if result_payload.get('error'):
        return HttpResponse(result_payload['error'], status=404)

    response = HttpResponse(content_type='application/pdf')
    safe_name = (selected_student.fullName or "student").replace(" ", "_")
    response['Content-Disposition'] = f'attachment; filename="student_result_{safe_name}.pdf"'
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=24, leftMargin=24, topMargin=24, bottomMargin=24)
    styles = getSampleStyleSheet()
    elements = [
        Paragraph("Student Academic Result", styles['Heading2']),
        Spacer(1, 8),
        Paragraph(f"Name: {selected_student.fullName or '-'}", styles['BodyText']),
        Paragraph(f"Index Number: {selected_student.indexNumber or '-'}", styles['BodyText']),
        Paragraph(f"Class: {selected_student.teacherclass.ClassName.class_name}", styles['BodyText']),
        Paragraph(f"Examination: {selected_exam.exam_name}", styles['BodyText']),
        Paragraph(f"Grading: {selected_grade}", styles['BodyText']),
        Spacer(1, 8),
    ]
    table_data = [['Subject', 'Mark', 'Grade']]
    for item in result_payload['student_marks']:
        table_data.append([item['subject_name'], item['mark'] if item['mark'] is not None else '-', item['grade']])
    table = Table(table_data, colWidths=[280, 90, 80])
    table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor("#0b86d8")),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.grey),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('ALIGN', (1, 1), (-1, -1), 'CENTER'),
    ]))
    elements.extend([
        table,
        Spacer(1, 10),
        Paragraph(f"Total Marks: {result_payload['total_marks']}", styles['BodyText']),
        Paragraph(f"Average: {result_payload['average_marks']} ({result_payload['overall_grade']})", styles['BodyText']),
        Paragraph(f"Position: {result_payload['student_position']}", styles['BodyText']),
    ])
    if not result_payload['is_primary']:
        elements.append(Paragraph(f"Division: {result_payload['division']} ({result_payload['total_points']} pts)", styles['BodyText']))
    doc.build(elements)
    return response


