@effective_user_decorator
@login_required
@transaction.atomic
def save_student_information(request, student_id):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Invalid request method.'}, status=400)

    student = get_object_or_404(Student, id=student_id, manager__in=[request.effective_user, request.user])
    model_key = request.POST.get('model_key')
    record_id = request.POST.get('record_id')
    config = STUDENT_MODEL_CONFIG.get(model_key)

    if not config:
        return JsonResponse({'success': False, 'message': 'Invalid information type.'}, status=400)

    instance = None
    if config['multiple']:
        if record_id:
            instance = get_object_or_404(config['model'], id=record_id, student=student)
    else:
        instance = config['model'].objects.filter(student=student).first()

    form = config['form'](request.POST, request.FILES, instance=instance)
    if form.is_valid():
        saved = form.save(commit=False)
        saved.student = student
        photo_changed = False
        captured_photo = None
        if model_key == 'passport':
            captured_photo = build_uploaded_image_from_data_url(
                request.POST.get('captured_photo_data'),
                student.fullName or student.indexNumber or f"student-{student.id}",
            )
            if captured_photo:
                saved.passport_photo = captured_photo
                saved.captured_at = timezone.now()
                saved.uploaded_at = timezone.now()
                photo_changed = True
            elif request.FILES.get('passport_photo'):
                saved.captured_at = None
                saved.uploaded_at = timezone.now()
                photo_changed = True
        saved.save()
        response = {'success': True, 'message': f"{config['title']} saved successfully."}
        if model_key == 'passport' and photo_changed:
            response['student_photo_url'] = sync_student_photo_from_passport(student, saved)
        return JsonResponse(response)

    return JsonResponse({'success': False, 'errors': form.errors}, status=400)


