@effective_user_decorator
@login_required
@transaction.atomic
def import_student_information(request, model_key):
    if request.method != 'POST':
        return redirect('create_student')

    config = STUDENT_MODEL_CONFIG.get(model_key)
    if not config:
        messages.error(request, 'Invalid import type selected.')
        return redirect('create_student')

    file = request.FILES.get('file')
    if not file:
        messages.error(request, 'Please select a file to import.')
        return redirect('create_student')

    extension = file.name.split('.')[-1].lower()
    if extension == 'csv':
        df = pd.read_csv(file)
    elif extension in ['xls', 'xlsx']:
        df = pd.read_excel(file)
    else:
        messages.error(request, 'Unsupported file format. Use CSV/XLS/XLSX.')
        return redirect('create_student')

    required = {'indexNumber'}
    if not required.issubset(df.columns):
        messages.error(request, "File must include 'indexNumber' column.")
        return redirect('create_student')

    form_class = config['form']
    imported_count = 0
    skipped_count = 0

    for _, row in df.iterrows():
        index_number = str(row.get('indexNumber', '')).strip()
        if not index_number:
            skipped_count += 1
            continue

        student = Student.objects.filter(indexNumber=index_number, manager__in=[request.effective_user, request.user]).first()
        if not student:
            skipped_count += 1
            continue

        clean_data = {}
        for name, field in form_class.base_fields.items():
            value = row.get(name)
            clean_data[name] = None if pd.isna(value) else value

        instance = None
        if config['multiple']:
            instance = None
        else:
            instance = config['model'].objects.filter(student=student).first()

        form = form_class(clean_data, instance=instance)
        if form.is_valid():
            obj = form.save(commit=False)
            obj.student = student
            obj.save()
            imported_count += 1
        else:
            skipped_count += 1

    messages.success(request, f"{config['title']} import completed: {imported_count} saved, {skipped_count} skipped.")
    return redirect('create_student')


