@effective_user_decorator
@login_required
def transport_dashboard(request):

    vehicle_id, start_date, end_date, filtered_vehicle = get_transport_filters(request)
    vehicles = _transport_vehicle_queryset(request)
    if vehicle_id:
        vehicles = vehicles.filter(pk=vehicle_id)

    vehicle_summaries = []
    total_fuel_cost = Decimal('0')
    total_maintenance_cost = Decimal('0')
    total_other_expenses = Decimal('0')

    for vehicle in vehicles:
        fuel_records = filter_transport_records(vehicle.fuel_records.all(), start_date, end_date)
        maintenance_records = filter_transport_records(vehicle.maintenances.all(), start_date, end_date)
        expense_records = filter_transport_records(vehicle.expenses.all(), start_date, end_date)

        fuel_cost = sum((record.cost or Decimal('0')) for record in fuel_records)
        maintenance_cost = sum((record.cost or Decimal('0')) for record in maintenance_records)
        expense_cost = sum((record.amount or Decimal('0')) for record in expense_records)
        total_cost = fuel_cost + maintenance_cost + expense_cost

        total_fuel_cost += fuel_cost
        total_maintenance_cost += maintenance_cost
        total_other_expenses += expense_cost

        vehicle_summaries.append({
            'vehicle': vehicle,
            'routes_count': vehicle.routes.count(),
            'fuel_cost': fuel_cost,
            'maintenance_cost': maintenance_cost,
            'expense_cost': expense_cost,
            'total_cost': total_cost,
        })

    return render(request, 'transport/dashboard.html', {
        'vehicles': _transport_vehicle_queryset(request),
        'vehicle_summaries': vehicle_summaries,
        'total_fuel_cost': total_fuel_cost,
        'total_maintenance_cost': total_maintenance_cost,
        'total_other_expenses': total_other_expenses,
        'selected_vehicle': filtered_vehicle,
        'start_date': start_date,
        'end_date': end_date,
    })


