@effective_user_decorator
@login_required
def vehicle_detail(request, pk):

    vehicle = get_object_or_404(
        filter_by_user(
            Vehicle.objects.select_related('driver', 'driver__user').prefetch_related('routes', 'fuel_records', 'maintenances', 'expenses'),
            request,
        ),
        pk=pk,
    )
    fuel_records = vehicle.fuel_records.all().order_by('-date', '-id')
    maintenance_logs = vehicle.maintenances.all().order_by('-date', '-id')
    other_expenses = vehicle.expenses.all().order_by('-date', '-id')

    total_fuel_cost = sum((record.cost or Decimal('0')) for record in fuel_records)
    total_maintenance_cost = sum((record.cost or Decimal('0')) for record in maintenance_logs)
    total_other_expenses = sum((record.amount or Decimal('0')) for record in other_expenses)
    total_fuel_liters = sum((Decimal(str(record.liters or 0)) for record in fuel_records), Decimal('0'))

    fleet_fuel_average = Decimal('0')
    fleet_maintenance_average = Decimal('0')
    fleet = filter_by_user(Vehicle.objects.prefetch_related('fuel_records', 'maintenances'), request)
    if fleet:
        fuel_totals = [sum((record.cost or Decimal('0')) for record in item.fuel_records.all()) for item in fleet]
        maintenance_totals = [sum((record.cost or Decimal('0')) for record in item.maintenances.all()) for item in fleet]
        if fuel_totals:
            fleet_fuel_average = sum(fuel_totals, Decimal('0')) / len(fuel_totals)
        if maintenance_totals:
            fleet_maintenance_average = sum(maintenance_totals, Decimal('0')) / len(maintenance_totals)

    analytics = {
        'high_fuel_usage': total_fuel_cost > fleet_fuel_average or total_fuel_liters > Decimal('500'),
        'high_maintenance_cost': total_maintenance_cost > fleet_maintenance_average or total_maintenance_cost > Decimal('1000'),
    }

    return render(request, 'transport/vehicle_detail.html', {
        'vehicle': vehicle,
        'assigned_routes': vehicle.routes.all(),
        'fuel_records': fuel_records,
        'maintenance_logs': maintenance_logs,
        'other_expenses': other_expenses,
        'total_fuel_cost': total_fuel_cost,
        'total_maintenance_cost': total_maintenance_cost,
        'total_other_expenses': total_other_expenses,
        'total_cost': total_fuel_cost + total_maintenance_cost + total_other_expenses,
        'total_fuel_liters': total_fuel_liters,
        'analytics': analytics,
    })


def _transport_crud_view(request, form_class, template_title, success_url, instance=None, success_message='Saved successfully.'):
    form = form_class(request.POST or None, instance=instance)
    _restrict_transport_form_choices(form, request)
    if request.method == 'POST' and form.is_valid():
        obj = form.save(commit=False)
        if hasattr(obj, 'vehicle') and obj.vehicle_id and obj.vehicle.user_id != request.effective_user.id:
            messages.error(request, 'You can only use your own vehicles.')
            return render(request, 'transport/form.html', {'form': form, 'title': template_title, 'cancel_url': success_url})
        if isinstance(obj, Vehicle):
            obj.user = request.effective_user
        if isinstance(obj, FuelRecord):
            obj.added_by = request.effective_user
        obj.save()
        if hasattr(form, 'save_m2m'):
            form.save_m2m()
        messages.success(request, success_message)
        return redirect(success_url)
    return render(request, 'transport/form.html', {'form': form, 'title': template_title, 'cancel_url': success_url})


