from .forms import CRMLeadForm
from .models import CRMLead


from django.core.paginator import Paginator
from django.db.models import Count, Q
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.utils import timezone
from datetime import timedelta


def _crm_user_display_name_from_values(row):
    first_name = (row.get('served_by__first_name') or '').strip()
    last_name = (row.get('served_by__last_name') or '').strip()
    full_name = f"{first_name} {last_name}".strip()
    return (
        full_name
        or row.get('served_by__username')
        or row.get('served_by__email')
        or "Unknown"
    )


@effective_user_decorator
@login_required
def crm_lead_list_create(request):
    base_lead_qs = CRMLead.objects.filter(
        created_by=request.effective_user
    ).select_related('created_by', 'served_by')

    if request.method == 'POST':
        form = CRMLeadForm(request.POST)
        if form.is_valid():
            lead = form.save(commit=False)
            lead.created_by = request.effective_user
            lead.served_by = request.user
            lead.save()
            messages.success(request, 'Lead created successfully.')
            return redirect('crm_lead_list')
        messages.error(request, 'Please fix form errors and try again.')
    else:
        form = CRMLeadForm()

    query = request.GET.get('q', '').strip()
    status_filter = request.GET.get('status', '').strip()
    class_filter = request.GET.get('academic_class', '').strip()
    source_filter = request.GET.get('source', '').strip()
    lead_qs = base_lead_qs

    if query:
        lead_qs = lead_qs.filter(
            Q(name__icontains=query)
            | Q(phone__icontains=query)
            | Q(email__icontains=query)
            | Q(student_first_name__icontains=query)
            | Q(student_middle_name__icontains=query)
            | Q(student_last_name__icontains=query)
            | Q(served_by__username__icontains=query)
            | Q(served_by__first_name__icontains=query)
            | Q(served_by__last_name__icontains=query)
            | Q(served_by__email__icontains=query)
        )

    if status_filter:
        lead_qs = lead_qs.filter(status=status_filter)

    if class_filter:
        lead_qs = lead_qs.filter(academic_class=class_filter)

    if source_filter:
        lead_qs = lead_qs.filter(source=source_filter)

    total_leads = lead_qs.count()
    today_leads = lead_qs.filter(created_at__date=timezone.localdate()).count()
    enrolled_leads = lead_qs.filter(status='Enrolled').count()
    lost_leads = lead_qs.filter(status='Lost').count()
    active_followups = lead_qs.filter(status__in=['New', 'Contacted', 'Interested', 'Follow Up']).count()
    conversion_rate = (enrolled_leads / total_leads * 100) if total_leads else 0

    served_user_stats = list(
        lead_qs.values(
            'served_by',
            'served_by__username',
            'served_by__first_name',
            'served_by__last_name',
            'served_by__email',
        )
        .annotate(count=Count('id'))
        .order_by('-count', 'served_by__username')
    )
    for row in served_user_stats:
        row['display_name'] = _crm_user_display_name_from_values(row)
        row['percentage'] = (row['count'] / total_leads * 100) if total_leads else 0

    top_served_user = served_user_stats[0] if served_user_stats else None

    source_stats = lead_qs.values('source').annotate(count=Count('id')).order_by('-count', 'source')
    status_stats = lead_qs.values('status').annotate(count=Count('id')).order_by('-count', 'status')
    class_stats = lead_qs.values('academic_class').annotate(count=Count('id')).order_by('-count', 'academic_class')

    lead_qs = lead_qs.order_by('-created_at')

    # Pagination
    page_number = request.GET.get('page', 1)
    per_page = request.GET.get('per_page', 25)

    try:
        per_page = int(per_page)
    except ValueError:
        per_page = 25

    allowed_per_page = [10, 25, 50, 100]
    if per_page not in allowed_per_page:
        per_page = 25

    paginator = Paginator(lead_qs, per_page)
    page_obj = paginator.get_page(page_number)

    context = {
        'form': form,

        # Use page_obj in template loop
        'leads': page_obj,

        # Pagination objects
        'page_obj': page_obj,
        'paginator': paginator,
        'per_page': per_page,
        'allowed_per_page': allowed_per_page,

        # Filters
        'q': query,
        'selected_status': status_filter,
        'selected_academic_class': class_filter,
        'selected_source': source_filter,

        # Choices
        'status_choices': CRMLead.STATUS_CHOICES,
        'academic_class_choices': CRMLead.ACADEMIC_CLASS_CHOICES,
        'source_choices': CRMLead.SOURCE_CHOICES,

        # Analytics
        'total_leads': total_leads,
        'today_leads': today_leads,
        'enrolled_leads': enrolled_leads,
        'lost_leads': lost_leads,
        'active_followups': active_followups,
        'conversion_rate': conversion_rate,
        'served_user_stats': served_user_stats,
        'top_served_user': top_served_user,
        'source_stats': source_stats,
        'status_stats': status_stats,
        'class_stats': class_stats,
    }

    return render(request, 'crm/lead_list.html', context)


