def _application_year_label(academic_year):
    label = getattr(academic_year, 'academic_year_name', '') or str(timezone.now().year)
    match = re.search(r'(\d{4})', label)
    return match.group(1) if match else label


def _assign_application_number(application):
    if application.application_number:
        return
    year_label = _application_year_label(application.academic_year)
    prefix = f"BRT-{year_label}-"
    existing_numbers = StudentApplication.objects.select_for_update().filter(
        academic_year=application.academic_year,
        application_number__startswith=prefix,
    ).values_list('application_number', flat=True)
    max_counter = 0
    for number in existing_numbers:
        tail = str(number or '').split('-')[-1]
        if tail.isdigit():
            max_counter = max(max_counter, int(tail))
    counter = max_counter + 1
    while StudentApplication.objects.filter(application_number=f"{prefix}{counter}").exists():
        counter += 1
    application.application_number = f"{prefix}{counter}"


def _application_full_name(application):
    return application.full_name or f"Applicant {application.application_number or application.pk}"


def _gender_to_student_sex(gender):
    return {'Male': 'M', 'Female': 'F', 'Other': 'O'}.get(gender, 'O')


def _numeric_contact(value):
    digits = re.sub(r'\D+', '', value or '')
    return int(digits) if digits else None


def _normalize_class_name(value):
    value = (value or '').lower().strip()
    value = re.sub(r'[-_/]+', ' ', value)
    value = re.sub(r'[^\w\s]', '', value)
    words_to_numbers = {
        'zero': '0',
        'one': '1',
        'two': '2',
        'three': '3',
        'four': '4',
        'five': '5',
        'six': '6',
        'seven': '7',
        'eight': '8',
        'nine': '9',
        'ten': '10',
    }
    parts = [words_to_numbers.get(part, part) for part in value.split()]
    return ' '.join(parts)


def _class_name_similarity(a, b):
    normalized_a = _normalize_class_name(a)
    normalized_b = _normalize_class_name(b)
    if not normalized_a or not normalized_b:
        return 0
    if normalized_a == normalized_b:
        return 1
    if normalized_a in normalized_b or normalized_b in normalized_a:
        return 0.95
    return SequenceMatcher(None, normalized_a, normalized_b).ratio()


def _find_best_register_class(user, class_name):
    register_class = RegisterClass.objects.filter(
        user=user,
        class_name__iexact=class_name,
    ).first()
    if register_class:
        return register_class

    normalized_target = _normalize_class_name(class_name)
    if not normalized_target:
        return None

    best_match = None
    best_score = 0
    for existing_class in RegisterClass.objects.filter(user=user).only('id', 'class_name'):
        score = _class_name_similarity(existing_class.class_name, class_name)
        if score > best_score:
            best_score = score
            best_match = existing_class

    return best_match if best_score >= 0.82 else None


@transaction.atomic
def _create_student_from_application(request, application):
    if application.student:
        return application.student, False

    register_class = _find_best_register_class(request.effective_user, application.class_name)
    if not register_class:
        register_class = RegisterClass.objects.create(
            user=request.effective_user,
            class_name=application.class_name,
        )
    teacherclass = TeacherClass.objects.filter(
        user=request.effective_user,
        ClassName=register_class,
        academicclassyear=application.academic_year,
    ).first()
    if not teacherclass:
        teacherclass = TeacherClass.objects.create(
            user=request.effective_user,
            ClassName=register_class,
            academicclassyear=application.academic_year,
        )
    index_number = generate_student_index_number_for_class(request.effective_user, teacherclass)
    username = application.application_number or index_number
    password = application.phone or application.application_number or index_number
    student_user, user_created = User.objects.get_or_create(
        username=username,
        defaults={
            'email': application.email or '',
            'is_student': True,
            'is_teacher': False,
        }
    )
    if user_created:
        student_user.set_password(str(password))
        student_user.save()
    elif not student_user.is_student:
        student_user.is_student = True
        student_user.is_teacher = False
        student_user.save(update_fields=['is_student', 'is_teacher'])

    student = Student.objects.create(
        user=student_user,
        indexNumber=index_number,
        fullName=_application_full_name(application),
        sex=_gender_to_student_sex(application.gender),
        contact=_numeric_contact(application.phone),
        teacherclass=teacherclass,
        manager=request.effective_user,
    )
    StudentAcademicInformation.objects.update_or_create(
        student=student,
        defaults={
            'registration_number': student.indexNumber or '',
            'academic_level': application.academic_level or '',
            'academic_year': getattr(application.academic_year, 'academic_year_name', '') or '',
            'class_name': application.class_name or '',
            'class_focus': application.class_focus or '',
            'short_course_validity_months': 3 if application.academic_level in SHORT_COURSE_ACADEMIC_LEVELS else None,
            'remarks': application.remarks or '',
        }
    )
    if any([application.guardian_first_name, application.guardian_last_name, application.guardian_phone, application.guardian_email, application.guardian_address, application.guardian_occupation]):
        StudentGuardianInformation.objects.update_or_create(
            student=student,
            defaults={
                'guardian_name': application.guardian_full_name,
                'phone_number': application.guardian_phone or '',
                'email': application.guardian_email or '',
                'occupation': application.guardian_occupation or '',
                'address': application.guardian_address or '',
            }
        )
    if any([application.sponsor_name, application.sponsor_type, application.sponsor_phone, application.sponsor_email, application.sponsor_address, application.sponsor_details]):
        StudentSponsorInformation.objects.update_or_create(
            student=student,
            defaults={
                'sponsor_name': application.sponsor_name or '',
                'sponsor_type': application.sponsor_type or '',
                'phone_number': application.sponsor_phone or '',
                'email': application.sponsor_email or '',
                'address': application.sponsor_address or '',
                'remarks': application.sponsor_details or '',
            }
        )
    application.student = student
    application.save(update_fields=['student', 'updated_at'])
    return student, True


def _student_add_more_redirect_url(student):
    teacherclass_id = getattr(student, "teacherclass_id", None)
    url = reverse("create_student")
    params = {
        "created_student": student.id,
        "open_info": "1",
    }
    if teacherclass_id:
        params["class"] = teacherclass_id
    return f"{url}?{urlencode(params)}"


def _remove_application_student(application):
    student = application.student
    if not student:
        return False
    application.student = None
    application.save(update_fields=['student', 'updated_at'])
    student.delete()
    return True


def _application_logo_url(request):
    setting = StudentIDGlobalSetting.objects.filter(user=request.effective_user, logo__isnull=False).first()
    if setting and setting.logo:
        return setting.logo.url
    return settings.STATIC_URL + 'BRITISH_LOGO.png'


@effective_user_decorator
@login_required
def student_application_list(request):
    applications = StudentApplication.objects.filter(user=request.effective_user).select_related('academic_year', 'student')
    q = request.GET.get('q', '').strip()
    status = request.GET.get('status', '').strip()
    academic_year = request.GET.get('academic_year', '').strip()
    academic_level = request.GET.get('academic_level', '').strip()
    class_name = request.GET.get('class_name', '').strip()
    application_type = request.GET.get('application_type', '').strip()

    if q:
        applications = applications.filter(
            Q(application_number__icontains=q)
            | Q(first_name__icontains=q)
            | Q(middle_name__icontains=q)
            | Q(last_name__icontains=q)
            | Q(phone__icontains=q)
            | Q(class_name__icontains=q)
        )
    if status:
        applications = applications.filter(status=status)
    if academic_year:
        applications = applications.filter(academic_year_id=academic_year)
    if academic_level:
        applications = applications.filter(academic_level=academic_level)
    if class_name:
        applications = applications.filter(class_name=class_name)
    if application_type:
        applications = applications.filter(application_type=application_type)

    paginator = Paginator(applications.order_by('-created_at'), 15)
    page_obj = paginator.get_page(request.GET.get('page'))
    params = request.GET.copy()
    params.pop('page', None)

    context = {
        'applications': page_obj,
        'page_obj': page_obj,
        'q': q,
        'selected_status': status,
        'selected_academic_year': academic_year,
        'selected_academic_level': academic_level,
        'selected_class_name': class_name,
        'selected_application_type': application_type,
        'querystring': params.urlencode(),
        'status_choices': StudentApplication.STATUS_CHOICES,
        'academic_years': AcademicClassYear.objects.filter(user=request.effective_user, active_year=True).order_by('academic_year_name'),
        'academic_level_choices': StudentApplicationForm.ACADEMIC_LEVEL_CHOICES[1:],
        'class_choices': StudentApplicationForm.CLASS_CHOICES[1:],
        'application_type_choices': StudentApplicationForm.APPLICATION_TYPE_CHOICES[1:],
    }
    return render(request, 'applications/application_list.html', context)


@effective_user_decorator
@login_required
@transaction.atomic
def student_application_create(request):
    if request.method == 'POST':
        form = StudentApplicationForm(request.POST, user=request.effective_user)
        if form.is_valid():
            application = form.save(commit=False)
            application.user = request.effective_user
            _assign_application_number(application)
            application.save()
            if application.status == 'on_progress':
                student, _ = _create_student_from_application(request, application)
                messages.success(request, 'Student profile created and moved to registration progress.')
                if request.POST.get('add_more_info') == '1':
                    return redirect(_student_add_more_redirect_url(student))
            messages.success(request, 'Application created successfully.')
            return redirect('student_applications')
        messages.error(request, 'Please correct the highlighted fields.')
    else:
        form = StudentApplicationForm(user=request.effective_user, initial={'application_date': timezone.localdate(), 'status': 'not_returned'})
    return render(request, 'applications/application_form.html', {'form': form, 'title': 'Add Application', 'application': None})


